window.PA_SITUATIONS = [{"id": "ABH-01", "seq": 1, "module": "Foundations", "source": "Abhishek Pandey", "title": "The six PACS messages you will see everywhere", "explain": "ISO 20022 PACS messages carry payments and their status. pacs.008 is the customer credit transfer, pacs.009 is the financial institution transfer, pacs.002 reports status, pacs.004 returns a payment, pacs.028 requests a status, and pacs.029 resolves an investigation. Learn these six first, because every flow in this product is described with them.", "takeaway": "Learn these six first, because every flow in this product is described with them.", "visual": {"type": "diagram", "diagram": {"centre": "The six PACS messages", "parts": [{"label": "pacs.008", "note": "Customer credit transfer, the payment itself"}, {"label": "pacs.009", "note": "Financial institution transfer between banks"}, {"label": "pacs.002", "note": "Reports the status of a payment"}, {"label": "pacs.004", "note": "Returns a payment that was settled"}, {"label": "pacs.028", "note": "Requests the status of a payment"}, {"label": "pacs.029", "note": "Resolves an investigation on a payment"}]}}, "level": "foundation", "source_ref": "https://www.linkedin.com/in/abhishek2601/recent-activity/all/"}, {"id": "ABH-02", "seq": 2, "module": "Foundations", "source": "Abhishek Pandey", "title": "ISO 20022 is more than a messaging standard", "explain": "ISO 20022 is not just a new message format. It brings richer data, better automation, smarter compliance, and payment visibility across the whole lifecycle. A payment that carries structured data can be validated, screened, and reconciled without manual rework.", "takeaway": "A payment that carries structured data can be validated, screened, and reconciled without manual rework.", "visual": {"type": "diagram", "diagram": {"centre": "ISO 20022, more than a format", "parts": [{"label": "Richer data", "note": "Structured data travels with the payment"}, {"label": "Better automation", "note": "Straight-through processing without manual rework"}, {"label": "Smarter compliance", "note": "Data can be screened and validated in line"}, {"label": "Payment visibility", "note": "Status visible across the whole lifecycle"}, {"label": "Reconciliation", "note": "Structured data makes matching the payment easy"}]}}, "level": "foundation", "source_ref": "https://www.linkedin.com/in/abhishek2601/recent-activity/all/"}, {"id": "ABH-03", "seq": 3, "module": "Foundations", "source": "Abhishek Pandey", "title": "SEPA rejected versus returned, and why the stage matters", "explain": "A SEPA reject happens before settlement and is reported with a pacs.002, while a return happens after settlement and uses a pacs.004. The first question to ask about a failed SEPA payment is at which stage it failed. That single distinction decides the handling path.", "takeaway": "That single distinction decides the handling path.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Payment fails before settlement", "note": "Reject, reported with pacs.002"}, {"kind": "decision", "title": "At which stage did it fail?", "note": "The stage decides the handling path"}, {"kind": "step", "title": "Reject before settlement", "note": "Reported with pacs.002"}, {"kind": "step", "title": "Return after settlement", "note": "Reported with pacs.004"}]}}, "level": "foundation", "source_ref": "https://www.linkedin.com/in/abhishek2601/recent-activity/all/"}, {"id": "ABH-04", "seq": 4, "module": "Foundations", "source": "Abhishek Pandey", "title": "A card payment in three stages", "explain": "A card payment moves through authorization, clearing, and settlement. At authorization the issuer verifies the card, the balance, fraud signals, and the PIN, CVV, or 3DS check. Clearing is when the network exchanges the records, and settlement is when the funds actually move to the merchant.", "takeaway": "Clearing is when the network exchanges the records, and settlement is when the funds actually move to the merchant.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Authorization", "note": "Issuer verifies card, balance, fraud signals, PIN, CVV or 3DS"}, {"kind": "step", "title": "Clearing", "note": "Network exchanges the records between banks"}, {"kind": "step", "title": "Settlement", "note": "Funds actually move to the merchant"}]}}, "level": "foundation", "source_ref": "https://www.linkedin.com/in/abhishek2601/recent-activity/all/"}, {"id": "ABH-05", "seq": 5, "module": "Foundations", "source": "Abhishek Pandey", "title": "Connect the whole payment map", "explain": "Knowing ISO 20022 and SWIFT is not enough on its own. Real payments expertise means connecting the payment lifecycle, cards, rails, clearing and settlement, fraud and AML, APIs, and the end-to-end journey. Each piece only makes sense when you see how it joins the others.", "takeaway": "Each piece only makes sense when you see how it joins the others.", "visual": {"type": "diagram", "diagram": {"centre": "The connected payment lifecycle", "parts": [{"label": "Payment lifecycle", "note": "The journey every payment follows end to end"}, {"label": "Cards", "note": "Authorization, clearing and settlement"}, {"label": "Rails", "note": "The networks that carry the payment"}, {"label": "Clearing and settlement", "note": "Where records exchange and funds move"}, {"label": "Fraud and AML", "note": "Checks that keep payments safe and compliant"}, {"label": "APIs", "note": "How systems connect and exchange payment data"}, {"label": "End-to-end journey", "note": "Each piece only makes sense joined to the others"}]}}, "level": "foundation", "source_ref": "https://www.linkedin.com/in/abhishek2601/recent-activity/all/"}, {"id": "ABH-06", "seq": 6, "module": "Foundations", "source": "Abhishek Pandey", "title": "Do not learn payments in silos", "explain": "Payments is one connected system, not a set of separate topics. To become a strong payments professional, connect rails, cards, ISO 8583 and ISO 20022, APIs, PCI and tokenization, the lifecycle, compliance, and emerging payments. Study each piece by asking how it touches the rest.", "takeaway": "Study each piece by asking how it touches the rest.", "visual": {"type": "diagram", "diagram": {"centre": "Payments, one connected system", "parts": [{"label": "Rails", "note": "The networks payments travel on"}, {"label": "Cards", "note": "Authorization, clearing and settlement"}, {"label": "ISO 8583", "note": "Card message standard in the mix"}, {"label": "ISO 20022", "note": "Rich data messaging for payments"}, {"label": "APIs", "note": "Connections between payment systems"}, {"label": "PCI and tokenization", "note": "Protecting card data in the flow"}, {"label": "Lifecycle", "note": "The stages a payment passes through"}, {"label": "Compliance", "note": "Rules the whole system must meet"}]}}, "level": "foundation", "source_ref": "https://www.linkedin.com/in/abhishek2601/recent-activity/all/"}, {"id": "ABH-07", "seq": 7, "module": "Foundations", "source": "Abhishek Pandey", "title": "Cross-border payments, one connected world", "explain": "Cross-border payments connect different countries and different systems into one flow. The challenge is the same everywhere: speed, cost, compliance, and transparency. A payment that is fast but opaque, or cheap but non-compliant, has failed the test.", "takeaway": "A payment that is fast but opaque, or cheap but non-compliant, has failed the test.", "visual": {"type": "diagram", "diagram": {"centre": "Cross-border payments", "parts": [{"label": "Speed", "note": "How fast the payment reaches the beneficiary"}, {"label": "Cost", "note": "What the payment costs to send"}, {"label": "Compliance", "note": "Rules every cross-border payment must meet"}, {"label": "Transparency", "note": "Visibility on status, fees and timing"}, {"label": "Countries", "note": "Different systems joined into one flow"}]}}, "level": "foundation", "source_ref": "https://www.linkedin.com/in/abhishek2601/recent-activity/all/"}, {"id": "ABH-08", "seq": 8, "module": "Foundations", "source": "Abhishek Pandey", "title": "Can a Letter of Credit become fully digital", "explain": "A Letter of Credit is a trade finance instrument that has traditionally run on paper. A fully digital LC shows that even the most document-heavy payment product can move end to end without paper. The question for a BA is what changes in the process, the data, and the controls when the paper goes away.", "takeaway": "The question for a BA is what changes in the process, the data, and the controls when the paper goes away.", "visual": {"type": "diagram", "diagram": {"centre": "A fully digital Letter of Credit", "parts": [{"label": "Paper process", "note": "The traditional document-heavy LC"}, {"label": "Digital process", "note": "End to end without paper"}, {"label": "Process change", "note": "What changes when the paper goes away"}, {"label": "Data change", "note": "What data the digital LC carries"}, {"label": "Controls change", "note": "What controls replace paper checks"}]}}, "level": "foundation", "source_ref": "https://www.linkedin.com/in/abhishek2601/recent-activity/all/"}, {"id": "ABH-09", "seq": 9, "module": "Foundations", "source": "Abhishek Pandey", "title": "Asia's banking upgrade", "explain": "Banking in Asia is moving to real-time payments, API-first design, cloud, and ISO 20022. That shift creates a new engineering opportunity for people who understand both technology and the banking transaction lifecycle. The winners are the ones who can bridge the two.", "takeaway": "The winners are the ones who can bridge the two.", "visual": {"type": "diagram", "diagram": {"centre": "Asia's banking upgrade", "parts": [{"label": "Real-time payments", "note": "Banking moves to payments that settle instantly"}, {"label": "API-first design", "note": "Systems built around APIs from the start"}, {"label": "Cloud", "note": "Banking runs on cloud platforms"}, {"label": "ISO 20022", "note": "The common message standard for the shift"}]}}, "level": "foundation", "source_ref": "https://www.linkedin.com/in/abhishek2601/recent-activity/all/"}, {"id": "INS-121", "seq": 10, "module": "Foundations", "source": "Jebaraj D", "title": "Why direct debit matters for European recurring payments", "explain": "Direct debit is the standard way European businesses collect recurring payments, such as subscriptions and utility bills, because the creditor pulls the money on the due date instead of waiting for the customer to pay. It matters because it gives the creditor control over timing and reduces late payments, but it only works when the mandate, the creditor identifier, and the scheme rules are set up correctly. A business analyst needs to understand why a market uses direct debit before designing a collection flow for it.", "takeaway": "A business analyst needs to understand why a market uses direct debit before designing a collection flow for it.", "visual": {"type": "diagram", "diagram": {"centre": "Direct debit for recurring payments", "parts": [{"label": "Recurring collections", "note": "Subscriptions and utility bills are the typical recurring collections"}, {"label": "Creditor pulls funds", "note": "Creditor pulls money on the due date instead of waiting for the customer to pay"}, {"label": "Timing control", "note": "Creditor controls timing and reduces late payments"}, {"label": "Mandate", "note": "Mandate must be set up correctly for collections to work"}, {"label": "Creditor Identifier", "note": "Creditor Identifier must be set up correctly for collections to work"}, {"label": "Scheme rules", "note": "Scheme rules must be set up correctly for collections to work"}]}}, "level": "foundation", "source_ref": "JEB-05"}, {"id": "INS-122", "seq": 11, "module": "Foundations", "source": "Jebaraj D", "title": "Creditor role and Creditor Identifier", "explain": "In SEPA Direct Debit, the creditor is the business that collects the money, and the Creditor Identifier is the unique code that identifies that creditor across the scheme. The identifier travels with every collection so the debtor bank and the debtor can recognise who is pulling the funds. Without a correct Creditor Identifier, a collection cannot be initiated or matched to the right creditor.", "takeaway": "Without a correct Creditor Identifier, a collection cannot be initiated or matched to the right creditor.", "visual": {"type": "diagram", "diagram": {"centre": "Creditor and Creditor Identifier", "parts": [{"label": "Creditor", "note": "Business that collects the money in SEPA Direct Debit"}, {"label": "Creditor Identifier", "note": "Unique code that identifies that creditor across the scheme"}, {"label": "Travels with collection", "note": "Identifier travels with every collection for recognition"}, {"label": "Debtor bank recognition", "note": "Debtor bank can recognise who is pulling the funds"}, {"label": "Debtor recognition", "note": "Debtor can recognise who is pulling the funds"}, {"label": "Correct identifier needed", "note": "Without a correct identifier, a collection cannot be initiated or matched"}]}}, "level": "foundation", "source_ref": "JEB-06"}, {"id": "INS-125", "seq": 12, "module": "Foundations", "source": "Jebaraj D", "title": "The four-corner model", "explain": "A SEPA Direct Debit moves through four corners: the creditor, the creditor PSP, the clearing and settlement mechanism, and the debtor PSP with the debtor. The creditor sends the collection file to its PSP, the PSP passes it to the clearing system, and the debtor PSP debits the debtor account on the due date. Each corner has a distinct responsibility, and when a collection fails, the model tells you which party owns the failure.", "takeaway": "Each corner has a distinct responsibility, and when a collection fails, the model tells you which party owns the failure.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Creditor sends collection file", "note": "Creditor sends the collection file to its PSP"}, {"kind": "step", "title": "Creditor PSP receives file", "note": "Creditor PSP receives the collection file from the creditor"}, {"kind": "step", "title": "Clearing system processes it", "note": "PSP passes the collection to the clearing system"}, {"kind": "step", "title": "Debtor PSP debits debtor", "note": "Debtor PSP debits the debtor account on the due date"}, {"kind": "decision", "title": "Which party owns a failure?", "note": "Model shows which corner owns the failure when a collection fails"}]}}, "level": "foundation", "source_ref": "JEB-08"}, {"id": "INS-124", "seq": 13, "module": "Foundations", "source": "Jebaraj D", "title": "Due date versus settlement date versus debit date", "explain": "The due date is the date the creditor wants the money, the debit date is the date the debtor account is actually debited, and the settlement date is the date the funds move between the banks. These three dates are often the same day, but they can differ when a PSP is closed or the clearing system is unavailable. Confusing them causes wrong value dating and reconciliation breaks.", "takeaway": "Confusing them causes wrong value dating and reconciliation breaks.", "visual": {"type": "diagram", "diagram": {"centre": "Due, debit and settlement dates", "parts": [{"label": "Due date", "note": "Date the creditor wants the money"}, {"label": "Debit date", "note": "Date the debtor account is actually debited"}, {"label": "Settlement date", "note": "Date the funds move between the banks"}, {"label": "Often the same day", "note": "The three dates are often the same day"}, {"label": "Dates can differ", "note": "Dates can differ when a PSP is closed or clearing is unavailable"}, {"label": "Wrong dating risk", "note": "Confusing them causes wrong value dating and reconciliation breaks"}]}}, "level": "foundation", "source_ref": "JEB-07"}, {"id": "INS-126", "seq": 14, "module": "Foundations", "source": "Jebaraj D", "title": "Pre-notification versus collection submission", "explain": "Pre-notification is the notice the creditor sends to the debtor before the collection, telling them the amount and the date. Collection submission is the creditor PSP sending the collection file into the scheme for processing. These are two separate steps on different timelines, and generating the file is not the same as notifying the customer. If the amount changes and the pre-notification is not updated, the debtor can dispute the collection.", "takeaway": "If the amount changes and the pre-notification is not updated, the debtor can dispute the collection.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Pre-notification sent", "note": "Creditor notifies the debtor of the amount and the date before collection"}, {"kind": "step", "title": "Collection file generated", "note": "Creditor generates the collection file for submission"}, {"kind": "step", "title": "Collection submitted", "note": "Creditor PSP sends the collection file into the scheme for processing"}, {"kind": "decision", "title": "Amount changed without update?", "note": "If the amount changes and notice is not updated, the debtor can dispute"}]}}, "level": "foundation", "source_ref": "JEB-09"}, {"id": "INS-157", "seq": 15, "module": "Foundations", "source": "Jebaraj D", "title": "Creditor pre-notification agreement", "explain": "The scheme expects the creditor to notify the debtor before each collection, usually 14 calendar days in advance, unless the creditor and debtor have agreed a different timeline. That agreed alternative must be evidenced, so the creditor can prove the debtor accepted a shorter notice period. A shorter notice without agreement leaves the collection open to dispute.", "takeaway": "A shorter notice without agreement leaves the collection open to dispute.", "visual": {"type": "diagram", "diagram": {"centre": "Creditor pre-notification agreement", "parts": [{"label": "Notify before collection", "note": "Creditor notifies the debtor before each collection"}, {"label": "14 calendar days", "note": "Notice is usually 14 calendar days in advance"}, {"label": "Agreed alternative", "note": "Creditor and debtor can agree a different timeline"}, {"label": "Evidence required", "note": "Agreed alternative must be evidenced by the creditor"}, {"label": "Shorter notice risk", "note": "Shorter notice without agreement leaves the collection open to dispute"}]}}, "level": "foundation", "source_ref": "JEB-09"}, {"id": "INS-128", "seq": 16, "module": "Foundations", "source": "Jebaraj D", "title": "Calendar days versus banking business days", "explain": "Some scheme timelines are counted in calendar days and others in banking business days, and using the wrong calendar gives the wrong date. Pre-notification, refund windows, and scheme timelines each specify which calendar applies. A business analyst must check the calendar for each timeline rather than assuming they all work the same way.", "takeaway": "A business analyst must check the calendar for each timeline rather than assuming they all work the same way.", "visual": {"type": "diagram", "diagram": {"centre": "Scheme timeline calendars", "parts": [{"label": "Calendar days", "note": "Some scheme timelines are counted in calendar days"}, {"label": "Banking business days", "note": "Other timelines are counted in banking business days"}, {"label": "Pre-notification", "note": "Pre-notification specifies which calendar applies"}, {"label": "Refund windows", "note": "Refund windows specify which calendar applies"}, {"label": "Scheme timelines", "note": "Scheme timelines each specify which calendar applies"}, {"label": "Check each timeline", "note": "Analyst must check the calendar for each timeline"}]}}, "level": "foundation", "source_ref": "JEB-11"}, {"id": "INS-127", "seq": 17, "module": "Foundations", "source": "Jebaraj D", "title": "Participant calendars and TARGET and CSM closure", "explain": "A direct debit collection depends on three calendars at once: the creditor PSP, the debtor PSP, and the clearing and settlement mechanism. If any one of them is closed on the due date, the collection cannot complete on that date, even if the other two are open. Planning collections on a single calendar, such as only the creditor's own business calendar, causes late debits.", "takeaway": "Planning collections on a single calendar, such as only the creditor's own business calendar, causes late debits.", "visual": {"type": "diagram", "diagram": {"centre": "Three calendars for a collection", "parts": [{"label": "Creditor PSP calendar", "note": "Creditor PSP calendar must be open on the due date"}, {"label": "Debtor PSP calendar", "note": "Debtor PSP calendar must be open on the due date"}, {"label": "Clearing mechanism calendar", "note": "Clearing and settlement mechanism calendar must be open"}, {"label": "Any closure blocks it", "note": "If any one is closed, the collection cannot complete on that date"}, {"label": "Single calendar risk", "note": "Planning on only the creditor calendar causes late debits"}]}}, "level": "foundation", "source_ref": "JEB-10"}, {"id": "INS-135", "seq": 18, "module": "Foundations", "source": "Jebaraj D", "title": "Why cross-border payments remain slower than domestic instant payments", "explain": "A domestic instant payment moves inside one system with one set of rules, while a cross-border payment passes through several payment service providers, currency conversions, compliance checks, and settlement systems. Each hop adds time, and the hops depend on each other's operating hours. That chain of dependencies is why cross-border payments are slower even when each individual leg is fast.", "takeaway": "That chain of dependencies is why cross-border payments are slower even when each individual leg is fast.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Domestic instant payment", "note": "Moves inside one system with one set of rules"}, {"kind": "step", "title": "Several providers involved", "note": "Cross-border payment passes through several payment service providers"}, {"kind": "step", "title": "Currency conversion", "note": "Payment passes through currency conversions"}, {"kind": "step", "title": "Compliance checks", "note": "Payment passes through compliance checks"}, {"kind": "step", "title": "Settlement systems and hours", "note": "Each hop adds time and hops depend on each other's operating hours"}]}}, "level": "foundation", "source_ref": "JEB-14"}, {"id": "INS-139", "seq": 19, "module": "Foundations", "source": "Jebaraj D", "title": "UETR as a tracking reference", "explain": "The UETR is a unique end-to-end transaction reference that stays with a payment across every bank and system it passes through. It lets any party trace the payment and ask each hop for its status using the same reference. A UETR proves the payment exists and can be tracked, but it does not by itself prove where the money is or that it settled.", "takeaway": "A UETR proves the payment exists and can be tracked, but it does not by itself prove where the money is or that it settled.", "visual": {"type": "diagram", "diagram": {"centre": "UETR tracking reference", "parts": [{"label": "Unique reference", "note": "Unique end-to-end transaction reference for the payment"}, {"label": "Stays with the payment", "note": "Stays with the payment across every bank and system it passes through"}, {"label": "Trace the payment", "note": "Lets any party trace the payment end to end"}, {"label": "Status enquiry", "note": "Each hop can be asked for its status using the same reference"}, {"label": "Proves existence", "note": "Proves the payment exists and can be tracked"}, {"label": "Does not prove settlement", "note": "Does not by itself prove where the money is or that it settled"}]}}, "level": "foundation", "source_ref": "JEB-17"}, {"id": "INS-152", "seq": 20, "module": "Foundations", "source": "Jebaraj D", "title": "Instant payment does not mean instant settlement everywhere", "explain": "When a customer sends an instant payment, the beneficiary may see the credit within seconds, but the banks behind the payment may still settle between themselves later. The customer experience, the scheme processing, and the settlement finality are three different things that do not always happen at the same moment. A payment can look instant to the customer while the interbank settlement is still pending.", "takeaway": "A payment can look instant to the customer while the interbank settlement is still pending.", "visual": {"type": "diagram", "diagram": {"centre": "Instant payment versus settlement", "parts": [{"label": "Customer credit in seconds", "note": "Beneficiary may see the credit within seconds"}, {"label": "Banks settle later", "note": "Banks behind the payment may still settle between themselves later"}, {"label": "Customer experience", "note": "Customer experience is one of three different things"}, {"label": "Scheme processing", "note": "Scheme processing does not always happen at the same moment"}, {"label": "Settlement finality", "note": "Settlement finality does not always happen at the same moment"}, {"label": "Looks instant, still pending", "note": "Payment can look instant while interbank settlement is still pending"}]}}, "level": "foundation", "source_ref": "JEB-16"}, {"id": "INS-168", "seq": 21, "module": "Foundations", "source": "Jebaraj D", "title": "G20 cross-border payment objectives", "explain": "The G20 set targets for cross-border payments covering speed, cost, transparency, and access, so that sending money across borders becomes cheaper, faster, and easier to track. These are goals for the industry, not guarantees for a single payment, and each target needs concrete product and operational measures to be met. A business analyst uses the objectives to judge whether a corridor design is actually improving the customer outcome.", "takeaway": "A business analyst uses the objectives to judge whether a corridor design is actually improving the customer outcome.", "visual": {"type": "diagram", "diagram": {"centre": "G20 cross-border payment objectives", "parts": [{"label": "Speed", "note": "Sending money across borders faster"}, {"label": "Cost", "note": "Sending money across borders cheaper"}, {"label": "Transparency", "note": "Sending money easier to track"}, {"label": "Access", "note": "Cross-border payments easier to reach"}]}}, "level": "foundation", "source_ref": "JEB-25"}, {"id": "INS-120", "seq": 22, "module": "Foundations", "source": "Jebaraj D", "title": "Explain payment rules without jargon", "explain": "Payment scheme rules are written in technical language, but developers and business users need them as a clear trigger, decision, rule, timeline, and system behaviour. Translating a rule into what happens, when, and what the system must do is what makes it buildable. Jargon in a requirement leads to a system that does the wrong thing confidently.", "takeaway": "Jargon in a requirement leads to a system that does the wrong thing confidently.", "visual": {"type": "diagram", "diagram": {"centre": "Payment rules without jargon", "parts": [{"label": "Trigger", "note": "Clear trigger states what starts the rule"}, {"label": "Decision", "note": "Clear decision states what is decided"}, {"label": "Rule", "note": "Clear rule states what must happen"}, {"label": "Timeline", "note": "Clear timeline states when it happens"}, {"label": "System behaviour", "note": "Clear system behaviour states what the system must do"}, {"label": "Jargon risk", "note": "Jargon in a requirement leads to a system doing the wrong thing confidently"}]}}, "level": "foundation", "source_ref": "JEB-03"}, {"id": "JEB-A11", "seq": 23, "module": "Foundations", "source": "Jebaraj D", "title": "camt.052, camt.053 and camt.054: three views of the same account", "explain": "Liquidity is about knowing when funds are available, not only how much is available, and the camt.052, camt.053 and camt.054 messages give different views of the same account. The camt.052 account report shows the intraday position, what has happened so far today; the camt.053 statement shows the end-of-day position; and the camt.054 notification reports individual debits and credits as they occur. With a EUR 9 million opening balance, EUR 4 million coming in and a EUR 6 million payment to make, the intraday view shows EUR 7 million only if the incoming payment arrives in time. Relying on the camt.053 alone shows only the end of the day and misses the intraday picture.", "takeaway": "Relying on the camt.053 alone shows only the end of the day and misses the intraday picture.", "visual": {"type": "diagram", "diagram": {"centre": "Three views of one account", "parts": [{"label": "camt.052 intraday report", "note": "Shows the intraday position, what has happened so far today"}, {"label": "camt.053 end-of-day statement", "note": "Shows the end-of-day position after the close of business"}, {"label": "camt.054 notification", "note": "Reports individual debits and credits as they occur"}, {"label": "EUR 9 million opening balance", "note": "Opening balance with EUR 4 million coming in and EUR 6 million to pay"}, {"label": "EUR 7 million intraday", "note": "Intraday view shows EUR 7 million only if the incoming payment arrives in time"}]}}, "level": "foundation", "source_ref": "https://www.linkedin.com/posts/jebaraj-d-65b5b01a_businessanalysis-iso20022-payments-share-7518499820861460480-hZPU/"}, {"id": "JEB-A13", "seq": 24, "module": "Foundations", "source": "Jebaraj D", "title": "pain.001 promises ten payments, but three are on-us", "explain": "A pain.001 file promises a batch of payments, but not every payment in the file becomes a pacs.008. When a corporate submits 10 payments and only 7 pacs.008 messages reach the next bank, the other 3 are on-us payments, where sender and beneficiary hold accounts with the same bank and the payment is handled internally. Counting only the pacs.008 messages shows 7 payments and suggests 3 are missing, while comparing the file total with the message count reveals the 3 on-us payments and explains the gap. A pain.001 is a promise that payments will be made, not a guarantee of a pacs.008 for each one.", "takeaway": "A pain.001 is a promise that payments will be made, not a guarantee of a pacs.008 for each one.", "visual": {"type": "diagram", "diagram": {"centre": "pain.001 promises ten payments", "parts": [{"label": "10 payments submitted", "note": "Corporate submits 10 payments in the pain.001 file"}, {"label": "7 pacs.008 messages", "note": "Only 7 pacs.008 messages reach the next bank"}, {"label": "3 on-us payments", "note": "Sender and beneficiary hold accounts with the same bank, handled internally"}, {"label": "Comparing file and message counts", "note": "Comparing the file total with the message count explains the gap"}, {"label": "Promise, not guarantee", "note": "A pain.001 promises payments, not a pacs.008 for each one"}]}}, "level": "foundation", "source_ref": "https://www.linkedin.com/posts/jebaraj-d-65b5b01a_payments-iso20022-pain001-ugcPost-7517050961157165056-Ffv3/"}, {"id": "JEB-B01", "seq": 25, "module": "Foundations", "source": "Jebaraj D", "title": "Payment confirmation: trust the reply, not the debit", "explain": "When you pay on PhonePe, the app shows Payment Successful only after the beneficiary bank confirms the credit and UPI passes that reply back. In UPI the reply is called RespPay, and it carries the result, credited or failed. Schemes that use ISO 20022 have the same step under a different name, pacs.002, the Payment Status Report. A payment is confirmed only when the receiving side sends back a status, so trust the confirmation, not the debit.", "takeaway": "A payment is confirmed only when the receiving side sends back a status, so trust the confirmation, not the debit.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Payment sent", "note": "The payer sends the payment and the debit is made"}, {"kind": "step", "title": "Beneficiary bank confirms credit", "note": "App shows success only after the beneficiary bank confirms the credit"}, {"kind": "step", "title": "RespPay carries the result", "note": "In UPI the reply is called RespPay and carries credited or failed"}, {"kind": "step", "title": "pacs.002 in ISO 20022", "note": "Schemes using ISO 20022 have the same step, the pacs.002 status report"}, {"kind": "step", "title": "Trust the confirmation", "note": "A payment is confirmed only when the receiving side sends back a status"}]}}, "level": "foundation", "source_ref": "https://www.linkedin.com/posts/jebaraj-d-65b5b01a_upi-iso20022-payments-ugcPost-7515266332385501185-st2S/"}, {"id": "JEB-B11", "seq": 26, "module": "Foundations", "source": "Jebaraj D", "title": "Open Finance consent: know what you are agreeing to", "explain": "When you apply for a loan and see 'provide consent to access your financial information', the consent is not simply a yes to everything. Before clicking, check who is asking for your data, what data they want, why they need it, how often they will access it, and how long the consent is valid, because two services can need very different data for different purposes. Under India's Account Aggregator ecosystem, consent can be revoked, and revoking it can stop further access to your data. Good consent is a clear purpose, a clear duration and a clear way to withdraw, in words anyone can understand.", "takeaway": "Good consent is a clear purpose, a clear duration and a clear way to withdraw, in words anyone can understand.", "visual": {"type": "diagram", "diagram": {"centre": "Know what you are agreeing to", "parts": [{"label": "Who is asking for your data?", "note": "Check who is asking for your data before clicking consent"}, {"label": "What data and why?", "note": "Check what data they want and why they need it"}, {"label": "How often and how long?", "note": "Check how often they will access it and how long the consent is valid"}, {"label": "Consent can be revoked", "note": "Under the Account Aggregator ecosystem, consent can be revoked"}, {"label": "Revoking stops further access", "note": "Revoking consent can stop further access to your data"}, {"label": "Clear purpose, duration, withdrawal", "note": "Good consent states a clear purpose, duration and way to withdraw"}]}}, "level": "foundation", "source_ref": "https://www.linkedin.com/posts/deebak-t-safe%C2%AE-popm-%C2%AE-00582852_openfinance-accountaggregator-dataconsent-ugcPost-7510165588435042304-gj8e/"}, {"id": "JEB-B14", "seq": 27, "module": "Foundations", "source": "Jebaraj D", "title": "Open Finance: the information moves, the account stays", "explain": "A salary account with one bank does not stop another bank from offering a competitive loan, because the financial relationship no longer has to sit with a single institution. One customer can hold an account with ICICI, a loan with SBI, insights with CRED and payments with Google Pay, while the salary account stays where it is. What moves between providers is the financial information, and it moves only with the customer's consent. That changes the competitive question from how to become your bank to how to become the provider you choose for your next financial need.", "takeaway": "That changes the competitive question from how to become your bank to how to become the provider you choose for your next financial need.", "visual": {"type": "diagram", "diagram": {"centre": "The information moves, the account stays", "parts": [{"label": "Account with ICICI", "note": "One customer can hold an account with ICICI"}, {"label": "Loan with SBI", "note": "The same customer can hold a loan with SBI"}, {"label": "Insights with CRED", "note": "Insights can sit with CRED while payments sit with Google Pay"}, {"label": "Salary account stays put", "note": "The salary account stays where it is"}, {"label": "Information moves only with consent", "note": "Financial information moves between providers only with consent"}, {"label": "Become the chosen provider", "note": "The question becomes how to be the provider chosen for the next need"}]}}, "level": "foundation", "source_ref": "https://www.linkedin.com/posts/deebak-t-safe%C2%AE-popm-%C2%AE-00582852_openbanking-openfinance-digitalbanking-share-7508750246189973504-Mw_8/"}, {"id": "JEB-C01", "seq": 28, "module": "Foundations", "source": "Jebaraj D", "title": "Verification of Payee says No Match: the payment does not always stop", "explain": "Verification of Payee checks whether the name the payer gave matches the name the payee bank holds for the account, to cut authorised push payment fraud and misdirected payments. A No Match result does not stop the payment automatically; depending on the bank's process, the payer can review and correct the details or continue, knowing the payment may go to the wrong payee. A No Match says only that the name does not match, not whether it is fraud or a simple error, so it needs attention but not automatic rejection. When documenting VoP requirements, the BA must capture these rules rather than assume a No Match means stop.", "takeaway": "When documenting VoP requirements, the BA must capture these rules rather than assume a No Match means stop.", "visual": {"type": "diagram", "diagram": {"centre": "No Match does not always stop payment", "parts": [{"label": "Name match check", "note": "VoP checks whether the payer name matches the name the payee bank holds"}, {"label": "Cuts fraud and misdirection", "note": "The check cuts authorised push payment fraud and misdirected payments"}, {"label": "Review and correct, or continue", "note": "The payer can review and correct the details or continue with the payment"}, {"label": "No Match is not proof of fraud", "note": "No Match says only the name does not match, not whether it is fraud or an error"}, {"label": "Attention, not automatic rejection", "note": "A No Match needs attention but not automatic rejection"}, {"label": "Capture the rules", "note": "Document the rules rather than assuming a No Match means stop"}]}}, "level": "foundation", "source_ref": "https://www.linkedin.com/posts/jebaraj-d-65b5b01a_verificationofpayee-vop-payments-share-7507273922971594752-ryJX/"}, {"id": "JEB-C07", "seq": 29, "module": "Foundations", "source": "Jebaraj D", "title": "Ask the right questions: the BA as stakeholder translator", "explain": "A payments BA works with many stakeholders at once, from compliance and business teams to developers and vendors, across several projects and dependent systems. The work starts by asking whether each stakeholder understands the payment concepts, the sequence of payments, the business and its rules, and the payment journey, and whether the BA understands the system, the processing and where they fit in the flow. When a stakeholder does not know an answer, the BA helps them understand the question and reach it, because that translation is what makes the requirements workable. Asking the right questions is the core of stakeholder management, not a soft skill on the side.", "takeaway": "Asking the right questions is the core of stakeholder management, not a soft skill on the side.", "visual": {"type": "diagram", "diagram": {"centre": "The BA as stakeholder translator", "parts": [{"label": "Many stakeholders at once", "note": "Compliance and business teams, developers and vendors, across several projects"}, {"label": "Do they understand the concepts?", "note": "Ask whether each stakeholder understands the payment concepts and sequence"}, {"label": "Do they understand the journey?", "note": "Ask whether they understand the business, its rules and the payment journey"}, {"label": "Does the BA understand the system?", "note": "The BA must understand the system, the processing and where they fit in the flow"}, {"label": "Help them reach the answer", "note": "When a stakeholder does not know, help them understand the question and reach it"}, {"label": "Asking the right questions", "note": "Asking the right questions is the core of stakeholder management"}]}}, "level": "foundation", "source_ref": "https://www.linkedin.com/posts/jebaraj-d-65b5b01a_paymentba-businessanalysis-payments-share-7495759584918372353-X3e4/"}, {"id": "JEB-C11", "seq": 30, "module": "Foundations", "source": "Jebaraj D", "title": "Account aggregator: your money stays with your bank", "explain": "An account aggregator is not a bank and does not hold your money; it connects you to the financial institutions that do, giving you one dashboard across banks, mutual funds, insurers and NBFCs. Its three roles are pulling the data together, managing the customer's consent before any access, and sharing the information with other financial institutions only with that consent. Apps like Paytm, PhonePe and Google Pay work the same way: they fetch and move money through your banks without holding it themselves. The single most important role of the aggregator is consent management, because it never holds the funds it connects you to.", "takeaway": "The single most important role of the aggregator is consent management, because it never holds the funds it connects you to.", "visual": {"type": "diagram", "diagram": {"centre": "Your money stays with your bank", "parts": [{"label": "Not a bank, holds no money", "note": "An account aggregator is not a bank and does not hold your money"}, {"label": "One dashboard across providers", "note": "One dashboard across banks, mutual funds, insurers and NBFCs"}, {"label": "Pulling the data together", "note": "One of its three roles is pulling the data together"}, {"label": "Managing customer consent", "note": "It manages the customer consent before any access"}, {"label": "Sharing only with consent", "note": "It shares information with other institutions only with that consent"}, {"label": "Consent is the most important role", "note": "Consent management matters most because it never holds the funds"}]}}, "level": "foundation", "source_ref": "https://www.linkedin.com/posts/deebak-t-safe%C2%AE-popm-%C2%AE-00582852_openbanking-openfinance-accountaggregator-share-7508020905416163328-KfSR/"}, {"id": "JEB-C13", "seq": 31, "module": "Foundations", "source": "Jebaraj D", "title": "Three accounts, one place: what Open Banking makes possible", "explain": "Open Banking uses APIs and the Account Information Service to let one app show accounts held at several banks, so a customer can see three accounts in one place without switching apps. An account aggregator combines those accounts into a single dashboard, and the aggregated data can also support payments and loan eligibility decisions. The test is whether the app reaches the banking information through open APIs; if it locks the data in instead, that is monetisation of a latch-on mechanism, not Open Banking. A customer should not have to open a new bank account just to view other accounts.", "takeaway": "A customer should not have to open a new bank account just to view other accounts.", "visual": {"type": "diagram", "diagram": {"centre": "Three accounts, one place", "parts": [{"label": "APIs and Account Information Service", "note": "Open Banking uses APIs and the Account Information Service"}, {"label": "Three accounts in one place", "note": "A customer can see three accounts in one place without switching apps"}, {"label": "Aggregator combines the accounts", "note": "An account aggregator combines those accounts into a single dashboard"}, {"label": "Data supports payments and loans", "note": "Aggregated data can support payments and loan eligibility decisions"}, {"label": "Open APIs, not locked-in data", "note": "If the app locks the data in, that is monetisation, not Open Banking"}, {"label": "No new account needed to view", "note": "A customer should not have to open a new bank account just to view accounts"}]}}, "level": "foundation", "source_ref": "https://www.linkedin.com/posts/deebak-t-safe%C2%AE-popm-%C2%AE-00582852_episode-2-three-accounts-one-place-what-share-7505824467332308992-g0y3/"}, {"id": "JEB-C15", "seq": 32, "module": "Foundations", "source": "Jebaraj D", "title": "Open Banking is accounts; Open Finance is the whole financial life", "explain": "Open Banking lets one app show a customer's bank accounts, track expenses, pay bills or apply for a loan, but it covers only bank accounts. Open Finance goes further, letting insurers, mutual fund companies and banks share information about investments, insurance, pensions and mortgages through APIs, always with the customer's consent. Fintech apps like Paytm and PhonePe are not banks; they connect to banks to share account information, and Open Finance extends that same consented sharing beyond banking. The difference is scope: Open Banking is banking data, Open Finance is the customer's whole financial life.", "takeaway": "The difference is scope: Open Banking is banking data, Open Finance is the customer's whole financial life.", "visual": {"type": "diagram", "diagram": {"centre": "Open Finance is the whole financial life", "parts": [{"label": "Open Banking: bank accounts only", "note": "Open Banking covers only bank accounts"}, {"label": "Track expenses, pay bills, apply for loans", "note": "One app can show accounts, track expenses, pay bills or apply for a loan"}, {"label": "Open Finance goes further", "note": "Insurers, mutual funds and banks share information through APIs"}, {"label": "Investments, insurance, pensions, mortgages", "note": "Open Finance covers investments, insurance, pensions and mortgages"}, {"label": "Always with customer consent", "note": "Sharing always happens with the customer consent"}, {"label": "Fintech apps are not banks", "note": "Apps like Paytm and PhonePe connect to banks, they do not hold the money"}]}}, "level": "foundation", "source_ref": "https://www.linkedin.com/posts/deebak-t-safe%C2%AE-popm-%C2%AE-00582852_openbanking-openfinance-digitalbanking-share-7505101145049124864-MLlZ/"}, {"id": "INS-082", "seq": 33, "module": "Foundations", "source": "Harish Kavire", "title": "BA responsibilities across the software delivery lifecycle", "explain": "The business analyst works across the whole delivery lifecycle, from discovery through deployment and post-release validation. In discovery the analyst learns the business problem and the users, in analysis and design the analyst turns that understanding into requirements, and in build and test the analyst supports the team and checks the increment against what was agreed. After release the analyst validates that the change delivered the intended outcome and reports what is still open.", "takeaway": "After release the analyst validates that the change delivered the intended outcome and reports what is still open.", "visual": {"type": "diagram", "diagram": {"centre": "BA across the delivery lifecycle", "parts": [{"label": "Discovery", "note": "Learns the business problem and the users."}, {"label": "Analysis and design", "note": "Turns understanding into requirements."}, {"label": "Build and test", "note": "Supports the team and checks the increment."}, {"label": "Post-release validation", "note": "Validates the outcome and reports what is open."}]}}, "level": "foundation", "source_ref": "HAR-16"}, {"id": "INS-013", "seq": 34, "module": "Foundations", "source": "Harish Kavire", "title": "The BA role in Agile Scrum", "explain": "In a Scrum team the business analyst contributes at every stage of the sprint. During refinement the analyst clarifies stories and acceptance criteria, during planning the analyst helps the team understand scope and priorities, during delivery the analyst answers questions and refines detail as it emerges, and during review and acceptance the analyst verifies the built increment against the agreed criteria.", "takeaway": "During refinement the analyst clarifies stories and acceptance criteria, during planning the analyst helps the team understand scope and priorities, during delivery the analyst answers questions and refines detail as it emerges, and during review and acceptance the analyst verifies the built increment against the agreed criteria.", "visual": {"type": "diagram", "diagram": {"centre": "BA contribution in a Scrum sprint", "parts": [{"label": "Refinement", "note": "Clarifies stories and acceptance criteria."}, {"label": "Planning", "note": "Helps the team understand scope and priorities."}, {"label": "Delivery", "note": "Answers questions and refines detail as it emerges."}, {"label": "Review and acceptance", "note": "Verifies the increment against agreed criteria."}]}}, "level": "foundation", "source_ref": "HAR-02"}, {"id": "INS-080", "seq": 35, "module": "Foundations", "source": "Harish Kavire", "title": "Functional versus non-functional requirements", "explain": "Functional requirements describe what a system must do, such as validating a payment or posting a ledger entry. Non-functional requirements describe how well it must do it, covering performance, security, availability, usability and supportability. Both kinds must be stated explicitly, because a payment that works correctly but is too slow or unavailable still fails the customer.", "takeaway": "Both kinds must be stated explicitly, because a payment that works correctly but is too slow or unavailable still fails the customer.", "visual": {"type": "diagram", "diagram": {"centre": "Functional and non-functional needs", "parts": [{"label": "Functional requirements", "note": "Describe what the system must do, such as validating a payment."}, {"label": "Non-functional requirements", "note": "Describe how well: performance, security, availability, usability."}, {"label": "Why both matter", "note": "A correct but slow or unavailable payment still fails the customer."}]}}, "level": "foundation", "source_ref": "HAR-16"}, {"id": "INS-016", "seq": 36, "module": "Foundations", "source": "Harish Kavire", "title": "User story versus use case", "explain": "A user story is outcome oriented and describes what a user wants to achieve and why, which makes it good for prioritisation and conversation. A use case is interaction oriented and describes the steps, actors and outcomes of a specific interaction, which makes it good when the flow, the decisions and the exception paths need to be pinned down. Choose the form that fits the need being addressed, not the form the team happens to prefer.", "takeaway": "Choose the form that fits the need being addressed, not the form the team happens to prefer.", "visual": {"type": "diagram", "diagram": {"centre": "User story versus use case", "parts": [{"label": "User story", "note": "Outcome oriented: what a user wants to achieve and why."}, {"label": "Use case", "note": "Interaction oriented: steps, actors and outcomes of one interaction."}, {"label": "Choosing the form", "note": "Fit the need being addressed, not the form the team prefers."}]}}, "level": "foundation", "source_ref": "HAR-02"}, {"id": "INS-014", "seq": 37, "module": "Foundations", "source": "Harish Kavire", "title": "BRD, FRD and use-case selection", "explain": "A business requirements document states what the business needs and why, a functional requirements document states what the system must do in detail, and a use case describes a specific interaction between actors and the system. Choose the artefact based on the audience, the complexity of the change, the traceability required and the delivery context, so that each reader gets the detail they need and nothing they do not.", "takeaway": "Choose the artefact based on the audience, the complexity of the change, the traceability required and the delivery context, so that each reader gets the detail they need and nothing they do not.", "visual": {"type": "diagram", "diagram": {"centre": "Choosing the requirements artefact", "parts": [{"label": "Business requirements document", "note": "States what the business needs and why."}, {"label": "Functional requirements document", "note": "States what the system must do in detail."}, {"label": "Use case", "note": "Describes a specific interaction between actors and the system."}, {"label": "Selection factors", "note": "Audience, complexity, traceability required and delivery context."}]}}, "level": "foundation", "source_ref": "HAR-02"}, {"id": "INS-026", "seq": 38, "module": "Foundations", "source": "Harish Kavire", "title": "Post-deployment stakeholder reporting", "explain": "After a release, stakeholders need a clear report on adoption, incidents, defects, service levels, benefits realised and open risks. Adoption shows whether people are using the change, incidents and defects show what is still broken, service levels show whether the change is performing, and benefits and open risks show whether the intended outcome is on track. The report should be factual and regular, so stakeholders can decide what needs attention next.", "takeaway": "The report should be factual and regular, so stakeholders can decide what needs attention next.", "visual": {"type": "diagram", "diagram": {"centre": "Post-deployment stakeholder reporting", "parts": [{"label": "Adoption", "note": "Whether people are using the change"}, {"label": "Incidents", "note": "Shows what is still broken"}, {"label": "Defects", "note": "Shows what is still broken"}, {"label": "Service levels", "note": "Whether the change is performing"}, {"label": "Benefits realised", "note": "Whether the intended outcome is on track"}, {"label": "Open risks", "note": "What still needs attention next"}]}}, "level": "foundation", "source_ref": "HAR-02"}, {"id": "INS-076", "seq": 39, "module": "Foundations", "source": "Harish Kavire", "title": "Translate business value for stakeholders", "explain": "Stakeholders decide on outcomes, not on technical detail. When presenting a change, state the outcome it delivers, the customer impact, the revenue or cost effect, the compliance position, the timing and the decisions needed. Keep the language plain and tie every point to something the stakeholder is accountable for, so the discussion stays on value rather than on features.", "takeaway": "Keep the language plain and tie every point to something the stakeholder is accountable for, so the discussion stays on value rather than on features.", "visual": {"type": "diagram", "diagram": {"centre": "Presenting change by business value", "parts": [{"label": "Outcome delivered", "note": "State the outcome the change delivers."}, {"label": "Customer impact", "note": "State how customers are affected."}, {"label": "Revenue or cost effect", "note": "State the money effect of the change."}, {"label": "Compliance position", "note": "State where the change leaves compliance."}, {"label": "Timing and decisions needed", "note": "State timing and the decisions stakeholders must make."}]}}, "level": "foundation", "source_ref": "HAR-15"}, {"id": "INS-079", "seq": 40, "module": "Foundations", "source": "Harish Kavire", "title": "Translate incident and recovery status for support", "explain": "When an incident happens, support teams need a status they can repeat to customers without guessing. Provide the symptom in plain language, the users affected, a workaround if one exists, the owner, the severity and the time of the next update. Update at the promised time even if the news is that nothing has changed, because silence makes customers assume the worst.", "takeaway": "Update at the promised time even if the news is that nothing has changed, because silence makes customers assume the worst.", "visual": {"type": "diagram", "diagram": {"centre": "Incident status support can repeat", "parts": [{"label": "Symptom in plain language", "note": "A status support teams can repeat without guessing."}, {"label": "Users affected", "note": "Names who the incident touches."}, {"label": "Workaround", "note": "Given if one exists."}, {"label": "Owner and severity", "note": "Names who owns the incident and how severe it is."}, {"label": "Time of the next update", "note": "Update at the promised time even if nothing has changed."}]}}, "level": "foundation", "source_ref": "HAR-15"}, {"id": "INS-095", "seq": 41, "module": "Foundations", "source": "Harish Kavire", "title": "Managing written communication and sign-offs", "explain": "Written communication creates the record that protects a delivery. Use meeting notes that name the action, the owner and the due date, record decisions and the assumptions behind them, and obtain explicit approval rather than assuming silence means agreement. A sign-off is only useful if it states exactly what was approved and by whom, so there is no later dispute about scope.", "takeaway": "A sign-off is only useful if it states exactly what was approved and by whom, so there is no later dispute about scope.", "visual": {"type": "diagram", "diagram": {"centre": "Written record that protects delivery", "parts": [{"label": "Meeting notes", "note": "Name the action, the owner and the due date."}, {"label": "Decisions and assumptions", "note": "Recorded with the assumptions behind them."}, {"label": "Explicit approval", "note": "Obtained rather than assuming silence means agreement."}, {"label": "Sign-off content", "note": "States exactly what was approved and by whom."}]}}, "level": "foundation", "source_ref": "HAR-15"}, {"id": "INS-070", "seq": 42, "module": "Foundations", "source": "Harish Kavire", "title": "Difference between a payment gateway and a payment processor", "explain": "A payment gateway orchestrates the payment: it connects the merchant to the payment methods, routes the instruction, and returns the outcome. A payment processor performs the transaction processing: it moves the instruction through authorisation, clearing and settlement with the scheme and the banks. Some providers do both, so always check which role a provider actually performs before assuming what it is responsible for.", "takeaway": "Some providers do both, so always check which role a provider actually performs before assuming what it is responsible for.", "visual": {"type": "diagram", "diagram": {"centre": "Payment gateway versus payment processor", "parts": [{"label": "Payment gateway", "note": "Connects the merchant, routes the instruction, returns the outcome"}, {"label": "Payment processor", "note": "Moves the instruction through authorisation, clearing and settlement"}, {"label": "Both roles", "note": "Some providers do both, check which role a provider performs"}]}}, "level": "foundation", "source_ref": "HAR-13"}, {"id": "INS-086", "seq": 43, "module": "Foundations", "source": "Harish Kavire", "title": "Common payment failure reasons", "explain": "Payment failures fall into a small set of causes that an analyst should be able to classify. Issuer declines happen when the issuer refuses authorisation, validation failures happen when the instruction is incomplete or wrong, limit failures happen when an amount or frequency limit is exceeded, timeout failures happen when a response does not arrive in time, connectivity failures happen when a link drops, risk failures happen when a fraud or sanctions screen blocks the payment, and downstream processing failures happen after the payment has been accepted. Classifying the failure correctly decides who must act and what the customer should be told.", "takeaway": "Classifying the failure correctly decides who must act and what the customer should be told.", "visual": {"type": "diagram", "diagram": {"centre": "Classifying payment failures", "parts": [{"label": "Issuer declines", "note": "The issuer refuses authorisation."}, {"label": "Validation failures", "note": "The instruction is incomplete or wrong."}, {"label": "Limit failures", "note": "An amount or frequency limit is exceeded."}, {"label": "Timeout failures", "note": "A response does not arrive in time."}, {"label": "Connectivity failures", "note": "A link drops during the payment."}, {"label": "Risk failures", "note": "A fraud or sanctions screen blocks the payment."}, {"label": "Downstream processing failures", "note": "The failure happens after the payment was accepted."}]}}, "level": "foundation", "source_ref": "HAR-13"}, {"id": "INS-083", "seq": 44, "module": "Foundations", "source": "Harish Kavire", "title": "Translate prior domain experience into BA value", "explain": "Moving into business analysis from another domain works when transferable skills are mapped to the work a BA actually does. Experience in operations, support or product maps to domain knowledge, elicitation, documentation, delivery support and outcome measurement. State the mapping explicitly, with concrete examples of work done, rather than listing a previous job title and hoping the reader makes the connection.", "takeaway": "State the mapping explicitly, with concrete examples of work done, rather than listing a previous job title and hoping the reader makes the connection.", "visual": {"type": "diagram", "diagram": {"centre": "Transferable skills into BA value", "parts": [{"label": "Domain knowledge", "note": "Operations, support or product experience maps to it."}, {"label": "Elicitation", "note": "Prior experience maps to drawing out needs."}, {"label": "Documentation", "note": "Prior experience maps to recording requirements."}, {"label": "Delivery support", "note": "Prior experience maps to supporting the build."}, {"label": "Outcome measurement", "note": "Prior experience maps to measuring results."}]}}, "level": "foundation", "source_ref": "HAR-18"}, {"id": "INS-096", "seq": 45, "module": "Foundations", "source": "Harish Kavire", "title": "Choose a target BA domain before learning tools", "explain": "Before learning tools, choose the domain to work in. Evaluate transferable experience, demand for the domain, genuine interest and a realistic entry path, because a BA is hired for domain understanding first and tool skill second. A focused domain choice makes learning faster and makes a profile credible to a recruiter in that domain.", "takeaway": "A focused domain choice makes learning faster and makes a profile credible to a recruiter in that domain.", "visual": {"type": "diagram", "diagram": {"centre": "Choose a BA domain before tools", "parts": [{"label": "Transferable experience", "note": "What can be carried into the domain."}, {"label": "Demand for the domain", "note": "Whether the domain is hiring."}, {"label": "Genuine interest", "note": "Whether the domain truly interests the person."}, {"label": "Realistic entry path", "note": "Whether there is a credible way in."}, {"label": "Why domain first", "note": "A BA is hired for domain understanding before tool skill."}]}}, "level": "foundation", "source_ref": "HAR-18"}, {"id": "INS-098", "seq": 46, "module": "Foundations", "source": "Harish Kavire", "title": "Optimise recruiter search visibility", "explain": "Recruiters search by keywords that match the role they are filling. Align profile keywords with the target role, the domain, the skills and the verifiable experience, so that a search for that role surfaces the profile. Only claim what can be evidenced, because a keyword that cannot be backed up damages credibility in the first conversation.", "takeaway": "Only claim what can be evidenced, because a keyword that cannot be backed up damages credibility in the first conversation.", "visual": {"type": "diagram", "diagram": {"centre": "Recruiter search visibility", "parts": [{"label": "Target role keywords", "note": "Aligned with the role being sought."}, {"label": "Domain keywords", "note": "Aligned with the target domain."}, {"label": "Skills keywords", "note": "Aligned with the skills held."}, {"label": "Verifiable experience", "note": "Only claim what can be evidenced."}]}}, "level": "foundation", "source_ref": "HAR-19"}, {"id": "INS-085", "seq": 47, "module": "Foundations", "source": "Harish Kavire", "title": "Respond when you do not know a technical answer", "explain": "In an interview, not knowing a response is acceptable if it is handled honestly. State the assumptions being made, explain the reasoning that follows from them, identify what would need to be validated before committing to a response, and avoid bluffing. Interviewers are testing judgement and honesty as much as knowledge, and a confident guess that turns out wrong is worse than a clear statement of what is known and what is not.", "takeaway": "Interviewers are testing judgement and honesty as much as knowledge, and a confident guess that turns out wrong is worse than a clear statement of what is known and what is not.", "visual": {"type": "diagram", "diagram": {"centre": "Handling an unknown answer honestly", "parts": [{"label": "State assumptions", "note": "Say what is being assumed."}, {"label": "Explain reasoning", "note": "Show the reasoning that follows from the assumptions."}, {"label": "Identify what needs validation", "note": "Name what must be checked before committing."}, {"label": "Avoid bluffing", "note": "A confident wrong guess is worse than a clear statement."}]}}, "level": "foundation", "source_ref": "HAR-20"}, {"id": "INS-099", "seq": 48, "module": "Foundations", "source": "Harish Kavire", "title": "Explain an unfamiliar scenario logically", "explain": "When faced with an unfamiliar scenario, work through it in a fixed order. Clarify the assumptions, break the flow down into its stages, identify the risks at each stage, and state what evidence would be obtained before deciding. This structure shows clear thinking even when the specific domain is new, and it prevents the response from becoming a guess.", "takeaway": "This structure shows clear thinking even when the specific domain is new, and it prevents the response from becoming a guess.", "visual": {"type": "diagram", "diagram": {"centre": "Working through an unfamiliar scenario", "parts": [{"label": "Clarify assumptions", "note": "Start by stating the assumptions."}, {"label": "Break the flow into stages", "note": "Work through the flow stage by stage."}, {"label": "Identify risks at each stage", "note": "Name the risk at every stage."}, {"label": "State evidence needed", "note": "Say what evidence would be obtained before deciding."}]}}, "level": "foundation", "source_ref": "HAR-20"}, {"id": "PAI-C001", "seq": 49, "module": "Foundations", "source": "Paiementor", "title": "Serial and cover payments: how the funds and the information travel", "explain": "In a serial payment the funds and the payment information travel together in a single chain, from the originator bank through each intermediary to the beneficiary bank. In a cover payment the information travels in an MT103 while the funds travel separately in an MT202 COV, so the two legs are settled independently. Knowing which method a payment uses decides how it is tracked, how charges are applied, and how a return is handled.", "takeaway": "Knowing which method a payment uses decides how it is tracked, how charges are applied, and how a return is handled.", "visual": {"type": "diagram", "diagram": {"centre": "Serial and cover payments", "parts": [{"label": "Serial payment", "note": "Funds and information travel together in one chain"}, {"label": "Cover payment", "note": "Information in MT103, funds separately in MT202 COV"}, {"label": "Why the method matters", "note": "It decides tracking, charges and how a return is handled"}]}}, "level": "foundation", "source_ref": "https://www.paiementor.com/swift-serial-and-cover-payments/"}, {"id": "PAI-C002", "seq": 50, "module": "Foundations", "source": "Paiementor", "title": "MT202 COV versus a plain MT202", "explain": "An MT202 COV is a cover payment: it moves the funds that settle an MT103 customer payment, and it carries the reference that links it to that MT103. A plain MT202 is a bank-to-bank transfer with no customer payment behind it, used when one bank simply moves its own funds to another. Confusing the two is a common error, because both move money between banks but only the COV is tied to a customer instruction.", "takeaway": "Confusing the two is a common error, because both move money between banks but only the COV is tied to a customer instruction.", "visual": {"type": "diagram", "diagram": {"centre": "MT202 COV versus a plain MT202", "parts": [{"label": "MT202 COV", "note": "Moves funds settling an MT103, carries the linking reference"}, {"label": "Plain MT202", "note": "Bank-to-bank transfer, no customer payment behind it"}, {"label": "Common error", "note": "Confusing the two, only the COV is tied to a customer instruction"}]}}, "level": "foundation", "source_ref": "https://www.paiementor.com/swift-mt103-202-cover-payment-analysis-part-1/"}, {"id": "PAI-C003", "seq": 51, "module": "Foundations", "source": "Paiementor", "title": "Why a bank chooses the cover method", "explain": "A bank uses the cover method when it wants the payment information and the funds to move on separate paths, which lets the customer payment reach the beneficiary bank quickly while the funds settle through correspondent accounts. The cover method also keeps the customer details out of the funds leg, which matters for privacy and for correspondent banking. The trade-off is that the two legs must be matched, and a mismatch in amount or reference creates an exception.", "takeaway": "The trade-off is that the two legs must be matched, and a mismatch in amount or reference creates an exception.", "visual": {"type": "diagram", "diagram": {"centre": "The cover method", "parts": [{"label": "Separate paths for information and funds", "note": "The customer payment reaches the beneficiary bank quickly while funds settle separately"}, {"label": "Customer details kept out of funds leg", "note": "Keeping customer details out of the funds leg matters for privacy"}, {"label": "Two legs must be matched", "note": "A mismatch in amount or reference creates an exception"}]}}, "level": "foundation", "source_ref": "https://www.paiementor.com/swift-mt103-202-cover-payment-analysis-part-1/"}, {"id": "PAI-C004", "seq": 52, "module": "Foundations", "source": "Paiementor", "title": "When MT103 is used and when MT202 is used", "explain": "An MT103 carries a customer payment instruction: it tells the receiving bank to pay a named beneficiary a named amount. An MT202 carries a bank-to-bank instruction: it tells the receiving bank to move funds between banks, with no customer beneficiary. A payment that starts with a customer always has an MT103, and it gains an MT202 only when a separate funds leg is needed.", "takeaway": "A payment that starts with a customer always has an MT103, and it gains an MT202 only when a separate funds leg is needed.", "visual": {"type": "diagram", "diagram": {"centre": "When MT103 is used and when MT202 is used", "parts": [{"label": "MT103", "note": "Customer payment instruction to pay a named beneficiary"}, {"label": "MT202", "note": "Bank-to-bank instruction to move funds between banks"}, {"label": "When both appear", "note": "A customer payment gains an MT202 only for a separate funds leg"}]}}, "level": "foundation", "source_ref": "https://www.paiementor.com/basic-swift-mt103-message-decrypted/"}, {"id": "PAI-C005", "seq": 53, "module": "Foundations", "source": "Paiementor", "title": "Reading an MT103: field 59 and field 57", "explain": "Field 59 of an MT103 carries the beneficiary customer and the account to be credited, so it is the first place to look when a payment must reach the right person. Field 57 carries the beneficiary bank, identified by its BIC, so it tells the chain which bank must receive the instruction. In a serial payment each bank reads these fields from the MT103 it receives and forwards the message to the next bank in the chain.", "takeaway": "In a serial payment each bank reads these fields from the MT103 it receives and forwards the message to the next bank in the chain.", "visual": {"type": "diagram", "diagram": {"centre": "Reading an MT103", "parts": [{"label": "Field 59: beneficiary customer", "note": "Carries the beneficiary customer and the account to be credited, the first place to look"}, {"label": "Field 57: beneficiary bank", "note": "Carries the beneficiary bank by BIC, telling the chain which bank receives it"}, {"label": "Each bank reads and forwards", "note": "In a serial payment each bank reads these fields and forwards the message to the next bank"}]}}, "level": "foundation", "source_ref": "https://www.paiementor.com/swift-mt103-serial-payment-analysis-1-3/"}, {"id": "PAI-C006", "seq": 54, "module": "Foundations", "source": "Paiementor", "title": "Field 50 and field 72 in an MT103", "explain": "Field 50 identifies the ordering customer, the party who instructed the payment, and it is the field that screening and reconciliation check first. Field 72 carries sender-to-receiver information, additional instructions that do not fit in the structured fields. The two fields serve different purposes: field 50 says who is paying, field 72 says what else the receiver needs to know.", "takeaway": "The two fields serve different purposes: field 50 says who is paying, field 72 says what else the receiver needs to know.", "visual": {"type": "diagram", "diagram": {"centre": "Fields 50 and 72 in an MT103", "parts": [{"label": "Field 50: ordering customer", "note": "Identifies the party who instructed the payment, checked first by screening"}, {"label": "Field 72: sender-to-receiver information", "note": "Carries additional instructions that do not fit in the structured fields"}, {"label": "Different purposes", "note": "Field 50 says who is paying, field 72 says what else the receiver needs to know"}]}}, "level": "foundation", "source_ref": "https://www.paiementor.com/swift-mt103-serial-payment-analysis-1-3/"}, {"id": "PAI-C007", "seq": 55, "module": "Foundations", "source": "Paiementor", "title": "SEPA Direct Debit Core versus B2B", "explain": "SEPA Direct Debit Core is the scheme for collecting from consumers and businesses, with a refund right that lets the debtor claim the money back within eight weeks without giving a reason. SEPA Direct Debit B2B is only for business-to-business collections, and it gives the debtor no such refund right, which is why the debtor bank must verify the mandate before the first collection. Choosing the wrong scheme is a real error, because the refund rules and the mandate checks are different.", "takeaway": "Choosing the wrong scheme is a real error, because the refund rules and the mandate checks are different.", "visual": {"type": "diagram", "diagram": {"centre": "SEPA Direct Debit Core versus B2B", "parts": [{"label": "SDD Core", "note": "For consumers and businesses, refund within eight weeks"}, {"label": "SDD B2B", "note": "Business to business only, no refund right"}, {"label": "Mandate check", "note": "Debtor bank must verify the mandate before the first collection"}]}}, "level": "foundation", "source_ref": "https://www.paiementor.com/differences-uk-faster-payments-sepa-swift-payments/"}, {"id": "PAI-C008", "seq": 56, "module": "Foundations", "source": "Paiementor", "title": "A SEPA payment is independent of its format", "explain": "A SEPA payment is defined by the scheme rules, not by the message format that carries it, so the same payment can be initiated with an MT101 or an MT103 as well as with a pain.001. The format is the envelope; the scheme is the set of rules about timing, reason codes, and returns. This is why an MT103 and a pacs.008 can carry the same underlying SEPA payment, with the pacs.008 as the ISO 20022 form of that payment.", "takeaway": "This is why an MT103 and a pacs.008 can carry the same underlying SEPA payment, with the pacs.008 as the ISO 20022 form of that payment.", "visual": {"type": "diagram", "diagram": {"centre": "A SEPA payment", "parts": [{"label": "Defined by scheme rules", "note": "The scheme rules cover timing, reason codes, and returns, not the message format"}, {"label": "Format is the envelope", "note": "The same payment can be initiated with an MT101 or an MT103 as well as a pain.001"}, {"label": "MT103 and pacs.008 carry the same payment", "note": "An MT103 and a pacs.008 can carry the same underlying SEPA payment"}]}}, "level": "foundation", "source_ref": "https://www.paiementor.com/differences-uk-faster-payments-sepa-swift-payments/"}, {"id": "PAI-C009", "seq": 57, "module": "Foundations", "source": "Paiementor", "title": "pacs.004 is the return and camt.056 is the recall request", "explain": "A pacs.004 returns a payment that has already been settled, sending the funds back along the chain to the originator. A camt.056 requests a recall, asking the beneficiary bank to return a payment that has already been credited. The two messages are often confused, but they do opposite jobs: the pacs.004 moves the money back, while the camt.056 asks for the money back.", "takeaway": "The two messages are often confused, but they do opposite jobs: the pacs.004 moves the money back, while the camt.056 asks for the money back.", "visual": {"type": "diagram", "diagram": {"centre": "pacs.004 is the return, camt.056 is the recall", "parts": [{"label": "pacs.004", "note": "Returns a settled payment, sends funds back along the chain"}, {"label": "camt.056", "note": "Requests a recall, asks the beneficiary bank to return credited funds"}, {"label": "Opposite jobs", "note": "pacs.004 moves the money back, camt.056 asks for it back"}]}}, "level": "foundation", "source_ref": "https://www.paiementor.com/messages-pacs-004-camt-056-and-camt-029/"}, {"id": "PAI-C010", "seq": 58, "module": "Foundations", "source": "Paiementor", "title": "Detecting a duplicate pacs.008", "explain": "A duplicate pacs.008 is detected through the unique identification carried in every payment in the pacs.008 file, so a file that contains the same transaction twice can be caught before it is processed. The check matters because a bulk file such as a pain.001 can carry the same instruction more than once, and paying it twice is a real loss. The identification is the control that stops a duplicate from becoming a second payment.", "takeaway": "The identification is the control that stops a duplicate from becoming a second payment.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "pacs.008 carries unique identification", "note": "Every payment in the pacs.008 file carries its own unique identification"}, {"kind": "decision", "title": "Check the file for a repeated identification", "note": "A file with the same transaction twice is caught before it is processed"}, {"kind": "step", "title": "Duplicate blocked before it is processed", "note": "The identification is the control that stops a duplicate becoming a second payment"}]}}, "level": "foundation", "source_ref": "https://www.paiementor.com/messages-in-the-interbank-space-pacs-008-and-pacs-002/"}, {"id": "PAI-C059", "seq": 59, "module": "Foundations", "source": "Paiementor", "title": "pacs.008, pacs.009 and pacs.004: the ISO 20022 equivalents of MT103 and MT202", "explain": "A pacs.008 is the ISO 20022 customer credit transfer, the equivalent of an MT103, and a pacs.009 is the financial institution credit transfer, the equivalent of an MT202. A pacs.004 is the payment return, used when a pacs.008 cannot be applied and the funds must go back. The two families describe the same payments, so a team moving from MT to MX only has to learn the new names for the same legs.", "takeaway": "The two families describe the same payments, so a team moving from MT to MX only has to learn the new names for the same legs.", "visual": {"type": "diagram", "diagram": {"centre": "pacs.008, pacs.009 and pacs.004", "parts": [{"label": "pacs.008", "note": "Customer credit transfer, the MT103 equivalent"}, {"label": "pacs.009", "note": "Financial institution transfer, the MT202 equivalent"}, {"label": "pacs.004", "note": "Payment return when a pacs.008 cannot be applied"}]}}, "level": "foundation", "source_ref": "https://www.paiementor.com/swift-mt103-202-cover-payment-analysis-part-3/"}, {"id": "PAI-C068", "seq": 60, "module": "Foundations", "source": "Paiementor", "title": "A corporate sends MT101, never MT103", "explain": "A corporation connected to SWIFT instructs its bank with an MT101, and it is the bank that sends the MT103, or the MT103 plus an MT202 COV, into the interbank chain. Even a corporate with its own BIC and a direct relationship with a clearer does not send an MT103 itself. The rule is simple: corporates instruct, banks pay.", "takeaway": "The rule is simple: corporates instruct, banks pay.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Corporate instructs its bank with MT101", "note": "A corporation connected to SWIFT instructs its bank with an MT101"}, {"kind": "step", "title": "Bank sends MT103 into the chain", "note": "The bank sends the MT103, or the MT103 plus an MT202 COV, into the interbank chain"}, {"kind": "step", "title": "Corporate with own BIC still instructs", "note": "Even a corporate with its own BIC and a clearer relationship does not send an MT103 itself"}, {"kind": "step", "title": "Corporates instruct, banks pay", "note": "The rule is simple: corporates instruct, banks pay"}]}}, "level": "foundation", "source_ref": "https://www.paiementor.com/swift-mt103-202-cover-payment-analysis-part-3/"}, {"id": "PAI-C077", "seq": 61, "module": "Foundations", "source": "Paiementor", "title": "Nostro and vostro: the same account seen from two sides", "explain": "When a bank holds an account with another bank in a foreign currency, it calls that account a nostro account, meaning our account with you. The bank that holds the account calls the very same account a vostro account, meaning your account with us. There is only one account, and the two words simply say which side of it each bank is standing on.", "takeaway": "There is only one account, and the two words simply say which side of it each bank is standing on.", "visual": {"type": "diagram", "diagram": {"centre": "Nostro and vostro: one account", "parts": [{"label": "Nostro: our account with you", "note": "A bank calls its foreign currency account with another bank a nostro account"}, {"label": "Vostro: your account with us", "note": "The bank that holds the account calls the same account a vostro account"}, {"label": "Only one account exists", "note": "There is only one account, and the two words say which side each bank stands on"}]}}, "level": "foundation", "source_ref": "https://www.paiementor.com/mt103-swift-message-with-optional-fields-52a-and-57a/"}, {"id": "PAI-C080", "seq": 62, "module": "Foundations", "source": "Paiementor", "title": "Block 2: input or output depends on which side of the network you sit", "explain": "Block 2 of a SWIFT message, the application header, says whether the message is entering or leaving the SWIFT network. The same payment looks different from the two sides: from the sending bank it is an input message, and from the receiving bank it is an output message. An operator reading a stored message must therefore know which bank's copy it is looking at before deciding what block 2 means.", "takeaway": "An operator reading a stored message must therefore know which bank's copy it is looking at before deciding what block 2 means.", "visual": {"type": "diagram", "diagram": {"centre": "Block 2: input or output", "parts": [{"label": "Application header of a SWIFT message", "note": "Block 2 of a SWIFT message is the application header"}, {"label": "Says whether the message enters or leaves", "note": "Block 2 says whether the message is entering or leaving the SWIFT network"}, {"label": "Sending bank sees an input message", "note": "From the sending bank the same payment is an input message"}, {"label": "Receiving bank sees an output message", "note": "From the receiving bank it is an output message"}, {"label": "Know whose copy you are reading", "note": "An operator must know which bank's copy it is before deciding what block 2 means"}]}}, "level": "foundation", "source_ref": "https://www.paiementor.com/mt103-swift-message-with-optional-fields-52a-and-57a/"}, {"id": "PAI-C083", "seq": 63, "module": "Foundations", "source": "Paiementor", "title": "One MT103, one beneficiary", "explain": "An MT103 carries a single beneficiary in field 59, so one message pays one beneficiary at one bank. A payment that must reach a seller and a manufacturer at different banks needs two separate MT103 messages, one for each beneficiary. Trying to name two beneficiaries in a single MT103 is not possible, because the message has nowhere to put the second one.", "takeaway": "Trying to name two beneficiaries in a single MT103 is not possible, because the message has nowhere to put the second one.", "visual": {"type": "diagram", "diagram": {"centre": "One MT103, one beneficiary", "parts": [{"label": "Field 59 carries a single beneficiary", "note": "An MT103 carries a single beneficiary in field 59"}, {"label": "One message, one beneficiary, one bank", "note": "One message pays one beneficiary at one bank"}, {"label": "Seller and manufacturer need two MT103s", "note": "A payment to a seller and a manufacturer at different banks needs two MT103 messages"}, {"label": "No place for a second beneficiary", "note": "Two beneficiaries cannot be named in one MT103; the message has nowhere for the second one"}]}}, "level": "foundation", "source_ref": "https://www.paiementor.com/swift-mt103-message-example-with-optional-fields-53b-70-and-71g-explained/"}, {"id": "PAI-C085", "seq": 64, "module": "Foundations", "source": "Paiementor", "title": "Field 32A: value date, currency and the amount that actually settles", "explain": "Field 32A carries three things: the value date in year-month-day order, the currency, and the interbank settlement amount. The value date is the date the funds are to be available to the receiver, not the date the message was sent. The currency in field 32A is the currency the receiver's bank actually receives, which is why it can differ from the currency the ordering customer instructed in field 33B.", "takeaway": "The currency in field 32A is the currency the receiver's bank actually receives, which is why it can differ from the currency the ordering customer instructed in field 33B.", "visual": {"type": "diagram", "diagram": {"centre": "Field 32A in an MT103", "parts": [{"label": "Value date in year-month-day order", "note": "Field 32A carries the value date in year-month-day order"}, {"label": "Value date is when funds are available", "note": "The value date is when the funds are to be available to the receiver, not the date sent"}, {"label": "Currency the receiver actually gets", "note": "The currency in field 32A is the currency the receiver's bank actually receives"}, {"label": "Interbank settlement amount", "note": "Field 32A carries the interbank settlement amount"}, {"label": "Currency can differ from field 33B", "note": "The currency in 32A can differ from the currency instructed in field 33B"}]}}, "level": "foundation", "source_ref": "https://www.paiementor.com/swift-mt103-message-example-with-optional-fields-53b-70-and-71g-explained/"}, {"id": "PAI-C091", "seq": 65, "module": "Foundations", "source": "Paiementor", "title": "Not every character is allowed in a SWIFT message", "explain": "SWIFT MT messages use a restricted character set, and characters outside it cannot be used in a message at all. That is why country-specific characters, such as Japanese or Thai script, cannot appear in an MT101 or an MT103, even when the underlying instruction is domestic. Names and addresses must be written with the characters the SWIFT set allows, or the message will not be accepted.", "takeaway": "Names and addresses must be written with the characters the SWIFT set allows, or the message will not be accepted.", "visual": {"type": "diagram", "diagram": {"centre": "The restricted SWIFT character set", "parts": [{"label": "Characters outside the set cannot be used", "note": "SWIFT MT messages use a restricted character set, and outside characters cannot be used"}, {"label": "Country-specific scripts excluded", "note": "Country-specific characters, like Japanese or Thai script, cannot appear in MT messages"}, {"label": "Applies even to domestic instructions", "note": "The restriction applies even when the underlying instruction is domestic"}, {"label": "Names must use the allowed characters", "note": "Names and addresses must use the characters the SWIFT set allows, or the message fails"}]}}, "level": "foundation", "source_ref": "https://www.paiementor.com/swift-mt103-message-example-with-optional-fields-53b-70-and-71g-explained/"}, {"id": "PAI-C097", "seq": 66, "module": "Foundations", "source": "Paiementor", "title": "What an MT101 can move", "explain": "An MT101 can move funds between an ordering customer's own accounts, in favour of a third party domestically, and in favour of a third party internationally. All three uses are valid, because the message is a general request for transfer, not a payment for one kind of beneficiary. The same message therefore serves a corporate moving money between its own accounts and a corporate paying a supplier abroad.", "takeaway": "The same message therefore serves a corporate moving money between its own accounts and a corporate paying a supplier abroad.", "visual": {"type": "diagram", "diagram": {"centre": "What an MT101 can move", "parts": [{"label": "Between the customer's own accounts", "note": "An MT101 can move funds between an ordering customer's own accounts"}, {"label": "In favour of a third party domestically", "note": "An MT101 can move funds in favour of a third party domestically"}, {"label": "In favour of a third party internationally", "note": "An MT101 can move funds in favour of a third party internationally"}, {"label": "A general request for transfer", "note": "The message is a general request for transfer, not a payment for one kind of beneficiary"}]}}, "level": "foundation", "source_ref": "https://www.paiementor.com/basic-swift-mt101-message-with-two-domestic-transactions/"}, {"id": "RUN3-001", "seq": 67, "module": "Foundations", "source": "Paiementor", "title": "SCT rejection: a pacs.002 from the CSM means the beneficiary bank never knew", "explain": "In a SEPA credit transfer the payment travels from the originator bank through the clearing and settlement mechanism to the beneficiary bank in a pacs.008. If the clearing mechanism rejects it, it sends back a pacs.002, and that rejection happens before the beneficiary bank is ever aware of the payment. If the problem is found at the beneficiary bank instead, the payment comes back as a pacs.004 return, because by then the beneficiary bank has received it.", "takeaway": "If the problem is found at the beneficiary bank instead, the payment comes back as a pacs.004 return, because by then the beneficiary bank has received it.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Originator bank sends the payment", "note": "The payment travels in a pacs.008 through the clearing and settlement mechanism."}, {"kind": "decision", "title": "Clearing mechanism accepts it?", "note": "If the clearing mechanism rejects it, it sends back a pacs.002."}, {"kind": "step", "title": "pacs.002 returns to the sender", "note": "The rejection happens before the beneficiary bank is ever aware of the payment."}, {"kind": "step", "title": "Beneficiary bank checks the payment", "note": "If the beneficiary bank finds the problem, the payment comes back as a pacs.004 return."}, {"kind": "step", "title": "pacs.004 return sent back", "note": "The return happens because the beneficiary bank has already received the payment."}]}}, "level": "foundation", "source_ref": "https://www.paiementor.com/the-messages-exchanged-in-the-sepa-credit-transfer-scheme/"}, {"id": "RUN3-009", "seq": 68, "module": "Foundations", "source": "Paiementor", "title": "Advices first, statement last: MT900 and MT910 are followed by the end of day MT950", "explain": "During the day a bank sends MT900 and MT910 advices as individual debits and credits hit the account, so the account owner learns about each movement as it happens. At the end of the day the MT950 statement arrives and brings all of those movements together in one statement. The advices and the statement must reconcile, because they describe the same day from two angles.", "takeaway": "The advices and the statement must reconcile, because they describe the same day from two angles.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "MT900 and MT910 advices sent", "note": "During the day the bank sends advices as individual debits and credits hit the account."}, {"kind": "step", "title": "Account owner learns of each movement", "note": "Each advice tells the owner about a movement as it happens."}, {"kind": "step", "title": "MT950 arrives at end of day", "note": "The end of day statement brings all of those movements together in one statement."}, {"kind": "step", "title": "Advices and statement reconcile", "note": "They must reconcile because they describe the same day from two angles."}]}}, "level": "foundation", "source_ref": "https://www.paiementor.com/swift-mt910-confirmation-of-credit-detailed-analysis/"}, {"id": "RUN3-010", "seq": 69, "module": "Foundations", "source": "Paiementor", "title": "MT910: the account servicing bank tells the account owner a credit has landed", "explain": "An MT910 is sent by the account servicing bank to the account owner to confirm a credit to the account. It is triggered by the credit entry itself, so it arrives because money has actually been posted, not because a payment was merely instructed. That makes the MT910 the point where the account owner can treat the funds as received.", "takeaway": "That makes the MT910 the point where the account owner can treat the funds as received.", "visual": {"type": "diagram", "diagram": {"centre": "MT910 confirmation of credit", "parts": [{"label": "Sent by the account servicing bank", "note": "The MT910 is sent by the account servicing bank to the account owner."}, {"label": "Triggered by the credit entry", "note": "It arrives because money has actually been posted, not because a payment was instructed."}, {"label": "Funds treated as received", "note": "The MT910 is the point where the account owner can treat the funds as received."}]}}, "level": "foundation", "source_ref": "https://www.paiementor.com/swift-mt910-confirmation-of-credit-detailed-analysis/"}, {"id": "RUN4-001", "seq": 70, "module": "Foundations", "source": "Paiementor", "title": "Nostro vs nostro mirror: only the real account holds funds", "explain": "When Bank A opens an account with Bank B, that account is Bank A's nostro account, and it sits in Bank B's books where the real funds are held. Bank A also keeps a mirror nostro in its own books, but the mirror holds no funds at all, it only reflects what happens on the real account. The mirror is kept in the same currency as the real account, so a USD nostro has a USD mirror. If you know what the mirror shows, you can work out what the real account should show, because the mirror is a faithful image of it.", "takeaway": "If you know what the mirror shows, you can work out what the real account should show, because the mirror is a faithful image of it.", "visual": {"type": "diagram", "diagram": {"centre": "Nostro account and its mirror", "parts": [{"label": "Real nostro at Bank B", "note": "Bank A's nostro sits in Bank B's books, where the real funds are held."}, {"label": "Mirror nostro at Bank A", "note": "Bank A keeps a mirror nostro in its own books, but the mirror holds no funds at all."}, {"label": "Same currency", "note": "The mirror is kept in the same currency as the real account."}, {"label": "Mirror reflects the real account", "note": "If you know what the mirror shows, you can work out what the real account should show."}]}}, "level": "foundation", "source_ref": "https://www.paiementor.com/strategy-2-understand-how-cross-border-payments-work/"}, {"id": "RUN4-002", "seq": 71, "module": "Foundations", "source": "Paiementor", "title": "Where the money really sits when a customer holds a foreign currency account", "explain": "When a customer opens a USD account with a bank in France, the bank opens the account in its own books, but the real USD funds are held with the bank's correspondent in the USA. To fund the account, the customer either buys USD or receives it from someone, and the sending bank finds the French bank's US correspondent and sends the funds there. The correspondent then advises the French bank with an MT103, and only then is the customer's account credited.", "takeaway": "The correspondent then advises the French bank with an MT103, and only then is the customer's account credited.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Customer opens a USD account", "note": "The bank in France opens the account in its own books for the customer."}, {"kind": "step", "title": "Customer funds the account", "note": "The customer either buys USD or receives it from someone."}, {"kind": "step", "title": "Sending bank finds the US correspondent", "note": "The sending bank finds the French bank's US correspondent and sends the funds there."}, {"kind": "step", "title": "Correspondent advises with MT103", "note": "The correspondent advises the French bank with an MT103."}, {"kind": "step", "title": "Customer account credited", "note": "Only then is the customer's account credited."}]}}, "level": "foundation", "source_ref": "https://www.paiementor.com/strategy-2-understand-how-cross-border-payments-work/"}, {"id": "RUN4-003", "seq": 72, "module": "Foundations", "source": "Paiementor", "title": "A new nostro starts empty: open the account first, then fund it through the FX market", "explain": "Currency never leaves its home country, so a bank funds a new nostro by buying the foreign currency on the FX market and naming its nostro account as the account that should receive the funds. If no banking relationship exists yet, the bank must first ask a bank in that currency's country to open the account, which starts with a zero balance, and only then do the FX deal. If the bank already holds the currency in an account elsewhere, it can simply instruct that bank to move the funds to the new account, with no FX deal needed.", "takeaway": "If the bank already holds the currency in an account elsewhere, it can simply instruct that bank to move the funds to the new account, with no FX deal needed.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Buy foreign currency on the FX market", "note": "Currency never leaves its home country, so the bank buys it for its nostro account."}, {"kind": "decision", "title": "Banking relationship exists yet?", "note": "If no relationship exists, the bank must first ask a bank there to open the account."}, {"kind": "step", "title": "New account starts at zero", "note": "The account opens with a zero balance, and only then does the FX deal happen."}, {"kind": "step", "title": "Or move funds from an existing account", "note": "If the bank holds the currency elsewhere, it instructs that bank to move the funds."}]}}, "level": "foundation", "source_ref": "https://www.paiementor.com/4-key-strategies-understand-how-cross-border-payments-work/"}, {"id": "RUN4-004", "seq": 73, "module": "Foundations", "source": "Paiementor", "title": "Domestic payments never travel on SWIFT", "explain": "A payment inside one country goes through that country's own clearing and settlement systems, using local formats based on flat or XML files, and it never touches the SWIFT network. SWIFT was created for cross-border payments, and the large majority of cross-border payments still travel on it. The two worlds are separate: local networks for local payments, SWIFT for payments that cross a border.", "takeaway": "The two worlds are separate: local networks for local payments, SWIFT for payments that cross a border.", "visual": {"type": "diagram", "diagram": {"centre": "Domestic vs cross-border payments", "parts": [{"label": "Local clearing for domestic", "note": "A payment inside one country goes through that country's own clearing system."}, {"label": "Local formats", "note": "Domestic payments use local formats based on flat or XML files."}, {"label": "Never touches SWIFT", "note": "A domestic payment never touches the SWIFT network."}, {"label": "SWIFT for cross-border", "note": "SWIFT was created for cross-border payments, and most still travel on it."}]}}, "level": "foundation", "source_ref": "https://www.paiementor.com/strategy-3-understand-how-cross-border-payments-work/"}, {"id": "RUN4-005", "seq": 74, "module": "Foundations", "source": "Paiementor", "title": "Bid and ask: read them from the bank's side first", "explain": "Bid means buy and ask means sell, and the prices are set by the bank, not by the customer. The bank buys the currency from the customer at the bid rate and sells it to the customer at the ask rate, so the customer buys at the higher ask rate and sells at the lower bid rate. The bank always makes money on the difference. A base currency exporter watches the ask price, while a base currency importer watches the bid price.", "takeaway": "A base currency exporter watches the ask price, while a base currency importer watches the bid price.", "visual": {"type": "diagram", "diagram": {"centre": "Bid and ask rates", "parts": [{"label": "Bid means buy", "note": "Bid means buy and ask means sell, and the prices are set by the bank."}, {"label": "Bank buys at the bid rate", "note": "The bank buys the currency from the customer at the bid rate."}, {"label": "Bank sells at the ask rate", "note": "The bank sells the currency to the customer at the ask rate."}, {"label": "Customer buys high, sells low", "note": "The customer buys at the higher ask rate and sells at the lower bid rate."}, {"label": "Exporter watches the ask", "note": "A base currency exporter watches the ask price."}, {"label": "Importer watches the bid", "note": "A base currency importer watches the bid price."}]}}, "level": "foundation", "source_ref": "https://www.paiementor.com/strategy-4-understand-how-cross-border-payments-work/"}, {"id": "RUN4-006", "seq": 75, "module": "Foundations", "source": "Paiementor", "title": "Direct quote: the domestic currency is the price currency", "explain": "In a direct currency quote, the domestic currency is the quoted currency, which is the same thing as the price currency. So for a bank in the euro area quoting EUR/USD, the euro is the domestic currency and the price is expressed in euros. Getting this the right way round matters, because the direct and indirect quotes describe the same pair from opposite sides.", "takeaway": "Getting this the right way round matters, because the direct and indirect quotes describe the same pair from opposite sides.", "visual": {"type": "diagram", "diagram": {"centre": "Direct currency quote", "parts": [{"label": "Domestic currency is quoted", "note": "In a direct quote, the domestic currency is the quoted currency."}, {"label": "Quoted equals price currency", "note": "The quoted currency is the same thing as the price currency."}, {"label": "EUR/USD example", "note": "For a bank in the euro area quoting EUR/USD, the euro is the domestic currency."}, {"label": "Price expressed in euros", "note": "The price is expressed in euros for the euro area bank."}, {"label": "Opposite of indirect quote", "note": "Direct and indirect quotes describe the same pair from opposite sides."}]}}, "level": "foundation", "source_ref": "https://www.paiementor.com/strategy-4-understand-how-cross-border-payments-work/"}, {"id": "RUN4-007", "seq": 76, "module": "Foundations", "source": "Paiementor", "title": "Buying EUR/USD means buying the base currency", "explain": "In the quote EUR/USD, EUR is the base currency and USD is the quoted currency, and buying and selling always refer to the base currency. If you buy EUR/USD you receive EUR and give USD, and if you sell EUR/USD you give EUR and receive USD. The number in the quote, such as 1.1635, is the amount of the quoted currency that one unit of the base currency is worth.", "takeaway": "The number in the quote, such as 1.1635, is the amount of the quoted currency that one unit of the base currency is worth.", "visual": {"type": "diagram", "diagram": {"centre": "EUR/USD quote", "parts": [{"label": "EUR is the base currency", "note": "In the quote EUR/USD, EUR is the base currency and USD is the quoted currency."}, {"label": "Buying means buying the base", "note": "Buying and selling always refer to the base currency."}, {"label": "Buy EUR/USD, receive EUR", "note": "If you buy EUR/USD you receive EUR and give USD."}, {"label": "Sell EUR/USD, give EUR", "note": "If you sell EUR/USD you give EUR and receive USD."}, {"label": "Quote number 1.1635", "note": "The number in the quote, such as 1.1635, is the quoted currency one unit of base is worth."}]}}, "level": "foundation", "source_ref": "https://www.paiementor.com/strategy-4-understand-how-cross-border-payments-work/"}, {"id": "RUN5-004", "seq": 77, "module": "Foundations", "source": "Paiementor", "title": "Who pays what in a card transaction", "explain": "The costs of a card transaction are split between the merchant and the cardholder, and each side pays for different things. The merchant is charged by the issuer and the processing chain for the transactions it accepts. The cardholder does not pay per transaction, but pays the annual fee for the card and interest whenever a statement balance is not paid in full.", "takeaway": "The cardholder does not pay per transaction, but pays the annual fee for the card and interest whenever a statement balance is not paid in full.", "visual": {"type": "diagram", "diagram": {"centre": "Who pays what in a card transaction", "parts": [{"label": "Merchant pays issuer charges", "note": "The merchant is charged by the issuer and the processing chain for the transactions."}, {"label": "Cardholder pays no per-transaction fee", "note": "The cardholder does not pay per transaction."}, {"label": "Cardholder pays the annual fee", "note": "The cardholder pays the annual fee for the card."}, {"label": "Cardholder pays interest if unpaid", "note": "The cardholder pays interest whenever a statement balance is not paid in full."}]}}, "level": "foundation", "source_ref": "https://www.paiementor.com/4-party-scheme-in-card-flow-exchanges-for-a-card-payment/"}, {"id": "RUN5-006", "seq": 78, "module": "Foundations", "source": "Paiementor", "title": "Monthly fee versus payment processing fee", "explain": "A merchant pays two different kinds of fees to a payment processor, and they are easy to confuse. The monthly fee is a fixed amount charged every month for using the payment processing service, and its level is set by the processing firm. The payment processing fee is different: it is charged on a per-transaction basis, so it rises and falls with the number of transactions the merchant processes.", "takeaway": "The payment processing fee is different: it is charged on a per-transaction basis, so it rises and falls with the number of transactions the merchant processes.", "visual": {"type": "diagram", "diagram": {"centre": "Merchant fees to a processor", "parts": [{"label": "Monthly fee is fixed", "note": "The monthly fee is a fixed amount charged every month for using the processing service."}, {"label": "Monthly fee set by the processor", "note": "Its level is set by the processing firm."}, {"label": "Processing fee is per transaction", "note": "The payment processing fee is charged on a per-transaction basis."}, {"label": "Processing fee rises with volume", "note": "It rises and falls with the number of transactions the merchant processes."}]}}, "level": "foundation", "source_ref": "https://www.paiementor.com/payment-processors-in-card-transactions/"}, {"id": "RUN5-008", "seq": 79, "module": "Foundations", "source": "Paiementor", "title": "Cheque presentation by image instead of paper", "explain": "A cheque no longer has to travel as a piece of paper to be collected. It is the beneficiary bank that presents the cheque to the drawee bank, and in many countries it presents only an image of the cheque to collect the funds. Physical presentation of the cheque is no longer required in those countries, which is why cheque clearing can run on images rather than on the movement of paper.", "takeaway": "Physical presentation of the cheque is no longer required in those countries, which is why cheque clearing can run on images rather than on the movement of paper.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Beneficiary bank presents the cheque", "note": "It is the beneficiary bank that presents the cheque to the drawee bank."}, {"kind": "step", "title": "Image presented, not paper", "note": "In many countries it presents only an image of the cheque to collect the funds."}, {"kind": "step", "title": "No physical presentation needed", "note": "Physical presentation of the cheque is no longer required in those countries."}, {"kind": "step", "title": "Clearing runs on images", "note": "Cheque clearing can run on images rather than on the movement of paper."}]}}, "level": "foundation", "source_ref": "https://www.paiementor.com/the-four-corner-model-for-cheque-payment/"}, {"id": "ABH-10", "seq": 80, "module": "Core", "source": "Abhishek Pandey", "title": "One click to Pay, fifteen steps and nine decisions", "explain": "A corporate payment passes fifteen steps and nine decisions from maker to ledger. The preprocessor checks entitlement, account, limits, fees, and payee, then the workflow approves it, the bank screens and debits it, the network clears it, and the ledger closes it. Every Yes moves the payment forward, and every No stops or re-routes it.", "takeaway": "Every Yes moves the payment forward, and every No stops or re-routes it.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Maker initiates the payment", "note": "Fifteen steps and nine decisions to the ledger"}, {"kind": "decision", "title": "Preprocessor checks clear?", "note": "Entitlement, account, limits, fees and payee"}, {"kind": "step", "title": "Workflow approves the payment", "note": "Approval moves it to the bank"}, {"kind": "decision", "title": "Bank screening clear?", "note": "A No stops or re-routes the payment"}, {"kind": "step", "title": "Bank debits the account", "note": "Funds leave the payer account"}, {"kind": "step", "title": "Network clears the payment", "note": "Clearing moves it to the beneficiary bank"}, {"kind": "step", "title": "Ledger closes the payment", "note": "Posting completes the journey"}]}}, "level": "core", "source_ref": "https://www.linkedin.com/posts/abhishek2601_payments-corporatebanking-transactionbanking-ugcPost-7525358191421968384-WDGr/"}, {"id": "ABH-11", "seq": 81, "module": "Core", "source": "Abhishek Pandey", "title": "From corporate channel to core banking posting", "explain": "A corporate payment starts in a channel, passes an API gateway, validation, and the payment hub, then compliance screening, routing and clearing, and finally the core banking debit and credit posting. Each hand-off is a place where the payment can be checked, enriched, or stopped.", "takeaway": "Each hand-off is a place where the payment can be checked, enriched, or stopped.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Corporate channel", "note": "Where the payment starts"}, {"kind": "step", "title": "API gateway", "note": "Entry point into the bank systems"}, {"kind": "step", "title": "Validation", "note": "Payment checked before it moves on"}, {"kind": "step", "title": "Payment hub", "note": "Central processing for the payment"}, {"kind": "decision", "title": "Compliance screening clear?", "note": "A failed screen stops the payment here"}, {"kind": "step", "title": "Routing and clearing", "note": "Payment routed to the right rail and cleared"}, {"kind": "step", "title": "Core banking posting", "note": "Debit and credit posted to the ledger"}]}}, "level": "core", "source_ref": "https://www.linkedin.com/posts/abhishek2601_corporatebanking-paymentprocessing-bankingtechnology-share-7523749792137560065-m5CO/"}, {"id": "ABH-12", "seq": 82, "module": "Core", "source": "Abhishek Pandey", "title": "After you click Pay in Vietnam, the preprocessor is the control point", "explain": "In a domestic payment in Vietnam, the payment preprocessor is the central control point. The flow runs from the corporate, through the preprocessor, to the payment hub, then NAPAS, then the beneficiary bank. Nothing reaches the rail until the preprocessor has cleared it.", "takeaway": "Nothing reaches the rail until the preprocessor has cleared it.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Corporate initiates payment", "note": "The payment starts with the corporate"}, {"kind": "step", "title": "Preprocessor control point", "note": "Nothing reaches the rail until it clears here"}, {"kind": "step", "title": "Payment hub", "note": "Central processing after the preprocessor"}, {"kind": "step", "title": "NAPAS", "note": "The domestic rail in Vietnam"}, {"kind": "step", "title": "Beneficiary bank", "note": "Final bank that credits the beneficiary"}]}}, "level": "core", "source_ref": "https://www.linkedin.com/in/abhishek2601/recent-activity/all/"}, {"id": "ABH-13", "seq": 83, "module": "Core", "source": "Abhishek Pandey", "title": "After you click Send in Vietnam, what really happens", "explain": "A domestic payment in Vietnam moves from the channel to core banking, then the payment hub, validation and routing, NAPAS, the receiving bank, and reconciliation. Each stage has a job, and reconciliation at the end proves the money arrived where it should.", "takeaway": "Each stage has a job, and reconciliation at the end proves the money arrived where it should.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Channel", "note": "Where the payment is sent from"}, {"kind": "step", "title": "Core banking", "note": "Payment enters the bank core"}, {"kind": "step", "title": "Payment hub", "note": "Central processing and control"}, {"kind": "step", "title": "Validation and routing", "note": "Checked, then routed to the right path"}, {"kind": "step", "title": "NAPAS", "note": "The domestic rail that carries it"}, {"kind": "step", "title": "Receiving bank", "note": "Bank that receives for the beneficiary"}, {"kind": "step", "title": "Reconciliation", "note": "Proves the money arrived where it should"}]}}, "level": "core", "source_ref": "https://www.linkedin.com/in/abhishek2601/recent-activity/all/"}, {"id": "ABH-14", "seq": 84, "module": "Core", "source": "Abhishek Pandey", "title": "How a domestic payment works in Vietnam, the preprocessor checks", "explain": "The preprocessor validates the account, the format, the authorisation, the limits, AML and sanctions, duplicates, routing, and enrichment before the payment moves on. These checks are the reason a payment can be trusted to reach the right account.", "takeaway": "These checks are the reason a payment can be trusted to reach the right account.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Account validation", "note": "Account exists and is valid"}, {"kind": "step", "title": "Format check", "note": "Message format is correct"}, {"kind": "step", "title": "Authorisation check", "note": "Payment is properly authorised"}, {"kind": "decision", "title": "Limits, AML and sanctions clear?", "note": "Limits, AML and sanctions all checked"}, {"kind": "step", "title": "Duplicate check", "note": "Payment is not a repeat"}, {"kind": "step", "title": "Routing", "note": "Payment routed to the right path"}, {"kind": "step", "title": "Enrichment", "note": "Payment enriched before it moves on"}]}}, "level": "core", "source_ref": "https://www.linkedin.com/in/abhishek2601/recent-activity/all/"}, {"id": "ABH-15", "seq": 85, "module": "Core", "source": "Abhishek Pandey", "title": "The payment preprocessor, control tower of cross-border payments", "explain": "In cross-border payments the preprocessor is the control tower. It validates, enriches, checks compliance, routes, and processes the payment, so that fewer payments are rejected and more go straight through. A strong preprocessor is what makes straight-through processing possible.", "takeaway": "A strong preprocessor is what makes straight-through processing possible.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Validate the payment", "note": "Checks before the payment moves on"}, {"kind": "step", "title": "Enrich the payment", "note": "Data added for straight-through processing"}, {"kind": "decision", "title": "Compliance checks clear?", "note": "Compliance checked before routing"}, {"kind": "step", "title": "Route the payment", "note": "Sent down the right rail"}, {"kind": "step", "title": "Process the payment", "note": "Fewer rejections, more straight-through"}]}}, "level": "core", "source_ref": "https://www.linkedin.com/in/abhishek2601/recent-activity/all/"}, {"id": "ABH-16", "seq": 86, "module": "Core", "source": "Abhishek Pandey", "title": "The preprocessor in cross-border payments, layer by layer", "explain": "Preprocessor validation works in layers: technical, payment data, business, compliance, and routing. Each layer catches a different kind of error, and the full lifecycle runs from initiation through to settlement and reconciliation.", "takeaway": "Each layer catches a different kind of error, and the full lifecycle runs from initiation through to settlement and reconciliation.", "visual": {"type": "diagram", "diagram": {"centre": "Preprocessor validation, layer by layer", "parts": [{"label": "Technical", "note": "Catches technical errors"}, {"label": "Payment data", "note": "Catches payment data errors"}, {"label": "Business", "note": "Catches business errors"}, {"label": "Compliance", "note": "Catches compliance errors"}, {"label": "Routing", "note": "Catches routing errors"}, {"label": "Full lifecycle", "note": "Initiation through settlement and reconciliation"}]}}, "level": "core", "source_ref": "https://www.linkedin.com/in/abhishek2601/recent-activity/all/"}, {"id": "ABH-17", "seq": 87, "module": "Core", "source": "Abhishek Pandey", "title": "Finastra GPP, the technical payment flow", "explain": "From a Tech BA view, a payment flows from the channel through the API gateway and message queue into GPP, where it is parsed, validated, checked for duplicates, mapped to ISO 20022, screened for compliance, routed to a SWIFT or domestic rail, acknowledged, and finally posted to core banking with reconciliation. Exceptions are handled at each stage.", "takeaway": "Exceptions are handled at each stage.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Channel", "note": "Where the payment starts"}, {"kind": "step", "title": "API gateway and message queue", "note": "Entry and queuing into the bank"}, {"kind": "step", "title": "GPP parse and validate", "note": "Parsed, validated and duplicate-checked"}, {"kind": "step", "title": "Map to ISO 20022", "note": "Payment mapped to the rich data standard"}, {"kind": "decision", "title": "Compliance screening clear?", "note": "Screened before routing"}, {"kind": "step", "title": "Route to SWIFT or domestic rail", "note": "Routed to the right rail"}, {"kind": "step", "title": "Acknowledge, post and reconcile", "note": "Acknowledged, posted to core banking, reconciled"}]}}, "level": "core", "source_ref": "https://www.linkedin.com/posts/abhishek2601_finastra-gpp-globalpayplus-share-7515580094627631104-LHUO/"}, {"id": "ABH-18", "seq": 88, "module": "Core", "source": "Abhishek Pandey", "title": "A payment does not simply move from A to B", "explain": "The Finastra GPP end-to-end flow has real implementation challenges: ISO 20022 mapping, routing, duplicates, core banking integration, testing, and reconciliation. Each of these is a place where a payment can fail or be delayed, and each needs its own design and test coverage.", "takeaway": "Each of these is a place where a payment can fail or be delayed, and each needs its own design and test coverage.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "ISO 20022 mapping", "note": "Mapping can fail or delay the payment"}, {"kind": "step", "title": "Routing", "note": "Wrong route delays or fails the payment"}, {"kind": "step", "title": "Duplicate handling", "note": "Duplicates must be caught before posting"}, {"kind": "step", "title": "Core banking integration", "note": "Integration gaps stall the payment"}, {"kind": "step", "title": "Testing", "note": "Each stage needs its own test coverage"}, {"kind": "step", "title": "Reconciliation", "note": "Proves the payment completed correctly"}]}}, "level": "core", "source_ref": "https://www.linkedin.com/posts/abhishek2601_finastra-gpp-globalpayplus-share-7515253659883016192-CWu4/"}, {"id": "ABH-19", "seq": 89, "module": "Core", "source": "Abhishek Pandey", "title": "How Finastra GPP works in corporate banking, nine steps", "explain": "GPP runs a nine-step journey from payment origination to settlement and reporting in corporate banking. The steps cover initiation, validation, compliance, routing, clearing, and the final posting and reporting. Knowing the nine steps lets a BA place any issue at the right stage.", "takeaway": "Knowing the nine steps lets a BA place any issue at the right stage.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Initiation", "note": "Payment origination starts the journey"}, {"kind": "step", "title": "Validation", "note": "Payment checked before it moves on"}, {"kind": "decision", "title": "Compliance clear?", "note": "Compliance checked before routing"}, {"kind": "step", "title": "Routing", "note": "Payment routed to the right rail"}, {"kind": "step", "title": "Clearing", "note": "Payment cleared through the network"}, {"kind": "step", "title": "Settlement", "note": "Funds move to complete the payment"}, {"kind": "step", "title": "Posting and reporting", "note": "Final posting and reporting close the journey"}]}}, "level": "core", "source_ref": "https://www.linkedin.com/in/abhishek2601/recent-activity/all/"}, {"id": "ABH-20", "seq": 90, "module": "Core", "source": "Abhishek Pandey", "title": "Finastra GPP as one platform for many rails", "explain": "GPP orchestrates multiple payment types and rails from one platform: domestic, cross-border, real-time, and high-value payments, with routing, compliance, and reconciliation. One platform means one set of controls and one view of the payment, whatever the rail.", "takeaway": "One platform means one set of controls and one view of the payment, whatever the rail.", "visual": {"type": "diagram", "diagram": {"centre": "Finastra GPP, one platform", "parts": [{"label": "Domestic payments", "note": "Orchestrated from the one platform"}, {"label": "Cross-border payments", "note": "Orchestrated from the one platform"}, {"label": "Real-time payments", "note": "Orchestrated from the one platform"}, {"label": "High-value payments", "note": "Orchestrated from the one platform"}, {"label": "Routing", "note": "One set of controls, whatever the rail"}, {"label": "Compliance", "note": "One set of controls, whatever the rail"}, {"label": "Reconciliation", "note": "One view of the payment, whatever the rail"}]}}, "level": "core", "source_ref": "https://www.linkedin.com/in/abhishek2601/recent-activity/all/"}, {"id": "ABH-21", "seq": 91, "module": "Core", "source": "Abhishek Pandey", "title": "GPP integration in cross-border payments", "explain": "GPP integration in cross-border payments covers initiation, validation and enrichment, compliance, routing and orchestration, ISO 20022 and SWIFT, exceptions, and settlement with reconciliation. Each stage is a hand-off, and the integration is only as strong as the weakest hand-off.", "takeaway": "Each stage is a hand-off, and the integration is only as strong as the weakest hand-off.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Initiation", "note": "Payment starts in the channel"}, {"kind": "step", "title": "Validation and enrichment", "note": "Checked and enriched before it moves on"}, {"kind": "decision", "title": "Compliance clear?", "note": "Compliance checked before routing"}, {"kind": "step", "title": "Routing and orchestration", "note": "Routed across rails from one platform"}, {"kind": "step", "title": "ISO 20022 and SWIFT", "note": "Mapped to the standard and sent on SWIFT"}, {"kind": "step", "title": "Exceptions", "note": "Handled when a stage fails"}, {"kind": "step", "title": "Settlement and reconciliation", "note": "Settled, then reconciled to close the flow"}]}}, "level": "core", "source_ref": "https://www.linkedin.com/in/abhishek2601/recent-activity/all/"}, {"id": "ABH-22", "seq": 92, "module": "Core", "source": "Abhishek Pandey", "title": "Finastra is more than a payment processor", "explain": "Finastra is a broader banking technology ecosystem, not just a payment processor. Its products cover more of the bank than payments alone, which is why a BA working with Finastra needs to understand the wider platform, not only the payment flow.", "takeaway": "Its products cover more of the bank than payments alone, which is why a BA working with Finastra needs to understand the wider platform, not only the payment flow.", "visual": {"type": "diagram", "diagram": {"centre": "Finastra banking ecosystem", "parts": [{"label": "Payments", "note": "One part of the wider platform"}, {"label": "Wider banking products", "note": "Cover more of the bank than payments"}, {"label": "The BA view", "note": "Understand the wider platform, not only payments"}]}}, "level": "core", "source_ref": "https://www.linkedin.com/in/abhishek2601/recent-activity/all/"}, {"id": "ABH-23", "seq": 93, "module": "Core", "source": "Abhishek Pandey", "title": "GPP integration, the big picture", "explain": "GPP integration connects the bank's channels and systems to the payment hub so that a payment can flow end to end. The integration is the plumbing that makes the nine-step journey possible.", "takeaway": "The integration is the plumbing that makes the nine-step journey possible.", "visual": {"type": "diagram", "diagram": {"centre": "GPP integration", "parts": [{"label": "Channels and systems", "note": "Connected to the payment hub"}, {"label": "Payment hub", "note": "Where payments flow end to end"}, {"label": "Nine-step journey", "note": "Made possible by the integration"}]}}, "level": "core", "source_ref": "https://www.linkedin.com/in/abhishek2601/recent-activity/all/"}, {"id": "ABH-24", "seq": 94, "module": "Core", "source": "Abhishek Pandey", "title": "What makes a reliable Payment API architecture", "explain": "A reliable payment API rests on stateless validation, synchronous fraud and risk checks, idempotency, metadata-driven configuration, orchestration, compliance, and reconciliation. Idempotency matters because a retried call must never create a duplicate payment.", "takeaway": "Idempotency matters because a retried call must never create a duplicate payment.", "visual": {"type": "diagram", "diagram": {"centre": "A reliable payment API", "parts": [{"label": "Stateless validation", "note": "Validation without stored session state"}, {"label": "Synchronous fraud and risk checks", "note": "Fraud and risk checked in line"}, {"label": "Idempotency", "note": "A retried call never creates a duplicate payment"}, {"label": "Metadata-driven configuration", "note": "Behaviour driven by metadata"}, {"label": "Orchestration", "note": "Steps coordinated across the flow"}, {"label": "Compliance", "note": "Rules enforced in the API flow"}, {"label": "Reconciliation", "note": "Proves payments completed correctly"}]}}, "level": "core", "source_ref": "https://www.linkedin.com/posts/abhishek2601_paymentarchitecture-apis-bankingtechnology-share-7524499284860329984--IjB/"}, {"id": "ABH-25", "seq": 95, "module": "Core", "source": "Abhishek Pandey", "title": "API analysis is a critical BA skill", "explain": "Analysing an API means looking beyond the endpoint. A BA must understand the data, the consumers, the dependencies, and the impact of a change. An API that looks simple at the endpoint can have deep downstream effects.", "takeaway": "An API that looks simple at the endpoint can have deep downstream effects.", "visual": {"type": "diagram", "diagram": {"centre": "API analysis", "parts": [{"label": "Data", "note": "What the API carries and changes"}, {"label": "Consumers", "note": "Who calls the API"}, {"label": "Dependencies", "note": "What the API relies on downstream"}, {"label": "Impact of change", "note": "What a change breaks or moves"}, {"label": "The endpoint", "note": "Only the surface, not the whole API"}]}}, "level": "core", "source_ref": "https://www.linkedin.com/in/abhishek2601/recent-activity/all/"}, {"id": "ABH-26", "seq": 96, "module": "Core", "source": "Abhishek Pandey", "title": "Why every business analyst should understand APIs", "explain": "A BA who understands APIs can work with endpoints, payloads, data gaps, impact analysis, security, and backward compatibility. Without that knowledge, the BA cannot write a complete requirement or assess the impact of a change.", "takeaway": "Without that knowledge, the BA cannot write a complete requirement or assess the impact of a change.", "visual": {"type": "diagram", "diagram": {"centre": "A BA who understands APIs", "parts": [{"label": "Endpoints", "note": "Where the API is called"}, {"label": "Payloads", "note": "What the API carries"}, {"label": "Data gaps", "note": "What is missing in the data"}, {"label": "Impact analysis", "note": "What a change affects"}, {"label": "Security", "note": "How the API is protected"}, {"label": "Backward compatibility", "note": "Old callers keep working after a change"}, {"label": "Complete requirements", "note": "Possible only with API knowledge"}]}}, "level": "core", "source_ref": "https://www.linkedin.com/in/abhishek2601/recent-activity/all/"}, {"id": "INS-129", "seq": 97, "module": "Core", "source": "Jebaraj D", "title": "Creditor PSP closed on due date", "explain": "If the creditor PSP is closed on the due date, the collection cannot be submitted into the scheme on that date, even if the debtor PSP is open. The creditor-side processing constraint moves the collection to the next business day. The creditor must plan for its own closure days, not just the debtor's.", "takeaway": "The creditor must plan for its own closure days, not just the debtor's.", "visual": {"type": "diagram", "diagram": {"centre": "Creditor PSP closed on due date", "parts": [{"label": "Creditor PSP closed", "note": "Creditor PSP is closed on the due date"}, {"label": "Cannot submit", "note": "Collection cannot be submitted into the scheme on that date"}, {"label": "Debtor PSP open", "note": "Debtor PSP may be open, but that does not help"}, {"label": "Moves to next business day", "note": "Collection moves to the next business day"}, {"label": "Plan for own closure", "note": "Creditor must plan for its own closure days, not just the debtor's"}]}}, "level": "core", "source_ref": "JEB-10"}, {"id": "INS-130", "seq": 98, "module": "Core", "source": "Jebaraj D", "title": "Debtor PSP closed on due date", "explain": "If the debtor PSP is closed on the due date, the debtor account cannot be debited on that date, so the debit moves to the next business day the debtor PSP is open. The collection is not lost, but the timing shifts, and the creditor must know which date the debit will actually happen. This is why the debtor PSP calendar matters as much as the creditor's.", "takeaway": "This is why the debtor PSP calendar matters as much as the creditor's.", "visual": {"type": "diagram", "diagram": {"centre": "Debtor PSP closed on due date", "parts": [{"label": "Debtor PSP closed", "note": "Debtor PSP is closed on the due date"}, {"label": "Cannot debit", "note": "Debtor account cannot be debited on that date"}, {"label": "Moves to next business day", "note": "Debit moves to the next business day the debtor PSP is open"}, {"label": "Collection is not lost", "note": "Collection is not lost, but the timing shifts"}, {"label": "Creditor must know actual date", "note": "Creditor must know which date the debit will actually happen"}, {"label": "Debtor calendar matters", "note": "Debtor PSP calendar matters as much as the creditor's"}]}}, "level": "core", "source_ref": "JEB-10"}, {"id": "INS-131", "seq": 99, "module": "Core", "source": "Jebaraj D", "title": "Clearing and settlement mechanism closed", "explain": "The clearing and settlement mechanism is the infrastructure that moves collections between the creditor PSP and the debtor PSP. If it is closed on the due date, the collections cannot be submitted and settled that day, even when both banks are open and working. Both banks being open is not enough; the infrastructure between them must also be open.", "takeaway": "Both banks being open is not enough; the infrastructure between them must also be open.", "visual": {"type": "diagram", "diagram": {"centre": "Clearing mechanism closed", "parts": [{"label": "Clearing mechanism", "note": "Infrastructure that moves collections between creditor PSP and debtor PSP"}, {"label": "Closed on due date", "note": "Clearing and settlement mechanism is closed on the due date"}, {"label": "Cannot submit and settle", "note": "Collections cannot be submitted and settled that day"}, {"label": "Both banks open", "note": "Both banks can be open and working"}, {"label": "Infrastructure must be open", "note": "Infrastructure between them must also be open"}]}}, "level": "core", "source_ref": "JEB-10"}, {"id": "INS-132", "seq": 100, "module": "Core", "source": "Jebaraj D", "title": "Authorised SDD Core refund window", "explain": "When a debtor authorised a SEPA Direct Debit collection, they can ask for a refund within eight weeks of the debit date. The eight-week rule is the stated scheme position, but the exact application can vary by jurisdiction, so it must be checked against the current EPC rulebook. A refund inside this window is a normal scheme right, not an exception.", "takeaway": "A refund inside this window is a normal scheme right, not an exception.", "visual": {"type": "diagram", "diagram": {"centre": "Authorised SDD refund window", "parts": [{"label": "Authorised collection", "note": "Debtor authorised the SEPA Direct Debit collection"}, {"label": "Eight weeks", "note": "Refund can be asked within eight weeks of the debit date"}, {"label": "Scheme position", "note": "Eight-week rule is the stated scheme position"}, {"label": "Varies by jurisdiction", "note": "Exact application can vary by jurisdiction"}, {"label": "Check the rulebook", "note": "Must be checked against the current EPC rulebook"}, {"label": "Normal scheme right", "note": "Refund inside this window is a normal scheme right, not an exception"}]}}, "level": "core", "source_ref": "JEB-12"}, {"id": "INS-133", "seq": 101, "module": "Core", "source": "Jebaraj D", "title": "Unauthorised SDD claim window", "explain": "When a debtor says a direct debit was never authorised, they can claim a refund for up to 13 months after the debit. The 13-month period is the stated scheme position, and the precise legal and scheme conditions must be checked against the current rulebook. An unauthorised claim is a different process from an authorised refund, with a longer window and different evidence.", "takeaway": "An unauthorised claim is a different process from an authorised refund, with a longer window and different evidence.", "visual": {"type": "diagram", "diagram": {"centre": "Unauthorised SDD claim window", "parts": [{"label": "Never authorised", "note": "Debtor says a direct debit was never authorised"}, {"label": "13 months", "note": "Refund can be claimed for up to 13 months after the debit"}, {"label": "Scheme position", "note": "13-month period is the stated scheme position"}, {"label": "Check the rulebook", "note": "Precise legal and scheme conditions must be checked against the rulebook"}, {"label": "Different process", "note": "Unauthorised claim is a different process from an authorised refund"}, {"label": "Longer window, more evidence", "note": "Longer window and different evidence apply"}]}}, "level": "core", "source_ref": "JEB-13"}, {"id": "INS-134", "seq": 102, "module": "Core", "source": "Jebaraj D", "title": "Return, refund and reversal distinctions", "explain": "A return, a refund, and a reversal are three different money-back events with different initiators, reasons, messages, and accounting treatment: a return is started by the debtor PSP, usually because the account cannot be debited; a refund is started by the debtor asking for money back; and a reversal is started by the creditor PSP to undo a collection. Treating them as the same thing causes wrong messages, wrong timelines, and wrong ledger entries.", "takeaway": "Treating them as the same thing causes wrong messages, wrong timelines, and wrong ledger entries.", "visual": {"type": "diagram", "diagram": {"centre": "Return, refund and reversal", "parts": [{"label": "Return", "note": "Started by the debtor PSP, usually because the account cannot be debited"}, {"label": "Refund", "note": "Started by the debtor asking for money back"}, {"label": "Reversal", "note": "Started by the creditor PSP to undo a collection"}, {"label": "Different initiators", "note": "Three events have different initiators"}, {"label": "Different reasons", "note": "Three events have different reasons"}, {"label": "Different messages and accounting", "note": "Different messages and accounting treatment apply"}, {"label": "Confusing them", "note": "Treating them the same causes wrong messages, timelines, ledger entries"}]}}, "level": "core", "source_ref": "JEB-03"}, {"id": "INS-109", "seq": 103, "module": "Core", "source": "Jebaraj D", "title": "SDD pacs.004 return versus refund", "explain": "A SEPA Direct Debit return and a refund can arrive on the same day and look similar, but they are different business events. A return happens when the debtor bank sends the collection back, for example because the account has insufficient funds, and it travels as a pacs.004. A refund happens when the debtor asks for an authorised collection to be repaid. Each has its own trigger, timeline, and accounting treatment, and the system must handle them as separate events.", "takeaway": "Each has its own trigger, timeline, and accounting treatment, and the system must handle them as separate events.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Collection presented", "note": "Collection is presented for debit"}, {"kind": "decision", "title": "Return or refund?", "note": "Return and refund can arrive the same day and look similar but differ"}, {"kind": "step", "title": "Return travels as pacs.004", "note": "Debtor bank sends the collection back, for example insufficient funds"}, {"kind": "step", "title": "Refund on debtor request", "note": "Debtor asks for an authorised collection to be repaid"}, {"kind": "step", "title": "Handle them separately", "note": "Each has its own trigger, timeline, and accounting treatment"}]}}, "level": "core", "source_ref": "JEB-03"}, {"id": "INS-162", "seq": 104, "module": "Core", "source": "Jebaraj D", "title": "Return reason and timeline handling", "explain": "When a direct debit collection is returned, the pacs.004 carries a reason code that explains why, and the scheme sets a timeline for when the return must happen. The creditor needs to learn about the return quickly and understand whether the collection can be presented again. If the returns team cannot interpret the reason codes consistently, creditors find out days late with no clear explanation.", "takeaway": "If the returns team cannot interpret the reason codes consistently, creditors find out days late with no clear explanation.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Collection is returned", "note": "Direct debit collection is returned"}, {"kind": "step", "title": "Reason code in pacs.004", "note": "pacs.004 carries a reason code that explains why"}, {"kind": "step", "title": "Scheme timeline applies", "note": "Scheme sets a timeline for when the return must happen"}, {"kind": "step", "title": "Creditor learns quickly", "note": "Creditor needs to learn about the return quickly"}, {"kind": "decision", "title": "Can it be presented again?", "note": "Creditor must understand whether the collection can be presented again"}, {"kind": "step", "title": "Interpret codes consistently", "note": "Without consistent interpretation, creditors find out days late"}]}}, "level": "core", "source_ref": "JEB-03"}, {"id": "INS-136", "seq": 105, "module": "Core", "source": "Jebaraj D", "title": "Euro leg versus non-euro leg", "explain": "In an instant cross-border payment from Europe, the euro leg inside SEPA can complete in seconds, but the non-euro leg outside SEPA follows different rules and a different timeline. The customer sees the euro leg finish and expects the whole payment to be done, then nothing happens for hours while the other leg is processed. The two legs must be explained separately, with their own coverage and responsibilities.", "takeaway": "The two legs must be explained separately, with their own coverage and responsibilities.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Euro leg inside SEPA", "note": "Euro leg inside SEPA can complete in seconds"}, {"kind": "step", "title": "Non-euro leg outside SEPA", "note": "Non-euro leg outside SEPA follows different rules and timeline"}, {"kind": "step", "title": "Customer sees euro leg finish", "note": "Customer sees the euro leg finish and expects the whole payment done"}, {"kind": "step", "title": "Hours pass, nothing happens", "note": "Nothing happens for hours while the other leg is processed"}, {"kind": "step", "title": "Explain legs separately", "note": "Two legs must be explained separately, with own coverage and duties"}]}}, "level": "core", "source_ref": "JEB-15"}, {"id": "INS-137", "seq": 106, "module": "Core", "source": "Jebaraj D", "title": "Clearing, processing and settlement efficiency", "explain": "For an instant payment to feel instant end to end, every step must be fast: the customer channel, the payment engine, clearing, and settlement. If any one step is slow, the customer promise breaks even when the other steps are instant. The work is to find which step is the bottleneck and optimise it, rather than assuming the rail alone makes the payment instant.", "takeaway": "The work is to find which step is the bottleneck and optimise it, rather than assuming the rail alone makes the payment instant.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Customer channel", "note": "Customer channel must be fast"}, {"kind": "step", "title": "Payment engine", "note": "Payment engine must be fast"}, {"kind": "step", "title": "Clearing", "note": "Clearing must be fast"}, {"kind": "step", "title": "Settlement", "note": "Settlement must be fast"}, {"kind": "decision", "title": "Which step is the bottleneck?", "note": "Find which step is the bottleneck and optimise it"}]}}, "level": "core", "source_ref": "JEB-16"}, {"id": "INS-138", "seq": 107, "module": "Core", "source": "Jebaraj D", "title": "FX transparency for customer", "explain": "When a customer pays in a different currency, they need to see the exchange rate, the fees, how long the rate is valid, and the exact amount the beneficiary will receive. If the rate changes or the fees are not shown clearly, the beneficiary is credited a different amount and the customer cannot reconcile the payment. Transparency means showing the total cost and the applied rate before the customer confirms.", "takeaway": "Transparency means showing the total cost and the applied rate before the customer confirms.", "visual": {"type": "diagram", "diagram": {"centre": "FX transparency for customer", "parts": [{"label": "Exchange rate", "note": "Customer needs to see the exchange rate"}, {"label": "Fees", "note": "Customer needs to see the fees"}, {"label": "Rate validity", "note": "Customer needs to see how long the rate is valid"}, {"label": "Beneficiary amount", "note": "Customer needs the exact amount the beneficiary will receive"}, {"label": "Rate change risk", "note": "If the rate changes, the beneficiary is credited a different amount"}, {"label": "Unclear fees risk", "note": "If fees are not shown clearly, the beneficiary is credited a different amount"}, {"label": "Show before confirming", "note": "Show the total cost and the applied rate before the customer confirms"}]}}, "level": "core", "source_ref": "JEB-16"}, {"id": "INS-140", "seq": 108, "module": "Core", "source": "Jebaraj D", "title": "Structured remittance and party data", "explain": "Every cross-border payment carries payer, beneficiary, purpose, and remittance data that the supplier needs to allocate the cash and that compliance screening depends on. If the data is unstructured or incomplete, the supplier cannot match the payment to the invoice and the screening cannot run properly. Structured data is what makes a payment reconcilable and compliant at the same time.", "takeaway": "Structured data is what makes a payment reconcilable and compliant at the same time.", "visual": {"type": "diagram", "diagram": {"centre": "Structured payment data", "parts": [{"label": "Payer data", "note": "Payment carries payer data the supplier needs"}, {"label": "Beneficiary data", "note": "Payment carries beneficiary data"}, {"label": "Purpose data", "note": "Payment carries purpose data"}, {"label": "Remittance data", "note": "Payment carries remittance data the supplier needs to allocate cash"}, {"label": "Compliance screening", "note": "Structured data lets screening run properly"}, {"label": "Unstructured data risk", "note": "Unstructured or incomplete data means supplier cannot match payment to invoice"}]}}, "level": "core", "source_ref": "JEB-18"}, {"id": "INS-143", "seq": 109, "module": "Core", "source": "Jebaraj D", "title": "FX provider role in instant cross-border payments", "explain": "A bank that does not hold liquidity in every currency relies on an FX provider to source quotes, lock rates, execute the conversion, and supply the settlement currency. The arrangement works on quiet days, but a quote can expire while screening runs, or the provider may not have the currency when it is needed. The FX provider is a dependency in the payment chain, and its failure modes must be designed for.", "takeaway": "The FX provider is a dependency in the payment chain, and its failure modes must be designed for.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Bank relies on FX provider", "note": "Bank does not hold liquidity in every currency"}, {"kind": "step", "title": "Source quotes, lock rates", "note": "FX provider sources quotes and locks rates"}, {"kind": "step", "title": "Execute the conversion", "note": "FX provider executes the conversion"}, {"kind": "step", "title": "Supply settlement currency", "note": "FX provider supplies the settlement currency"}, {"kind": "decision", "title": "Quote still valid?", "note": "Quote can expire while screening runs"}, {"kind": "decision", "title": "Currency available?", "note": "Provider may not have the currency when it is needed"}]}}, "level": "core", "source_ref": "JEB-21"}, {"id": "INS-144", "seq": 110, "module": "Core", "source": "Jebaraj D", "title": "Currency liquidity constraint", "explain": "Having a competitive exchange rate is not the same as having the settlement currency available at the moment it is needed. A bank can offer instant dollar payments and still fail on some mornings because it does not hold enough dollars to settle. The constraint is liquidity, not conversion, and it must be managed by treasury, not just by the payment engine.", "takeaway": "The constraint is liquidity, not conversion, and it must be managed by treasury, not just by the payment engine.", "visual": {"type": "diagram", "diagram": {"centre": "Currency liquidity constraint", "parts": [{"label": "Competitive rate", "note": "Bank can offer a competitive exchange rate"}, {"label": "Currency must be available", "note": "Settlement currency must be available at the moment it is needed"}, {"label": "Instant dollar payments", "note": "Bank can offer instant dollar payments and still fail on some mornings"}, {"label": "Not enough dollars", "note": "Bank may not hold enough dollars to settle"}, {"label": "Liquidity, not conversion", "note": "Constraint is liquidity, not conversion"}, {"label": "Managed by treasury", "note": "Must be managed by treasury, not just by the payment engine"}]}}, "level": "core", "source_ref": "JEB-22"}, {"id": "INS-147", "seq": 111, "module": "Core", "source": "Jebaraj D", "title": "Ambiguous payment status across multiple PSPs", "explain": "When a cross-border payment passes through several payment service providers, each one can show a different status: the app says pending, the engine says processed, and the ledger has no posting. The customer and the contact centre cannot tell whether the money has left, arrived, or is lost. The fix is consistent status meanings, a status enquiry path, and clear customer communication at every step.", "takeaway": "The fix is consistent status meanings, a status enquiry path, and clear customer communication at every step.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Payment passes several PSPs", "note": "Cross-border payment passes through several payment service providers"}, {"kind": "step", "title": "App says pending", "note": "App says pending"}, {"kind": "step", "title": "Engine says processed", "note": "Engine says processed"}, {"kind": "step", "title": "Ledger has no posting", "note": "Ledger has no posting"}, {"kind": "step", "title": "Customer cannot tell", "note": "Customer and contact centre cannot tell whether money left, arrived, or is lost"}, {"kind": "step", "title": "Fix with consistent statuses", "note": "Fix is consistent status meanings, a status enquiry path, clear communication"}]}}, "level": "core", "source_ref": "JEB-24"}, {"id": "INS-150", "seq": 112, "module": "Core", "source": "Jebaraj D", "title": "Failure and timeout across corridor legs", "explain": "In a corridor where a payment crosses two fast payment systems joined by an orchestration layer, a timeout leaves the outcome uncertain: the money may have moved, or it may not have. If the customer taps send again, the bank can end up with two instructions and one debit. The safe handling is to establish the true state, never retry blindly, and use an inter-PSP investigation to resolve the uncertainty.", "takeaway": "The safe handling is to establish the true state, never retry blindly, and use an inter-PSP investigation to resolve the uncertainty.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Two fast systems joined", "note": "Payment crosses two fast payment systems joined by an orchestration layer"}, {"kind": "step", "title": "Timeout occurs", "note": "Timeout leaves the outcome uncertain"}, {"kind": "decision", "title": "Money moved or not?", "note": "Money may have moved, or it may not have"}, {"kind": "step", "title": "Customer taps send again", "note": "Customer taps send again"}, {"kind": "step", "title": "Two instructions, one debit", "note": "Bank can end up with two instructions and one debit"}, {"kind": "step", "title": "Establish the true state", "note": "Safe handling is to establish the true state, never retry blindly"}, {"kind": "step", "title": "Inter-PSP investigation", "note": "Use an inter-PSP investigation to resolve the uncertainty"}]}}, "level": "core", "source_ref": "JEB-24"}, {"id": "INS-170", "seq": 113, "module": "Core", "source": "Jebaraj D", "title": "Customer visibility across multiple payment systems", "explain": "A payment that travels through a bank, a correspondent, and the supplier bank shows only one status on the customer screen, usually Pending, while the supplier says it has not been paid. The clerk cannot say where the money is because the status does not reflect the intermediary steps. Customer-facing statuses must stay accurate while the underlying processing is still pending, so the customer is not left guessing.", "takeaway": "Customer-facing statuses must stay accurate while the underlying processing is still pending, so the customer is not left guessing.", "visual": {"type": "diagram", "diagram": {"centre": "Customer visibility across systems", "parts": [{"label": "Bank, correspondent, supplier", "note": "Payment travels through a bank, a correspondent, and the supplier bank"}, {"label": "One status on screen", "note": "Customer screen shows only one status, usually Pending"}, {"label": "Supplier says not paid", "note": "Supplier says it has not been paid"}, {"label": "Clerk cannot say where it is", "note": "Clerk cannot say where the money is"}, {"label": "Status hides middle steps", "note": "Status does not reflect the intermediary steps"}, {"label": "Accurate statuses needed", "note": "Customer-facing statuses must stay accurate while processing is pending"}]}}, "level": "core", "source_ref": "JEB-24"}, {"id": "INS-112", "seq": 114, "module": "Core", "source": "Jebaraj D", "title": "Ninety percent of a remittance file enters repair", "explain": "A large corporate customer sends a daily remittance file with thousands of supplier payments, and around 90 percent of the transactions enter the manual repair queue because key data is missing or inconsistent, such as account numbers that fail the modulus check or incomplete remittance information. The repair queue becomes the bottleneck, and the business must balance transaction-level repair flexibility against operational capacity, customer experience, and reconciliation. Fixing the data at the source matters more than adding repair staff.", "takeaway": "Fixing the data at the source matters more than adding repair staff.", "visual": {"type": "stacked", "stacked": {"segments": [{"label": "Enters manual repair", "note": "Around 90 percent enter the repair queue, key data missing or inconsistent", "value": 90}, {"label": "Passes without repair", "note": "Remaining share passes without entering the manual repair queue", "value": 10}], "unit": "%"}}, "level": "core", "source_ref": "JEB-01"}, {"id": "INS-113", "seq": 115, "module": "Core", "source": "Jebaraj D", "title": "Country-specific MS03 reject and return reason privacy", "explain": "When a payment is rejected, the internal diagnostic reason can be precise and sensitive, such as the account being closed or the name not matching. That reason cannot always be shared with the customer, because privacy rules differ by country. The bank must configure what reason is shown, at what scope, and through which channel, so the customer gets a useful explanation without exposing sensitive information.", "takeaway": "The bank must configure what reason is shown, at what scope, and through which channel, so the customer gets a useful explanation without exposing sensitive information.", "visual": {"type": "diagram", "diagram": {"centre": "Reject reason privacy by country", "parts": [{"label": "Internal diagnostic reason", "note": "Internal reason can be precise and sensitive"}, {"label": "Account closed example", "note": "Example reason is the account being closed"}, {"label": "Name mismatch example", "note": "Example reason is the name not matching"}, {"label": "Privacy rules differ", "note": "Privacy rules differ by country"}, {"label": "Configure what is shown", "note": "Bank must configure what reason is shown"}, {"label": "Configure scope and channel", "note": "Bank must configure scope and channel for the reason"}, {"label": "Useful but safe explanation", "note": "Customer gets a useful explanation without exposing sensitive information"}]}}, "level": "core", "source_ref": "JEB-02"}, {"id": "INS-117", "seq": 116, "module": "Core", "source": "Jebaraj D", "title": "EU instant payments maximum amount regulatory change", "explain": "The scheme maximum for instant euro payments and the limits a bank sets for its own customers are two different numbers. An older internal guide may still say the scheme maximum is 100,000 euro when the regulation has changed it, so the product configuration and the routing rules must be updated together. A payment above the scheme maximum cannot go as an instant payment at all, whatever the customer limit says.", "takeaway": "A payment above the scheme maximum cannot go as an instant payment at all, whatever the customer limit says.", "visual": {"type": "diagram", "diagram": {"centre": "Instant payment maximum amount", "parts": [{"label": "Scheme maximum", "note": "Scheme maximum for instant euro payments"}, {"label": "Bank customer limit", "note": "Limits a bank sets for its own customers are a different number"}, {"label": "Older guide says 100,000 euro", "note": "Older internal guide may still say the scheme maximum is 100,000 euro"}, {"label": "Regulation changed it", "note": "Regulation has changed the scheme maximum"}, {"label": "Update configuration", "note": "Product configuration must be updated"}, {"label": "Update routing rules", "note": "Routing rules must be updated together with configuration"}, {"label": "Above maximum cannot go instant", "note": "Payment above the scheme maximum cannot go as an instant payment"}]}}, "level": "core", "source_ref": "JEB-04"}, {"id": "INS-119", "seq": 117, "module": "Core", "source": "Jebaraj D", "title": "Vendor says a capability exists, verify configuration granularity", "explain": "A vendor may say a capability exists, but the real question is whether it can be configured at the right level: by country, by entity, by product, or by payment type. A capability that only works globally, when the bank needs it per country, is not fit for purpose. The business analyst must verify the configuration granularity before accepting that a requirement is met.", "takeaway": "The business analyst must verify the configuration granularity before accepting that a requirement is met.", "visual": {"type": "diagram", "diagram": {"centre": "Vendor capability granularity", "parts": [{"label": "Vendor says it exists", "note": "Vendor may say a capability exists"}, {"label": "Configure by country", "note": "Check whether it can be configured by country"}, {"label": "Configure by entity", "note": "Check whether it can be configured by entity"}, {"label": "Configure by product", "note": "Check whether it can be configured by product"}, {"label": "Configure by payment type", "note": "Check whether it can be configured by payment type"}, {"label": "Global only is not fit", "note": "Capability only working globally is not fit when the bank needs per country"}, {"label": "Verify before accepting", "note": "Analyst must verify granularity before accepting that a requirement is met"}]}}, "level": "core", "source_ref": "JEB-02"}, {"id": "SCN-01", "seq": 118, "module": "Core", "source": "Jebaraj D", "title": "One payment, two amounts", "explain": "The same cross-border payment can show a different amount at different stages, because the payment engine and the clearing layer apply different rules. The engine validates the instruction and converts it to ISO 20022, while the clearing layer settles a different amount after fees, charges, or an FX conversion at a shifted value date. The investigation starts by comparing the instructed amount in the pacs.008 against what clearing actually settled, then finding which rule changed it.", "takeaway": "The investigation starts by comparing the instructed amount in the pacs.008 against what clearing actually settled, then finding which rule changed it.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Engine validates instruction", "note": "Engine validates the instruction and converts it to ISO 20022"}, {"kind": "step", "title": "Clearing settles a different amount", "note": "Clearing layer settles a different amount after fees, charges, or FX conversion"}, {"kind": "step", "title": "Value date shifts", "note": "FX conversion can apply at a shifted value date"}, {"kind": "step", "title": "Compare instructed amount", "note": "Compare the instructed amount in pacs.008 against what clearing settled"}, {"kind": "decision", "title": "Which rule changed it?", "note": "Find which rule changed the amount"}]}}, "level": "core", "source_ref": "Scenario 1, Payment Stories EP01"}, {"id": "SCN-02", "seq": 119, "module": "Core", "source": "Jebaraj D", "title": "Nostro feed failure, stale Treasury funding view", "explain": "A payment can settle correctly while the Nostro ledger feed fails, leaving Treasury to fund from a stale screen. In this case the real funding requirement moved from 2 million to 5 million dollars before cut-off, and nothing alerted Treasury. The payment settled, but the bank was making funding decisions from outdated data, which is a critical operational risk even though no payment failed.", "takeaway": "The payment settled, but the bank was making funding decisions from outdated data, which is a critical operational risk even though no payment failed.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Payment settles correctly", "note": "Payment settles correctly"}, {"kind": "step", "title": "Nostro ledger feed fails", "note": "Nostro ledger feed fails"}, {"kind": "step", "title": "Treasury funds from stale screen", "note": "Treasury funds from a stale screen"}, {"kind": "step", "title": "Funding need moves to 5 million", "note": "Real funding requirement moved from 2 million to 5 million dollars before cut-off"}, {"kind": "step", "title": "Nothing alerts Treasury", "note": "Nothing alerted Treasury"}, {"kind": "step", "title": "Decisions from outdated data", "note": "Bank makes funding decisions from outdated data, a critical operational risk"}]}}, "level": "core", "source_ref": "Scenario 2, Payment Stories EP02"}, {"id": "SCN-03", "seq": 120, "module": "Core", "source": "Jebaraj D", "title": "One hour cut-off extension is not a small change", "explain": "Extending a branch cut-off for RTGS or NEFT by one hour sounds small, but a cut-off is a contract between the bank, the clearing system, and every downstream batch. Settlement windows are fixed, and core banking hours, batch jobs, standing instructions, and reconciliation all read the same clock. Moving the cut-off means re-validating everything that depends on it, and a payment accepted past the clearing window will be rejected downstream.", "takeaway": "Moving the cut-off means re-validating everything that depends on it, and a payment accepted past the clearing window will be rejected downstream.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Cut-off extended one hour", "note": "Branch cut-off for RTGS or NEFT extended by one hour"}, {"kind": "step", "title": "Cut-off is a contract", "note": "Cut-off is a contract between the bank, the clearing system, downstream batches"}, {"kind": "step", "title": "Settlement windows are fixed", "note": "Settlement windows are fixed"}, {"kind": "step", "title": "Dependent systems read same clock", "note": "Core banking hours, batch jobs, standing instructions, reconciliation read same clock"}, {"kind": "step", "title": "Re-validate dependencies", "note": "Moving the cut-off means re-validating everything that depends on it"}, {"kind": "step", "title": "Payment past window rejected", "note": "Payment accepted past the clearing window will be rejected downstream"}]}}, "level": "core", "source_ref": "Scenario 3, Payment BA Awareness EP22"}, {"id": "JEB-A03", "seq": 121, "module": "Core", "source": "Jebaraj D", "title": "camt.055 only works before settlement: check the lifecycle first", "explain": "A camt.055 cancellation only works while the payment is still moving through its lifecycle, from initiation through validation, processing and settlement. Once the payment has been settled and credited to the beneficiary, a camt.055 is rejected, and the bank receives a camt.029 with an RJCR status. At that point the only route is recovery: send a camt.056 to request the return of funds, or receive a pacs.004 with the funds back. The common mistake is sending a camt.055 after settlement, so the bank should check the payment's lifecycle stage first and then choose the right message.", "takeaway": "The common mistake is sending a camt.055 after settlement, so the bank should check the payment's lifecycle stage first and then choose the right message.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Check the lifecycle stage first", "note": "Find where the payment sits before choosing any message"}, {"kind": "step", "title": "Initiation to settlement", "note": "camt.055 works from initiation through validation, processing and settlement"}, {"kind": "decision", "title": "Already settled and credited?", "note": "Once settled and credited to the beneficiary, camt.055 is rejected"}, {"kind": "step", "title": "camt.029 with RJCR arrives", "note": "The bank receives a camt.029 with an RJCR status for the rejected request"}, {"kind": "step", "title": "Recover with camt.056 or pacs.004", "note": "Send camt.056 to request the return, or receive a pacs.004 with the funds back"}]}}, "level": "core", "source_ref": "https://www.linkedin.com/posts/jebaraj-d-65b5b01a_businessanalysis-payments-iso20022-share-7523941324891258880-bRuj/"}, {"id": "JEB-A05", "seq": 122, "module": "Core", "source": "Jebaraj D", "title": "pacs.009 COV rejected with FF01: read the reason code before re-crediting", "explain": "When a pacs.009 COV is rejected with reason code FF01, invalid account number, the money does not return to the customer account even though the payment itself failed. A rejected cover message does not necessarily mean the payment failed; it can be an account mapping issue, with the funds still held by the bank. The bank must investigate the reason code before re-crediting the customer, because crediting too quickly can pay the customer twice or send the funds to the wrong account. The reason code, not the rejection alone, decides the next step.", "takeaway": "The reason code, not the rejection alone, decides the next step.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "pacs.009 COV rejected with FF01", "note": "Cover rejected for invalid account number, yet the money does not return"}, {"kind": "decision", "title": "Did the payment itself fail?", "note": "A rejected cover does not necessarily mean the payment failed"}, {"kind": "step", "title": "Investigate the reason code", "note": "Check whether it is an account mapping issue with funds still held by the bank"}, {"kind": "step", "title": "Do not re-credit too quickly", "note": "Crediting too quickly can pay the customer twice or send funds to the wrong account"}, {"kind": "step", "title": "Let the reason code decide", "note": "The reason code, not the rejection alone, decides the next step"}]}}, "level": "core", "source_ref": "https://www.linkedin.com/posts/jebaraj-d-65b5b01a_businessanalysis-payments-iso20022-share-7521404558254866433-BAHR/"}, {"id": "JEB-A06", "seq": 123, "module": "Core", "source": "Jebaraj D", "title": "SSI beats the customer instruction: routing follows the agreed rule", "explain": "When a customer instruction conflicts with a Standing Settlement Instruction, the engine follows the SSI, because the SSI is a pre-agreed settlement instruction between the banks that names the preferred correspondent for a currency and a counterparty. In this case the customer asked for Citi New York as intermediary, but the engine chose Chase New York from the SSI, and a SwiftRef update did not change that. If the customer wants a different intermediary, the SSI must be updated first, or the payment message must explicitly override it. Routing is not only about the payment message; it is about the rules that govern the payment.", "takeaway": "Routing is not only about the payment message; it is about the rules that govern the payment.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Customer asks for Citi New York", "note": "Customer instruction names Citi New York as intermediary"}, {"kind": "step", "title": "Engine follows the SSI", "note": "SSI is a pre-agreed instruction naming the preferred correspondent"}, {"kind": "step", "title": "Chase New York is chosen", "note": "Engine chose Chase New York from the SSI, and a SwiftRef update did not change that"}, {"kind": "decision", "title": "Want a different intermediary?", "note": "To change it, update the SSI first or explicitly override it in the message"}, {"kind": "step", "title": "Update SSI or override in message", "note": "Routing follows the rules that govern the payment, not only the message"}]}}, "level": "core", "source_ref": "https://www.linkedin.com/posts/jebaraj-d-65b5b01a_businessanalysis-payments-paymentrouting-share-7520680137885974529-GQIQ/"}, {"id": "JEB-A08", "seq": 124, "module": "Core", "source": "Jebaraj D", "title": "pacs.009 ADV is a visibility tool, not the payment itself", "explain": "A pacs.009 ADV is an advice that funds are on the way, and it gives treasury visibility before the money arrives, for liquidity planning and forecasting. It is not a pacs.008 payment instruction, and it may carry only part of the amount, so when treasury expects EUR 20 million but sees EUR 18 million, the missing EUR 2 million is in transit rather than lost. Treating the advice as if it were the payment itself is the mistake; the two messages have different purposes, and treasury needs to see the difference. A pacs.009 ADV tells the receiving bank that a large payment is coming, but the payment itself is still the pacs.008.", "takeaway": "A pacs.009 ADV tells the receiving bank that a large payment is coming, but the payment itself is still the pacs.008.", "visual": {"type": "diagram", "diagram": {"centre": "pacs.009 ADV: advice, not payment", "parts": [{"label": "Treasury visibility", "note": "Gives treasury visibility before the money arrives"}, {"label": "Liquidity planning", "note": "Supports liquidity planning and forecasting"}, {"label": "Part of the amount", "note": "May carry only part of the amount, so EUR 18 million of EUR 20 million is seen"}, {"label": "Missing EUR 2 million in transit", "note": "The missing EUR 2 million is in transit rather than lost"}, {"label": "pacs.008 is the payment", "note": "The payment itself is still the pacs.008, not the advice"}]}}, "level": "core", "source_ref": "https://www.linkedin.com/posts/jebaraj-d-65b5b01a_payments-iso20022-pacs009adv-share-7519586248601096192-0_96/"}, {"id": "JEB-A09", "seq": 125, "module": "Core", "source": "Jebaraj D", "title": "Warehousing is risk management: re-validate a future-dated payment at execution", "explain": "A future-dated payment that is accepted on Monday and stored for execution on Friday is warehoused, and warehousing is a commitment to execute, not just storage. Between submission and execution the account balance, the account details, the sanctions status and the cut-off times can all change, so a payment that was valid on Monday is not necessarily valid on Friday. At execution the payment must be re-validated on balance, account status, sanctions and cut-offs, and then executed or rejected. Warehousing is risk management between submission and execution, not a guarantee.", "takeaway": "Warehousing is risk management between submission and execution, not a guarantee.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Payment accepted on Monday", "note": "Future-dated payment accepted and stored for execution on Friday"}, {"kind": "step", "title": "Warehousing is a commitment", "note": "Warehousing commits to execute, it is not just storage"}, {"kind": "step", "title": "Things change before Friday", "note": "Balance, account details, sanctions status and cut-off times can all change"}, {"kind": "step", "title": "Re-validate at execution", "note": "Check balance, account status, sanctions and cut-offs again at execution"}, {"kind": "decision", "title": "Still valid on Friday?", "note": "A payment valid on Monday is not necessarily valid on Friday"}, {"kind": "step", "title": "Execute or reject", "note": "Execute the payment, or reject it if re-validation fails"}]}}, "level": "core", "source_ref": "https://www.linkedin.com/posts/jebaraj-d-65b5b01a_businessanalysis-payments-paymentprocessing-share-7519227928900124672-FV0k/"}, {"id": "JEB-A12", "seq": 126, "module": "Core", "source": "Jebaraj D", "title": "camt.056 with no answer: every waiting state needs a way out", "explain": "When a bank sends a camt.056 asking for a return of funds and receives no answer at all, the payment sits in a waiting state: not completed and not rejected, just stuck. The way out is a camt.029 status check, followed by waiting for a response or escalating if the beneficiary does not reply within the agreed time. Every waiting state needs a way in, a way out, a time limit, a status check and an escalation route, and the bank should agree those in advance. The open questions are how long to wait before checking with a camt.029, how long before escalating, and what happens if there is no response at all.", "takeaway": "The open questions are how long to wait before checking with a camt.029, how long before escalating, and what happens if there is no response at all.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "camt.056 sent, no answer", "note": "Bank asks for a return of funds and receives no answer at all"}, {"kind": "step", "title": "Payment sits waiting", "note": "Not completed and not rejected, just stuck in a waiting state"}, {"kind": "step", "title": "Send camt.029 status check", "note": "Check the status and wait for a response"}, {"kind": "decision", "title": "Reply within agreed time?", "note": "Escalate if the beneficiary does not reply within the agreed time"}, {"kind": "step", "title": "Agree the way out in advance", "note": "Every waiting state needs a way in, a way out, a time limit and an escalation route"}]}}, "level": "core", "source_ref": "https://www.linkedin.com/posts/jebaraj-d-65b5b01a_businessanalysis-payments-iso20022-share-7517774876166770688-pJVi/"}, {"id": "JEB-B02", "seq": 127, "module": "Core", "source": "Jebaraj D", "title": "Payment controls: sequential, parallel, or mixed", "explain": "When thousands of payments arrive at once, running every control one after another is not always the smartest design. If the account is closed and the defined outcome is rejection, the payment can be rejected after the account check, unless the business requires it to be flagged for other checks too. Compliance and fraud checks can run in parallel, so two checks taking 3 and 4 seconds finish in 4 seconds together instead of 7 in sequence, which can decide whether the SLA is met. The BA must also define what happens when a control fails, times out, or returns an inconclusive result, because otherwise the decision is left to technical defaults.", "takeaway": "The BA must also define what happens when a control fails, times out, or returns an inconclusive result, because otherwise the decision is left to technical defaults.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Thousands of payments arrive", "note": "Running every control one after another is not always the smartest design"}, {"kind": "decision", "title": "Account closed?", "note": "If the account is closed and the outcome is rejection, reject after the account check"}, {"kind": "step", "title": "Run compliance and fraud in parallel", "note": "Two checks taking 3 and 4 seconds finish in 4 seconds together instead of 7"}, {"kind": "step", "title": "Meet the SLA", "note": "Parallel checks can decide whether the SLA is met"}, {"kind": "step", "title": "Define failure outcomes", "note": "Define what happens when a control fails, times out or returns inconclusive"}]}}, "level": "core", "source_ref": "https://www.linkedin.com/posts/jebaraj-d-65b5b01a_paymentba-businessanalysis-payments-share-7515250558673252352-q0x1/"}, {"id": "JEB-B04", "seq": 128, "module": "Core", "source": "Jebaraj D", "title": "pacs.009 COV and ADV are use cases, not separate messages", "explain": "COV and ADV are not separate messages in the ISO 20022 catalogue. They use the same underlying pacs.009 message, Financial Institution Credit Transfer, with a different business use case: Core is a bank-to-bank transfer of funds, COV is the cover or funding leg for an underlying customer payment, and ADV is advice of an expected funds movement. CBPR+ defines Core, Cover and Advise for cross-border payments, while the EPC SEPA schemes do not use pacs.009 at all. A requirement that says 'we need pacs.009' is incomplete until it also names the use case, the scheme, the usage guideline and the business context.", "takeaway": "A requirement that says 'we need pacs.009' is incomplete until it also names the use case, the scheme, the usage guideline and the business context.", "visual": {"type": "diagram", "diagram": {"centre": "One pacs.009, three use cases", "parts": [{"label": "Core: bank-to-bank transfer", "note": "A bank-to-bank transfer of funds"}, {"label": "COV: cover leg", "note": "The cover or funding leg for an underlying customer payment"}, {"label": "ADV: advice of funds movement", "note": "Advice of an expected funds movement"}, {"label": "CBPR+ defines all three", "note": "CBPR+ defines Core, Cover and Advise for cross-border payments"}, {"label": "SEPA does not use pacs.009", "note": "The EPC SEPA schemes do not use pacs.009 at all"}, {"label": "Name the use case", "note": "A pacs.009 requirement must also name the use case, scheme and business context"}]}}, "level": "core", "source_ref": "https://www.linkedin.com/posts/jebaraj-d-65b5b01a_iso20022-cbprplus-payments-share-7513788744081088512-PKGT/"}, {"id": "JEB-B05", "seq": 129, "module": "Core", "source": "Jebaraj D", "title": "Direct Debit migration: reuse is not a business decision", "explain": "On a Direct Debit migration to a new platform, the existing process had been defined for Germany and worked well there, so reusing it looked efficient. But the Netherlands has its own local specification, the Overstapservice, a bank-switching service that lets Direct Debits continue after a customer moves to a new Dutch bank, so an incoming Direct Debit for a closed account may need to be redirected rather than rejected. Reuse is an implementation strategy, not a business decision, so before agreeing to reuse, check whether the requirement is a common scheme rule or a local specification, and whether the new country adds requirements the existing logic never had to meet.", "takeaway": "Reuse is an implementation strategy, not a business decision, so before agreeing to reuse, check whether the requirement is a common scheme rule or a local specification, and whether the new country adds requirements the existing logic never had to meet.", "visual": {"type": "diagram", "diagram": {"centre": "Reuse is not a business decision", "parts": [{"label": "German process worked well", "note": "The existing process was defined for Germany and worked well there"}, {"label": "Dutch Overstapservice", "note": "A bank-switching service that lets Direct Debits continue after a move"}, {"label": "Redirect, not reject", "note": "An incoming Direct Debit for a closed account may need redirecting, not rejecting"}, {"label": "Common rule or local spec?", "note": "Check whether the requirement is a common scheme rule or a local specification"}, {"label": "New country requirements", "note": "Check whether the new country adds requirements the existing logic never met"}]}}, "level": "core", "source_ref": "https://www.linkedin.com/posts/jebaraj-d-65b5b01a_paymentba-businessanalysis-payments-share-7513426888493633536-Yyex/"}, {"id": "JEB-B07", "seq": 130, "module": "Core", "source": "Jebaraj D", "title": "One statement line, many ledger entries: reconcile the batch", "explain": "Payments are settled in batches, so one statement line can represent many ledger entries that share a common batch reference. Reconciliation must group the entries using the batch reference and reconcile the group together against the statement line, rather than matching a single entry. If one entry is missing, the whole group breaks and a temporary GL entry may be posted during investigation. The payment engine must keep the batch reference linked across the items, and the point is to understand why the batch exists, not just how it matches.", "takeaway": "The payment engine must keep the batch reference linked across the items, and the point is to understand why the batch exists, not just how it matches.", "visual": {"type": "diagram", "diagram": {"centre": "Reconcile the batch, not one entry", "parts": [{"label": "One statement line, many entries", "note": "One statement line can represent many ledger entries"}, {"label": "Common batch reference", "note": "The entries share a common batch reference"}, {"label": "Group and reconcile together", "note": "Group the entries by the batch reference and reconcile the group together"}, {"label": "One missing entry breaks the group", "note": "If one entry is missing, the whole group breaks"}, {"label": "Temporary GL entry", "note": "A temporary GL entry may be posted during investigation"}, {"label": "Keep the reference linked", "note": "The payment engine must keep the batch reference linked across the items"}]}}, "level": "core", "source_ref": "https://www.linkedin.com/posts/jebaraj-d-65b5b01a_payments-reconciliation-banking-share-7512394531091267584-sqSO/"}, {"id": "JEB-B08", "seq": 131, "module": "Core", "source": "Jebaraj D", "title": "Treasury waiting on a Nostro credit: choose the message by the decision", "explain": "A Treasury desk waiting for a Nostro credit before releasing an outgoing payment needs to know one thing before the cut-off: has the expected credit arrived. The camt.053 statement contains the account movements and the balance after the close of business, so it cannot answer a question that must be decided during the day. The camt.052 intraday report and the camt.054 debit or credit notification are the candidates for an intraday answer, and the post leaves the choice open, with the poll split evenly between them. The real lesson is to choose the message by the business decision it must support, not by its definition alone.", "takeaway": "The real lesson is to choose the message by the business decision it must support, not by its definition alone.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Treasury waits for Nostro credit", "note": "Treasury needs the credit before releasing an outgoing payment"}, {"kind": "decision", "title": "Has the expected credit arrived?", "note": "The question must be answered before the cut-off"}, {"kind": "step", "title": "camt.053 cannot answer it", "note": "The statement shows the balance after the close of business, too late for the day"}, {"kind": "step", "title": "camt.052 and camt.054 are candidates", "note": "The intraday report and the debit or credit notification can answer during the day"}, {"kind": "step", "title": "Choose by the decision", "note": "Choose the message by the business decision it must support, not by its definition alone"}]}}, "level": "core", "source_ref": "https://www.linkedin.com/posts/jebaraj-d-65b5b01a_questionoftheweek-iso20022-payments-ugcPost-7512339237808111616-jBRA/"}, {"id": "JEB-B09", "seq": 132, "module": "Core", "source": "Jebaraj D", "title": "Routing rules decide the engine, not the message", "explain": "A perfectly valid pain.001 can still become a production incident when the routing rules send it to the wrong payment engine. The payment business defines the routing rules and the acquisition layer applies them; the pain.001 provides the clues, such as instrument, currency and amount, but the engine does not invent or override the route. If the rules are incomplete or incorrectly applied, a valid USD payment can reach an instant payment engine that only processes EUR, and the payment gets held, delayed or rejected even though the customer instruction was correct. The message provides the clues, and the business rules determine the route.", "takeaway": "The message provides the clues, and the business rules determine the route.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Valid pain.001 arrives", "note": "A perfectly valid pain.001 can still become a production incident"}, {"kind": "step", "title": "Routing rules are defined", "note": "The payment business defines the routing rules and the acquisition layer applies them"}, {"kind": "step", "title": "pain.001 provides the clues", "note": "Instrument, currency and amount are the clues, but the engine does not invent the route"}, {"kind": "decision", "title": "Rules complete and correct?", "note": "If the rules are incomplete or incorrectly applied, the route can be wrong"}, {"kind": "step", "title": "USD payment reaches EUR engine", "note": "A valid USD payment can reach an instant payment engine that only processes EUR"}, {"kind": "step", "title": "Payment held, delayed or rejected", "note": "The payment is held, delayed or rejected even though the instruction was correct"}]}}, "level": "core", "source_ref": "https://www.linkedin.com/posts/jebaraj-d-65b5b01a_iso20022-payments-paymentstories-share-7511976136898174976-pkHh/"}, {"id": "JEB-B12", "seq": 133, "module": "Core", "source": "Jebaraj D", "title": "API success is not a business decision", "explain": "An API can return HTTP 200 because the call was technically successful, while the payment engine still rejects the payment based on the response and the business rules. Checking whether an account is open or closed is not enough if the engine also needs the account currency and the product does not support FX, so the BA must ask what information the engine needs to make its decision. A fraud score works the same way: the fraud system owns its scoring model, but the engine must translate the score into an action, for example above 90 reject, 50 to 90 process with a customer alert, and below 50 process normally. An API can be technically correct and still produce the wrong business outcome if the business rules are not defined, so start with the business decision the process needs to make, not the API to build.", "takeaway": "An API can be technically correct and still produce the wrong business outcome if the business rules are not defined, so start with the business decision the process needs to make, not the API to build.", "visual": {"type": "diagram", "diagram": {"centre": "API success is not a business decision", "parts": [{"label": "HTTP 200 is only technical", "note": "An API can return HTTP 200 while the engine still rejects the payment"}, {"label": "Account currency matters", "note": "Checking open or closed is not enough if the engine also needs the currency"}, {"label": "Fraud score above 90: reject", "note": "Above 90 reject, the engine translates the score into an action"}, {"label": "Score 50 to 90: alert", "note": "From 50 to 90 process with a customer alert"}, {"label": "Score below 50: process normally", "note": "Below 50 process the payment normally"}, {"label": "Start with the business decision", "note": "Start with the business decision the process needs to make, not the API"}]}}, "level": "core", "source_ref": "https://www.linkedin.com/posts/jebaraj-d-65b5b01a_paymentba-businessanalysis-payments-share-7509093919327178753-6aMd/"}, {"id": "JEB-C02", "seq": 134, "module": "Core", "source": "Jebaraj D", "title": "Optional in the message, mandatory for the flow: the cover payment reference", "explain": "In a four-bank cover payment, Bank A sends pacs.008 to Bank B and a pacs.009 cover to intermediary Bank C, which must link the cover to the customer payment using the same UETR and related remittance reference. The pacs.009 RltdRmtInf field carries that link, and although it is optional in the message, the intermediary cannot reconcile the cover without it. Optional or mandatory is a property of the message, not of the process, so a field marked optional can still be required to make the payment work. The message flow and the field status must be handled as two separate things.", "takeaway": "The message flow and the field status must be handled as two separate things.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Bank A sends pacs.008 to Bank B", "note": "The customer payment goes directly to the beneficiary bank"}, {"kind": "step", "title": "Bank A sends pacs.009 cover to Bank C", "note": "The cover goes to the intermediary bank"}, {"kind": "step", "title": "Link cover with UETR and reference", "note": "Bank C must link the cover using the same UETR and remittance reference"}, {"kind": "step", "title": "RltdRmtInf carries the link", "note": "The pacs.009 RltdRmtInf field carries that link"}, {"kind": "decision", "title": "Optional in the message?", "note": "The field is optional in the message, yet the intermediary cannot reconcile without it"}, {"kind": "step", "title": "Treat flow and field status separately", "note": "Optional or mandatory is a property of the message, not of the process"}]}}, "level": "core", "source_ref": "https://www.linkedin.com/posts/jebaraj-d-65b5b01a_paymentba-payments-businessanalysis-share-7506541291170627585--4Vy/"}, {"id": "JEB-C03", "seq": 135, "module": "Core", "source": "Jebaraj D", "title": "Serial or cover: the remitting bank decides by accounts and currency", "explain": "In the serial method the remitting bank sends one pacs.008 with settlement to the beneficiary bank, which suits cases where correspondent or nostro accounts exist and the settlement currency matches the payer account currency. In the cover method the pacs.008 goes without settlement and a separate pacs.009 cover moves the funds through an intermediary, which suits cases with no direct relationship or a different settlement currency. The bank decides by checking whether nostro accounts exist in the beneficiary bank's country and which settlement systems the currency needs, such as Fedwire, TARGET2 or CHAPS. The cover method adds an extra leg, so the choice is about infrastructure and settlement, not about the customer instruction.", "takeaway": "The cover method adds an extra leg, so the choice is about infrastructure and settlement, not about the customer instruction.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "decision", "title": "Do nostro accounts exist?", "note": "Check whether nostro accounts exist in the beneficiary bank country"}, {"kind": "decision", "title": "Does the currency match?", "note": "Check whether the settlement currency matches the payer account currency"}, {"kind": "step", "title": "Serial: one pacs.008 with settlement", "note": "Suits cases where correspondent accounts exist and the currency matches"}, {"kind": "step", "title": "Cover: pacs.008 plus pacs.009", "note": "Suits cases with no direct relationship or a different settlement currency"}, {"kind": "step", "title": "Check the settlement systems", "note": "Check which systems the currency needs, such as Fedwire, TARGET2 or CHAPS"}, {"kind": "step", "title": "Choice is about infrastructure", "note": "The cover method adds an extra leg, so the choice is about settlement"}]}}, "level": "core", "source_ref": "https://www.linkedin.com/posts/jebaraj-d-65b5b01a_paymentba-payments-businessanalysis-share-7505094204532899840-88D5/"}, {"id": "JEB-C04", "seq": 136, "module": "Core", "source": "Jebaraj D", "title": "MT is retiring, not retired: know which messages survive November 2026", "explain": "The CBPR+ November 2026 deadline is often called the end of MT for cross-border payments, but the picture is mixed: many MT messages migrate to MX by then, some were already retired, and others keep running after the deadline for specialised or domestic use. The reason SWIFT is driving the migration is that MT cannot carry the rich data, structured addresses and granularity that compliance and monitoring need. So the right description is that MT is retiring, not retired, and a BA should know the nuance rather than repeat the slogan. That nuance matters in migration planning, because the end date is not the same for every message.", "takeaway": "That nuance matters in migration planning, because the end date is not the same for every message.", "visual": {"type": "diagram", "diagram": {"centre": "MT is retiring, not retired", "parts": [{"label": "Many migrate by November 2026", "note": "Many MT messages migrate to MX by the deadline"}, {"label": "Some already retired", "note": "Some messages were already retired before the deadline"}, {"label": "Others keep running after the deadline", "note": "Others keep running for specialised or domestic use"}, {"label": "MT cannot carry rich data", "note": "MT cannot carry the rich data, structured addresses and granularity needed"}, {"label": "Compliance and monitoring need more", "note": "Compliance and monitoring need the richer data that MX carries"}, {"label": "End date differs per message", "note": "The end date is not the same for every message"}]}}, "level": "core", "source_ref": "https://www.linkedin.com/posts/jebaraj-d-65b5b01a_paymentba-paymentmisconceptions-payments-share-7504730202346889216-B6ip/"}, {"id": "JEB-C05", "seq": 137, "module": "Core", "source": "Jebaraj D", "title": "An optional field can still be mandatory for processing", "explain": "In pain.001, a field marked optional may still be needed by the sender bank, for example the sending business agent's address and postcode, to process the payment correctly. If the field is left out, the beneficiary or intermediary bank may fall back to default values, which can cause compliance issues, errors or deductions even when the payment goes through. A field's M, O or C status describes the message, while whether the information must be captured is decided by the business rules of the process. The BA should therefore always ask whether the field is needed for the process, rather than trusting the message status alone.", "takeaway": "The BA should therefore always ask whether the field is needed for the process, rather than trusting the message status alone.", "visual": {"type": "diagram", "diagram": {"centre": "Optional can still be mandatory", "parts": [{"label": "Optional field, needed by the bank", "note": "A field marked optional may still be needed by the sender bank"}, {"label": "Agent address and postcode", "note": "For example the sending business agent address and postcode"}, {"label": "Default values cause problems", "note": "Falling back to defaults can cause compliance issues, errors or deductions"}, {"label": "M, O or C describes the message", "note": "A field status describes the message, not the process"}, {"label": "Business rules decide capture", "note": "Whether the information must be captured is decided by business rules"}, {"label": "Ask whether the field is needed", "note": "Always ask whether the field is needed for the process"}]}}, "level": "core", "source_ref": "https://www.linkedin.com/posts/jebaraj-d-65b5b01a_paymentba-businessanalysis-payments-share-7504004808090017793-9JFt/"}, {"id": "JEB-C06", "seq": 138, "module": "Core", "source": "Jebaraj D", "title": "Sequential for validation, parallel for screening", "explain": "Some payment controls depend on the result of the previous one, so they run one after another and stop the payment as soon as one fails, while others have no dependency and can run at the same time. Validation checks such as account number and currency, name matching, account status and closure belong in the sequential group, while sanction screening, fraud screening, limit checks, risk assessment and regulatory checks can run in parallel. The design question is therefore which controls depend on each other and which do not, because that decides both speed and the stopping point. For a finance BA, the rule of thumb is sequential for validation and parallel for screening.", "takeaway": "For a finance BA, the rule of thumb is sequential for validation and parallel for screening.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Controls with dependencies run in sequence", "note": "They run one after another and stop the payment as soon as one fails"}, {"kind": "step", "title": "Validation checks are sequential", "note": "Account number and currency, name matching, account status and closure"}, {"kind": "step", "title": "Controls without dependencies run in parallel", "note": "They can run at the same time because they have no dependency"}, {"kind": "step", "title": "Screening checks are parallel", "note": "Sanction, fraud, limit, risk and regulatory checks"}, {"kind": "step", "title": "Decide by dependency", "note": "Which controls depend on each other decides both speed and the stopping point"}, {"kind": "step", "title": "Sequential validation, parallel screening", "note": "The rule of thumb is sequential for validation and parallel for screening"}]}}, "level": "core", "source_ref": "https://www.linkedin.com/posts/jebaraj-d-65b5b01a_paymentba-payments-businessanalysis-share-7498938644460744704-Jt5r/"}, {"id": "JEB-C08", "seq": 139, "module": "Core", "source": "Jebaraj D", "title": "MT to MX: same SWIFT, different shape of data", "explain": "MT messages are FIN messages written as structured text with character limits, while MX messages are ISO 20022 XML with properly structured data such as name, address, town and country. Converting a payment means translating it field by field and message by message, and the translator must also look at the MT structure, correspondent and account information and the business rules to derive the right MX settlement method. Banks must migrate certain payment types to MX under CBPR+, and getting the mapping right early is what keeps straight-through processing high. The conversion is a business mapping exercise, not just a format change.", "takeaway": "The conversion is a business mapping exercise, not just a format change.", "visual": {"type": "diagram", "diagram": {"centre": "MT to MX: same SWIFT, different data", "parts": [{"label": "MT: structured text, character limits", "note": "MT messages are FIN messages written as structured text with character limits"}, {"label": "MX: structured XML data", "note": "MX messages are ISO 20022 XML with properly structured data"}, {"label": "Translate field by field", "note": "Converting a payment means translating it field by field and message by message"}, {"label": "Derive the settlement method", "note": "Use MT structure, correspondent and account information and business rules"}, {"label": "Migrate payment types to MX", "note": "Banks must migrate certain payment types to MX under CBPR+"}, {"label": "Business mapping, not format change", "note": "Getting the mapping right early keeps straight-through processing high"}]}}, "level": "core", "source_ref": "https://www.linkedin.com/posts/jebaraj-d-65b5b01a_paymentba-payments-iso20022-share-7493950169122713600-gtls/"}, {"id": "JEB-C10", "seq": 140, "module": "Core", "source": "Jebaraj D", "title": "Design for failure: every solution can fail somewhere", "explain": "A payment solution can fail in three places: functionally, when requirements change or were captured wrongly; technically, when processing is delayed, a system is down or performance drops; and in business terms, when a payment is processed with wrong details or a check like verification of payee fails. The BA should plan for each kind of failure, know the alternative when a solution fails, and keep a communication plan with the business and stakeholders. Before implementing, the question to ask is whether all possible failure scenarios have been covered, because one payment change rarely touches only one application. A solution owner should prioritise the fix and evaluate the options, not chase perfection.", "takeaway": "A solution owner should prioritise the fix and evaluate the options, not chase perfection.", "visual": {"type": "diagram", "diagram": {"centre": "Design for failure: three places", "parts": [{"label": "Functional failure", "note": "Requirements change or were captured wrongly"}, {"label": "Technical failure", "note": "Processing is delayed, a system is down or performance drops"}, {"label": "Business failure", "note": "A payment is processed with wrong details or a check like verification of payee fails"}, {"label": "Plan for each kind of failure", "note": "The BA should plan for each kind of failure and know the alternative"}, {"label": "Keep a communication plan", "note": "Keep a communication plan with the business and stakeholders"}, {"label": "Cover all failure scenarios", "note": "Ask whether all possible failure scenarios have been covered before implementing"}]}}, "level": "core", "source_ref": "https://www.linkedin.com/posts/jebaraj-d-65b5b01a_paymentba-businessanalysis-payments-share-7495398556187398144-SUI-/"}, {"id": "JEB-C14", "seq": 141, "module": "Core", "source": "Jebaraj D", "title": "Do not document the requirement, decode it", "explain": "A high-level need such as letting a customer schedule a payment looks simple, but it has to be decoded into business rules: a payment can be scheduled for a future date, recreated or rescheduled with a new effective date, never scheduled for a date in the past, scheduled for several payment types, and cancelled if it is not processed on the requested date. The same applies to messages: in a request to pay such as pain.013, the execution date should not be shown to the customer when the data element is empty. The BA's job is to find the business rule behind the requirement rather than mapping one field to another. A requirement that cannot be written as a simple rule is not a simple requirement.", "takeaway": "A requirement that cannot be written as a simple rule is not a simple requirement.", "visual": {"type": "diagram", "diagram": {"centre": "Decode the requirement, do not document it", "parts": [{"label": "Schedule for a future date", "note": "A payment can be scheduled for a future date"}, {"label": "Recreate or reschedule", "note": "A payment can be recreated or rescheduled with a new effective date"}, {"label": "Never schedule in the past", "note": "A payment is never scheduled for a date in the past"}, {"label": "Several payment types", "note": "A payment can be scheduled for several payment types"}, {"label": "Cancel if not processed on the date", "note": "Cancel the payment if it is not processed on the requested date"}, {"label": "pain.013 execution date", "note": "In a request to pay, do not show the execution date when the data is empty"}]}}, "level": "core", "source_ref": "https://www.linkedin.com/posts/jebaraj-d-65b5b01a_paymentba-payments-businessanalysis-share-7497573345773674497-o5Um/"}, {"id": "INS-001", "seq": 142, "module": "Core", "source": "Harish Kavire", "title": "End-to-end card transaction flow", "explain": "A card transaction moves through four stages across four parties. Authorisation is the issuer approving the payment at the point of sale, clearing is the network exchanging the transaction records between acquirer and issuer, settlement is the movement of funds between the banks, and reconciliation is matching the clearing records, the settlement positions and the ledger postings so every amount agrees. The issuer, the acquirer, the network and the merchant each have a distinct role at each stage, and a failure at any stage has a different owner and a different fix.", "takeaway": "The issuer, the acquirer, the network and the merchant each have a distinct role at each stage, and a failure at any stage has a different owner and a different fix.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Authorisation", "note": "The issuer approves the payment at the point of sale."}, {"kind": "step", "title": "Clearing", "note": "The network exchanges records between acquirer and issuer."}, {"kind": "step", "title": "Settlement", "note": "Funds move between the banks."}, {"kind": "step", "title": "Reconciliation", "note": "Clearing records, settlement positions and ledger postings agree."}]}}, "level": "core", "source_ref": "HAR-01"}, {"id": "INS-002", "seq": 143, "module": "Core", "source": "Harish Kavire", "title": "Debit versus credit card transaction behaviour", "explain": "A debit card payment draws directly on the customer's account balance, so the funds leave the account at authorisation and settlement moves money the customer already holds. A credit card payment draws on a credit line, so the issuer funds the payment and the customer repays later, which changes the settlement timing, the interest treatment and the risk the issuer carries. The account and settlement implications are different even though the customer experience at the terminal looks the same.", "takeaway": "The account and settlement implications are different even though the customer experience at the terminal looks the same.", "visual": {"type": "diagram", "diagram": {"centre": "Debit versus credit card payment", "parts": [{"label": "Debit card", "note": "Draws on the customer balance, funds leave at authorisation"}, {"label": "Credit card", "note": "Draws on a credit line, issuer funds it, customer repays later"}, {"label": "Settlement and risk", "note": "Timing, interest treatment and issuer risk differ"}]}}, "level": "core", "source_ref": "HAR-01"}, {"id": "INS-003", "seq": 144, "module": "Core", "source": "Harish Kavire", "title": "Card authorisation decision", "explain": "When a card is presented, the issuer decides whether to approve or decline the payment. The issuer checks the card status, the available funds or credit, the transaction limits and the fraud rules, and then returns an approval or a decline with a response code. The outcome depends on all of these checks together, so a payment can be declined even when the balance is sufficient if a fraud rule or a limit is breached.", "takeaway": "The outcome depends on all of these checks together, so a payment can be declined even when the balance is sufficient if a fraud rule or a limit is breached.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Card presented", "note": "The issuer must decide whether to approve or decline."}, {"kind": "decision", "title": "Check card status", "note": "The issuer checks the card status."}, {"kind": "decision", "title": "Check funds or credit", "note": "The issuer checks available funds or credit."}, {"kind": "decision", "title": "Check limits and fraud rules", "note": "Limits and fraud rules are checked."}, {"kind": "step", "title": "Return approval or decline", "note": "An approval or decline is returned with a response code."}]}}, "level": "core", "source_ref": "HAR-01"}, {"id": "INS-004", "seq": 145, "module": "Core", "source": "Harish Kavire", "title": "Card settlement and reconciliation", "explain": "After clearing, the settlement position is the net amount each bank owes or is owed, and the ledger postings must match that position exactly. Reconciliation compares the clearing records, the settlement positions and the ledger postings, and any break between them is investigated rather than written off. A settlement that does not reconcile means money is unaccounted for, which is a control failure even if the customer-facing payment appeared to succeed.", "takeaway": "A settlement that does not reconcile means money is unaccounted for, which is a control failure even if the customer-facing payment appeared to succeed.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Clearing completes", "note": "The settlement position is the net amount each bank owes."}, {"kind": "step", "title": "Compare the records", "note": "Clearing records, settlement positions and ledger postings."}, {"kind": "decision", "title": "Do the records agree", "note": "Any break between them is investigated."}, {"kind": "step", "title": "Investigate the break", "note": "A break is investigated rather than written off."}]}}, "level": "core", "source_ref": "HAR-01"}, {"id": "INS-005", "seq": 146, "module": "Core", "source": "Harish Kavire", "title": "Chargeback lifecycle and reason codes for disputes", "explain": "A chargeback starts when a cardholder disputes a transaction and the issuer raises it with the scheme. The acquirer and merchant respond with representment evidence, the scheme applies its timelines and reason codes, and the financial impact moves between issuer, acquirer and merchant as the case progresses. Knowing the reason code matters because it decides what evidence is needed and who bears the loss at each stage.", "takeaway": "Knowing the reason code matters because it decides what evidence is needed and who bears the loss at each stage.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Cardholder disputes", "note": "The cardholder disputes a transaction; the issuer raises it."}, {"kind": "step", "title": "Acquirer and merchant respond", "note": "Representment evidence is provided."}, {"kind": "step", "title": "Scheme applies rules", "note": "The scheme applies its timelines and reason codes."}, {"kind": "step", "title": "Financial impact moves", "note": "Impact moves between issuer, acquirer and merchant."}]}}, "level": "core", "source_ref": "HAR-01"}, {"id": "INS-028", "seq": 147, "module": "Core", "source": "Harish Kavire", "title": "NEFT, RTGS and IMPS comparison", "explain": "NEFT, RTGS and IMPS are three different domestic rails with different operating models. NEFT settles in batches and is suited to payments that can wait, RTGS settles each payment individually in central bank money and is suited to high value payments that must be final, and IMPS settles instantly around the clock and is suited to payments that must arrive immediately. Compare them on speed, availability, settlement model and customer use case, and use the current scheme rules rather than an old summary.", "takeaway": "Compare them on speed, availability, settlement model and customer use case, and use the current scheme rules rather than an old summary.", "visual": {"type": "diagram", "diagram": {"centre": "NEFT, RTGS and IMPS", "parts": [{"label": "NEFT", "note": "Settles in batches, for payments that can wait"}, {"label": "RTGS", "note": "Settles each payment individually in central bank money"}, {"label": "IMPS", "note": "Settles instantly around the clock"}, {"label": "How to compare", "note": "Speed, availability, settlement model and use case"}]}}, "level": "core", "source_ref": "HAR-03"}, {"id": "INS-027", "seq": 148, "module": "Core", "source": "Harish Kavire", "title": "Loan lifecycle overview", "explain": "A loan moves from application through decision, agreement, disbursement, servicing, repayment and closure. At application the bank collects the request and the supporting information, at decision it assesses credit and affordability, at agreement it records the terms, at disbursement it releases the funds, during servicing it collects repayments and manages changes, and at closure it confirms the balance is settled and the account is closed. Each stage has its own data, controls and hand-offs, so a failure at one stage does not always show up until a later stage.", "takeaway": "Each stage has its own data, controls and hand-offs, so a failure at one stage does not always show up until a later stage.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Application", "note": "The bank collects the request and supporting information."}, {"kind": "step", "title": "Decision", "note": "Credit and affordability are assessed."}, {"kind": "step", "title": "Agreement", "note": "The terms are recorded."}, {"kind": "step", "title": "Disbursement", "note": "The funds are released."}, {"kind": "step", "title": "Servicing", "note": "Repayments are collected and changes managed."}, {"kind": "step", "title": "Repayment and closure", "note": "The balance is confirmed settled and the account closed."}]}}, "level": "core", "source_ref": "HAR-03"}, {"id": "INS-034", "seq": 149, "module": "Core", "source": "Harish Kavire", "title": "Approved loan but disbursement fails", "explain": "A loan can be approved and still fail to disburse. Trace the path from approval through account validation, the disbursement instruction, the ledger posting and the customer communication, because the break can sit at any of these points. A valid approval with a wrong account, a failed instruction or a missing ledger posting all look the same to the customer, who simply sees that the money has not arrived, so the investigation must check each stage in order rather than assuming the approval was the problem.", "takeaway": "A valid approval with a wrong account, a failed instruction or a missing ledger posting all look the same to the customer, who simply sees that the money has not arrived, so the investigation must check each stage in order rather than assuming the approval was the problem.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Approval", "note": "The loan is approved."}, {"kind": "step", "title": "Account validation", "note": "The account details are validated."}, {"kind": "step", "title": "Disbursement instruction", "note": "The instruction to release funds is sent."}, {"kind": "step", "title": "Ledger posting", "note": "The posting is recorded in the ledger."}, {"kind": "step", "title": "Customer communication", "note": "The customer is told whether the money arrived."}, {"kind": "step", "title": "Check each stage in order", "note": "The break can sit at any stage, so check them all."}]}}, "level": "core", "source_ref": "HAR-03"}, {"id": "INS-090", "seq": 150, "module": "Core", "source": "Harish Kavire", "title": "Settlement cycle and customer communication", "explain": "A settlement cycle is the period after which funds move between banks, and T+1 or T+2 are only examples of how long that can take. The actual timing depends on the scheme and the product, so always use the scheme and product specific rules rather than a generic T+1 or T+2. Customer communication must state the real timing for that product, because telling a customer the money will arrive tomorrow when the scheme settles in two days creates a complaint that was avoidable.", "takeaway": "Customer communication must state the real timing for that product, because telling a customer the money will arrive tomorrow when the scheme settles in two days creates a complaint that was avoidable.", "visual": {"type": "diagram", "diagram": {"centre": "Settlement cycle and customer timing", "parts": [{"label": "Settlement cycle", "note": "The period after which funds move between banks."}, {"label": "T+1 or T+2", "note": "Only examples of how long a cycle can take."}, {"label": "Scheme and product rules", "note": "The actual timing depends on these, not a generic label."}, {"label": "Customer communication", "note": "Must state the real timing for that product."}]}}, "level": "core", "source_ref": "HAR-13"}, {"id": "INS-069", "seq": 151, "module": "Core", "source": "Harish Kavire", "title": "Checkout, authentication, status, refund and reversal APIs", "explain": "A payment product exposes several APIs across the lifecycle, not just one for taking payment. The checkout API initiates the payment, the authentication API proves who is paying, the status API reports where a payment stands, the refund API returns money for a completed payment, and the reversal API cancels a payment that should not have completed. Map each touchpoint to the stage of the lifecycle it serves, so the product does not end up with a payment that can be taken but cannot be refunded or checked.", "takeaway": "Map each touchpoint to the stage of the lifecycle it serves, so the product does not end up with a payment that can be taken but cannot be refunded or checked.", "visual": {"type": "diagram", "diagram": {"centre": "Payment product APIs across lifecycle", "parts": [{"label": "Checkout API", "note": "Initiates the payment."}, {"label": "Authentication API", "note": "Proves who is paying."}, {"label": "Status API", "note": "Reports where a payment stands."}, {"label": "Refund API", "note": "Returns money for a completed payment."}, {"label": "Reversal API", "note": "Cancels a payment that should not have completed."}]}}, "level": "core", "source_ref": "HAR-13"}, {"id": "INS-088", "seq": 152, "module": "Core", "source": "Harish Kavire", "title": "Refund API versus reversal API", "explain": "A refund and a reversal look similar but have different triggers, timing and ledger effects. A refund returns money for a completed payment, is linked to the original transaction, and posts as a new credit to the customer. A reversal cancels a payment that should not have completed, is also linked to the original transaction, but unwinds the original posting rather than creating a separate refund. Validate the rail and provider semantics before building either one, because the same word can mean different things on different rails.", "takeaway": "Validate the rail and provider semantics before building either one, because the same word can mean different things on different rails.", "visual": {"type": "diagram", "diagram": {"centre": "Refund API versus reversal API", "parts": [{"label": "Refund", "note": "Returns money for a completed payment, a new credit to the customer"}, {"label": "Reversal", "note": "Cancels a payment that should not have completed, unwinds the posting"}, {"label": "Shared link", "note": "Both are linked to the original transaction"}]}}, "level": "core", "source_ref": "HAR-13"}, {"id": "INS-012", "seq": 153, "module": "Core", "source": "Harish Kavire", "title": "Gateway versus bank responsibilities", "explain": "In a card payment the gateway, the bank and the merchant each own a distinct part. The gateway orchestrates the instruction and returns the outcome, the bank authorises and processes the payment and moves the funds, and the merchant is notified of the outcome and must act on it. When a payment fails, knowing which party owns which step decides who must fix it and who must tell the customer, so the boundary between gateway, bank and merchant must be explicit in the design.", "takeaway": "When a payment fails, knowing which party owns which step decides who must fix it and who must tell the customer, so the boundary between gateway, bank and merchant must be explicit in the design.", "visual": {"type": "diagram", "diagram": {"centre": "Gateway, bank and merchant ownership", "parts": [{"label": "Gateway", "note": "Orchestrates the instruction and returns the outcome."}, {"label": "Bank", "note": "Authorises and processes the payment and moves the funds."}, {"label": "Merchant", "note": "Is notified of the outcome and must act on it."}]}}, "level": "core", "source_ref": "HAR-01"}, {"id": "INS-023", "seq": 154, "module": "Core", "source": "Harish Kavire", "title": "Finding customers with repeated failed transactions", "explain": "To find customers with repeated failed transactions, translate the business rule into a time-windowed aggregation. Define the window, the failure condition and the threshold, then aggregate the transaction data over that window and validate the data quality before acting on the result. A count that includes test transactions, duplicates or a wrong window will target the wrong customers, so the data quality check is part of the work, not an afterthought.", "takeaway": "A count that includes test transactions, duplicates or a wrong window will target the wrong customers, so the data quality check is part of the work, not an afterthought.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Define the window", "note": "Set the time window for the aggregation"}, {"kind": "step", "title": "Define the failure condition", "note": "Set what counts as a failed transaction"}, {"kind": "step", "title": "Set the threshold", "note": "Set how many failures count as repeated"}, {"kind": "step", "title": "Aggregate the data", "note": "Aggregate transactions over the window"}, {"kind": "step", "title": "Validate data quality", "note": "Exclude test transactions and duplicates"}, {"kind": "step", "title": "Act on the result", "note": "Target the right customers"}]}}, "level": "core", "source_ref": "HAR-02"}, {"id": "INS-024", "seq": 155, "module": "Core", "source": "Harish Kavire", "title": "BA understanding of AML and CFT controls", "explain": "Anti-money laundering and counter-terrorist financing controls cover both the customer and the transaction. Map the customer risk controls and the transaction risk controls, the screening outcomes, the case escalation path and the audit trail. A BA must understand these controls well enough to write requirements that keep the audit trail complete, because a control that cannot be evidenced is treated as if it did not happen.", "takeaway": "A BA must understand these controls well enough to write requirements that keep the audit trail complete, because a control that cannot be evidenced is treated as if it did not happen.", "visual": {"type": "diagram", "diagram": {"centre": "AML and CFT controls for a BA", "parts": [{"label": "Customer risk controls", "note": "Cover the customer side of the controls."}, {"label": "Transaction risk controls", "note": "Cover the transaction side of the controls."}, {"label": "Screening outcomes", "note": "Recorded as part of the control set."}, {"label": "Case escalation path", "note": "Shows how a case moves when it is raised."}, {"label": "Audit trail", "note": "A control that cannot be evidenced is treated as absent."}]}}, "level": "core", "source_ref": "HAR-02"}, {"id": "INS-007", "seq": 156, "module": "Core", "source": "Harish Kavire", "title": "Handling ambiguous business requirements", "explain": "Ambiguity is normal at the start of a requirement. Use discovery questions to find what is actually meant, concrete examples to pin down the behaviour, process observation to see how the work is really done, and playback to confirm the understanding with stakeholders. The output is a requirement that is testable, meaning it states an observable outcome, a boundary condition and an acceptance criterion, rather than a vague wish that no one can verify.", "takeaway": "The output is a requirement that is testable, meaning it states an observable outcome, a boundary condition and an acceptance criterion, rather than a vague wish that no one can verify.", "visual": {"type": "diagram", "diagram": {"centre": "Handling ambiguous requirements", "parts": [{"label": "Discovery questions", "note": "Find what is actually meant."}, {"label": "Concrete examples", "note": "Pin down the behaviour."}, {"label": "Process observation", "note": "See how the work is really done."}, {"label": "Playback", "note": "Confirm understanding with stakeholders."}, {"label": "Testable output", "note": "States an observable outcome, a boundary and a criterion."}]}}, "level": "core", "source_ref": "HAR-01"}, {"id": "INS-008", "seq": 157, "module": "Core", "source": "Harish Kavire", "title": "Making requirements testable", "explain": "A requirement is testable when it defines an observable outcome, the boundary conditions, the negative cases and the acceptance criteria. An observable outcome states what can be seen or measured, a boundary condition states where the rule starts and stops, a negative case states what must not happen, and an acceptance criterion states the condition that proves the requirement is met. Without these four, a requirement cannot be verified and a dispute about whether it was delivered cannot be resolved.", "takeaway": "Without these four, a requirement cannot be verified and a dispute about whether it was delivered cannot be resolved.", "visual": {"type": "diagram", "diagram": {"centre": "What makes a requirement testable", "parts": [{"label": "Observable outcome", "note": "States what can be seen or measured."}, {"label": "Boundary conditions", "note": "State where the rule starts and stops."}, {"label": "Negative cases", "note": "State what must not happen."}, {"label": "Acceptance criteria", "note": "State the condition that proves it is met."}]}}, "level": "core", "source_ref": "HAR-01"}, {"id": "INS-009", "seq": 158, "module": "Core", "source": "Harish Kavire", "title": "Resolving conflicting stakeholder requirements", "explain": "When stakeholders disagree, compare the competing requirements on value, risk, urgency, customer impact and dependencies, then facilitate a documented decision. The comparison must be evidence based, so each stakeholder can see why one requirement was chosen over another. Document the decision, who made it and why, because an undocumented compromise will be reopened the next time the same stakeholders meet.", "takeaway": "Document the decision, who made it and why, because an undocumented compromise will be reopened the next time the same stakeholders meet.", "visual": {"type": "diagram", "diagram": {"centre": "Resolving conflicting requirements", "parts": [{"label": "Value", "note": "Compare the competing requirements on value."}, {"label": "Risk", "note": "Compare them on risk."}, {"label": "Urgency", "note": "Compare them on urgency."}, {"label": "Customer impact", "note": "Compare them on customer impact."}, {"label": "Dependencies", "note": "Compare them on dependencies."}, {"label": "Documented decision", "note": "Record the decision, who made it and why."}]}}, "level": "core", "source_ref": "HAR-01"}, {"id": "INS-015", "seq": 159, "module": "Core", "source": "Harish Kavire", "title": "Eliciting requirements from non-technical stakeholders", "explain": "Non-technical stakeholders describe what they need in business language, not in system language. Use interviews to hear the need, workshops to build shared understanding, observation to see how the work is actually done, examples to pin down the detail, and structured playback to confirm the understanding before it is written down. Playback matters most, because it catches misunderstandings while they are still cheap to fix.", "takeaway": "Playback matters most, because it catches misunderstandings while they are still cheap to fix.", "visual": {"type": "diagram", "diagram": {"centre": "Eliciting from non-technical stakeholders", "parts": [{"label": "Interviews", "note": "Hear the need in business language."}, {"label": "Workshops", "note": "Build shared understanding."}, {"label": "Observation", "note": "See how the work is actually done."}, {"label": "Examples", "note": "Pin down the detail."}, {"label": "Structured playback", "note": "Catches misunderstandings while they are cheap to fix."}]}}, "level": "core", "source_ref": "HAR-02"}, {"id": "INS-017", "seq": 160, "module": "Core", "source": "Harish Kavire", "title": "Resolving a late requirement gap", "explain": "A late requirement gap is found when a piece of the need was missed. Trace the gap back to where it was lost, whether in discovery, analysis, design, implementation or testing, and agree corrective action with the owner of that stage. Tracing the gap to its origin matters because it decides whether the fix is a small correction or a rework of a whole stage, and it prevents the same gap from recurring.", "takeaway": "Tracing the gap to its origin matters because it decides whether the fix is a small correction or a rework of a whole stage, and it prevents the same gap from recurring.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Find the gap", "note": "A piece of the need was missed."}, {"kind": "step", "title": "Trace it to its origin", "note": "Discovery, analysis, design, implementation or testing."}, {"kind": "step", "title": "Agree corrective action", "note": "Agreed with the owner of the stage where it was lost."}, {"kind": "step", "title": "Prevent recurrence", "note": "Tracing the origin stops the same gap recurring."}]}}, "level": "core", "source_ref": "HAR-02"}, {"id": "INS-018", "seq": 161, "module": "Core", "source": "Harish Kavire", "title": "Creating process and data-flow diagrams", "explain": "Choose the diagram that fits the problem being solved, then validate it. A process diagram must show the actors, the triggers, the decisions, the hand-offs and the data stores, and each of these must be checked against reality rather than assumed. Validate the diagram with the people who do the work, because a diagram that does not match the real process will mislead everyone who relies on it.", "takeaway": "Validate the diagram with the people who do the work, because a diagram that does not match the real process will mislead everyone who relies on it.", "visual": {"type": "diagram", "diagram": {"centre": "Process and data-flow diagrams", "parts": [{"label": "Actors", "note": "Shown and checked against reality."}, {"label": "Triggers", "note": "Shown and checked against reality."}, {"label": "Decisions", "note": "Shown and checked against reality."}, {"label": "Hand-offs", "note": "Shown and checked against reality."}, {"label": "Data stores", "note": "Shown and checked against reality."}, {"label": "Validation", "note": "Validated with the people who do the work."}]}}, "level": "core", "source_ref": "HAR-02"}, {"id": "INS-019", "seq": 162, "module": "Core", "source": "Harish Kavire", "title": "Validating requirements before development", "explain": "Before development starts, run walkthroughs with stakeholders, consistency checks across the requirement set, testability checks on each requirement and a formal sign-off. A walkthrough catches misunderstandings, a consistency check catches contradictions, a testability check catches requirements that cannot be verified, and sign-off records agreement. Skipping validation does not save time; it moves the cost into development and testing, where fixes are far more expensive.", "takeaway": "Skipping validation does not save time; it moves the cost into development and testing, where fixes are far more expensive.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Walkthroughs", "note": "Walkthroughs with stakeholders catch misunderstandings."}, {"kind": "step", "title": "Consistency checks", "note": "Checks across the set catch contradictions."}, {"kind": "step", "title": "Testability checks", "note": "Checks on each requirement catch what cannot be verified."}, {"kind": "step", "title": "Formal sign-off", "note": "Sign-off records agreement before development starts."}]}}, "level": "core", "source_ref": "HAR-02"}, {"id": "INS-081", "seq": 163, "module": "Core", "source": "Harish Kavire", "title": "Requirements Traceability Matrix", "explain": "A traceability matrix connects business objectives to requirements, stories, design, tests, defects and release evidence. Each row shows the chain from the objective through the requirement to the test that proves it, so that any change can be traced forward to its impact and any defect can be traced back to its origin. Without traceability, a team cannot prove that what was built is what was asked for, and cannot assess the impact of a change safely.", "takeaway": "Without traceability, a team cannot prove that what was built is what was asked for, and cannot assess the impact of a change safely.", "visual": {"type": "diagram", "diagram": {"centre": "Requirements Traceability Matrix", "parts": [{"label": "Business objectives", "note": "The start of each traceability chain."}, {"label": "Requirements", "note": "Linked from the objective."}, {"label": "Stories", "note": "Linked from the requirement."}, {"label": "Design", "note": "Linked from the story."}, {"label": "Tests", "note": "Prove the requirement is met."}, {"label": "Defects and release evidence", "note": "Traced back to their origin."}]}}, "level": "core", "source_ref": "HAR-16"}, {"id": "INS-038", "seq": 164, "module": "Core", "source": "Harish Kavire", "title": "Stakeholder changes requirements every week", "explain": "Frequent requirement changes are managed with a clear change intake, impact analysis, prioritisation and decision governance. Change intake records what is being asked and why, impact analysis states what the change costs in scope, effort and risk, prioritisation ranks the change against other work, and decision governance records who approved it and why. Without this discipline, weekly changes silently erode the scope and the delivery date.", "takeaway": "Without this discipline, weekly changes silently erode the scope and the delivery date.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Change intake", "note": "Records what is asked and why."}, {"kind": "step", "title": "Impact analysis", "note": "States the cost in scope, effort and risk."}, {"kind": "step", "title": "Prioritisation", "note": "Ranks the change against other work."}, {"kind": "step", "title": "Decision governance", "note": "Records who approved it and why."}]}}, "level": "core", "source_ref": "HAR-04"}, {"id": "INS-039", "seq": 165, "module": "Core", "source": "Harish Kavire", "title": "Business wants two weeks, development estimates six", "explain": "When the business wants two weeks and development estimates six, clarify the minimum outcome that would still be valuable, then work through the options. Slice the scope to the smallest useful increment, identify the dependencies that drive the estimate, and present evidence based trade-offs rather than arguing over the number. The decision is then about what to deliver and what to defer, not about whose estimate is right.", "takeaway": "The decision is then about what to deliver and what to defer, not about whose estimate is right.", "visual": {"type": "diagram", "diagram": {"centre": "Two weeks wanted, six estimated", "parts": [{"label": "Minimum valuable outcome", "note": "Clarify the smallest outcome still worth having."}, {"label": "Slice the scope", "note": "Cut scope to the smallest useful increment."}, {"label": "Dependencies", "note": "Identify what drives the estimate."}, {"label": "Evidence based trade-offs", "note": "Present trade-offs rather than arguing over the number."}]}}, "level": "core", "source_ref": "HAR-04"}, {"id": "INS-044", "seq": 166, "module": "Core", "source": "Harish Kavire", "title": "Senior management asks for a solution without requirements", "explain": "When senior management asks for a solution without requirements, reframe the request around outcomes, constraints, options and decision criteria. Ask what outcome is needed, what constraints apply, what options exist and what criteria will decide between them. This turns a request for a specific solution into a decision that can be made on evidence, and it avoids building something that does not solve the real problem.", "takeaway": "This turns a request for a specific solution into a decision that can be made on evidence, and it avoids building something that does not solve the real problem.", "visual": {"type": "diagram", "diagram": {"centre": "Solution requested without requirements", "parts": [{"label": "Outcomes", "note": "Ask what outcome is needed."}, {"label": "Constraints", "note": "Ask what constraints apply."}, {"label": "Options", "note": "Ask what options exist."}, {"label": "Decision criteria", "note": "Ask what criteria will decide between options."}]}}, "level": "core", "source_ref": "HAR-04"}, {"id": "INS-045", "seq": 167, "module": "Core", "source": "Harish Kavire", "title": "Business says requirements complete, developers disagree", "explain": "When the business believes requirements are complete but developers disagree, the gap is usually in interpretation rather than in content. Use concrete examples to show how each side reads the requirement, run walkthroughs to surface the differences, use traceability to show what is covered and what is not, and agree shared definitions for the terms that are being read differently. Close the interpretation gap before development, because it is far cheaper to agree on meaning now than to rebuild later.", "takeaway": "Close the interpretation gap before development, because it is far cheaper to agree on meaning now than to rebuild later.", "visual": {"type": "diagram", "diagram": {"centre": "Business says complete, developers disagree", "parts": [{"label": "Concrete examples", "note": "Show how each side reads the requirement."}, {"label": "Walkthroughs", "note": "Surface the differences in interpretation."}, {"label": "Traceability", "note": "Show what is covered and what is not."}, {"label": "Shared definitions", "note": "Agree definitions for terms read differently."}]}}, "level": "core", "source_ref": "HAR-04"}, {"id": "INS-046", "seq": 168, "module": "Core", "source": "Harish Kavire", "title": "Digital transformation faces user resistance", "explain": "User resistance to a digital change usually has a cause that can be identified. Map the impacts on each group of users, identify the stakeholder groups and their concerns, define the training needs, find champions who will support the change, collect feedback and measure adoption. Resistance that is understood can be addressed; resistance that is dismissed as stubbornness will grow and will damage the change.", "takeaway": "Resistance that is understood can be addressed; resistance that is dismissed as stubbornness will grow and will damage the change.", "visual": {"type": "diagram", "diagram": {"centre": "User resistance to digital change", "parts": [{"label": "Impacts on each user group", "note": "Map how the change affects each group."}, {"label": "Stakeholder groups and concerns", "note": "Identify who is concerned and about what."}, {"label": "Training needs", "note": "Define what training each group needs."}, {"label": "Champions", "note": "Find people who will support the change."}, {"label": "Feedback and adoption", "note": "Collect feedback and measure adoption."}]}}, "level": "core", "source_ref": "HAR-04"}, {"id": "INS-047", "seq": 169, "module": "Core", "source": "Harish Kavire", "title": "Demonstrating measurable BA contribution", "explain": "A business analyst demonstrates contribution by connecting process changes to measurable outcomes. Link the change to cost, cycle time, error rates, customer experience and benefits realisation, and measure before and after so the improvement can be shown rather than claimed. Benefits realisation is the final step: it proves that the change delivered the value that justified it, which is what stakeholders remember.", "takeaway": "Benefits realisation is the final step: it proves that the change delivered the value that justified it, which is what stakeholders remember.", "visual": {"type": "diagram", "diagram": {"centre": "Demonstrating measurable BA contribution", "parts": [{"label": "Cost", "note": "Link the change to cost, measure before and after"}, {"label": "Cycle time", "note": "Link the change to cycle time, measure before and after"}, {"label": "Error rates", "note": "Link the change to error rates, measure before and after"}, {"label": "Customer experience", "note": "Link the change to customer experience"}, {"label": "Benefits realisation", "note": "The final step, proves the value delivered"}]}}, "level": "core", "source_ref": "HAR-04"}, {"id": "INS-010", "seq": 170, "module": "Core", "source": "Harish Kavire", "title": "Managing requirement change mid-sprint", "explain": "A change requested mid-sprint must be assessed before it is agreed. Assess the scope of the change, the impact on the sprint goal, the effort required and the dependencies it introduces. Only then decide whether to accept it, defer it or swap it for something else. Accepting a change without this assessment silently breaks the sprint goal and leaves the team accountable for a target it never agreed to.", "takeaway": "Accepting a change without this assessment silently breaks the sprint goal and leaves the team accountable for a target it never agreed to.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Assess the scope", "note": "Assess the scope of the change."}, {"kind": "step", "title": "Assess the sprint goal impact", "note": "Assess the impact on the sprint goal."}, {"kind": "step", "title": "Assess the effort", "note": "Assess the effort the change requires."}, {"kind": "step", "title": "Assess dependencies", "note": "Assess the dependencies it introduces."}, {"kind": "decision", "title": "Decide accept, defer or swap", "note": "Decide only after the assessment."}]}}, "level": "core", "source_ref": "HAR-01"}, {"id": "INS-052", "seq": 171, "module": "Core", "source": "Harish Kavire", "title": "Change requested after 70 percent of sprint is complete", "explain": "A change requested when most of the sprint is done needs a careful assessment. Establish the reason for the change, the effort it requires, the dependencies it affects and the options the product owner has, and do not silently compromise the sprint goal to absorb it. The product owner decides, with the evidence in front of them, whether the change is worth the disruption or whether it waits for the next sprint.", "takeaway": "The product owner decides, with the evidence in front of them, whether the change is worth the disruption or whether it waits for the next sprint.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Establish the reason", "note": "Establish the reason for the change."}, {"kind": "step", "title": "Assess the effort", "note": "Assess the effort it requires."}, {"kind": "step", "title": "Assess dependencies", "note": "Assess the dependencies it affects."}, {"kind": "step", "title": "Present the options", "note": "Lay out the options the product owner has."}, {"kind": "decision", "title": "Product owner decides", "note": "Worth the disruption, or it waits for next sprint."}]}}, "level": "core", "source_ref": "HAR-07"}, {"id": "INS-053", "seq": 172, "module": "Core", "source": "Harish Kavire", "title": "Two senior stakeholders want opposite outcomes", "explain": "When two senior stakeholders want opposite outcomes, facilitate an evidence based prioritisation and document the accountable decision. Lay out the value, the risk, the cost and the customer impact of each requirement, let the evidence drive the ranking, and record who made the decision and why. A documented decision ends the debate; an undocumented one will be reopened every time the stakeholders meet.", "takeaway": "A documented decision ends the debate; an undocumented one will be reopened every time the stakeholders meet.", "visual": {"type": "diagram", "diagram": {"centre": "Two senior stakeholders, opposite outcomes", "parts": [{"label": "Value", "note": "Lay out the value of each requirement."}, {"label": "Risk", "note": "Lay out the risk of each requirement."}, {"label": "Cost", "note": "Lay out the cost of each requirement."}, {"label": "Customer impact", "note": "Lay out the customer impact of each requirement."}, {"label": "Accountable decision", "note": "Record who made the decision and why."}]}}, "level": "core", "source_ref": "HAR-07"}, {"id": "INS-037", "seq": 173, "module": "Core", "source": "Harish Kavire", "title": "Business process change just before UAT", "explain": "A process change just before user acceptance testing must be assessed for requirement impact, test scope, release risk and decision rights. Determine which requirements change, which tests must be added or rerun, what risk the change introduces to the release, and who has the authority to approve it. A change approved without this assessment can invalidate the testing that has already been done and put the release date at risk.", "takeaway": "A change approved without this assessment can invalidate the testing that has already been done and put the release date at risk.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Assess requirement impact", "note": "Determine which requirements change."}, {"kind": "step", "title": "Assess test scope", "note": "Determine which tests must be added or rerun."}, {"kind": "step", "title": "Assess release risk", "note": "Determine what risk the change adds to the release."}, {"kind": "step", "title": "Confirm decision rights", "note": "Confirm who has the authority to approve it."}]}}, "level": "core", "source_ref": "HAR-03"}, {"id": "INS-041", "seq": 174, "module": "Core", "source": "Harish Kavire", "title": "User rejects feature built to signed-off requirements", "explain": "When a user rejects a feature that was built to signed-off requirements, determine whether the issue is a defect, an ambiguity, a missed need or a scope change. A defect means the build does not match the requirement, an ambiguity means the requirement was read differently, a missed need means the requirement was incomplete, and a scope change means the need has moved. Each cause has a different owner and a different fix, so classifying it correctly is the first step.", "takeaway": "Each cause has a different owner and a different fix, so classifying it correctly is the first step.", "visual": {"type": "diagram", "diagram": {"centre": "User rejects a signed-off feature", "parts": [{"label": "Defect", "note": "The build does not match the requirement."}, {"label": "Ambiguity", "note": "The requirement was read differently."}, {"label": "Missed need", "note": "The requirement was incomplete."}, {"label": "Scope change", "note": "The need has moved since sign-off."}]}}, "level": "core", "source_ref": "HAR-04"}, {"id": "INS-020", "seq": 175, "module": "Core", "source": "Harish Kavire", "title": "Planning UAT and preparing test cases", "explain": "User acceptance testing coverage is derived from the business journeys, the acceptance criteria, the roles involved and the exception paths. For each business journey, define the acceptance criteria that prove it works, the roles that must be able to perform it, and the exception paths that must be handled. Test cases built from this coverage test the business outcome rather than the system mechanics, which is what acceptance testing is for.", "takeaway": "Test cases built from this coverage test the business outcome rather than the system mechanics, which is what acceptance testing is for.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Map business journeys", "note": "Coverage starts from the business journeys."}, {"kind": "step", "title": "Define acceptance criteria", "note": "Criteria that prove each journey works."}, {"kind": "step", "title": "Identify the roles", "note": "The roles that must be able to perform each journey."}, {"kind": "step", "title": "Cover exception paths", "note": "The exception paths that must be handled."}, {"kind": "step", "title": "Build the test cases", "note": "Cases test the business outcome, not system mechanics."}]}}, "level": "core", "source_ref": "HAR-02"}, {"id": "INS-060", "seq": 176, "module": "Core", "source": "Harish Kavire", "title": "BA role in SIT defect discussions", "explain": "In system integration testing defect discussions, the analyst assesses reproducibility, requirement traceability, business impact, fix validation and regression. Reproducibility decides whether the defect is real, traceability shows which requirement it breaks, business impact decides its priority, fix validation confirms the fix works, and regression confirms nothing else broke. This assessment keeps defect discussions focused on evidence rather than on opinion.", "takeaway": "This assessment keeps defect discussions focused on evidence rather than on opinion.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Assess reproducibility", "note": "Reproducibility decides whether the defect is real."}, {"kind": "step", "title": "Check traceability", "note": "Traceability shows which requirement it breaks."}, {"kind": "step", "title": "Assess business impact", "note": "Business impact decides the priority."}, {"kind": "step", "title": "Validate the fix", "note": "Fix validation confirms the fix works."}, {"kind": "step", "title": "Check regression", "note": "Regression confirms nothing else broke."}]}}, "level": "core", "source_ref": "HAR-09"}, {"id": "INS-061", "seq": 177, "module": "Core", "source": "Harish Kavire", "title": "BA support during deployment and hypercare", "explain": "During deployment and hypercare, the analyst monitors the critical journeys, the exception rates, the unresolved transactions and the stakeholder updates. Critical journeys show whether customers can complete their payments, exception rates show whether the system is handling failures, unresolved transactions show what still needs attention, and stakeholder updates keep everyone informed. Hypercare ends when these measures are stable, not when a fixed number of days has passed.", "takeaway": "Hypercare ends when these measures are stable, not when a fixed number of days has passed.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Monitor critical journeys", "note": "Show whether customers can complete payments."}, {"kind": "step", "title": "Monitor exception rates", "note": "Show whether the system handles failures."}, {"kind": "step", "title": "Monitor unresolved transactions", "note": "Show what still needs attention."}, {"kind": "step", "title": "Send stakeholder updates", "note": "Keep everyone informed through hypercare."}, {"kind": "step", "title": "End hypercare when stable", "note": "Ends when measures are stable, not after fixed days."}]}}, "level": "core", "source_ref": "HAR-09"}, {"id": "INS-051", "seq": 178, "module": "Core", "source": "Harish Kavire", "title": "Requirement, development, testing or environment miss", "explain": "When intended behaviour diverges from production behaviour, use a layered failure model to locate where it went wrong. Check the requirement first, then the development, then the testing, then the environment, and find the layer where the divergence was introduced. Locating the layer matters because it decides whether the fix is a requirement correction, a code change, a test improvement or an environment fix, and it prevents the same miss from recurring.", "takeaway": "Locating the layer matters because it decides whether the fix is a requirement correction, a code change, a test improvement or an environment fix, and it prevents the same miss from recurring.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Check the requirement layer", "note": "Find whether the divergence started in requirements."}, {"kind": "step", "title": "Check the development layer", "note": "Find whether it started in development."}, {"kind": "step", "title": "Check the testing layer", "note": "Find whether it started in testing."}, {"kind": "step", "title": "Check the environment layer", "note": "Find whether it started in the environment."}, {"kind": "step", "title": "Fix at the layer found", "note": "The layer decides the fix and prevents recurrence."}]}}, "level": "core", "source_ref": "HAR-06"}, {"id": "INS-021", "seq": 179, "module": "Core", "source": "Harish Kavire", "title": "KPI design for a digital banking application", "explain": "Key performance indicators for a digital banking application should cover adoption, task completion, failure, service, risk and customer outcome measures. Adoption shows whether customers use the feature, task completion shows whether they can finish what they start, failure shows where they are blocked, service shows whether the system performs, risk shows whether controls are holding, and customer outcome shows whether the feature delivered value. A KPI set that covers only one of these gives a misleading picture of health.", "takeaway": "A KPI set that covers only one of these gives a misleading picture of health.", "visual": {"type": "diagram", "diagram": {"centre": "KPI design for a digital banking application", "parts": [{"label": "Adoption", "note": "Whether customers use the feature"}, {"label": "Task completion", "note": "Whether customers finish what they start"}, {"label": "Failure", "note": "Where customers are blocked"}, {"label": "Service", "note": "Whether the system performs"}, {"label": "Risk", "note": "Whether controls are holding"}, {"label": "Customer outcome", "note": "Whether the feature delivered value"}]}}, "level": "core", "source_ref": "HAR-02"}, {"id": "INS-072", "seq": 180, "module": "Core", "source": "Harish Kavire", "title": "Why customers abandon the payment page", "explain": "Customers abandon a payment page for reasons that can be found in the evidence. Analyse the funnel to see where they drop off, the validation errors they encounter, the latency they experience, the payment options available and the user experience they report. Each of these points to a different fix, so the analysis must separate them rather than treating abandonment as a single problem with a single cause.", "takeaway": "Each of these points to a different fix, so the analysis must separate them rather than treating abandonment as a single problem with a single cause.", "visual": {"type": "diagram", "diagram": {"centre": "Why customers abandon the payment page", "parts": [{"label": "Funnel drop-off", "note": "Where customers drop off"}, {"label": "Validation errors", "note": "The errors customers encounter"}, {"label": "Latency", "note": "The latency customers experience"}, {"label": "Payment options", "note": "The payment options available"}, {"label": "User experience", "note": "What customers report"}]}}, "level": "core", "source_ref": "HAR-14"}, {"id": "INS-073", "seq": 181, "module": "Core", "source": "Harish Kavire", "title": "Why loan approval time rises from hours to days", "explain": "When loan approval time rises from hours to days, map the process to find the bottleneck. Look for queues where applications wait, manual checks that add delay, dependencies on other teams or systems, and rework where applications are sent back for correction. The bottleneck is usually a queue or a manual step rather than the decision itself, so measuring where time is actually spent is more useful than asking people where they think the delay is.", "takeaway": "The bottleneck is usually a queue or a manual step rather than the decision itself, so measuring where time is actually spent is more useful than asking people where they think the delay is.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Map the process", "note": "Map the approval process to find the bottleneck."}, {"kind": "step", "title": "Find the queues", "note": "Look for queues where applications wait."}, {"kind": "step", "title": "Find manual checks", "note": "Look for manual checks that add delay."}, {"kind": "step", "title": "Find dependencies", "note": "Look for dependencies on other teams or systems."}, {"kind": "step", "title": "Find the rework", "note": "Look for applications sent back for correction."}]}}, "level": "core", "source_ref": "HAR-14"}, {"id": "INS-074", "seq": 182, "module": "Core", "source": "Harish Kavire", "title": "Why UAT fails despite all test cases passing", "explain": "User acceptance testing can fail even when all test cases pass, because passing test cases do not prove the business need is met. Check the test design for gaps, the representativeness of the test data, the expected outcomes for correctness, and whether the unmet business need was ever covered by a test at all. A test suite that passes but does not represent the real business journeys gives false confidence and a failed acceptance.", "takeaway": "A test suite that passes but does not represent the real business journeys gives false confidence and a failed acceptance.", "visual": {"type": "diagram", "diagram": {"centre": "UAT fails despite passing test cases", "parts": [{"label": "Test design gaps", "note": "Check the design for gaps."}, {"label": "Representativeness of test data", "note": "Check the data matches real business use."}, {"label": "Expected outcomes", "note": "Check the expected outcomes are correct."}, {"label": "Unmet business need", "note": "Check whether the need was ever covered by a test."}]}}, "level": "core", "source_ref": "HAR-14"}, {"id": "INS-075", "seq": 183, "module": "Core", "source": "Harish Kavire", "title": "Why the same change is requested every sprint", "explain": "When the same change is requested every sprint, the root cause is usually unresolved. Look for an unresolved root need that the change does not actually satisfy, weak discovery that missed the real requirement, policy uncertainty that leaves the team guessing, or a lack of decision ownership so no one can say no. Fixing the root cause stops the repeated request; implementing the same change again will not.", "takeaway": "Fixing the root cause stops the repeated request; implementing the same change again will not.", "visual": {"type": "diagram", "diagram": {"centre": "Same change requested every sprint", "parts": [{"label": "Unresolved root need", "note": "The change does not actually satisfy the need."}, {"label": "Weak discovery", "note": "The real requirement was missed."}, {"label": "Policy uncertainty", "note": "Uncertainty leaves the team guessing."}, {"label": "Lack of decision ownership", "note": "No one can say no to the request."}]}}, "level": "core", "source_ref": "HAR-14"}, {"id": "INS-077", "seq": 184, "module": "Core", "source": "Harish Kavire", "title": "Translate rules and edge cases for developers", "explain": "Developers need rules and edge cases stated precisely. Explain the triggers that start a rule, the conditions that apply, the data involved, the expected behaviour and the failure outcomes. A rule stated as a business sentence leaves the developer guessing about the boundary, while a rule stated with triggers, conditions and failure outcomes can be built and tested without further questions.", "takeaway": "A rule stated as a business sentence leaves the developer guessing about the boundary, while a rule stated with triggers, conditions and failure outcomes can be built and tested without further questions.", "visual": {"type": "diagram", "diagram": {"centre": "Rules and edge cases for developers", "parts": [{"label": "Triggers", "note": "State what starts a rule."}, {"label": "Conditions", "note": "State the conditions that apply."}, {"label": "Data involved", "note": "State the data the rule uses."}, {"label": "Expected behaviour", "note": "State what should happen."}, {"label": "Failure outcomes", "note": "State what happens when the rule fails."}]}}, "level": "core", "source_ref": "HAR-15"}, {"id": "INS-078", "seq": 185, "module": "Core", "source": "Harish Kavire", "title": "Translate scenarios into testable QA coverage", "explain": "Test coverage is built by translating business scenarios into positive, negative, boundary and regression scenarios with expected results. Positive scenarios prove the happy path works, negative scenarios prove invalid input is handled, boundary scenarios prove the limits behave correctly, and regression scenarios prove existing behaviour still works. Each scenario needs an expected result, because a test without an expected result cannot pass or fail.", "takeaway": "Each scenario needs an expected result, because a test without an expected result cannot pass or fail.", "visual": {"type": "diagram", "diagram": {"centre": "Business scenarios into QA coverage", "parts": [{"label": "Positive scenarios", "note": "Prove the happy path works."}, {"label": "Negative scenarios", "note": "Prove invalid input is handled."}, {"label": "Boundary scenarios", "note": "Prove the limits behave correctly."}, {"label": "Regression scenarios", "note": "Prove existing behaviour still works."}, {"label": "Expected results", "note": "Every scenario needs one, or it cannot pass or fail."}]}}, "level": "core", "source_ref": "HAR-15"}, {"id": "INS-091", "seq": 186, "module": "Core", "source": "Harish Kavire", "title": "Feature technically complete but business problem remains", "explain": "A feature can be technically complete while the business problem remains unsolved. Revisit the hypothesis behind the feature, the actual user behaviour, the process adoption, the operational constraints and the outcome measures. The gap is usually that the feature was built as specified but the hypothesis was wrong, or that users did not adopt it, or that an operational constraint was missed. Measuring the outcome rather than the delivery reveals the gap.", "takeaway": "Measuring the outcome rather than the delivery reveals the gap.", "visual": {"type": "diagram", "diagram": {"centre": "Feature complete, problem remains", "parts": [{"label": "Hypothesis behind the feature", "note": "Revisit whether the hypothesis was right."}, {"label": "Actual user behaviour", "note": "Check what users really do."}, {"label": "Process adoption", "note": "Check whether users adopted the change."}, {"label": "Operational constraints", "note": "Check for a constraint that was missed."}, {"label": "Outcome measures", "note": "Measure the outcome rather than the delivery."}]}}, "level": "core", "source_ref": "HAR-14"}, {"id": "INS-092", "seq": 187, "module": "Core", "source": "Harish Kavire", "title": "Loan approval time increases from two hours to two days", "explain": "When loan approval time increases from two hours to two days, analyse queue time, manual reviews, document quality, decision rules and hand-offs. Queue time shows where applications wait, manual reviews show where human effort adds delay, document quality shows where rework is created, decision rules show where the logic is slow, and hand-offs show where work is lost between teams. The fix depends on which of these is actually causing the delay, so measure before changing anything.", "takeaway": "The fix depends on which of these is actually causing the delay, so measure before changing anything.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Analyse queue time", "note": "Queue time shows where applications wait."}, {"kind": "step", "title": "Analyse manual reviews", "note": "Manual reviews show where human effort adds delay."}, {"kind": "step", "title": "Analyse document quality", "note": "Document quality shows where rework is created."}, {"kind": "step", "title": "Analyse decision rules", "note": "Decision rules show where the logic is slow."}, {"kind": "step", "title": "Analyse hand-offs", "note": "Hand-offs show where work is lost between teams."}]}}, "level": "core", "source_ref": "HAR-14"}, {"id": "INS-093", "seq": 188, "module": "Core", "source": "Harish Kavire", "title": "Why stakeholders repeat the same change request", "explain": "When stakeholders repeat the same change request, investigate the root need, the decision latency, the incomplete discovery and the feedback loops. The root need may never have been satisfied, the decision may have taken so long that the requester assumed it was ignored, the discovery may have missed the real requirement, or the feedback loop may never have closed the loop with the requester. Each cause has a different fix, and implementing the change again without fixing the cause will only repeat the cycle.", "takeaway": "Each cause has a different fix, and implementing the change again without fixing the cause will only repeat the cycle.", "visual": {"type": "diagram", "diagram": {"centre": "Stakeholders repeat the same request", "parts": [{"label": "Root need", "note": "It may never have been satisfied."}, {"label": "Decision latency", "note": "A slow decision can look like being ignored."}, {"label": "Incomplete discovery", "note": "The real requirement may have been missed."}, {"label": "Feedback loops", "note": "The loop with the requester may never have closed."}]}}, "level": "core", "source_ref": "HAR-14"}, {"id": "INS-094", "seq": 189, "module": "Core", "source": "Harish Kavire", "title": "BA ownership without direct authority", "explain": "A business analyst often owns delivery outcomes without having direct authority over the teams involved. Drive clarity by stating what is needed and by when, keep decision records so accountability is visible, follow up on actions rather than assuming they will happen, and escalate transparently when a decision or a delivery is blocked. Ownership without authority works through clarity and follow-through, not through control.", "takeaway": "Ownership without authority works through clarity and follow-through, not through control.", "visual": {"type": "diagram", "diagram": {"centre": "BA ownership without direct authority", "parts": [{"label": "State what is needed and by when", "note": "Drive clarity on the ask and the date."}, {"label": "Decision records", "note": "Keep accountability visible."}, {"label": "Follow up on actions", "note": "Do not assume actions will happen."}, {"label": "Escalate transparently", "note": "Escalate when a decision or delivery is blocked."}]}}, "level": "core", "source_ref": "HAR-15"}, {"id": "INS-056", "seq": 190, "module": "Core", "source": "Harish Kavire", "title": "Client says the new process has damaged operations", "explain": "When a client says a new process has damaged their operations, acknowledge the impact first, then establish the facts. Provide a safe workaround so the client can keep operating, agree the recovery communications, and investigate what actually changed. Acknowledging the impact does not admit fault, it shows the client is being taken seriously, and it creates the space to find the real cause without the conversation becoming adversarial.", "takeaway": "Acknowledging the impact does not admit fault, it shows the client is being taken seriously, and it creates the space to find the real cause without the conversation becoming adversarial.", "visual": {"type": "diagram", "diagram": {"centre": "Client says the process damaged operations", "parts": [{"label": "Acknowledge the impact first", "note": "Shows the client is taken seriously."}, {"label": "Safe workaround", "note": "Lets the client keep operating."}, {"label": "Recovery communications", "note": "Agreed with the client."}, {"label": "Investigate what changed", "note": "Find the real cause without becoming adversarial."}]}}, "level": "core", "source_ref": "HAR-08"}, {"id": "INS-068", "seq": 191, "module": "Core", "source": "Harish Kavire", "title": "Evidence required during a payment surge", "explain": "During a payment surge, the evidence needed is specific. Collect transaction IDs, gateway responses, API logs, timeout rates, timestamps and reconciliation status. Transaction IDs link the evidence to individual payments, gateway responses and API logs show what each system did, timeout rates show where the system is struggling, timestamps show when it happened, and reconciliation status shows whether money is accounted for. Without this evidence, the incident response is guesswork.", "takeaway": "Without this evidence, the incident response is guesswork.", "visual": {"type": "diagram", "diagram": {"centre": "Evidence needed during a payment surge", "parts": [{"label": "Transaction IDs", "note": "Link evidence to individual payments."}, {"label": "Gateway responses", "note": "Show what the gateway did."}, {"label": "API logs", "note": "Show what each system did."}, {"label": "Timeout rates", "note": "Show where the system is struggling."}, {"label": "Timestamps", "note": "Show when it happened."}, {"label": "Reconciliation status", "note": "Shows whether money is accounted for."}]}}, "level": "core", "source_ref": "HAR-12"}, {"id": "INS-063", "seq": 192, "module": "Core", "source": "Harish Kavire", "title": "Coordinating business, dev, QA, gateway and support", "explain": "Coordinating business, development, QA, gateway and support teams during an incident needs one incident view, clear owners, evidence requests and an update cadence. One incident view prevents each team from working from a different picture, clear owners prevent work from falling between teams, evidence requests ensure the right data is collected, and a regular update cadence keeps everyone aligned. Without this coordination, teams duplicate effort and the incident lasts longer than it should.", "takeaway": "Without this coordination, teams duplicate effort and the incident lasts longer than it should.", "visual": {"type": "diagram", "diagram": {"centre": "Coordinating teams during an incident", "parts": [{"label": "One incident view", "note": "Prevents teams working from different pictures."}, {"label": "Clear owners", "note": "Prevents work falling between teams."}, {"label": "Evidence requests", "note": "Ensure the right data is collected."}, {"label": "Update cadence", "note": "Keeps everyone aligned through the incident."}]}}, "level": "core", "source_ref": "HAR-10"}, {"id": "INS-097", "seq": 193, "module": "Core", "source": "Harish Kavire", "title": "Build practical BA projects rather than only theory", "explain": "A practical BA portfolio is built from real work rather than from theory alone. Create a portfolio with a problem statement, process maps, user stories, an API contract and UAT evidence, so that a reviewer can see the full chain from problem to delivered outcome. Theory shows what was studied; a portfolio shows what was actually done, which is what an employer needs to see.", "takeaway": "Theory shows what was studied; a portfolio shows what was actually done, which is what an employer needs to see.", "visual": {"type": "diagram", "diagram": {"centre": "Practical BA portfolio, not only theory", "parts": [{"label": "Problem statement", "note": "States the problem the work solved."}, {"label": "Process maps", "note": "Show the process as it was mapped."}, {"label": "User stories", "note": "Show the needs as stories."}, {"label": "API contract", "note": "Shows the integration as defined."}, {"label": "UAT evidence", "note": "Shows the outcome was tested and accepted."}]}}, "level": "core", "source_ref": "HAR-18"}, {"id": "INS-084", "seq": 194, "module": "Core", "source": "Harish Kavire", "title": "Present project experience with evidence", "explain": "Present project experience by structuring the walkthrough around the problem, the role played, the decisions made, the systems involved, the risks managed and the measurable result. This structure shows the scope of the work and the contribution made, rather than a list of tasks. Measurable results matter most, because they prove the work delivered value rather than simply occupying time.", "takeaway": "Measurable results matter most, because they prove the work delivered value rather than simply occupying time.", "visual": {"type": "diagram", "diagram": {"centre": "Presenting project experience", "parts": [{"label": "Problem", "note": "Structure the walkthrough around the problem."}, {"label": "Role played", "note": "Show the part played in the work."}, {"label": "Decisions made", "note": "Show the judgement exercised."}, {"label": "Systems involved", "note": "Show the technical landscape."}, {"label": "Risks managed", "note": "Show the risks handled."}, {"label": "Measurable result", "note": "Proves the work delivered value."}]}}, "level": "core", "source_ref": "HAR-20"}, {"id": "INS-100", "seq": 195, "module": "Core", "source": "Harish Kavire", "title": "Walk through current project and exact BA responsibilities", "explain": "When walking through a current project, structure the walkthrough around context, scope, stakeholders, systems, deliverables, decisions and outcomes. Context sets the scene, scope shows the size of the work, stakeholders show who was involved, systems show the technical landscape, deliverables show what was produced, decisions show judgement, and outcomes show the result. This structure keeps the walkthrough focused and complete, and it prevents it from becoming a list of tasks.", "takeaway": "This structure keeps the walkthrough focused and complete, and it prevents it from becoming a list of tasks.", "visual": {"type": "diagram", "diagram": {"centre": "Walking through a current project", "parts": [{"label": "Context", "note": "Sets the scene."}, {"label": "Scope", "note": "Shows the size of the work."}, {"label": "Stakeholders", "note": "Shows who was involved."}, {"label": "Systems", "note": "Shows the technical landscape."}, {"label": "Deliverables", "note": "Shows what was produced."}, {"label": "Decisions", "note": "Show judgement."}, {"label": "Outcomes", "note": "Show the result."}]}}, "level": "core", "source_ref": "HAR-17"}, {"id": "PAI-C011", "seq": 196, "module": "Core", "source": "Paiementor", "title": "The intermediary forwards a pacs.004 back to the originator", "explain": "When a beneficiary bank returns a payment with a pacs.004, the intermediary bank that received that pacs.004 sends a new pacs.004 back to the originator bank, so the return travels the chain in reverse. The intermediary does not keep the return; it forwards it, including the reference to the original payment, so the originator bank can match it. This is the rule in a three-bank chain: every bank that handled the payment forwards the return to the bank that sent it the payment.", "takeaway": "This is the rule in a three-bank chain: every bank that handled the payment forwards the return to the bank that sent it the payment.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Beneficiary bank returns with pacs.004", "note": "The beneficiary bank sends the return as a pacs.004"}, {"kind": "step", "title": "Intermediary receives the pacs.004", "note": "The intermediary bank receives the return from the beneficiary bank"}, {"kind": "step", "title": "Intermediary sends a new pacs.004 onward", "note": "It forwards the return to the originator bank with the original reference"}, {"kind": "step", "title": "Originator bank matches the return", "note": "The originator bank matches the return to the payment it sent"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/messages-pacs-004-camt-056-and-camt-029/"}, {"id": "PAI-C012", "seq": 197, "module": "Core", "source": "Paiementor", "title": "How a pacs.004 links back to the original payment", "explain": "A pacs.004 carries the original instruction identification and the original end-to-end identification, which link it to the payment it returns. The originator bank reads those references and matches the return to the payment it sent, even when the return has passed through an intermediary. Without those references a return is just a credit with no story, and reconciliation cannot prove which payment it belongs to.", "takeaway": "Without those references a return is just a credit with no story, and reconciliation cannot prove which payment it belongs to.", "visual": {"type": "diagram", "diagram": {"centre": "How a pacs.004 links back", "parts": [{"label": "Original instruction identification", "note": "The pacs.004 carries the original instruction identification"}, {"label": "Original end-to-end identification", "note": "The pacs.004 carries the original end-to-end identification"}, {"label": "Originator bank matches the return", "note": "The originator bank reads the references and matches the return to the payment it sent"}, {"label": "Without references, no story", "note": "Without those references a return is just a credit with no story"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/messages-pacs-004-camt-056-and-camt-029/"}, {"id": "PAI-C013", "seq": 198, "module": "Core", "source": "Paiementor", "title": "The recall flow through an intermediary bank", "explain": "When an originator asks to recall a payment that went through an intermediary, the originator bank sends a camt.056 to the intermediary, and the intermediary forwards it to the beneficiary bank. The beneficiary bank checks whether the recall is feasible, and if it is, it sends the funds back with a pacs.004 to the intermediary, which sends a pacs.004 back to the originator bank. The recall is therefore a chain of messages, not a single message, and each bank in the chain must act for the funds to come back.", "takeaway": "The recall is therefore a chain of messages, not a single message, and each bank in the chain must act for the funds to come back.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Originator bank sends camt.056", "note": "The originator bank sends the recall to the intermediary"}, {"kind": "step", "title": "Intermediary forwards camt.056", "note": "The intermediary forwards the recall to the beneficiary bank"}, {"kind": "decision", "title": "Beneficiary bank checks feasibility", "note": "The beneficiary bank checks whether the recall is feasible"}, {"kind": "step", "title": "Beneficiary bank returns funds by pacs.004", "note": "If feasible, it sends the funds back with a pacs.004 to the intermediary"}, {"kind": "step", "title": "Intermediary sends pacs.004 to originator", "note": "The intermediary sends a pacs.004 back to the originator bank"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/messages-pacs-004-camt-056-and-camt-029/"}, {"id": "PAI-C014", "seq": 199, "module": "Core", "source": "Paiementor", "title": "Who can initiate a pacs.004", "explain": "Both the originator payment service provider and the beneficiary payment service provider can initiate a pacs.004, because a return can be started from either end of the payment. The originator side initiates a return when it recalls or reverses a payment, and the beneficiary side initiates one when it rejects or returns a payment it cannot apply. The message is the same in both cases; what differs is which bank starts it and why.", "takeaway": "The message is the same in both cases; what differs is which bank starts it and why.", "visual": {"type": "diagram", "diagram": {"centre": "Who can initiate a pacs.004", "parts": [{"label": "Originator payment service provider", "note": "Initiates a return when it recalls or reverses a payment"}, {"label": "Beneficiary payment service provider", "note": "Initiates a return when it rejects or returns a payment it cannot apply"}, {"label": "Same message, different starter", "note": "The message is the same in both cases; what differs is which bank starts it and why"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/messages-pacs-004-camt-056-and-camt-029/"}, {"id": "PAI-C015", "seq": 200, "module": "Core", "source": "Paiementor", "title": "camt.029: the answer to a recall request", "explain": "A camt.029 is the response to a camt.056 recall request, and it states whether the recall has been accepted or refused. The open question readers raise is who sends it, the beneficiary bank or the clearing system, and what it must contain in each case. The answer matters because the originator bank cannot close the recall until it receives that response and knows whether the funds are coming back.", "takeaway": "The answer matters because the originator bank cannot close the recall until it receives that response and knows whether the funds are coming back.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Recall request sent as camt.056", "note": "The recall starts with a camt.056 request"}, {"kind": "step", "title": "camt.029 states accepted or refused", "note": "The camt.029 response states whether the recall has been accepted or refused"}, {"kind": "step", "title": "Originator bank closes the recall", "note": "The originator bank cannot close the recall until it receives that response"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/messages-pacs-004-camt-056-and-camt-029/"}, {"id": "PAI-C016", "seq": 201, "module": "Core", "source": "Paiementor", "title": "Who gives the reason for a return or a reject", "explain": "When a payment is returned or rejected, the reason code comes from the bank that refused it, and the question readers raise is whether a payment service provider can add its own reason codes beyond those in the scheme rulebook. The rulebook lists the permitted codes, and a bank that invents its own code risks the return being rejected by the next bank in the chain. The reason code is therefore a controlled vocabulary, not a free-text field.", "takeaway": "The reason code is therefore a controlled vocabulary, not a free-text field.", "visual": {"type": "diagram", "diagram": {"centre": "The reason for a return or reject", "parts": [{"label": "Reason code comes from the refusing bank", "note": "When a payment is returned or rejected, the reason code comes from the refusing bank"}, {"label": "Rulebook lists the permitted codes", "note": "The scheme rulebook lists the permitted codes a bank may use"}, {"label": "Invented codes risk rejection", "note": "A bank that invents its own code risks the return being rejected by the next bank"}, {"label": "Controlled vocabulary, not free text", "note": "The reason code is a controlled vocabulary, not a free-text field"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/messages-in-the-interbank-space-pacs-008-and-pacs-002/"}, {"id": "PAI-C017", "seq": 202, "module": "Core", "source": "Paiementor", "title": "What a pacs.002 carries when a pacs.008 is rejected", "explain": "When a pacs.008 is rejected, the pacs.002 reports that rejection, and the question is which fields it must carry to explain what went wrong. The pacs.002 must identify the original payment and carry the status and the reason code, so the originator bank knows the payment did not settle and why. A pacs.002 without that information leaves the originator guessing, which is why readers ask exactly which fields are needed.", "takeaway": "A pacs.002 without that information leaves the originator guessing, which is why readers ask exactly which fields are needed.", "visual": {"type": "diagram", "diagram": {"centre": "A pacs.002 reporting a rejection", "parts": [{"label": "Identifies the original payment", "note": "The pacs.002 must identify the original payment that was rejected"}, {"label": "Carries the status", "note": "The pacs.002 must carry the status, so the originator knows the payment did not settle"}, {"label": "Carries the reason code", "note": "The pacs.002 must carry the reason code explaining what went wrong"}, {"label": "Without it, the originator guesses", "note": "A pacs.002 without that information leaves the originator guessing"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/messages-in-the-interbank-space-pacs-008-and-pacs-002/"}, {"id": "PAI-C018", "seq": 203, "module": "Core", "source": "Paiementor", "title": "When the MT103 arrives before the MT202 COV", "explain": "In a cover payment the MT103 and the MT202 COV travel separately, so the MT103 can reach the beneficiary bank before the funds leg arrives. The beneficiary bank must then hold the instruction and wait for the cover, because it cannot credit the beneficiary until the funds have settled. This timing gap is a normal feature of the cover method, not an error, but it is also the moment when a mismatch in amount or reference is most likely to surface.", "takeaway": "This timing gap is a normal feature of the cover method, not an error, but it is also the moment when a mismatch in amount or reference is most likely to surface.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "MT103 reaches beneficiary bank first", "note": "The information leg can arrive before the funds leg"}, {"kind": "step", "title": "Beneficiary bank holds the instruction", "note": "It must hold the instruction and wait for the cover"}, {"kind": "step", "title": "Cover arrives and funds settle", "note": "The beneficiary cannot be credited until the funds have settled"}, {"kind": "decision", "title": "Check amount and reference match", "note": "A mismatch in amount or reference is most likely to surface at this moment"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-mt103-202-cover-payment-analysis-part-1/"}, {"id": "PAI-C019", "seq": 204, "module": "Core", "source": "Paiementor", "title": "How the beneficiary bank recognises an MT202 COV", "explain": "When an MT202 COV reaches the beneficiary bank, the bank must recognise that its purpose is to cover a specific MT103, and the link is the reference and the fields that tie the two messages together. Without that link the cover is just a bank-to-bank transfer, and the beneficiary bank cannot match it to the customer payment it is meant to settle. The reference is therefore the bridge between the information leg and the funds leg.", "takeaway": "The reference is therefore the bridge between the information leg and the funds leg.", "visual": {"type": "diagram", "diagram": {"centre": "Recognising an MT202 COV", "parts": [{"label": "Purpose is to cover a specific MT103", "note": "The cover must be recognised as settling a specific MT103"}, {"label": "Reference links the two messages", "note": "The reference and the fields tie the two messages together"}, {"label": "Without the link, just a transfer", "note": "Without that link the cover is just a bank-to-bank transfer"}, {"label": "Reference is the bridge", "note": "The reference is the bridge between the information leg and the funds leg"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-mt103-202-cover-payment-analysis-part-1/"}, {"id": "PAI-C020", "seq": 205, "module": "Core", "source": "Paiementor", "title": "To whom the MT202 COV is addressed", "explain": "In a chain, the MT202 COV is addressed to the bank that holds the account from which the funds will settle, and each bank in the chain must address its own cover leg to the next bank that will fund it. Addressing the cover to the wrong bank breaks the settlement, because the funds land in an account that was not expecting them. The address is therefore part of the settlement design, not an administrative detail.", "takeaway": "The address is therefore part of the settlement design, not an administrative detail.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Cover addressed to the funding bank", "note": "The MT202 COV goes to the bank that holds the account for settlement"}, {"kind": "step", "title": "Each bank addresses its own leg onward", "note": "Each bank in the chain addresses its cover leg to the next funding bank"}, {"kind": "decision", "title": "Wrong address breaks settlement", "note": "Addressing the cover to the wrong bank breaks the settlement"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-mt103-202-cover-payment-analysis-part-1/"}, {"id": "PAI-C021", "seq": 206, "module": "Core", "source": "Paiementor", "title": "Who returns the funds when a cover payment is rejected", "explain": "When a cover payment is rejected, the question is who returns the funds and by which message, because the funds leg and the information leg have different senders. The bank that holds the rejected cover must return the funds to the bank that sent them, so the money travels back along the same correspondent path it came on. A return that goes to the wrong bank creates a second exception on top of the first.", "takeaway": "A return that goes to the wrong bank creates a second exception on top of the first.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Cover payment is rejected", "note": "The funds leg and the information leg have different senders"}, {"kind": "step", "title": "Bank holding the cover returns the funds", "note": "The bank that holds the rejected cover must return the funds"}, {"kind": "step", "title": "Funds travel back along the same path", "note": "The money travels back along the correspondent path it came on"}, {"kind": "step", "title": "Return reaches the bank that sent it", "note": "The funds go back to the bank that sent them"}, {"kind": "decision", "title": "Return to the wrong bank is a second error", "note": "A return to the wrong bank creates a second exception on top of the first"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-mt103-202-cover-payment-analysis-part-1/"}, {"id": "PAI-C022", "seq": 207, "module": "Core", "source": "Paiementor", "title": "The ordering customer when MT103 and MT202 COV differ", "explain": "In a cover payment the ordering customer named in the MT103 and the ordering customer named in the MT202 COV can be different parties, because the MT103 names the customer who instructed the payment while the MT202 COV names the bank that is moving the funds. The question readers raise is which one counts as the ordering customer for the payment, and the answer is that each message has its own ordering party for its own leg. Treating them as the same party is a common source of confusion in cover payments.", "takeaway": "Treating them as the same party is a common source of confusion in cover payments.", "visual": {"type": "diagram", "diagram": {"centre": "The ordering customer in a cover payment", "parts": [{"label": "MT103 names the instructing customer", "note": "The MT103 names the customer who instructed the payment"}, {"label": "MT202 COV names the funding bank", "note": "The MT202 COV names the bank that is moving the funds"}, {"label": "Each message has its own ordering party", "note": "Each message has its own ordering party for its own leg"}, {"label": "Treating them as one party confuses", "note": "Treating them as the same party is a common source of confusion"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-mt103-202-cover-payment-analysis-part-1/"}, {"id": "PAI-C023", "seq": 208, "module": "Core", "source": "Paiementor", "title": "Field 72 in the cover payment", "explain": "Field 72 carries sender-to-receiver information, and in a cover payment it is the field that tells the next bank what the cover is for and what to do with it. Readers ask repeatedly what field 72 should contain in an MT202 COV, because the field is free text and the wrong instruction can send the funds to the wrong place or delay settlement. The discipline is to put only the instruction the next bank needs, in the form the next bank expects.", "takeaway": "The discipline is to put only the instruction the next bank needs, in the form the next bank expects.", "visual": {"type": "diagram", "diagram": {"centre": "Field 72 in the cover payment", "parts": [{"label": "Sender-to-receiver information", "note": "Field 72 carries sender-to-receiver information"}, {"label": "Tells the next bank what the cover is for", "note": "It tells the next bank what the cover is for and what to do with it"}, {"label": "Free text, so discipline matters", "note": "The field is free text, and a wrong instruction can send funds astray or delay settlement"}, {"label": "Only the instruction the next bank needs", "note": "Put only the instruction the next bank needs, in the form the next bank expects"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-mt103-202-cover-payment-analysis-part-1/"}, {"id": "PAI-C024", "seq": 209, "module": "Core", "source": "Paiementor", "title": "Charges in a serial payment: who pays", "explain": "In a serial payment the ordering customer is responsible for paying the charges, and each intermediary bank deducts its own charge from the amount as the payment passes through. The beneficiary therefore receives the amount minus the charges deducted at each step, which is why the amount credited can be less than the amount sent. A business analyst who prices a serial payment must account for every deduction in the chain, not just the first one.", "takeaway": "A business analyst who prices a serial payment must account for every deduction in the chain, not just the first one.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Ordering customer bears the charges", "note": "The ordering customer is responsible for paying the charges"}, {"kind": "step", "title": "Each intermediary deducts its charge", "note": "Each intermediary bank deducts its own charge as the payment passes through"}, {"kind": "step", "title": "Beneficiary receives the reduced amount", "note": "The beneficiary receives the amount minus the charges deducted at each step"}, {"kind": "step", "title": "Analyst accounts for every deduction", "note": "Pricing must account for every deduction in the chain, not just the first"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-mt103-serial-payment-analysis-1-3/"}, {"id": "PAI-C025", "seq": 210, "module": "Core", "source": "Paiementor", "title": "How the beneficiary knows the amount after two deductions", "explain": "When two intermediary banks each deduct a charge, the beneficiary needs to know the amount that will actually be credited, and the answer is in fields 71A and 71F of the MT103. Field 71A states who bears the charges, and field 71F states the amount of each charge deducted, so the beneficiary bank can work out the final credit. Without those fields the beneficiary cannot reconcile the credit against the amount the ordering customer sent.", "takeaway": "Without those fields the beneficiary cannot reconcile the credit against the amount the ordering customer sent.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Two intermediaries each deduct a charge", "note": "Two intermediary banks each deduct a charge from the payment"}, {"kind": "step", "title": "Field 71A states who bears charges", "note": "Field 71A states who bears the charges"}, {"kind": "step", "title": "Field 71F states each charge deducted", "note": "Field 71F states the amount of each charge deducted"}, {"kind": "step", "title": "Beneficiary bank works out final credit", "note": "The beneficiary bank works out the final credit from those fields"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-mt103-serial-payment-analysis-1-3/"}, {"id": "PAI-C026", "seq": 211, "module": "Core", "source": "Paiementor", "title": "Calculating charges in serial and cover payments", "explain": "Charges in a serial payment are deducted step by step as the payment passes through each intermediary, while in a cover payment the charges on the information leg and the funds leg are handled separately. The calculation therefore depends on the method, and a payment that mixes the two methods without care can double-charge or under-charge. The analyst must know which method applies before working out what the beneficiary will receive.", "takeaway": "The analyst must know which method applies before working out what the beneficiary will receive.", "visual": {"type": "diagram", "diagram": {"centre": "Calculating charges in serial and cover payments", "parts": [{"label": "Serial payment", "note": "Charges deducted step by step at each intermediary"}, {"label": "Cover payment", "note": "Charges on the information leg and funds leg handled separately"}, {"label": "Mixed methods", "note": "Mixing the two can double-charge or under-charge"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-serial-and-cover-payments/"}, {"id": "PAI-C027", "seq": 212, "module": "Core", "source": "Paiementor", "title": "The MT103 return through the chain", "explain": "When an MT103 is returned, the funds come back through the same chain of banks that carried the payment forward, with each bank sending the return to the bank that sent it the payment. The charges on the return follow fields 71A and 71F, so the amount that comes back is the amount sent minus the charges already deducted. A return is therefore not a new payment; it is the original payment travelling backwards, and the chain must be able to trace it.", "takeaway": "A return is therefore not a new payment; it is the original payment travelling backwards, and the chain must be able to trace it.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "MT103 is returned", "note": "The return starts when the MT103 is returned"}, {"kind": "step", "title": "Each bank sends the return backwards", "note": "Each bank sends the return to the bank that sent it the payment"}, {"kind": "step", "title": "Charges follow fields 71A and 71F", "note": "The amount returned is the amount sent minus the charges already deducted"}, {"kind": "step", "title": "Return is the payment travelling backwards", "note": "The return is the original payment travelling backwards, and the chain must trace it"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-serial-and-cover-payments/"}, {"id": "PAI-C028", "seq": 213, "module": "Core", "source": "Paiementor", "title": "A return because the beneficiary account was invalid", "explain": "When the beneficiary bank finds the customer account invalid, it returns the payment, and the return must travel back through the intermediary to the originator bank. The beneficiary bank cannot simply keep the funds, and it cannot return them directly to the originator if an intermediary sits in between. The invalid account is one of the most common reasons for a return, and the handling is the same whether the invalidity is a wrong number, a closed account, or a name that does not match.", "takeaway": "The invalid account is one of the most common reasons for a return, and the handling is the same whether the invalidity is a wrong number, a closed account, or a name that does not match.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Beneficiary bank finds account invalid", "note": "The account may be a wrong number, closed, or a name that does not match"}, {"kind": "step", "title": "Beneficiary bank returns the payment", "note": "The beneficiary bank cannot keep the funds"}, {"kind": "step", "title": "Return travels back through intermediary", "note": "The return must travel back through the intermediary to the originator"}, {"kind": "step", "title": "Originator bank receives the return", "note": "The return reaches the originator bank through the chain"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/messages-pacs-004-camt-056-and-camt-029/"}, {"id": "PAI-C029", "seq": 214, "module": "Core", "source": "Paiementor", "title": "A clearing house that does not support camt.056", "explain": "Some clearing houses do not support the camt.056 recall message, which means the originator bank and the clearing system cannot send a recall to the beneficiary bank for a payment that has already settled. The Estonian clearing house is a real example: it does not support the recall message, so a settled SCT payment cannot be recalled through that route. A business analyst must know which clearing systems support a recall before promising a customer that a payment can be taken back.", "takeaway": "A business analyst must know which clearing systems support a recall before promising a customer that a payment can be taken back.", "visual": {"type": "diagram", "diagram": {"centre": "A clearing house without camt.056", "parts": [{"label": "Recall cannot be sent through it", "note": "The originator bank and the clearing system cannot send a recall for a settled payment"}, {"label": "Estonian clearing house example", "note": "The Estonian clearing house does not support the recall message for a settled SCT payment"}, {"label": "Analyst must check support first", "note": "An analyst must know which clearing systems support a recall before promising a customer"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/messages-pacs-004-camt-056-and-camt-029/"}, {"id": "PAI-C030", "seq": 215, "module": "Core", "source": "Paiementor", "title": "A recall after the beneficiary has spent the funds", "explain": "When a payment has been executed and the beneficiary has already spent the funds, a camt.056 can still be sent to ask the beneficiary bank to return the money, but the beneficiary bank must ask its customer whether it agrees. If the funds are no longer there, the recall cannot be completed by message alone, and the customer must take action against the beneficiary. The recall is therefore a request, not a reversal, once the money has been spent.", "takeaway": "The recall is therefore a request, not a reversal, once the money has been spent.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Payment executed and funds spent", "note": "The beneficiary has already spent the funds"}, {"kind": "step", "title": "camt.056 still sent to ask for return", "note": "A camt.056 can still be sent to ask the beneficiary bank to return the money"}, {"kind": "step", "title": "Beneficiary bank asks its customer", "note": "The beneficiary bank must ask its customer whether it agrees"}, {"kind": "decision", "title": "Funds still there or not", "note": "If the funds are no longer there, the recall cannot complete by message alone"}, {"kind": "step", "title": "Customer must act against beneficiary", "note": "The customer must take action against the beneficiary to recover the money"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/messages-pacs-004-camt-056-and-camt-029/"}, {"id": "PAI-C031", "seq": 216, "module": "Core", "source": "Paiementor", "title": "A recall in favour of a third-party beneficiary", "explain": "When a recall is made in favour of a third-party beneficiary, for example a bank acting as debtor agent, the question is who receives the recall and who must act on it. The recall is sent to the first agent in the chain, which is the bank that must return the credit, and that bank then passes the recall onward. The third party does not receive the recall directly; it receives the result through the bank that acts for it.", "takeaway": "The third party does not receive the recall directly; it receives the result through the bank that acts for it.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Recall made for a third-party beneficiary", "note": "For example, a bank acting as debtor agent"}, {"kind": "step", "title": "Recall sent to the first agent", "note": "The recall is sent to the first agent in the chain, the bank that must return the credit"}, {"kind": "step", "title": "First agent passes the recall onward", "note": "That bank then passes the recall onward"}, {"kind": "step", "title": "Third party receives the result", "note": "The third party receives the result through the bank that acts for it"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/messages-pacs-004-camt-056-and-camt-029/"}, {"id": "PAI-C032", "seq": 217, "module": "Core", "source": "Paiementor", "title": "A camt.056 rejection and the GVC reason code", "explain": "A camt.056 recall request can itself be rejected, and the question readers raise is what that rejection looks like and what the reason code means. One real case is a recall returned with a pacs.004 carrying the reason code GVC, which is not a code that should be used for a return, so the handling was wrong. The lesson is that a reason code must match the message and the situation, and a code used in the wrong place creates a second exception.", "takeaway": "The lesson is that a reason code must match the message and the situation, and a code used in the wrong place creates a second exception.", "visual": {"type": "diagram", "diagram": {"centre": "A rejected camt.056 recall request", "parts": [{"label": "Recall request can itself be rejected", "note": "A camt.056 recall request can itself be rejected"}, {"label": "GVC code on a pacs.004 return", "note": "One real case is a recall returned with a pacs.004 carrying the reason code GVC"}, {"label": "GVC should not be used for a return", "note": "GVC is not a code that should be used for a return, so the handling was wrong"}, {"label": "Code must match message and situation", "note": "A reason code must match the message and the situation, or it creates a second exception"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/messages-pacs-004-camt-056-and-camt-029/"}, {"id": "PAI-C033", "seq": 218, "module": "Core", "source": "Paiementor", "title": "camt.026 versus camt.056", "explain": "A camt.056 requests a recall of a payment, asking the beneficiary bank to return funds that have already been credited. A camt.026 reports that a payment cannot be applied, telling the sender that the instruction could not be processed. The two messages are often confused because both relate to a payment that did not complete, but they do different jobs: one asks for money back, the other reports that money could not be applied.", "takeaway": "The two messages are often confused because both relate to a payment that did not complete, but they do different jobs: one asks for money back, the other reports that money could not be applied.", "visual": {"type": "diagram", "diagram": {"centre": "camt.026 versus camt.056", "parts": [{"label": "camt.026", "note": "Reports a payment cannot be applied"}, {"label": "camt.056", "note": "Requests a recall of funds already credited"}, {"label": "Different jobs", "note": "One asks for money back, the other reports money could not be applied"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/messages-pacs-004-camt-056-and-camt-029/"}, {"id": "PAI-C034", "seq": 219, "module": "Core", "source": "Paiementor", "title": "Whether a pacs.004 is mandatory for a return", "explain": "When a payment must be returned, the question is whether a pacs.004 is mandatory, or whether the return can be made another way. The pacs.004 is the ISO 20022 message designed for returns in the SEPA interbank space, and it carries the link to the original payment that lets every bank in the chain match it. Using another route breaks that link, which is why the pacs.004 is the expected message for a return.", "takeaway": "Using another route breaks that link, which is why the pacs.004 is the expected message for a return.", "visual": {"type": "diagram", "diagram": {"centre": "Is a pacs.004 mandatory for a return", "parts": [{"label": "Designed for returns in SEPA", "note": "The pacs.004 is the ISO 20022 message designed for returns in the SEPA interbank space"}, {"label": "Carries the link to the original payment", "note": "It carries the link to the original payment that lets every bank in the chain match it"}, {"label": "Another route breaks the link", "note": "Using another route breaks that link between the return and the original payment"}, {"label": "Expected message for a return", "note": "The pacs.004 is the expected message for a return"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/messages-pacs-004-camt-056-and-camt-029/"}, {"id": "PAI-C035", "seq": 220, "module": "Core", "source": "Paiementor", "title": "Sanction screening of MT103 and MT202 COV", "explain": "An MT103 and its MT202 COV are both subject to sanction screening, and the screening must happen before the payment is credited to the beneficiary. The question readers raise is what the screening process looks like for a cover payment, because the information leg and the funds leg are screened separately and a hit on either leg stops the payment. A bank that screens only the MT103 and not the cover, or the reverse, leaves a gap that a regulator will find.", "takeaway": "A bank that screens only the MT103 and not the cover, or the reverse, leaves a gap that a regulator will find.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "MT103 screened before credit", "note": "The information leg is screened before the payment is credited"}, {"kind": "step", "title": "MT202 COV screened separately", "note": "The funds leg is screened separately from the information leg"}, {"kind": "decision", "title": "Hit on either leg stops payment", "note": "A hit on either leg stops the payment"}, {"kind": "step", "title": "Screening gap risks a regulator finding", "note": "Screening only one leg leaves a gap a regulator will find"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-mt103-202-cover-payment-analysis-part-1/"}, {"id": "PAI-C036", "seq": 221, "module": "Core", "source": "Paiementor", "title": "When the MT103 and MT202 COV do not match", "explain": "In a cover payment the MT103 and the MT202 COV must agree on amount and on the references that link them, and a mismatch between the two creates an exception that stops settlement. The discrepancy can be a different amount, a missing reference, or details that do not line up, and the bank must investigate before it credits the beneficiary. A mismatch is therefore not a minor data error; it is a break in the link between the information leg and the funds leg.", "takeaway": "A mismatch is therefore not a minor data error; it is a break in the link between the information leg and the funds leg.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "MT103 and MT202 COV must agree", "note": "They must agree on amount and on the references that link them"}, {"kind": "decision", "title": "Check amount and references match", "note": "A different amount, a missing reference, or details that do not line up stop settlement"}, {"kind": "step", "title": "Bank investigates before crediting", "note": "The bank must investigate before it credits the beneficiary"}, {"kind": "step", "title": "Mismatch is a break in the link", "note": "The mismatch breaks the link between the information leg and the funds leg"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-serial-and-cover-payments/"}, {"id": "PAI-C037", "seq": 222, "module": "Core", "source": "Paiementor", "title": "Whether a serial MT103 can be recalled", "explain": "A serial MT103 can be recalled, but the recall must travel the same chain of banks that carried the payment forward, because each bank in the chain holds part of the payment. The originator bank sends the recall to the next bank in the chain, and each bank passes it on until it reaches the beneficiary bank, which decides whether the funds can be returned. A recall that skips a bank in the chain cannot work, because the bank that was skipped still holds the funds.", "takeaway": "A recall that skips a bank in the chain cannot work, because the bank that was skipped still holds the funds.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Originator bank sends the recall", "note": "The originator bank sends the recall to the next bank in the chain"}, {"kind": "step", "title": "Each bank passes the recall onward", "note": "Each bank passes it on until it reaches the beneficiary bank"}, {"kind": "decision", "title": "Beneficiary bank decides on the funds", "note": "The beneficiary bank decides whether the funds can be returned"}, {"kind": "step", "title": "Recall cannot skip a bank", "note": "A recall that skips a bank cannot work, as the skipped bank still holds the funds"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-serial-and-cover-payments/"}, {"id": "PAI-C038", "seq": 223, "module": "Core", "source": "Paiementor", "title": "A beneficiary bank that is not a SWIFT member", "explain": "When the beneficiary bank is not a SWIFT member, the MT103 cannot be sent to it directly, so the payment must reach it through a bank that is a member and can forward the instruction. The forwarding bank becomes an intermediary in the chain, and the payment follows the same serial or cover logic as any other payment with an intermediary. The beneficiary bank's non-membership does not stop the payment; it adds a step to the chain.", "takeaway": "The beneficiary bank's non-membership does not stop the payment; it adds a step to the chain.", "visual": {"type": "diagram", "diagram": {"centre": "A beneficiary bank outside SWIFT", "parts": [{"label": "MT103 cannot be sent to it directly", "note": "The MT103 cannot be sent to a bank that is not a SWIFT member"}, {"label": "Forwarding bank becomes an intermediary", "note": "The payment reaches it through a member bank that can forward the instruction"}, {"label": "Same serial or cover logic applies", "note": "The payment follows the same serial or cover logic as any payment with an intermediary"}, {"label": "Non-membership adds a step", "note": "The beneficiary bank's non-membership does not stop the payment; it adds a step"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/basic-swift-mt103-message-decrypted/"}, {"id": "PAI-C039", "seq": 224, "module": "Core", "source": "Paiementor", "title": "An MT103 with field 57 empty", "explain": "When an MT103 arrives with field 57 empty, the message names no beneficiary bank, so the receiving bank must work out where the payment should go from the other fields. The empty field is not necessarily an error; it can mean the payment is to be handled by the receiving bank itself, or that the beneficiary bank is identified elsewhere in the chain. The analyst must read the whole message before deciding whether the empty field is a gap or a deliberate omission.", "takeaway": "The analyst must read the whole message before deciding whether the empty field is a gap or a deliberate omission.", "visual": {"type": "diagram", "diagram": {"centre": "An MT103 with field 57 empty", "parts": [{"label": "No beneficiary bank named", "note": "The message names no beneficiary bank"}, {"label": "Receiving bank works out the route", "note": "The receiving bank must work out where the payment should go from the other fields"}, {"label": "Not necessarily an error", "note": "It can mean the receiving bank handles the payment itself, or the bank is named elsewhere"}, {"label": "Read the whole message first", "note": "The analyst must read the whole message before judging whether the empty field is a gap"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-mt103-serial-payment-analysis-1-3/"}, {"id": "PAI-C040", "seq": 225, "module": "Core", "source": "Paiementor", "title": "A parent company paying on behalf of subsidiaries", "explain": "A parent company can pay on behalf of its subsidiaries using an MT101, and the question is how the instruction names the subsidiary as the ordering customer for each transaction. The MT101 carries a general instruction sequence and a per-transaction sequence, and the subsidiary appears as the ordering customer in the per-transaction sequence. The parent's bank must then report each transaction under the correct subsidiary, so the accounting and the screening both land on the right party.", "takeaway": "The parent's bank must then report each transaction under the correct subsidiary, so the accounting and the screening both land on the right party.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Parent instructs with an MT101", "note": "A parent company pays on behalf of its subsidiaries using an MT101"}, {"kind": "step", "title": "General instruction sequence carried", "note": "The MT101 carries a general instruction sequence"}, {"kind": "step", "title": "Subsidiary named per transaction", "note": "The subsidiary appears as the ordering customer in the per-transaction sequence"}, {"kind": "step", "title": "Bank reports under the right subsidiary", "note": "Each transaction is reported under the correct subsidiary for accounting and screening"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-mt103-202-cover-payment-analysis-part-1/"}, {"id": "PAI-C054", "seq": 226, "module": "Core", "source": "Paiementor", "title": "MT103 STP: only option A fields qualify", "explain": "An MT103 STP is a straight-through-processing version of the MT103, and it only allows option A for fields such as 52, 54 and 57. Option A carries the party identifier and the BIC, so the receiving system can identify the bank without human help. Any other option leaves the bank to work out who the party is by hand, which is why those options are not allowed in an STP message.", "takeaway": "Any other option leaves the bank to work out who the party is by hand, which is why those options are not allowed in an STP message.", "visual": {"type": "diagram", "diagram": {"centre": "MT103 STP", "parts": [{"label": "Straight-through-processing version", "note": "An MT103 STP is a straight-through-processing version of the MT103"}, {"label": "Only option A allowed", "note": "It only allows option A for fields such as 52, 54 and 57"}, {"label": "Option A carries party identifier and BIC", "note": "Option A carries the party identifier and the BIC"}, {"label": "Receiving system identifies the bank", "note": "The receiving system can identify the bank without human help"}, {"label": "Other options need manual work", "note": "Any other option leaves the bank to work out who the party is by hand"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-mt103-serial-payment-analysis-3-3/"}, {"id": "PAI-C055", "seq": 227, "module": "Core", "source": "Paiementor", "title": "A credit notification is not an MT103", "explain": "An MT103 instructs the receiving bank to debit the sender's account and pay the beneficiary, so it is an instruction to move money. When a bank only wants to say that an account has already been credited, it uses an MT910 confirmation of credit or an MT950 or MT940 statement instead. Sending an MT103 for a credit that has already happened confuses an instruction with a notification, and the receiving bank may try to debit an account that should not be debited.", "takeaway": "Sending an MT103 for a credit that has already happened confuses an instruction with a notification, and the receiving bank may try to debit an account that should not be debited.", "visual": {"type": "diagram", "diagram": {"centre": "A credit notification is not an MT103", "parts": [{"label": "MT103 instructs a payment", "note": "An MT103 instructs the receiving bank to debit the sender and pay the beneficiary"}, {"label": "MT910 confirms a credit", "note": "A bank that only wants to report a credit uses an MT910 confirmation of credit"}, {"label": "MT950 or MT940 statement instead", "note": "An MT950 or MT940 statement can also report a credit that has already happened"}, {"label": "Instruction confused with notification", "note": "Sending an MT103 for a credit already made may make the receiver debit the wrong account"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-mt103-serial-payment-analysis-3-3/"}, {"id": "PAI-C056", "seq": 228, "module": "Core", "source": "Paiementor", "title": "Fields 55 and 56: the intermediary and the third reimbursement institution", "explain": "Field 56 names the intermediary institution, the bank that receives the payment from the sender and forwards it to the account with institution in field 57. Field 55 names a third reimbursement institution, used when the funds are reimbursed through a bank that is neither the sender nor the receiver. When a serial chain gains an intermediary, field 56A is simply added, and when the receiver is itself the receiver's correspondent there is no need to name it in field 56 at all.", "takeaway": "When a serial chain gains an intermediary, field 56A is simply added, and when the receiver is itself the receiver's correspondent there is no need to name it in field 56 at all.", "visual": {"type": "diagram", "diagram": {"centre": "Fields 55 and 56 in an MT103", "parts": [{"label": "Field 56: intermediary institution", "note": "Field 56 names the intermediary that forwards the payment to the account with institution"}, {"label": "Field 55: third reimbursement institution", "note": "Field 55 names a third reimbursement institution, used when funds are reimbursed elsewhere"}, {"label": "Field 56A added with an intermediary", "note": "When a serial chain gains an intermediary, field 56A is simply added"}, {"label": "No field 56 if receiver is own correspondent", "note": "When the receiver is its own correspondent, there is no need to name it in field 56"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/mt103-swift-message-with-optional-fields-52a-and-57a-part-2/"}, {"id": "PAI-C057", "seq": 229, "module": "Core", "source": "Paiementor", "title": "MT900: the confirmation that a debit happened", "explain": "When a bank debits an account on the instruction of an MT103, it can confirm the debit with an MT900, a confirmation of debit. The MT900 is a separate message, not part of the MT103 itself, and whether one is sent depends on the agreement between the two banks. A payment can therefore settle correctly without any MT900 being exchanged.", "takeaway": "A payment can therefore settle correctly without any MT900 being exchanged.", "visual": {"type": "diagram", "diagram": {"centre": "MT900: confirmation of debit", "parts": [{"label": "Confirms a debit from an MT103", "note": "When a bank debits an account on an MT103 instruction, it can confirm it with an MT900"}, {"label": "Separate message, not part of MT103", "note": "The MT900 is a separate message, not part of the MT103 itself"}, {"label": "Sent only by agreement", "note": "Whether one is sent depends on the agreement between the two banks"}, {"label": "Payment can settle without an MT900", "note": "A payment can settle correctly without any MT900 being exchanged"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-mt103-serial-payment-analysis-2-3/"}, {"id": "PAI-C058", "seq": 230, "module": "Core", "source": "Paiementor", "title": "Serial or cover: the choice follows the account relationship", "explain": "A Canadian bank paying a United States beneficiary held its United States dollars with Wells Fargo, while the beneficiary held its account with Citibank New York. Because the sending bank had no account relationship with Citibank, the correct route was a cover payment: an MT103 sent directly to Citibank and an MT202 COV sent to Wells Fargo. If the sending bank had held an account with the beneficiary's bank, a single serial MT103 would have been enough.", "takeaway": "If the sending bank had held an account with the beneficiary's bank, a single serial MT103 would have been enough.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Canadian bank holds USD with Wells Fargo", "note": "The sending bank held its United States dollars with Wells Fargo"}, {"kind": "step", "title": "Beneficiary holds account with Citibank", "note": "The beneficiary held its account with Citibank New York"}, {"kind": "decision", "title": "Direct account relationship or not", "note": "The sending bank had no account relationship with Citibank"}, {"kind": "step", "title": "Cover payment used: MT103 plus MT202 COV", "note": "An MT103 went directly to Citibank and an MT202 COV went to Wells Fargo"}, {"kind": "step", "title": "Serial MT103 would have sufficed", "note": "With a direct account relationship, a single serial MT103 would have been enough"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-mt103-202-cover-payment-analysis-part-3/"}, {"id": "PAI-C060", "seq": 231, "module": "Core", "source": "Paiementor", "title": "The cover amount must never be lower than the MT103 amount", "explain": "It is forbidden to take charges from an MT202 COV, so the cover amount must never be lower than the amount announced in the MT103. If an intermediary needs to be paid for its part in the chain, it asks the sending bank to pay through an MT191 or debits the account directly under the agreement between the banks. A cover that arrives short of the announced amount is therefore an exception, not a normal deduction.", "takeaway": "A cover that arrives short of the announced amount is therefore an exception, not a normal deduction.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Charges must not be taken from MT202 COV", "note": "It is forbidden to take charges from an MT202 COV"}, {"kind": "step", "title": "Cover amount must match the MT103 amount", "note": "The cover amount must never be lower than the amount announced in the MT103"}, {"kind": "step", "title": "Intermediary claims charges separately", "note": "An intermediary asks the sending bank through an MT191 or debits the account directly"}, {"kind": "decision", "title": "Cover arriving short is an exception", "note": "A cover that arrives short of the announced amount is an exception"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-mt103-202-cover-payment-analysis-part-3/"}, {"id": "PAI-C061", "seq": 232, "module": "Core", "source": "Paiementor", "title": "RMA: a bank must authorise the sender before the MT103 can arrive", "explain": "Before one bank can send an MT103 to another over SWIFT, the receiving bank must set up an RMA, a relationship management authorisation, for that sender. Without an RMA the receiving bank's system will not accept the message, which is why a beneficiary bank is asked to establish one before a payment is sent. The RMA is therefore a precondition for the payment, not a formality that can be sorted out afterwards.", "takeaway": "The RMA is therefore a precondition for the payment, not a formality that can be sorted out afterwards.", "visual": {"type": "diagram", "diagram": {"centre": "RMA before an MT103 can arrive", "parts": [{"label": "Receiving bank sets up the RMA", "note": "The receiving bank must set up a relationship management authorisation for the sender"}, {"label": "Without an RMA, the message is refused", "note": "Without an RMA the receiving bank's system will not accept the message"}, {"label": "Beneficiary bank asked to establish it first", "note": "A beneficiary bank is asked to establish one before a payment is sent"}, {"label": "Precondition, not a formality", "note": "The RMA is a precondition for the payment, not a formality to sort out afterwards"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-mt103-202-cover-payment-analysis-part-3/"}, {"id": "PAI-C062", "seq": 233, "module": "Core", "source": "Paiementor", "title": "Sequence B of the MT202 COV must mirror the MT103", "explain": "In sequence B of an MT202 COV, only the ordering and beneficiary customer information in fields 50a and 59a is mandatory, and the other fields are optional. When the bank does provide a field such as field 72 or field 59, it must match the same field in the MT103 exactly, or the field must be left empty. Some banks reject a cover whose sequence B does not match the announcement, so a mismatch stops the funds even when the amounts agree.", "takeaway": "Some banks reject a cover whose sequence B does not match the announcement, so a mismatch stops the funds even when the amounts agree.", "visual": {"type": "diagram", "diagram": {"centre": "Sequence B of the MT202 COV", "parts": [{"label": "Only fields 50a and 59a are mandatory", "note": "Only the ordering and beneficiary customer information in fields 50a and 59a is mandatory"}, {"label": "Other fields are optional", "note": "The other fields in sequence B are optional"}, {"label": "Provided fields must match the MT103", "note": "When a field such as 72 or 59 is given, it must match the same field in the MT103 exactly"}, {"label": "Or the field must be left empty", "note": "If it cannot match, the field must be left empty"}, {"label": "Some banks reject a mismatched cover", "note": "Some banks reject a cover whose sequence B does not match the announcement"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-mt103-202-cover-payment-analysis-part-3/"}, {"id": "PAI-C063", "seq": 234, "module": "Core", "source": "Paiementor", "title": "SSI: how a bank knows the beneficiary's correspondent", "explain": "Banks tell each other how to send them funds in each currency through standing settlement instructions, exchanged as MT670 and MT671 messages and stored in payment engine databases. An SSI names the correspondent of the receiver and any intermediaries on the route, so the sending bank can build the MT103 and the cover from the database instead of asking every time. A sender who does not know the receiver's correspondent must find it out through SWIFT services or by asking the receiver directly.", "takeaway": "A sender who does not know the receiver's correspondent must find it out through SWIFT services or by asking the receiver directly.", "visual": {"type": "diagram", "diagram": {"centre": "Standing settlement instructions", "parts": [{"label": "Exchanged as MT670 and MT671", "note": "SSIs are exchanged as MT670 and MT671 messages and stored in payment engine databases"}, {"label": "Names the receiver's correspondent", "note": "An SSI names the correspondent of the receiver and any intermediaries on the route"}, {"label": "Sending bank builds from the database", "note": "The sending bank can build the MT103 and the cover from the database instead of asking"}, {"label": "Unknown correspondent must be found out", "note": "A sender who does not know the correspondent must find it via SWIFT services or by asking"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-mt103-202-cover-payment-analysis-part-3/"}, {"id": "PAI-C064", "seq": 235, "module": "Core", "source": "Paiementor", "title": "With several SSIs, the sender may take the shortest route", "explain": "A bank can publish several standing settlement instructions for one currency, marking one as preferred, but the preferred route is an option, not an order. The sender may use a shorter route, even one that passes through a bank named in a non-preferred instruction, because the aim is for the funds to reach the beneficiary. If the beneficiary is paid faster on the shorter route, no one in the chain will complain.", "takeaway": "If the beneficiary is paid faster on the shorter route, no one in the chain will complain.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Bank publishes several SSIs", "note": "A bank can publish several standing settlement instructions for one currency"}, {"kind": "step", "title": "One route marked as preferred", "note": "One instruction is marked as preferred, but it is an option, not an order"}, {"kind": "step", "title": "Sender may use a shorter route", "note": "The sender may use a shorter route through a bank named in a non-preferred instruction"}, {"kind": "step", "title": "Beneficiary paid faster", "note": "If the beneficiary is paid faster on the shorter route, no one in the chain will complain"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-mt103-202-cover-payment-analysis-part-3/"}, {"id": "PAI-C065", "seq": 236, "module": "Core", "source": "Paiementor", "title": "Field 57a means something different in an MT103 and in an MT202 COV", "explain": "In a serial MT103, field 57a names the bank that holds the beneficiary's account, and field 56 names the intermediary that forwards the payment to it. In an MT202 COV the roles shift: field 58a names the beneficiary bank, while field 57a names the correspondent bank of the beneficiary bank. Reading field 57a the same way in both messages is a common error, because the same field number points at a different bank in each leg.", "takeaway": "Reading field 57a the same way in both messages is a common error, because the same field number points at a different bank in each leg.", "visual": {"type": "diagram", "diagram": {"centre": "Field 57a in MT103 and MT202 COV", "parts": [{"label": "Serial MT103: bank holding the account", "note": "In a serial MT103, field 57a names the bank that holds the beneficiary's account"}, {"label": "Serial MT103: field 56 is the intermediary", "note": "In a serial MT103, field 56 names the intermediary that forwards the payment"}, {"label": "MT202 COV: field 58a is the beneficiary bank", "note": "In an MT202 COV, field 58a names the beneficiary bank"}, {"label": "MT202 COV: field 57a is the correspondent", "note": "In an MT202 COV, field 57a names the correspondent bank of the beneficiary bank"}, {"label": "Reading 57a the same way is an error", "note": "Reading field 57a the same way in both messages is a common error"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-mt103-202-cover-payment-analysis-part-3/"}, {"id": "PAI-C066", "seq": 237, "module": "Core", "source": "Paiementor", "title": "An MT202 COV is itself a serial payment between banks", "explain": "Looked at on its own, an MT202 COV is a serial payment: the sender instructs the receiver to debit the sender's account and credit the next bank in the chain. Each bank in the cover chain debits the previous bank's account and instructs the next bank, until the funds reach the beneficiary bank. The cover is therefore not a different kind of movement, it is the same serial mechanism carrying the funds leg of a customer payment.", "takeaway": "The cover is therefore not a different kind of movement, it is the same serial mechanism carrying the funds leg of a customer payment.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Sender instructs receiver to debit its account", "note": "The sender instructs the receiver to debit the sender's account and credit the next bank"}, {"kind": "step", "title": "Each bank debits the previous bank", "note": "Each bank in the cover chain debits the previous bank's account"}, {"kind": "step", "title": "Each bank instructs the next bank", "note": "Each bank instructs the next bank in the chain"}, {"kind": "step", "title": "Funds reach the beneficiary bank", "note": "The funds reach the beneficiary bank through the same serial mechanism"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-mt103-202-cover-payment-analysis-part-3/"}, {"id": "PAI-C069", "seq": 238, "module": "Core", "source": "Paiementor", "title": "MT190 and MT191: the messages that move charges between banks", "explain": "When one bank owes another bank charges or interest on a payment, the claim travels in an MT191, a request for payment of charges, and the advice travels in an MT190. These messages exist because charges must not be deducted from a cover payment, so an intermediary that is owed money asks for it separately instead of taking it from the funds. A reader who sees an MT191 in a chain is therefore looking at the charges leg, not the payment itself.", "takeaway": "A reader who sees an MT191 in a chain is therefore looking at the charges leg, not the payment itself.", "visual": {"type": "diagram", "diagram": {"centre": "MT190 and MT191 move charges", "parts": [{"label": "MT191: request for payment of charges", "note": "When one bank owes another charges or interest, the claim travels in an MT191"}, {"label": "MT190: advice of charges", "note": "The advice of charges or interest travels in an MT190"}, {"label": "Charges must not come from the cover", "note": "Charges must not come from the cover, so an intermediary asks for them separately"}, {"label": "MT191 is the charges leg, not the payment", "note": "A reader who sees an MT191 is looking at the charges leg, not the payment itself"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-mt103-202-cover-payment-analysis-part-2/"}, {"id": "PAI-C070", "seq": 239, "module": "Core", "source": "Paiementor", "title": "No bank in the chain may change the currency of a payment", "explain": "The sender decides the currency of a transaction, and no intermediary may change it on the way. If the beneficiary's account is in a different currency, the conversion happens as a separate foreign exchange step, and the beneficiary is credited in the currency of the account. A payment sent in United States dollars to a United States dollar account that arrives short because an intermediary converted it twice has gone wrong, and the banks in the chain must be challenged on it.", "takeaway": "A payment sent in United States dollars to a United States dollar account that arrives short because an intermediary converted it twice has gone wrong, and the banks in the chain must be challenged on it.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Sender decides the currency", "note": "The sender decides the currency of a transaction"}, {"kind": "step", "title": "Intermediaries pass the currency unchanged", "note": "No intermediary may change the currency on the way"}, {"kind": "step", "title": "Conversion is a separate FX step", "note": "If the account is in another currency, conversion is a separate foreign exchange step"}, {"kind": "step", "title": "Beneficiary credited in account currency", "note": "The beneficiary is credited in the currency of the account"}, {"kind": "decision", "title": "Payment arriving short is wrong", "note": "A payment arriving short because an intermediary converted it twice has gone wrong"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-mt103-202-cover-payment-analysis-part-2/"}, {"id": "PAI-C072", "seq": 240, "module": "Core", "source": "Paiementor", "title": "How long a cross-border payment takes, and when a delay means a problem", "explain": "A transfer in a major currency such as the United States dollar or the euro usually arrives in 48 to 72 hours, while a transfer in a less common local currency takes longer because the currency is harder to buy. A large amount can also slow a payment down, because it may need extra checks before it is released. If the money has not arrived after two weeks, there is definitely a problem, and the sending bank should be asked to trace it, since it knows every party in the chain.", "takeaway": "If the money has not arrived after two weeks, there is definitely a problem, and the sending bank should be asked to trace it, since it knows every party in the chain.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Major currency transfer takes 48 to 72 hours", "note": "A transfer in United States dollars or euros usually arrives in 48 to 72 hours"}, {"kind": "step", "title": "Less common currency takes longer", "note": "A less common local currency takes longer because it is harder to buy"}, {"kind": "step", "title": "Large amount may need extra checks", "note": "A large amount can slow a payment down because it may need extra checks"}, {"kind": "decision", "title": "Money not arrived after two weeks", "note": "If the money has not arrived after two weeks, there is definitely a problem"}, {"kind": "step", "title": "Sending bank asked to trace it", "note": "The sending bank should be asked to trace it, since it knows every party in the chain"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-mt103-202-cover-payment-analysis-part-2/"}, {"id": "PAI-C074", "seq": 241, "module": "Core", "source": "Paiementor", "title": "71A BEN: the beneficiary pays every charge in the chain", "explain": "When field 71A carries BEN, every charge in the chain is borne by the beneficiary, and each bank deducts its charge from the amount as the payment passes through. The sender does not prepay the downstream charges, because the beneficiary is the one who pays them. A bank copy that shows SHA where the sender instructed BEN is therefore a discrepancy worth querying, since the two codes give the beneficiary a different amount.", "takeaway": "A bank copy that shows SHA where the sender instructed BEN is therefore a discrepancy worth querying, since the two codes give the beneficiary a different amount.", "visual": {"type": "diagram", "diagram": {"centre": "71A BEN: beneficiary pays all charges", "parts": [{"label": "Every charge borne by the beneficiary", "note": "When field 71A carries BEN, every charge in the chain is borne by the beneficiary"}, {"label": "Each bank deducts its charge", "note": "Each bank deducts its charge from the amount as the payment passes through"}, {"label": "Sender does not prepay downstream charges", "note": "The sender does not prepay the downstream charges, because the beneficiary pays them"}, {"label": "SHA shown where BEN was instructed", "note": "A bank copy that shows SHA where the sender instructed BEN is a discrepancy worth querying"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/mt103-swift-message-with-optional-fields-52a-and-57a-part-2/"}, {"id": "PAI-C075", "seq": 242, "module": "Core", "source": "Paiementor", "title": "The charges equation: 32A equals 33B plus 71G minus 71F", "explain": "Field 32A is the amount that settles between banks, field 33B is the amount the ordering customer instructed, field 71G is the receiver's charges prepaid by the sender, and field 71F is each sender's charge deducted along the way. The relationship always holds: 32A equals 33B plus 71G minus all the 71F charges. Field 71A itself is set by the bank that generates the MT103 and cannot be changed by later banks, which can only add a 71F when they take a charge.", "takeaway": "Field 71A itself is set by the bank that generates the MT103 and cannot be changed by later banks, which can only add a 71F when they take a charge.", "visual": {"type": "diagram", "diagram": {"centre": "32A equals 33B plus 71G minus 71F", "parts": [{"label": "32A", "note": "Amount that settles between banks"}, {"label": "33B", "note": "Amount the ordering customer instructed"}, {"label": "71G", "note": "Receiver charges prepaid by the sender"}, {"label": "71F", "note": "Each sender charge deducted along the way"}, {"label": "71A", "note": "Set by the MT103 bank, later banks can only add a 71F"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/mt103-swift-message-with-optional-fields-52a-and-57a-part-2/"}, {"id": "PAI-C078", "seq": 243, "module": "Core", "source": "Paiementor", "title": "Options B, C and D of field 57: what goes in the party identifier", "explain": "Field 57 has four options, and option A, with a BIC, is the one that allows straight-through processing. Option B carries a party identifier, generally an account number, with the location of the account, and a BIC must not be passed in option B: if the BIC is to be used, option A is the right choice. Option D needs no routing code at all and can simply carry the bank's name and address. The code /C/ or /D/ before an account number in a party identifier is part of the standard but is almost never used in practice.", "takeaway": "The code /C/ or /D/ before an account number in a party identifier is part of the standard but is almost never used in practice.", "visual": {"type": "diagram", "diagram": {"centre": "Options B, C and D of field 57", "parts": [{"label": "Option A allows straight-through processing", "note": "Option A, with a BIC, is the one that allows straight-through processing"}, {"label": "Option B: party identifier and location", "note": "Option B carries a party identifier, generally an account number, with the location"}, {"label": "No BIC in option B", "note": "A BIC must not be passed in option B; if the BIC is used, option A is the right choice"}, {"label": "Option D: name and address only", "note": "Option D needs no routing code at all and can simply carry the bank's name and address"}, {"label": "Codes /C/ and /D/ are rarely used", "note": "The code /C/ or /D/ before an account number is standard but almost never used"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/mt103-swift-message-with-optional-fields-52a-and-57a/"}, {"id": "PAI-C079", "seq": 244, "module": "Core", "source": "Paiementor", "title": "A CHIPS UID in field 57A", "explain": "In option A of field 57, the line before the BIC is the party identifier, and for a United States payment that identifier can be the beneficiary bank's CHIPS UID. The CHIPS UID identifies the bank in the United States clearing system, while the BIC identifies it on SWIFT, so the two sit together in the same field. Using the BIC alone is also valid, but the UID removes any doubt about which clearing account should be used.", "takeaway": "Using the BIC alone is also valid, but the UID removes any doubt about which clearing account should be used.", "visual": {"type": "diagram", "diagram": {"centre": "A CHIPS UID in field 57A", "parts": [{"label": "Party identifier line before the BIC", "note": "In option A of field 57, the line before the BIC is the party identifier"}, {"label": "CHIPS UID identifies the US clearing bank", "note": "For a United States payment that identifier can be the beneficiary bank's CHIPS UID"}, {"label": "BIC identifies the bank on SWIFT", "note": "The CHIPS UID identifies the bank in US clearing, while the BIC identifies it on SWIFT"}, {"label": "BIC alone is also valid", "note": "Using the BIC alone is also valid, but the UID removes doubt about the clearing account"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/mt103-swift-message-with-optional-fields-52a-and-57a/"}, {"id": "PAI-C081", "seq": 245, "module": "Core", "source": "Paiementor", "title": "Field 53B: when a bank holds several accounts with the same correspondent", "explain": "A bank can hold more than one account with the same correspondent in the same currency, and field 53B exists to say exactly which account must be debited. Using option B tells the receiver that the sender has many accounts with it and wants a specific one used to settle the transaction. Field 53 itself is optional in an MT103, and it does not always contain the sender's nostro account, because the field has three options that can carry different information.", "takeaway": "Field 53 itself is optional in an MT103, and it does not always contain the sender's nostro account, because the field has three options that can carry different information.", "visual": {"type": "diagram", "diagram": {"centre": "Field 53B: which account to debit", "parts": [{"label": "Bank can hold several accounts", "note": "A bank can hold more than one account with the same correspondent in the same currency"}, {"label": "Field 53B names the exact account", "note": "Field 53B exists to say exactly which account must be debited"}, {"label": "Option B signals many accounts", "note": "Using option B tells the receiver the sender has many accounts and wants one used"}, {"label": "Field 53 is optional in an MT103", "note": "Field 53 itself is optional in an MT103"}, {"label": "Not always the sender's nostro account", "note": "Field 53 does not always contain the sender's nostro account, as its options differ"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-mt103-message-example-with-optional-fields-53b-70-and-71g-explained/"}, {"id": "PAI-C082", "seq": 246, "module": "Core", "source": "Paiementor", "title": "Field 70: one code, one reference, and the 16-character RFB limit", "explain": "Field 70 carries remittance information, and several references can be given if they are separated by a double slash, but a code such as /RFB/ or /INV/ must not be repeated between two references of the same kind. The reference that follows /RFB/ is limited to 16 characters, so a longer description must continue on the following lines of the field instead of stretching the reference. A field 70 that repeats a code or overruns the limit is not a valid instruction, even though no system may reject it automatically.", "takeaway": "A field 70 that repeats a code or overruns the limit is not a valid instruction, even though no system may reject it automatically.", "visual": {"type": "diagram", "diagram": {"centre": "Field 70: remittance information", "parts": [{"label": "Several references, separated by double slash", "note": "Several references can be given if they are separated by a double slash"}, {"label": "A code must not be repeated", "note": "A code such as /RFB/ or /INV/ must not be repeated between two references of the same kind"}, {"label": "/RFB/ reference limited to 16 characters", "note": "The reference that follows /RFB/ is limited to 16 characters"}, {"label": "Longer text continues on following lines", "note": "A longer description must continue on the following lines, not stretch the reference"}, {"label": "Invalid field, even if not rejected", "note": "A field 70 with a repeated code or an overrun limit is not valid"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-mt103-message-example-with-optional-fields-53b-70-and-71g-explained/"}, {"id": "PAI-C084", "seq": 247, "module": "Core", "source": "Paiementor", "title": "FFC: telling the beneficiary bank to credit a further account", "explain": "When the funds must be credited to an account other than the beneficiary's own account, the instruction travels as /FFC/, for further credit, in field 72, sender to receiver information. The beneficiary bank reads the code and passes the funds on to the account named after it, instead of crediting the beneficiary directly. Without the code, the bank has no instruction to look beyond the beneficiary named in field 59.", "takeaway": "Without the code, the bank has no instruction to look beyond the beneficiary named in field 59.", "visual": {"type": "diagram", "diagram": {"centre": "FFC: credit a further account", "parts": [{"label": "Instruction travels as /FFC/ in field 72", "note": "The instruction travels as /FFC/, for further credit, in field 72"}, {"label": "Beneficiary bank passes funds onward", "note": "The beneficiary bank reads the code and passes the funds on to the account named after it"}, {"label": "Without the code, no onward instruction", "note": "Without the code, the bank has no instruction to look beyond the beneficiary in field 59"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-mt103-message-example-with-optional-fields-53b-70-and-71g-explained/"}, {"id": "PAI-C087", "seq": 248, "module": "Core", "source": "Paiementor", "title": "The UETR lives in field 121 of block 3, and it is how a payment is tracked", "explain": "The unique end-to-end transaction reference, the UETR, is carried in field 121 of block 3 of the message header, not in the body of the MT103. When a payment is late or a bank cannot trace it, the UETR is the reference to give the bank, because every bank in the chain can use it to follow the payment across the network. A copy of an MT103 on its own proves nothing about whether the money moved; the UETR and the sending bank's records are what settle the question.", "takeaway": "A copy of an MT103 on its own proves nothing about whether the money moved; the UETR and the sending bank's records are what settle the question.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "UETR carried in field 121 of block 3", "note": "The UETR is carried in field 121 of block 3 of the message header, not in the body"}, {"kind": "step", "title": "Every bank in the chain can use it", "note": "Every bank in the chain can use it to follow the payment across the network"}, {"kind": "step", "title": "Payment late or untraceable", "note": "When a payment is late or untraceable, the UETR is the reference to give the bank"}, {"kind": "step", "title": "MT103 copy alone proves nothing", "note": "A copy of an MT103 on its own proves nothing about whether the money moved"}, {"kind": "step", "title": "UETR and bank records settle the question", "note": "The UETR and the sending bank's records are what settle the question"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-mt103-message-example-with-optional-fields-53b-70-and-71g-explained/"}, {"id": "PAI-C088", "seq": 249, "module": "Core", "source": "Paiementor", "title": "Field 50K: the ordering customer's name may run over more than one line", "explain": "Option K of field 50a allows the ordering customer's name and address in up to four lines of 35 characters each. The name does not have to fit on the first line: it can sit on one line with the address on the rest, or run over two or three lines with the address on what remains. The standard does not restrict the name to the first line, so a name split across lines is valid.", "takeaway": "The standard does not restrict the name to the first line, so a name split across lines is valid.", "visual": {"type": "diagram", "diagram": {"centre": "Field 50K: name over several lines", "parts": [{"label": "Up to four lines of 35 characters", "note": "Field 50K allows the name and address in up to four lines of 35 characters"}, {"label": "Name need not fit on the first line", "note": "The name does not have to fit on the first line"}, {"label": "Name on one line, address on the rest", "note": "The name can sit on one line with the address on the rest"}, {"label": "Name over two or three lines is valid", "note": "The name can run over two or three lines with the address on what remains"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-mt103-message-example-with-optional-fields-53b-70-and-71g-explained/"}, {"id": "PAI-C089", "seq": 250, "module": "Core", "source": "Paiementor", "title": "The MT103 announcement must say where the cover is coming from", "explain": "In a cover payment the MT103 announcement should state in field 53 which correspondent will send the cover, so the beneficiary bank knows where the funds will come from. When the cover arrives from a bank the announcement never mentioned, the beneficiary bank cannot match the two legs and will not credit the beneficiary. The fix sits with the sender, whose bank must correct the announcement so the two legs agree.", "takeaway": "The fix sits with the sender, whose bank must correct the announcement so the two legs agree.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "MT103 announcement states field 53", "note": "The MT103 announcement should state in field 53 which correspondent will send the cover"}, {"kind": "step", "title": "Beneficiary bank knows where funds come from", "note": "The beneficiary bank knows where the funds will come from"}, {"kind": "step", "title": "Cover arrives from an unmentioned bank", "note": "When the cover comes from an unmentioned bank, the legs cannot be matched"}, {"kind": "step", "title": "Beneficiary bank will not credit", "note": "The beneficiary bank cannot match the two legs and will not credit the beneficiary"}, {"kind": "step", "title": "Sender corrects the announcement", "note": "The sender's bank must correct the announcement so the two legs agree"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-mt103-message-example-with-optional-fields-53b-70-and-71g-explained/"}, {"id": "PAI-C090", "seq": 251, "module": "Core", "source": "Paiementor", "title": "An MT103 with no beneficiary name", "explain": "An MT103 can arrive showing only the beneficiary's IBAN and address in field 59, with no name at all. Field 59 is meant to identify the beneficiary, so a missing name leaves the beneficiary bank unable to confirm that the account belongs to the person the payment was meant for. The bank may hold the payment and ask for confirmation instead of crediting it, and the sender's bank is the one that must supply the missing name.", "takeaway": "The bank may hold the payment and ask for confirmation instead of crediting it, and the sender's bank is the one that must supply the missing name.", "visual": {"type": "diagram", "diagram": {"centre": "An MT103 with no beneficiary name", "parts": [{"label": "Only IBAN and address in field 59", "note": "An MT103 can arrive showing only the beneficiary's IBAN and address in field 59"}, {"label": "Field 59 must identify the beneficiary", "note": "Field 59 is meant to identify the beneficiary"}, {"label": "Bank cannot confirm the account owner", "note": "A missing name leaves the bank unable to confirm the account belongs to the right person"}, {"label": "Bank may hold and ask for confirmation", "note": "The bank may hold the payment and ask for confirmation instead of crediting it"}, {"label": "Sender's bank must supply the name", "note": "The sender's bank is the one that must supply the missing name"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-mt103-message-example-with-optional-fields-53b-70-and-71g-explained/"}, {"id": "PAI-C092", "seq": 252, "module": "Core", "source": "Paiementor", "title": "Field 20 and field 21R in an MT101: two references with two owners", "explain": "Field 20 is the sender's reference, assigned by the bank that sends the MT101 to identify the payment. Field 21R is the ordering customer's reference, assigned by the customer who ordered the payment, and it stays the same across every message sent for one order. The two references can coincide when the sender is also the ordering customer, but they belong to different parties, and field 21R is optional while field 20 is mandatory.", "takeaway": "The two references can coincide when the sender is also the ordering customer, but they belong to different parties, and field 21R is optional while field 20 is mandatory.", "visual": {"type": "diagram", "diagram": {"centre": "Fields 20 and 21R in an MT101", "parts": [{"label": "Field 20: sender's reference", "note": "Field 20 is the sender's reference, assigned by the bank that sends the MT101"}, {"label": "Field 21R: ordering customer's reference", "note": "Field 21R is the ordering customer's reference, assigned by the customer who ordered it"}, {"label": "Field 21R stays the same across messages", "note": "Field 21R stays the same across every message sent for one order"}, {"label": "References can coincide", "note": "The two references can coincide when the sender is also the ordering customer"}, {"label": "Field 20 mandatory, field 21R optional", "note": "Field 21R is optional while field 20 is mandatory"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-mt101-usage-for-funds-repatriation/"}, {"id": "PAI-C093", "seq": 253, "module": "Core", "source": "Paiementor", "title": "Who the beneficiary sees when a parent pays for a subsidiary", "explain": "When a parent company sends an MT101 to pay on behalf of a subsidiary, the sender of the payment is the parent company, not the subsidiary. The beneficiary is told the payment is from the subsidiary through the Instructing Party field, which names the subsidiary even though the parent sent the instruction. The beneficiary therefore sees the parent as the sender and the subsidiary as the party the payment is really from.", "takeaway": "The beneficiary therefore sees the parent as the sender and the subsidiary as the party the payment is really from.", "visual": {"type": "diagram", "diagram": {"centre": "Who the beneficiary sees", "parts": [{"label": "Sender is the parent company", "note": "When a parent sends an MT101 for a subsidiary, the sender is the parent company"}, {"label": "Instructing Party names the subsidiary", "note": "The beneficiary is told the payment is from the subsidiary via the Instructing Party field"}, {"label": "Beneficiary sees parent as sender", "note": "The beneficiary sees the parent as sender and the subsidiary as the real source"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-mt101-usage-parent-company-pay-behalf-subsidiaries/"}, {"id": "PAI-C094", "seq": 254, "module": "Core", "source": "Paiementor", "title": "A subsidiary paying from the parent's account needs authorisation", "explain": "A subsidiary cannot simply use its parent company's account to pay: an authorisation is required before the subsidiary may draw on the parent's account. In the MT101 the subsidiary appears as the Instructing Party in field 50L, while the parent company appears as the ordering customer in field 50H, because the parent owns the account that will be debited. The same need for authorisation applies whenever the sender of an instruction is not the owner of the account being debited.", "takeaway": "The same need for authorisation applies whenever the sender of an instruction is not the owner of the account being debited.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Subsidiary wants to use parent's account", "note": "A subsidiary cannot simply use its parent company's account to pay"}, {"kind": "step", "title": "Authorisation required first", "note": "An authorisation is required before the subsidiary may draw on the parent's account"}, {"kind": "step", "title": "Subsidiary appears as Instructing Party", "note": "In the MT101 the subsidiary appears as the Instructing Party in field 50L"}, {"kind": "step", "title": "Parent appears as ordering customer", "note": "The parent company appears as the ordering customer in field 50H, as it owns the account"}, {"kind": "step", "title": "Rule applies whenever sender is not owner", "note": "The same need applies whenever the sender is not the owner of the account debited"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/mt101-swift-message-usage-pay-subsidiary-account/"}, {"id": "PAI-C095", "seq": 255, "module": "Core", "source": "Paiementor", "title": "One MT101 to a concentrating bank instead of one to each bank", "explain": "A large corporate with accounts at many banks can send a single MT101 to one concentrating bank, and that bank forwards the instruction to each bank that holds an account to be debited. The alternative is for the corporate to prepare a separate MT101 for every bank, which is slower and harder to manage. The forwarding service is a genuine value-added service, and the concentrating bank charges for it.", "takeaway": "The forwarding service is a genuine value-added service, and the concentrating bank charges for it.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Corporate holds accounts at many banks", "note": "A large corporate has accounts at many banks"}, {"kind": "step", "title": "Alternative is one MT101 per bank", "note": "The alternative is a separate MT101 for every bank, which is slower and harder to manage"}, {"kind": "step", "title": "One MT101 to the concentrating bank", "note": "The corporate sends a single MT101 to one concentrating bank"}, {"kind": "step", "title": "Concentrating bank forwards to each bank", "note": "That bank forwards the instruction to each bank that holds an account to be debited"}, {"kind": "step", "title": "Concentrating bank charges for the service", "note": "The forwarding service is a genuine value-added service, and the bank charges for it"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/mt101-swift-message-usage-pay-subsidiary-account/"}, {"id": "PAI-C096", "seq": 256, "module": "Core", "source": "Paiementor", "title": "Field 28D: one order split across several MT101 messages", "explain": "An MT101 message is limited to 10,000 characters, so an order with many transactions must be split across several MT101 messages, numbered in field 28D as 1 of 5, 2 of 5, and so on. Banks are configured to hold a chained message until every message in the chain has arrived, because processing one element alone could pay the wrong amounts. Banks also set their own limits on how many transactions they will accept in one order, so a very large order should be agreed with the bank before it is sent.", "takeaway": "Banks also set their own limits on how many transactions they will accept in one order, so a very large order should be agreed with the bank before it is sent.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Order exceeds the 10,000 character limit", "note": "An MT101 message is limited to 10,000 characters"}, {"kind": "step", "title": "Order split across several MT101s", "note": "An order with many transactions must be split across several MT101 messages"}, {"kind": "step", "title": "Messages numbered in field 28D", "note": "Messages are numbered in field 28D as 1 of 5, 2 of 5, and so on"}, {"kind": "step", "title": "Banks hold the chain until all arrive", "note": "Banks hold a chained message until every message in the chain has arrived"}, {"kind": "step", "title": "Very large order agreed with the bank", "note": "A very large order should be agreed with the bank first, as banks set their own limits"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-mt101-definition-with-field-50a-in-sequence-b/"}, {"id": "PAI-C098", "seq": 257, "module": "Core", "source": "Paiementor", "title": "When debtor and beneficiary share one bank, one MT101 is enough", "explain": "If the same bank holds both the debtor's account and the beneficiary's account, the payment never leaves the bank, so no interbank message is needed. A single MT101 is enough: the bank debits the debtor's account and credits the beneficiary's account on its own books. An MT103 is only required when the beneficiary's bank is different from the debtor's bank.", "takeaway": "An MT103 is only required when the beneficiary's bank is different from the debtor's bank.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Same bank holds both accounts", "note": "The same bank holds both the debtor's account and the beneficiary's account"}, {"kind": "step", "title": "Payment never leaves the bank", "note": "The payment never leaves the bank, so no interbank message is needed"}, {"kind": "step", "title": "Single MT101 is enough", "note": "A single MT101 is enough for the payment"}, {"kind": "step", "title": "Bank debits debtor and credits beneficiary", "note": "The bank debits the debtor and credits the beneficiary on its own books"}, {"kind": "step", "title": "MT103 only needed for different banks", "note": "An MT103 is only required when the beneficiary's bank is different from the debtor's bank"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/basic-swift-mt101-message-with-two-domestic-transactions/"}, {"id": "PAI-C100", "seq": 258, "module": "Core", "source": "Paiementor", "title": "One MT940, one closing balance: 62F appears once", "explain": "A statement split across several MT940 messages must use the intermediate closing balance, tag 62M, in every message except the last. Only the final message carries the final closing balance, tag 62F, because there is only one closing balance for the whole statement. A client system that receives a 62F in an intermediate message may treat the statement as finished and fail to generate the messages that follow.", "takeaway": "A client system that receives a 62F in an intermediate message may treat the statement as finished and fail to generate the messages that follow.", "visual": {"type": "diagram", "diagram": {"centre": "One MT940, one closing balance", "parts": [{"label": "Intermediate messages use tag 62M", "note": "A statement split across several MT940s must use tag 62M in every message except the last"}, {"label": "Only the final message carries 62F", "note": "Only the final message carries the final closing balance, tag 62F"}, {"label": "Only one closing balance exists", "note": "There is only one closing balance for the whole statement"}, {"label": "Early 62F breaks the receiver's system", "note": "A client system receiving a 62F mid-statement may treat the statement as finished"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/opening-closing-and-forward-available-balances-in-the-swift-mt940-format/"}, {"id": "PAI-C101", "seq": 259, "module": "Core", "source": "Paiementor", "title": "The dates on intermediate balances in an MT940 should match the last entry", "explain": "When a statement is split across several MT940 messages, the intermediate opening balance tag 60M and the intermediate closing balance tag 62M should ideally carry the date of the last debit or credit entry in that message. In practice receivers care most that the balances themselves are correct, and the dates that truly matter are those of the opening balance, the closing balance, the closing available balance and the forward available balance. If the intermediate dates can be fixed easily, they should be.", "takeaway": "If the intermediate dates can be fixed easily, they should be.", "visual": {"type": "diagram", "diagram": {"centre": "Dates on intermediate MT940 balances", "parts": [{"label": "Tags 60M and 62M should match the last entry", "note": "Tags 60M and 62M should ideally carry the date of the last entry in that message"}, {"label": "Receivers care most that balances are correct", "note": "In practice receivers care most that the balances themselves are correct"}, {"label": "Dates that truly matter", "note": "The dates that matter are opening, closing, and forward available balances"}, {"label": "Fix intermediate dates if easy", "note": "If the intermediate dates can be fixed easily, they should be"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/opening-closing-and-forward-available-balances-in-the-swift-mt940-format/"}, {"id": "PAI-C102", "seq": 260, "module": "Core", "source": "Paiementor", "title": "A long statement arrives as several MT940 messages", "explain": "A single MT940 can carry only a limited number of entries, so a statement with many entries is split across several MT940 messages, one after another. Each message carries a statement number and a sequence number, and the sequence number rises with each new message, so the receiver can put the statement back together in order. The chain can run to a very large number of sequences, which is more than enough in practice.", "takeaway": "The chain can run to a very large number of sequences, which is more than enough in practice.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Statement has many entries", "note": "A single MT940 can carry only a limited number of entries"}, {"kind": "step", "title": "Statement split across several MT940s", "note": "The statement is split across several MT940 messages, one after another"}, {"kind": "step", "title": "Each message carries statement and sequence", "note": "Each message carries a statement number and a sequence number"}, {"kind": "step", "title": "Sequence number rises with each message", "note": "The sequence number rises with each message, so the receiver can rebuild the order"}, {"kind": "step", "title": "Chain can run to a very large number", "note": "The chain can run to a very large number of sequences, more than enough in practice"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/opening-closing-and-forward-available-balances-in-the-swift-mt940-format/"}, {"id": "RUN3-002", "seq": 261, "module": "Core", "source": "Paiementor", "title": "A pacs.002 carries no accounting entry, and a negative acknowledgement reverses prior postings exactly", "explain": "A pacs.002 is a status report, not a movement of money, so it normally carries no accounting entry of its own. When it reports a negative acknowledgement, any postings already made for that payment are reversed exactly, so the books return to the position before the payment was attempted. Treating the pacs.002 itself as a debit or credit would double count the payment.", "takeaway": "Treating the pacs.002 itself as a debit or credit would double count the payment.", "visual": {"type": "diagram", "diagram": {"centre": "pacs.002 status report", "parts": [{"label": "No accounting entry", "note": "A pacs.002 is a status report, not a movement of money, so it carries no entry of its own."}, {"label": "Negative acknowledgement", "note": "When it reports a negative acknowledgement, prior postings are reversed exactly."}, {"label": "Books return to prior position", "note": "Reversing the postings restores the books to the position before the payment attempt."}, {"label": "No double counting", "note": "Treating the pacs.002 as a debit or credit would double count the payment."}]}}, "level": "core", "source_ref": "https://www.paiementor.com/focus-on-sct-beneficiary-bank-messages-in-the-interbank-space/"}, {"id": "RUN3-003", "seq": 262, "module": "Core", "source": "Paiementor", "title": "camt.054 or MT900: the sender chooses how to notify a credit", "explain": "When a bank notifies its customer of a credit, it can use a camt.054 in ISO 20022 or an MT900 in the MT format. There is no governing rule that forces one or the other, so the choice belongs to the sender. Both carry the same job, telling the account owner that a credit has been applied, and the receiver must be able to read whichever form arrives.", "takeaway": "Both carry the same job, telling the account owner that a credit has been applied, and the receiver must be able to read whichever form arrives.", "visual": {"type": "diagram", "diagram": {"centre": "Credit notification choice", "parts": [{"label": "camt.054", "note": "An ISO 20022 message the bank can use to notify its customer of a credit."}, {"label": "MT900", "note": "The MT format message that does the same job of notifying a credit."}, {"label": "Sender chooses", "note": "No governing rule forces one or the other, so the choice belongs to the sender."}, {"label": "Receiver must read both", "note": "The receiver must be able to read whichever form arrives."}]}}, "level": "core", "source_ref": "https://www.paiementor.com/camt-messages-for-customer-reporting-in-the-customer-to-bank-space/"}, {"id": "RUN3-004", "seq": 263, "module": "Core", "source": "Paiementor", "title": "SDD: no scheme response after pacs.007, and the creditor bank cannot refuse a pacs.004", "explain": "In a SEPA direct debit the debtor bank sends no scheme response after the pacs.007 collection instruction, so silence after that point does not mean the collection failed. If the collection comes back as a pacs.004 return or refund, the creditor bank must process it and has no choice to refuse it. The creditor therefore has to handle returns in its own processing rather than expecting the debtor bank to ask permission.", "takeaway": "The creditor therefore has to handle returns in its own processing rather than expecting the debtor bank to ask permission.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Creditor sends pacs.007 collection", "note": "The collection instruction goes to the debtor bank under the SDD scheme."}, {"kind": "step", "title": "Debtor bank sends no response", "note": "Silence after that point does not mean the collection failed."}, {"kind": "step", "title": "Collection comes back as pacs.004", "note": "A pacs.004 return or refund must be processed by the creditor bank."}, {"kind": "step", "title": "Creditor bank processes the return", "note": "The creditor has no choice to refuse it and must handle returns in its own processing."}]}}, "level": "core", "source_ref": "https://www.paiementor.com/iso-20022-messages-exchanged-in-the-sdd-schemes/"}, {"id": "RUN3-005", "seq": 264, "module": "Core", "source": "Paiementor", "title": "pacs.004 return or refund: who initiates it decides which one it is", "explain": "A pacs.004 can be either a return or a refund, and the two are not interchangeable. The distinction turns on who initiates it, so the same message type covers two different business events depending on which side starts the process. Reading the initiator correctly matters, because a return and a refund follow different rules and different time limits.", "takeaway": "Reading the initiator correctly matters, because a return and a refund follow different rules and different time limits.", "visual": {"type": "diagram", "diagram": {"centre": "pacs.004 return or refund", "parts": [{"label": "Return", "note": "One of the two business events the pacs.004 can carry, started by one side."}, {"label": "Refund", "note": "The other business event the same message type covers, started by the other side."}, {"label": "Initiator decides", "note": "The distinction turns on who initiates it, so the initiator must be read correctly."}, {"label": "Different rules and time limits", "note": "A return and a refund follow different rules and different time limits."}]}}, "level": "core", "source_ref": "https://www.paiementor.com/iso-20022-messages-exchanged-in-the-sdd-schemes/"}, {"id": "RUN3-006", "seq": 265, "module": "Core", "source": "Paiementor", "title": "SDD Core refund windows: 8 weeks with a valid mandate, 13 months without one", "explain": "Under SDD Core a debtor can claim a refund within 8 weeks when there is a valid mandate behind the collection. The longer 13 month window applies only when there is no valid mandate at all, so the two periods must not be mixed up. The mandate itself is held by the creditor, which is why the creditor must be able to produce it when a refund claim is challenged.", "takeaway": "The mandate itself is held by the creditor, which is why the creditor must be able to produce it when a refund claim is challenged.", "visual": {"type": "diagram", "diagram": {"centre": "SDD Core refund windows", "parts": [{"label": "8 weeks with a valid mandate", "note": "A debtor can claim a refund within 8 weeks when a valid mandate backs the collection."}, {"label": "13 months without a valid mandate", "note": "The longer window applies only when there is no valid mandate at all."}, {"label": "Mandate held by the creditor", "note": "The creditor holds the mandate and must produce it when a refund claim is challenged."}]}}, "level": "core", "source_ref": "https://www.paiementor.com/main-differences-between-sepa-direct-debit-core-and-b2b-schemes/"}, {"id": "RUN3-007", "seq": 266, "module": "Core", "source": "Paiementor", "title": "MT950 intraday: a statement can run alongside the MT940 if both sides agree", "explain": "An MT950 statement is normally the end of day statement, but it can also be generated intraday alongside the MT940. The only condition is that both the account servicing bank and the account owner agree to it. That agreement matters because the intraday MT950 changes what the receiver expects to see during the day.", "takeaway": "That agreement matters because the intraday MT950 changes what the receiver expects to see during the day.", "visual": {"type": "diagram", "diagram": {"centre": "MT950 intraday statement", "parts": [{"label": "Normally end of day", "note": "An MT950 statement is normally the end of day statement."}, {"label": "Can run intraday", "note": "It can also be generated intraday alongside the MT940."}, {"label": "Both sides must agree", "note": "The account servicing bank and the account owner must agree to the intraday run."}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-mt950-statement-message-detailed-analysis/"}, {"id": "RUN3-008", "seq": 267, "module": "Core", "source": "Paiementor", "title": "MT950 structure: field 61 repeats for every transaction, field 62F appears once", "explain": "In an MT950 each transaction on the statement is carried in its own repeating field 61, so a statement with twenty transactions has twenty field 61 blocks. The closing balance in field 62F appears only once, at the end, and it must agree with the opening balance plus all the field 61 entries. Checking that arithmetic is the quickest way to confirm a statement is complete.", "takeaway": "Checking that arithmetic is the quickest way to confirm a statement is complete.", "visual": {"type": "diagram", "diagram": {"centre": "MT950 statement structure", "parts": [{"label": "Field 61 repeats per transaction", "note": "Each transaction is carried in its own repeating field 61 block."}, {"label": "Twenty transactions, twenty blocks", "note": "A statement with twenty transactions has twenty field 61 blocks."}, {"label": "Field 62F appears once", "note": "The closing balance in field 62F appears only once, at the end."}, {"label": "Balances must agree", "note": "Field 62F must agree with the opening balance plus all the field 61 entries."}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-mt950-statement-message-detailed-analysis/"}, {"id": "RUN3-011", "seq": 268, "module": "Core", "source": "Paiementor", "title": "MT940 fields 61 and 86: the transaction line and the story behind it", "explain": "In an MT940 each transaction is carried in field 61, the statement line, which holds the date, the amount, and the type of entry. Field 86 sits with that line and carries the information to the account owner, the narrative that explains what the transaction was. Reading field 61 alone tells you money moved, while field 86 tells you why, and reconciliation needs both.", "takeaway": "Reading field 61 alone tells you money moved, while field 86 tells you why, and reconciliation needs both.", "visual": {"type": "diagram", "diagram": {"centre": "MT940 statement fields", "parts": [{"label": "Field 61, the statement line", "note": "Each transaction is carried in field 61, holding the date, amount and type of entry."}, {"label": "Field 86, the narrative", "note": "Field 86 sits with the line and carries the information to the account owner."}, {"label": "Field 61 shows money moved", "note": "Reading field 61 alone tells you money moved, while field 86 tells you why."}, {"label": "Both needed for reconciliation", "note": "Reconciliation needs both the line and the story behind it."}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-mt940-customer-statement-detailed-analysis/"}, {"id": "RUN3-012", "seq": 269, "module": "Core", "source": "Paiementor", "title": "MT940 balances: 62M, 64 and 65 answer three different questions", "explain": "Field 62M is the interim closing balance, the balance at the point the statement was cut during the day. Field 64 is the closing available balance, the funds actually available at the end of the day. Field 65 is the forward available balance, the funds expected to be available on a future date. Mixing them up overstates or understates liquidity, so each must be read for the question it answers.", "takeaway": "Mixing them up overstates or understates liquidity, so each must be read for the question it answers.", "visual": {"type": "diagram", "diagram": {"centre": "MT940 balances answer three questions", "parts": [{"label": "62M", "note": "Interim closing balance, at the point the statement was cut"}, {"label": "64", "note": "Closing available balance, funds available at end of day"}, {"label": "65", "note": "Forward available balance, funds expected on a future date"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-mt940-customer-statement-detailed-analysis/"}, {"id": "RUN3-013", "seq": 270, "module": "Core", "source": "Paiementor", "title": "MT940 completeness: field 28C proves no statement is missing", "explain": "Field 28C carries the statement number and the sequence number, so it tells the receiver exactly which statement this is and where it sits in the run. If a statement is missing or arrives out of order, the gap shows up in the 28C sequence before any transaction is checked. That makes field 28C the first completeness check on every MT940 received.", "takeaway": "That makes field 28C the first completeness check on every MT940 received.", "visual": {"type": "diagram", "diagram": {"centre": "MT940 completeness check", "parts": [{"label": "Field 28C carries statement number", "note": "It tells the receiver exactly which statement this is and where it sits in the run."}, {"label": "Sequence reveals gaps", "note": "If a statement is missing or arrives out of order, the gap shows up in the 28C sequence."}, {"label": "Checked before transactions", "note": "The gap shows up before any transaction is checked."}, {"label": "First completeness check", "note": "Field 28C is the first completeness check on every MT940 received."}]}}, "level": "core", "source_ref": "https://www.paiementor.com/swift-mt940-customer-statement-detailed-analysis/"}, {"id": "RUN4-008", "seq": 271, "module": "Core", "source": "Paiementor", "title": "Small banks borrow big banks' correspondent networks", "explain": "Setting up and maintaining a correspondent network is costly and slow, so a small bank often opens a foreign currency account with a large bank in its own country that already has a correspondent in the currency's country. The large bank then acts as the intermediary for the small bank's cross-border payments, while the real funds still end up held in the country of the currency. Strictly speaking the large bank is the small bank's correspondent, but in a cross-border transfer it is usually called the intermediary bank.", "takeaway": "Strictly speaking the large bank is the small bank's correspondent, but in a cross-border transfer it is usually called the intermediary bank.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Small bank opens an account", "note": "The small bank opens a foreign currency account with a large bank in its own country."}, {"kind": "step", "title": "Large bank provides its correspondent", "note": "The large bank already has a correspondent in the currency's country."}, {"kind": "step", "title": "Large bank acts as intermediary", "note": "The large bank acts as the intermediary for the small bank's cross-border payments."}, {"kind": "step", "title": "Real funds held in currency country", "note": "The real funds still end up held in the country of the currency."}, {"kind": "step", "title": "Large bank is the correspondent", "note": "The large bank is the small bank's correspondent, usually called the intermediary bank."}]}}, "level": "core", "source_ref": "https://www.paiementor.com/strategy-2-understand-how-cross-border-payments-work/"}, {"id": "RUN4-009", "seq": 272, "module": "Core", "source": "Paiementor", "title": "Standing Settlement Instructions: how banks publish and find correspondents", "explain": "Banks tell each other who their correspondents are through Standing Settlement Instructions, exchanged as SWIFT MT670 and MT671 messages, and receiving banks store them in their payment engines. The MT671 is broadcast to all SWIFT institutions, whether or not they have a direct relationship with the sending bank. When a bank has several correspondents in one currency, it lists them all, and the sender chooses among them.", "takeaway": "When a bank has several correspondents in one currency, it lists them all, and the sender chooses among them.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Banks exchange settlement instructions", "note": "Banks tell each other who their correspondents are through settlement instructions."}, {"kind": "step", "title": "MT670 and MT671 sent", "note": "The instructions are exchanged as SWIFT MT670 and MT671 messages."}, {"kind": "step", "title": "MT671 broadcast widely", "note": "The MT671 is broadcast to all SWIFT institutions, with or without a direct relationship."}, {"kind": "step", "title": "Receiving banks store them", "note": "Receiving banks store the instructions in their payment engines."}, {"kind": "step", "title": "Sender chooses among correspondents", "note": "A bank with several correspondents in one currency lists them all, and the sender chooses."}]}}, "level": "core", "source_ref": "https://www.paiementor.com/strategy-2-understand-how-cross-border-payments-work/"}, {"id": "RUN4-010", "seq": 273, "module": "Core", "source": "Paiementor", "title": "Mirror nostro updates happen per transaction, not once a day", "explain": "Every movement on the real nostro is reflected on the mirror nostro one transaction at a time. When the nostro is credited, the correspondent advises the account holder, for example with an MT910 or MT950, and the mirror is updated from that advice. When the bank instructs its correspondent to debit the nostro, it updates the mirror right away. The entries on the two accounts are always for the same amount and with opposite signs.", "takeaway": "The entries on the two accounts are always for the same amount and with opposite signs.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Movement happens on the real nostro", "note": "Every movement on the real nostro is reflected on the mirror, one transaction at a time."}, {"kind": "step", "title": "Correspondent advises the holder", "note": "When the nostro is credited, the correspondent advises the holder with an MT910 or MT950."}, {"kind": "step", "title": "Mirror updated from the advice", "note": "The mirror is updated from that advice when the nostro is credited."}, {"kind": "step", "title": "Debit instructed, mirror updated at once", "note": "When the bank tells its correspondent to debit the nostro, the mirror is updated at once."}, {"kind": "step", "title": "Same amount, opposite signs", "note": "The entries on the two accounts are always for the same amount and with opposite signs."}]}}, "level": "core", "source_ref": "https://www.paiementor.com/strategy-2-understand-how-cross-border-payments-work/"}, {"id": "RUN4-011", "seq": 274, "module": "Core", "source": "Paiementor", "title": "Why the mirror shows the opposite sign", "explain": "A debit on the real nostro account shows as a credit on the mirror nostro, and a credit on the real account shows as a debit on the mirror, always for the same amount. The mirror is the reflection of the real account, so the two sides are opposite by design. Knowing the mirror balance and its movements lets a bank work out exactly what the real account should show.", "takeaway": "Knowing the mirror balance and its movements lets a bank work out exactly what the real account should show.", "visual": {"type": "diagram", "diagram": {"centre": "Mirror nostro opposite sign", "parts": [{"label": "Real debit, mirror credit", "note": "A debit on the real nostro shows as a credit on the mirror nostro."}, {"label": "Real credit, mirror debit", "note": "A credit on the real account shows as a debit on the mirror."}, {"label": "Same amount always", "note": "The two sides are always for the same amount."}, {"label": "Opposite by design", "note": "The mirror is the reflection of the real account, so the two sides are opposite by design."}, {"label": "Mirror reveals the real account", "note": "Knowing the mirror balance and movements lets a bank work out what the real account shows."}]}}, "level": "core", "source_ref": "https://www.paiementor.com/strategy-2-understand-how-cross-border-payments-work/"}, {"id": "RUN4-012", "seq": 275, "module": "Core", "source": "Paiementor", "title": "FX tenor and cut-off: the cut-off decides the settlement day", "explain": "An FX tenor such as Today, Tomorrow or Spot counts from the day the deal is traded, but only if the trade happens before the FX cut-off time. A trade done today before the cut-off settles today for a Today tenor, tomorrow for a Tomorrow tenor, and in two days or more for Spot. If the trade is done after the cut-off, settlement slips a day later, because after the cut-off the bank is already working on the next day.", "takeaway": "If the trade is done after the cut-off, settlement slips a day later, because after the cut-off the bank is already working on the next day.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Trade happens before cut-off", "note": "Tenors like Today, Tomorrow or Spot count from the trade day if traded before the cut-off."}, {"kind": "decision", "title": "Trade before the cut-off?", "note": "If the trade is done after the cut-off, settlement slips a day later."}, {"kind": "step", "title": "Today tenor settles today", "note": "A trade done today before the cut-off settles today for a Today tenor."}, {"kind": "step", "title": "Tomorrow tenor settles tomorrow", "note": "A Tomorrow tenor settles tomorrow when traded before the cut-off."}, {"kind": "step", "title": "Spot settles in two days or more", "note": "A Spot tenor settles in two days or more when traded before the cut-off."}, {"kind": "step", "title": "After cut-off, settlement slips a day", "note": "After the cut-off the bank is already working on the next day, so settlement slips a day."}]}}, "level": "core", "source_ref": "https://www.paiementor.com/strategy-4-understand-how-cross-border-payments-work/"}, {"id": "RUN4-013", "seq": 276, "module": "Core", "source": "Paiementor", "title": "How a treasury keeps a nostro funded", "explain": "A treasury team does not move money itself, it watches the balances on the correspondent accounts and buys or sells foreign exchange to keep enough funds there for the day's payments. When it buys currency in the FX market, the funds are credited to the correspondent bank account in the foreign country, and the mirror account simply reflects that credit. The mirror never does anything on its own, it only records what happened on the real account.", "takeaway": "The mirror never does anything on its own, it only records what happened on the real account.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Treasury watches correspondent balances", "note": "The treasury team watches the balances on the correspondent accounts."}, {"kind": "step", "title": "Treasury buys or sells FX", "note": "It buys or sells foreign exchange to keep enough funds there for the day's payments."}, {"kind": "step", "title": "Funds credited to correspondent account", "note": "When it buys currency, the funds are credited to the correspondent account abroad."}, {"kind": "step", "title": "Mirror reflects the credit", "note": "The mirror account simply reflects that credit and never does anything on its own."}]}}, "level": "core", "source_ref": "https://www.paiementor.com/strategy-4-understand-how-cross-border-payments-work/"}, {"id": "RUN4-014", "seq": 277, "module": "Core", "source": "Paiementor", "title": "The cover leg can settle through a local clearing system", "explain": "In a cross-border payment the cover payment moves funds between the sender's correspondent and the receiver's correspondent, and when both correspondents sit in the same country a local clearing system can settle that leg. The payment message still travels over SWIFT, but the money itself moves locally. Using the local system is cheaper than moving the funds over the SWIFT network.", "takeaway": "Using the local system is cheaper than moving the funds over the SWIFT network.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Cover payment moves between correspondents", "note": "The cover payment moves funds between the sender's and the receiver's correspondents."}, {"kind": "decision", "title": "Both correspondents in one country?", "note": "When both correspondents sit in one country a local clearing system can settle that leg."}, {"kind": "step", "title": "Local clearing settles the leg", "note": "The money itself moves locally through the local clearing system."}, {"kind": "step", "title": "Message still travels over SWIFT", "note": "The payment message still travels over SWIFT, but the money itself moves locally."}, {"kind": "step", "title": "Local route costs less", "note": "Using the local system is cheaper than moving the funds over the SWIFT network."}]}}, "level": "core", "source_ref": "https://www.paiementor.com/strategy-3-understand-how-cross-border-payments-work/"}, {"id": "RUN4-015", "seq": 278, "module": "Core", "source": "Paiementor", "title": "A euro leg inside Europe can go by SEPA instead of an MT202 COV", "explain": "When a bank outside Europe instructs its correspondent in France to pay a customer of a German bank in euros, it does not have to use an MT202 COV. The correspondent can pay through SEPA or another local system instead, and that is what happens most of the time. The local route is cheaper than sending the funds over the SWIFT network.", "takeaway": "The local route is cheaper than sending the funds over the SWIFT network.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Bank outside Europe instructs correspondent", "note": "A bank outside Europe instructs its French correspondent to pay a customer in euros."}, {"kind": "step", "title": "Correspondent pays through SEPA", "note": "The correspondent can pay through SEPA or another local system instead of an MT202 COV."}, {"kind": "step", "title": "Local route used most of the time", "note": "That is what happens most of the time."}, {"kind": "step", "title": "Local route costs less", "note": "The local route is cheaper than sending the funds over the SWIFT network."}]}}, "level": "core", "source_ref": "https://www.paiementor.com/strategy-3-understand-how-cross-border-payments-work/"}, {"id": "RUN4-016", "seq": 279, "module": "Core", "source": "Paiementor", "title": "Paying out foreign currency cash a customer holds abroad", "explain": "A customer who holds a USD account with a bank in France can ask to withdraw the funds in physical USD cash, even though the real dollars sit with the bank's correspondent in the USA. The bank keeps an estimated amount of USD cash on hand, based on customer demand, and gets it from customers who sell USD for euros or from another bank. It hands over the cash and debits the same amount from the customer's USD account.", "takeaway": "It hands over the cash and debits the same amount from the customer's USD account.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Customer asks for USD cash", "note": "A customer with a USD account in France asks to withdraw the funds in physical USD cash."}, {"kind": "step", "title": "Real dollars sit in the USA", "note": "The real dollars sit with the bank's correspondent in the USA."}, {"kind": "step", "title": "Bank keeps USD cash on hand", "note": "The bank keeps an estimated amount of USD cash on hand, based on customer demand."}, {"kind": "step", "title": "Bank sources the cash", "note": "It gets the cash from customers who sell USD for euros or from another bank."}, {"kind": "step", "title": "Cash handed over, account debited", "note": "It hands over the cash and debits the same amount from the customer's USD account."}]}}, "level": "core", "source_ref": "https://www.paiementor.com/strategy-2-understand-how-cross-border-payments-work/"}, {"id": "RUN4-018", "seq": 280, "module": "Core", "source": "Paiementor", "title": "Documentary collections: the banks are only intermediaries, with no promise to pay", "explain": "In a documentary collection the collecting bank and the remitting bank act only as intermediaries between the drawer and the drawee. Unlike a documentary credit, the collecting bank is not obliged to pay the drawer when the documents are in order. It hands the documents to the drawee when the drawee pays what is due, and the payment undertaking that exists under a letter of credit simply does not exist in a collection.", "takeaway": "It hands the documents to the drawee when the drawee pays what is due, and the payment undertaking that exists under a letter of credit simply does not exist in a collection.", "visual": {"type": "diagram", "diagram": {"centre": "Documentary collection", "parts": [{"label": "Collecting bank is an intermediary", "note": "The collecting bank acts only as an intermediary between the drawer and the drawee."}, {"label": "Remitting bank is an intermediary", "note": "The remitting bank also acts only as an intermediary."}, {"label": "No obligation to pay", "note": "The collecting bank is not obliged to pay the drawer when the documents are in order."}, {"label": "Documents handed over on payment", "note": "It hands the documents to the drawee when the drawee pays what is due."}, {"label": "No payment undertaking", "note": "The payment undertaking under a letter of credit simply does not exist in a collection."}]}}, "level": "core", "source_ref": "https://www.paiementor.com/collecting-bank-and-remitting-bank-in-swift-category-4-messages/"}, {"id": "RUN5-001", "seq": 281, "module": "Core", "source": "Paiementor", "title": "Credit card payment flow: who pays whom, and in what order", "explain": "When you pay by credit card, the order of money movement is not the order you might expect. First you pay with the card, then the issuer sends you a statement, then the acquirer pays the merchant at settlement, and finally you pay the issuer. The acquirer settles with the merchant every day for all transactions, while your payment to the issuer comes only after the statement arrives.", "takeaway": "The acquirer settles with the merchant every day for all transactions, while your payment to the issuer comes only after the statement arrives.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "You pay with the card", "note": "First you pay with the card."}, {"kind": "step", "title": "Issuer sends you a statement", "note": "Then the issuer sends you a statement."}, {"kind": "step", "title": "Acquirer pays the merchant", "note": "The acquirer pays the merchant at settlement, every day for all transactions."}, {"kind": "step", "title": "You pay the issuer", "note": "Finally you pay the issuer, only after the statement arrives."}]}}, "level": "core", "source_ref": "https://www.paiementor.com/the-four-corner-model-for-card-payments/"}, {"id": "RUN5-002", "seq": 282, "module": "Core", "source": "Paiementor", "title": "The credit card statement cycle and when interest starts", "explain": "Your interest-free credit period depends on where in the billing cycle you paid, and it can stretch to about 45 days if you paid at the start of a cycle. At the end of the cycle the issuer sends the statement, and you then have a set period, usually about 21 days, to pay. If you pay the full statement amount in that window you pay no interest, but if you pay less, interest is charged on the balance.", "takeaway": "If you pay the full statement amount in that window you pay no interest, but if you pay less, interest is charged on the balance.", "visual": {"type": "diagram", "diagram": {"centre": "Credit card statement cycle", "parts": [{"label": "Interest-free period up to 45 days", "note": "It can stretch to about 45 days if you paid at the start of a cycle."}, {"label": "Statement at end of cycle", "note": "At the end of the cycle the issuer sends the statement."}, {"label": "About 21 days to pay", "note": "You then have a set period, usually about 21 days, to pay."}, {"label": "Pay in full, no interest", "note": "If you pay the full statement amount in that window you pay no interest."}, {"label": "Pay less, interest charged", "note": "If you pay less, interest is charged on the balance."}]}}, "level": "core", "source_ref": "https://www.paiementor.com/the-four-corner-model-for-card-payments/"}, {"id": "RUN5-003", "seq": 283, "module": "Core", "source": "Paiementor", "title": "Interchange: the fee the acquirer pays the issuer", "explain": "Interchange is the compensation the acquirer pays the issuer for each card transaction, and it is also called the wholesale fee or interexchange fee. It is the issuer's transaction fee in clearing and settlement, and it typically runs to 75 to 85 percent of the merchant service charges. The merchant bears this cost through the fees charged on the transaction, not the cardholder.", "takeaway": "The merchant bears this cost through the fees charged on the transaction, not the cardholder.", "visual": {"type": "diagram", "diagram": {"centre": "Interchange, the fee the acquirer pays the issuer", "parts": [{"label": "What it is", "note": "Compensation the acquirer pays the issuer per transaction"}, {"label": "Also called", "note": "Wholesale fee or interexchange fee"}, {"label": "Size", "note": "Typically 75 to 85 percent of merchant service charges"}, {"label": "Who bears it", "note": "The merchant bears the cost, not the cardholder"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/4-party-scheme-in-card-flow-exchanges-for-a-card-payment/"}, {"id": "RUN5-007", "seq": 284, "module": "Core", "source": "Paiementor", "title": "How the card schemes collect their fees from merchants", "explain": "The card schemes collect fees from merchants alongside the processor, and each scheme charges in its own way. The payment processing firm typically debits the merchant's account directly for the fees it is owed. Mastercard charges per transaction, while Visa charges yearly or quarterly memberships, so a merchant's scheme cost depends on which cards its customers use and how much volume it puts through each scheme.", "takeaway": "Mastercard charges per transaction, while Visa charges yearly or quarterly memberships, so a merchant's scheme cost depends on which cards its customers use and how much volume it puts through each scheme.", "visual": {"type": "diagram", "diagram": {"centre": "How the card schemes collect their fees", "parts": [{"label": "Processor", "note": "Typically debits the merchant account directly for fees owed"}, {"label": "Mastercard", "note": "Charges per transaction"}, {"label": "Visa", "note": "Charges yearly or quarterly memberships"}, {"label": "Merchant cost", "note": "Depends on which cards customers use and the volume"}]}}, "level": "core", "source_ref": "https://www.paiementor.com/payment-processors-in-card-transactions/"}, {"id": "ABH-27", "seq": 285, "module": "Advanced", "source": "Abhishek Pandey", "title": "When AI agents make payments for customers", "explain": "An AI agent that pays on behalf of a customer follows six steps: understand, verify, evaluate, authorize, execute, and confirm. The use cases range from paying bills to paying vendor invoices. The authorisation step is the control that makes the whole flow safe.", "takeaway": "The authorisation step is the control that makes the whole flow safe.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Understand", "note": "Agent understands the payment request"}, {"kind": "step", "title": "Verify", "note": "Agent verifies the payment details"}, {"kind": "step", "title": "Evaluate", "note": "Agent evaluates the payment"}, {"kind": "decision", "title": "Authorize", "note": "The control that makes the flow safe"}, {"kind": "step", "title": "Execute", "note": "Pays bills and vendor invoices"}, {"kind": "step", "title": "Confirm", "note": "Payment confirmed to the customer"}]}}, "level": "advanced", "source_ref": "https://www.linkedin.com/posts/abhishek2601_agenticai-payments-bankinginnovation-share-7524642665360121856-I-Nm/"}, {"id": "ABH-28", "seq": 286, "module": "Advanced", "source": "Abhishek Pandey", "title": "Coinbase x402, internet-native payments", "explain": "Coinbase x402 is a standard for internet-native payments that lets AI agents pay for APIs and digital services with stablecoins. It enables pay-per-use, micropayments, and programmable payments, so a machine can pay a machine for exactly what it used.", "takeaway": "It enables pay-per-use, micropayments, and programmable payments, so a machine can pay a machine for exactly what it used.", "visual": {"type": "diagram", "diagram": {"centre": "Coinbase x402", "parts": [{"label": "Stablecoins", "note": "The payment currency for agents"}, {"label": "Pay-per-use", "note": "Pay for exactly what was used"}, {"label": "Micropayments", "note": "Small payments machines can make"}, {"label": "Programmable payments", "note": "Payments a machine can trigger"}, {"label": "APIs and digital services", "note": "What agents pay for"}, {"label": "Internet-native payments", "note": "Built for the internet, not cards"}]}}, "level": "advanced", "source_ref": "https://www.linkedin.com/posts/abhishek2601_payments-agenticai-stablecoins-share-7519017478988099585-IzeD/"}, {"id": "ABH-29", "seq": 287, "module": "Advanced", "source": "Abhishek Pandey", "title": "An AI assistant built for BFSI", "explain": "Anomic AI is an AI assistant built for banking, financial services, and insurance, for banking knowledge, BRD creation, and customer conversations. It is an example of AI aimed at the daily work of a banking professional rather than at the customer.", "takeaway": "It is an example of AI aimed at the daily work of a banking professional rather than at the customer.", "visual": {"type": "diagram", "diagram": {"centre": "An AI assistant for BFSI", "parts": [{"label": "Banking knowledge", "note": "Answers grounded in banking"}, {"label": "BRD creation", "note": "Drafts business requirements"}, {"label": "Customer conversations", "note": "Handles customer-facing chat"}, {"label": "Banking professionals", "note": "Built for daily banking work"}]}}, "level": "advanced", "source_ref": "https://www.linkedin.com/posts/abhishek2601_anomicai-bfsi-bankinginnovation-share-7524134250879574018-ZWgr/"}, {"id": "ABH-30", "seq": 288, "module": "Advanced", "source": "Abhishek Pandey", "title": "Smarter BFSI chatbots and BRDs in minutes", "explain": "The Anomic AI brand partnership promises smarter BFSI chatbots and BRDs in ten minutes instead of three days. The claim is about speed: the same banking document, produced far faster.", "takeaway": "The claim is about speed: the same banking document, produced far faster.", "visual": {"type": "diagram", "diagram": {"centre": "Smarter BFSI chatbots and BRDs", "parts": [{"label": "BRDs in ten minutes", "note": "The same document, produced far faster"}, {"label": "BRDs in three days", "note": "The old time to produce the document"}, {"label": "Smarter chatbots", "note": "Chatbots that serve banking better"}, {"label": "Speed", "note": "The claim is about speed, not new content"}]}}, "level": "advanced", "source_ref": "https://www.linkedin.com/posts/abhishek2601_anomicai-bfsi-bankinginnovation-ugcPost-7522685145603112960-WEDw/"}, {"id": "ABH-31", "seq": 289, "module": "Advanced", "source": "Abhishek Pandey", "title": "You can replace an employee, but can you replace their context", "explain": "AI scales execution, but human expertise gives it context. Replacing a person removes the context they carry about the business, the customer, and the history, and that context is not easily rebuilt.", "takeaway": "Replacing a person removes the context they carry about the business, the customer, and the history, and that context is not easily rebuilt.", "visual": {"type": "diagram", "diagram": {"centre": "AI and human expertise", "parts": [{"label": "AI execution", "note": "Scales how fast work gets done"}, {"label": "Human context", "note": "Business, customer and history knowledge"}, {"label": "Replacing a person", "note": "Removes the context they carry"}, {"label": "Rebuilding context", "note": "Not easily rebuilt once removed"}]}}, "level": "advanced", "source_ref": "https://www.linkedin.com/posts/abhishek2601_ai-agenticai-futureofwork-share-7521557255457210370-USM9/"}, {"id": "ABH-32", "seq": 290, "module": "Advanced", "source": "Abhishek Pandey", "title": "Think twice before layoffs, and reskill for AI", "explain": "The post asks CEOs, CTOs, and founders to think twice before layoffs, and offers free AI and GenAI reskilling help to anyone struggling. The point is that the AI shift is a skills problem as much as a headcount problem.", "takeaway": "The point is that the AI shift is a skills problem as much as a headcount problem.", "visual": {"type": "diagram", "diagram": {"centre": "Reskill for the AI shift", "parts": [{"label": "CEOs, CTOs and founders", "note": "Asked to think twice before layoffs"}, {"label": "Free AI and GenAI reskilling", "note": "Help offered to anyone struggling"}, {"label": "Skills problem", "note": "The AI shift is as much skills as headcount"}, {"label": "Headcount problem", "note": "Layoffs alone do not solve the shift"}]}}, "level": "advanced", "source_ref": "https://www.linkedin.com/posts/abhishek2601_a-humble-request-to-%F0%9D%97%96%F0%9D%97%98%F0%9D%97%A2%F0%9D%98%80-%F0%9D%97%96%F0%9D%97%A7%F0%9D%97%A2%F0%9D%98%80-%F0%9D%97%B3%F0%9D%97%BC%F0%9D%98%82%F0%9D%97%BB%F0%9D%97%B1%F0%9D%97%B2%F0%9D%97%BF%F0%9D%98%80-share-7524788326172758016-Nw46/"}, {"id": "ABH-33", "seq": 291, "module": "Advanced", "source": "Abhishek Pandey", "title": "US green-card crackdown and the PERM suspension", "explain": "Major tech and IT companies were suspended from the PERM program, and the post lists five actions Indian IT professionals should take. The situation shows how an immigration policy change can reshape career plans overnight.", "takeaway": "The situation shows how an immigration policy change can reshape career plans overnight.", "visual": {"type": "diagram", "diagram": {"centre": "PERM suspension", "parts": [{"label": "Major tech and IT companies", "note": "Suspended from the PERM program"}, {"label": "Five actions", "note": "Listed for Indian IT professionals to take"}, {"label": "Immigration policy change", "note": "Can reshape career plans overnight"}, {"label": "Indian IT professionals", "note": "The group the advice is aimed at"}]}}, "level": "advanced", "source_ref": "https://www.linkedin.com/posts/abhishek2601_usimmigration-greencard-h1bvisa-share-7514152913582084097-hyI2/"}, {"id": "ABH-34", "seq": 292, "module": "Advanced", "source": "Abhishek Pandey", "title": "A PERM suspension does not cancel an H-1B", "explain": "A PERM suspension does not automatically cancel H-1B visas. The advice is not to panic but to plan proactively, because the two programs are separate and a suspension in one does not end the other.", "takeaway": "The advice is not to panic but to plan proactively, because the two programs are separate and a suspension in one does not end the other.", "visual": {"type": "diagram", "diagram": {"centre": "PERM suspension and H-1B", "parts": [{"label": "PERM suspension", "note": "Does not automatically cancel H-1B visas"}, {"label": "H-1B visas", "note": "A separate program from PERM"}, {"label": "No panic", "note": "Plan proactively instead"}, {"label": "Two separate programs", "note": "A suspension in one does not end the other"}]}}, "level": "advanced", "source_ref": "https://www.linkedin.com/posts/abhishek2601_usimmigration-greencard-h1bvisa-share-7514152733050863616-GYjh/"}, {"id": "ABH-35", "seq": 293, "module": "Advanced", "source": "Abhishek Pandey", "title": "A Corporate Banking BA role in Hanoi", "explain": "The hiring post is for a Corporate Banking Business Analyst with six or more years of experience, onsite in Hanoi, covering onboarding, entitlements, fees, limits, and payments. It shows what a corporate banking BA is expected to own end to end.", "takeaway": "It shows what a corporate banking BA is expected to own end to end.", "visual": {"type": "diagram", "diagram": {"centre": "Corporate Banking BA role", "parts": [{"label": "Six or more years experience", "note": "The experience the role asks for"}, {"label": "Onsite in Hanoi", "note": "Where the role is based"}, {"label": "Onboarding", "note": "Owned end to end by the BA"}, {"label": "Entitlements", "note": "Owned end to end by the BA"}, {"label": "Fees", "note": "Owned end to end by the BA"}, {"label": "Limits", "note": "Owned end to end by the BA"}, {"label": "Payments", "note": "Owned end to end by the BA"}]}}, "level": "advanced", "source_ref": "https://www.linkedin.com/in/abhishek2601/recent-activity/all/"}, {"id": "ABH-36", "seq": 294, "module": "Advanced", "source": "Abhishek Pandey", "title": "Open to Work, Product Manager and Senior BA roles", "explain": "The post seeks Product Manager, Senior Project Manager, Product Owner, or Senior BA roles in the UK, Australia and New Zealand, Asia, Europe, and APAC. The background is Cognizant, Virtusa, and Coforge, with payments and product experience.", "takeaway": "The background is Cognizant, Virtusa, and Coforge, with payments and product experience.", "visual": {"type": "diagram", "diagram": {"centre": "Open to Work, PM and Senior BA", "parts": [{"label": "Product Manager", "note": "Role sought"}, {"label": "Senior Project Manager", "note": "Role sought"}, {"label": "Product Owner", "note": "Role sought"}, {"label": "Senior BA", "note": "Role sought"}, {"label": "UK, Australia, New Zealand, Asia, Europe, APAC", "note": "Regions sought"}, {"label": "Cognizant, Virtusa and Coforge", "note": "Background employers"}, {"label": "Payments and product experience", "note": "The experience on offer"}]}}, "level": "advanced", "source_ref": "https://www.linkedin.com/in/abhishek2601/recent-activity/all/"}, {"id": "ABH-37", "seq": 295, "module": "Advanced", "source": "Abhishek Pandey", "title": "Open to Work, Product Owner and Senior BA in banking", "explain": "The post seeks Product Owner or Senior Business Analyst roles in banking and payments, with SEPA, cross-border, ISO 20022, SWIFT MT and MX, and APIs. It is a clear statement of the skills a payments BA brings to a hiring manager.", "takeaway": "It is a clear statement of the skills a payments BA brings to a hiring manager.", "visual": {"type": "diagram", "diagram": {"centre": "Payments BA open to work", "parts": [{"label": "Product Owner", "note": "Role sought in banking and payments"}, {"label": "Senior Business Analyst", "note": "Role sought in banking and payments"}, {"label": "SEPA", "note": "Skill the BA brings"}, {"label": "Cross-border", "note": "Skill the BA brings"}, {"label": "ISO 20022", "note": "Skill the BA brings"}, {"label": "SWIFT MT and MX", "note": "Skill the BA brings"}, {"label": "APIs", "note": "Skill the BA brings"}]}}, "level": "advanced", "source_ref": "https://www.linkedin.com/in/abhishek2601/recent-activity/all/"}, {"id": "ABH-38", "seq": 296, "module": "Advanced", "source": "Abhishek Pandey", "title": "Opening the doors for Payments and BFS consulting", "explain": "The post opens paid Payments and BFS consulting covering functional consulting, all payment types, BRD and FRD, AI use cases, and product thinking, with curiosity free. It shows how a payments SME packages deep domain knowledge as a service.", "takeaway": "It shows how a payments SME packages deep domain knowledge as a service.", "visual": {"type": "diagram", "diagram": {"centre": "Payments and BFS consulting", "parts": [{"label": "Functional consulting", "note": "Consulting on how payments work"}, {"label": "All payment types", "note": "Covered by the consulting"}, {"label": "BRD and FRD", "note": "Documents the consulting produces"}, {"label": "AI use cases", "note": "Covered by the consulting"}, {"label": "Product thinking", "note": "Covered by the consulting"}, {"label": "Curiosity free", "note": "Questions welcome before engaging"}]}}, "level": "advanced", "source_ref": "https://www.linkedin.com/in/abhishek2601/recent-activity/all/"}, {"id": "ABH-39", "seq": 297, "module": "Advanced", "source": "Abhishek Pandey", "title": "When the booking link is blocked, reach out on LinkedIn", "explain": "The Topmate link is blocked because of the author's current living location, so he asks people not to book sessions through Topmate for now and to reach him on LinkedIn instead. It is a practical note about staying reachable when a platform blocks you.", "takeaway": "It is a practical note about staying reachable when a platform blocks you.", "visual": {"type": "diagram", "diagram": {"centre": "Staying reachable when blocked", "parts": [{"label": "Topmate link blocked", "note": "Blocked by current living location"}, {"label": "No Topmate bookings", "note": "Asked not to book sessions there for now"}, {"label": "LinkedIn instead", "note": "The channel to reach him on"}, {"label": "Practical note", "note": "Staying reachable when a platform blocks you"}]}}, "level": "advanced", "source_ref": "https://www.linkedin.com/posts/abhishek2601_%F0%9D%97%9B%F0%9D%97%B2%F0%9D%97%B9%F0%9D%97%BC-%F0%9D%97%98%F0%9D%97%83%F0%9D%97%B2%F0%9D%97%BF%F0%9D%98%86%F0%9D%97%BC%F0%9D%97%BB%F0%9D%97%B2-my-topmate-share-7512529894275297280-rdig/"}, {"id": "ABH-40", "seq": 298, "module": "Advanced", "source": "Abhishek Pandey", "title": "Expanding a professional network across Asia", "explain": "The post looks to expand a professional network across Asia, including Singapore, Malaysia, China, Vietnam, the Philippines, and more. A payments career in Asia is built on relationships across many markets, not one.", "takeaway": "A payments career in Asia is built on relationships across many markets, not one.", "visual": {"type": "diagram", "diagram": {"centre": "Professional network across Asia", "parts": [{"label": "Singapore", "note": "One market in the network"}, {"label": "Malaysia", "note": "One market in the network"}, {"label": "China", "note": "One market in the network"}, {"label": "Vietnam", "note": "One market in the network"}, {"label": "Philippines", "note": "One market in the network"}, {"label": "More markets", "note": "The network spans many markets, not one"}]}}, "level": "advanced", "source_ref": "https://www.linkedin.com/in/abhishek2601/recent-activity/all/"}, {"id": "ABH-41", "seq": 299, "module": "Advanced", "source": "Abhishek Pandey", "title": "The AI Alchemist award and the Virtusa Vietnam team", "explain": "The post thanks a colleague for the opportunity and the AI Alchemist award, and shares a repost about the Virtusa Vietnam team. It is a recognition post that shows the value of a team that explores AI and turns ideas into impact.", "takeaway": "It is a recognition post that shows the value of a team that explores AI and turns ideas into impact.", "visual": {"type": "diagram", "diagram": {"centre": "The AI Alchemist award", "parts": [{"label": "The award", "note": "Recognises exploring AI and turning ideas into impact"}, {"label": "The team", "note": "Explores AI and turns ideas into impact"}, {"label": "The recognition post", "note": "Thanks a colleague for the opportunity"}, {"label": "The repost", "note": "Shares the team story"}]}}, "level": "advanced", "source_ref": "https://www.linkedin.com/in/abhishek2601/recent-activity/all/"}, {"id": "ABH-42", "seq": 300, "module": "Advanced", "source": "Abhishek Pandey", "title": "Awarded The AI Alchemist at Virtusa", "explain": "The post announces the AI Alchemist award at Virtusa. The award recognises exploring AI and turning ideas into impact, which is the work the author had been sharing.", "takeaway": "The award recognises exploring AI and turning ideas into impact, which is the work the author had been sharing.", "visual": {"type": "diagram", "diagram": {"centre": "The AI Alchemist award", "parts": [{"label": "Exploring AI", "note": "The work the award recognises"}, {"label": "Turning ideas into impact", "note": "The work the award recognises"}, {"label": "The announcement", "note": "Marks receiving the award"}]}}, "level": "advanced", "source_ref": "https://www.linkedin.com/in/abhishek2601/recent-activity/all/"}, {"id": "ABH-43", "seq": 301, "module": "Advanced", "source": "Abhishek Pandey", "title": "A milestone for exploring AI and turning ideas into impact", "explain": "The post marks receiving the AI Alchemist award at Virtusa for exploring AI and turning ideas into impact. It frames the award as a milestone in a longer journey of sharing practical knowledge.", "takeaway": "It frames the award as a milestone in a longer journey of sharing practical knowledge.", "visual": {"type": "diagram", "diagram": {"centre": "A milestone in sharing knowledge", "parts": [{"label": "The award", "note": "Marks receiving the AI Alchemist award"}, {"label": "Exploring AI", "note": "The journey the award marks"}, {"label": "Turning ideas into impact", "note": "The journey the award marks"}, {"label": "Sharing practical knowledge", "note": "The longer journey the award sits in"}]}}, "level": "advanced", "source_ref": "https://www.linkedin.com/in/abhishek2601/recent-activity/all/"}, {"id": "ABH-44", "seq": 302, "module": "Advanced", "source": "Abhishek Pandey", "title": "Why do job postings say Only Females Can Apply", "explain": "The post asks HR and recruiters a genuine question: why do some job postings say only females can apply. It raises a fairness question about hiring language that a professional should be able to ask openly.", "takeaway": "It raises a fairness question about hiring language that a professional should be able to ask openly.", "visual": {"type": "diagram", "diagram": {"centre": "Fairness in hiring language", "parts": [{"label": "The question", "note": "Why do some postings say only females can apply"}, {"label": "HR and recruiters", "note": "Asked the genuine question"}, {"label": "Fairness", "note": "A question a professional should ask openly"}]}}, "level": "advanced", "source_ref": "https://www.linkedin.com/in/abhishek2601/recent-activity/all/"}, {"id": "ABH-45", "seq": 303, "module": "Advanced", "source": "Abhishek Pandey", "title": "Why demand joining in thirty days", "explain": "The post asks why companies require immediate joining or joining within thirty days, when an employee cannot leave that fast either. Notice periods run both ways, and a hiring process that ignores that creates a mismatch.", "takeaway": "Notice periods run both ways, and a hiring process that ignores that creates a mismatch.", "visual": {"type": "diagram", "diagram": {"centre": "Joining in thirty days", "parts": [{"label": "Immediate joining", "note": "What companies demand"}, {"label": "Joining within thirty days", "note": "What companies demand"}, {"label": "Notice periods", "note": "Run both ways, for employee and employer"}, {"label": "The mismatch", "note": "A process that ignores notice creates it"}]}}, "level": "advanced", "source_ref": "https://www.linkedin.com/in/abhishek2601/recent-activity/all/"}, {"id": "ABH-46", "seq": 304, "module": "Advanced", "source": "Abhishek Pandey", "title": "Do banks need Sunday branches", "explain": "The post questions Indian banks opening branches on Sundays, arguing that customers want better digital banking and bank employees deserve a Sunday with family. The point is that digital capability, not branch hours, is what customers actually need.", "takeaway": "The point is that digital capability, not branch hours, is what customers actually need.", "visual": {"type": "diagram", "diagram": {"centre": "Do banks need Sunday branches", "parts": [{"label": "Sunday branches", "note": "What banks are opening"}, {"label": "Better digital banking", "note": "What customers actually want"}, {"label": "Employees deserve Sunday", "note": "A Sunday with family"}, {"label": "Digital capability", "note": "What customers need, not branch hours"}]}}, "level": "advanced", "source_ref": "https://www.linkedin.com/in/abhishek2601/recent-activity/all/"}, {"id": "ABH-47", "seq": 305, "module": "Advanced", "source": "Abhishek Pandey", "title": "Earning far from home", "explain": "The Diwali post is about working away from family: the salary reaches home, but the heart wishes it could too. It is a reminder that a payments career often means working far from home, and that the human side of the job matters.", "takeaway": "It is a reminder that a payments career often means working far from home, and that the human side of the job matters.", "visual": {"type": "diagram", "diagram": {"centre": "Earning far from home", "parts": [{"label": "Working away from family", "note": "The reality of the payments career"}, {"label": "Salary reaches home", "note": "The money gets home"}, {"label": "Heart wishes it could too", "note": "The human side of the job"}, {"label": "The human side", "note": "It matters as much as the work"}]}}, "level": "advanced", "source_ref": "https://www.linkedin.com/posts/abhishek2601_%F0%9D%97%98%F0%9D%97%94%F0%9D%97%A5%F0%9D%97%A1%F0%9D%97%9C%F0%9D%97%A1%F0%9D%97%9A-%F0%9D%97%99%F0%9D%97%94%F0%9D%97%A5-%F0%9D%97%99%F0%9D%97%A5%F0%9D%97%A2%F0%9D%97%A0-%F0%9D%97%9B%F0%9D%97%A2%F0%9D%97%A0%F0%9D%97%98-share-7522138591813337088-BP0-/"}, {"id": "ABH-48", "seq": 306, "module": "Advanced", "source": "Abhishek Pandey", "title": "Simple me, GenZ", "explain": "This is a light, image-only personal post. It carries no payments teaching, but it shows the author's human side, which is part of how a professional builds a following.", "takeaway": "It carries no payments teaching, but it shows the author's human side, which is part of how a professional builds a following.", "visual": {"type": "diagram", "diagram": {"centre": "The human side of a professional", "parts": [{"label": "Light personal post", "note": "Image only, no payments teaching"}, {"label": "Human side", "note": "Shows the person behind the professional"}, {"label": "Building a following", "note": "Part of how a professional grows it"}]}}, "level": "advanced", "source_ref": "https://www.linkedin.com/in/abhishek2601/recent-activity/all/"}, {"id": "ABH-49", "seq": 307, "module": "Advanced", "source": "Abhishek Pandey", "title": "When good engineering saves lives", "explain": "The post is about a house that stood strong while everything around it was destroyed, with prayers for the people of Nepal. It is a reminder that good engineering is not abstract: it protects real people in real disasters.", "takeaway": "It is a reminder that good engineering is not abstract: it protects real people in real disasters.", "visual": {"type": "diagram", "diagram": {"centre": "When good engineering saves lives", "parts": [{"label": "The house that stood strong", "note": "Stood while everything around it was destroyed"}, {"label": "Prayers for the people of Nepal", "note": "The human cost behind the story"}, {"label": "Good engineering", "note": "Not abstract, it protects real people"}, {"label": "Real disasters", "note": "Where engineering is tested"}]}}, "level": "advanced", "source_ref": "https://www.linkedin.com/in/abhishek2601/recent-activity/all/"}, {"id": "ABH-50", "seq": 308, "module": "Advanced", "source": "Abhishek Pandey", "title": "Fifteen thousand followers and fifteen years in payments", "explain": "The milestone post marks fifteen thousand followers and fifteen years in payments, product management, APIs, and ISO 20022, with a commitment to keep sharing practical payments and fintech insights. It closes the set by showing the breadth of the field this product covers.", "takeaway": "It closes the set by showing the breadth of the field this product covers.", "visual": {"type": "diagram", "diagram": {"centre": "Fifteen years in payments", "parts": [{"label": "Fifteen thousand followers", "note": "The milestone the post marks"}, {"label": "Fifteen years", "note": "In payments, product management, APIs and ISO 20022"}, {"label": "Practical insights", "note": "Shared on payments and fintech"}, {"label": "Commitment to keep sharing", "note": "The close of the set"}]}}, "level": "advanced", "source_ref": "https://www.linkedin.com/in/abhishek2601/recent-activity/all/"}, {"id": "INS-141", "seq": 309, "module": "Advanced", "source": "Jebaraj D", "title": "Payment-system interoperability is more than an API", "explain": "Connecting two instant payment systems through an API proves that a message can be sent and a response received, but it does not prove the payment will work end to end. The systems must also align on message formats, scheme rules, clearing, settlement, compliance, and operations. A payment accepted by the channel can still be rejected by clearing if those layers do not match.", "takeaway": "A payment accepted by the channel can still be rejected by clearing if those layers do not match.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Connect via API", "note": "API proves a message can be sent and a response received"}, {"kind": "step", "title": "Align message formats", "note": "Systems must align on message formats"}, {"kind": "step", "title": "Align scheme rules", "note": "Systems must align on scheme rules"}, {"kind": "step", "title": "Align clearing and settlement", "note": "Systems must align on clearing and settlement"}, {"kind": "step", "title": "Align compliance and operations", "note": "Systems must align on compliance and operations"}, {"kind": "step", "title": "Channel accepts, clearing rejects", "note": "Payment accepted by the channel can still be rejected by clearing"}]}}, "level": "advanced", "source_ref": "JEB-19"}, {"id": "INS-166", "seq": 310, "module": "Advanced", "source": "Jebaraj D", "title": "Domestic instant payment system interoperability", "explain": "Connecting to instant payment systems in several markets, such as UPI in India, SCT Inst in Europe, and FedNow and RTP in the United States, is not just a technical connection. The systems differ in scheme rules, participants, operating hours, and dispute processes, so a payment that works in one market can fail in another for a non-technical reason. Technical connectivity and scheme alignment must both be designed.", "takeaway": "Technical connectivity and scheme alignment must both be designed.", "visual": {"type": "diagram", "diagram": {"centre": "Instant system interoperability", "parts": [{"label": "UPI in India", "note": "UPI in India is one market system to connect"}, {"label": "SCT Inst in Europe", "note": "SCT Inst in Europe is one market system to connect"}, {"label": "FedNow and RTP in US", "note": "FedNow and RTP in the United States are market systems to connect"}, {"label": "Scheme rules differ", "note": "Systems differ in scheme rules"}, {"label": "Participants differ", "note": "Systems differ in participants"}, {"label": "Operating hours differ", "note": "Systems differ in operating hours"}, {"label": "Dispute processes differ", "note": "Systems differ in dispute processes"}, {"label": "Technical plus scheme alignment", "note": "Technical connectivity and scheme alignment must both be designed"}]}}, "level": "advanced", "source_ref": "JEB-19"}, {"id": "INS-167", "seq": 311, "module": "Advanced", "source": "Jebaraj D", "title": "Payment message standards and APIs across corridors", "explain": "Different channels and corridors send similar but non-identical payment fields, and collapsing them into one generic set of fields loses information. A common data model must define how fields translate, how validation works, and what error semantics apply across different domestic rails. Without that model, small data differences become payment failures that are hard to trace.", "takeaway": "Without that model, small data differences become payment failures that are hard to trace.", "visual": {"type": "diagram", "diagram": {"centre": "Common data model across corridors", "parts": [{"label": "Similar but non-identical fields", "note": "Different channels and corridors send similar but non-identical fields"}, {"label": "Generic set loses information", "note": "Collapsing them into one generic set of fields loses information"}, {"label": "Field translation", "note": "Common data model must define how fields translate"}, {"label": "Validation", "note": "Common data model must define how validation works"}, {"label": "Error semantics", "note": "Common data model must define what error semantics apply"}, {"label": "Small differences become failures", "note": "Without that model, small differences become payment failures hard to trace"}]}}, "level": "advanced", "source_ref": "JEB-19"}, {"id": "INS-142", "seq": 312, "module": "Advanced", "source": "Jebaraj D", "title": "UPI and PayNow linkage", "explain": "The UPI and PayNow linkage lets a person in India send money to a family member in Singapore using only the recipient mobile number, and the reverse. It works through proxy identifiers and a participating institution model, where each side resolves the proxy to the right account. The scope of the linkage must be validated, because not every account type or transaction type is covered.", "takeaway": "The scope of the linkage must be validated, because not every account type or transaction type is covered.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Person in India sends", "note": "Person in India sends money to a family member in Singapore"}, {"kind": "step", "title": "Use only mobile number", "note": "Sender uses only the recipient mobile number"}, {"kind": "step", "title": "Proxy identifier resolved", "note": "Each side resolves the proxy to the right account"}, {"kind": "step", "title": "Participating institution model", "note": "Works through proxy identifiers and a participating institution model"}, {"kind": "step", "title": "Reverse direction works", "note": "Reverse direction works the same way"}, {"kind": "decision", "title": "Scope validated?", "note": "Scope must be validated, because not every account or transaction type is covered"}]}}, "level": "advanced", "source_ref": "JEB-20"}, {"id": "INS-169", "seq": 313, "module": "Advanced", "source": "Jebaraj D", "title": "Beneficiary identifier and proxy resolution", "explain": "In a linked payment ecosystem, the beneficiary can be identified by a mobile number, a UPI ID or virtual payment address, or a traditional account number. The system must resolve that identifier to the correct account before the payment is sent, and the resolution rules differ by scheme. Getting the proxy resolution wrong sends the money to the wrong person.", "takeaway": "Getting the proxy resolution wrong sends the money to the wrong person.", "visual": {"type": "diagram", "diagram": {"centre": "Beneficiary identifier resolution", "parts": [{"label": "Mobile number", "note": "Beneficiary can be identified by a mobile number"}, {"label": "UPI ID or virtual address", "note": "Beneficiary can be identified by a UPI ID or virtual payment address"}, {"label": "Traditional account number", "note": "Beneficiary can be identified by a traditional account number"}, {"label": "Resolve before sending", "note": "System must resolve the identifier to the correct account before sending"}, {"label": "Resolution rules differ", "note": "Resolution rules differ by scheme"}, {"label": "Wrong resolution risk", "note": "Getting the proxy resolution wrong sends the money to the wrong person"}]}}, "level": "advanced", "source_ref": "JEB-20"}, {"id": "INS-153", "seq": 314, "module": "Advanced", "source": "Jebaraj D", "title": "India-Europe payment bridge design", "explain": "Building a payment corridor from India to Europe means mapping every dependency: currency, scheme, compliance, data, FX, and settlement. Today a payment from a European buyer to an Indian exporter travels through a chain of correspondents, takes days, and gives neither side a reliable status. A bridge design must replace that chain with a defined path that both sides can track.", "takeaway": "A bridge design must replace that chain with a defined path that both sides can track.", "visual": {"type": "diagram", "diagram": {"centre": "India-Europe payment bridge", "parts": [{"label": "Currency", "note": "Bridge design must map the currency dependency"}, {"label": "Scheme", "note": "Bridge design must map the scheme dependency"}, {"label": "Compliance", "note": "Bridge design must map the compliance dependency"}, {"label": "Data", "note": "Bridge design must map the data dependency"}, {"label": "FX", "note": "Bridge design must map the FX dependency"}, {"label": "Settlement", "note": "Bridge design must map the settlement dependency"}, {"label": "Today via correspondents", "note": "Today the payment travels through a chain of correspondents and takes days"}, {"label": "Defined trackable path", "note": "Bridge must replace that chain with a defined path both sides can track"}]}}, "level": "advanced", "source_ref": "JEB-19"}, {"id": "INS-148", "seq": 315, "module": "Advanced", "source": "Jebaraj D", "title": "Interoperability as a business and operating model", "explain": "When two banks connect their instant payment systems, the technical link is only the start. They must agree who investigates a failed payment, who returns the funds, how long the customer waits, and how disputes are resolved. Without that governance, a payment that fails after the sender is debited leaves both banks pointing at different contracts. Interoperability is a business and operating agreement, not just a connection.", "takeaway": "Interoperability is a business and operating agreement, not just a connection.", "visual": {"type": "diagram", "diagram": {"centre": "Interoperability operating model", "parts": [{"label": "Technical link only the start", "note": "Technical link is only the start"}, {"label": "Who investigates a failure", "note": "Banks must agree who investigates a failed payment"}, {"label": "Who returns the funds", "note": "Banks must agree who returns the funds"}, {"label": "How long the customer waits", "note": "Banks must agree how long the customer waits"}, {"label": "How disputes are resolved", "note": "Banks must agree how disputes are resolved"}, {"label": "No governance risk", "note": "Without governance, a failed payment leaves both banks pointing at contracts"}, {"label": "Business and operating agreement", "note": "Interoperability is a business and operating agreement, not just a connection"}]}}, "level": "advanced", "source_ref": "JEB-25"}, {"id": "INS-149", "seq": 316, "module": "Advanced", "source": "Jebaraj D", "title": "Customer transparency on fees and FX", "explain": "A customer sending money across borders needs to see the total cost, the applied exchange rate, the fee breakdown, and the expected delivery status before confirming. If any of those are hidden or unclear, the customer cannot judge whether the payment is good value or when it will arrive. Transparency is a product requirement, not a nice-to-have.", "takeaway": "Transparency is a product requirement, not a nice-to-have.", "visual": {"type": "diagram", "diagram": {"centre": "Customer transparency on fees and FX", "parts": [{"label": "Total cost", "note": "Customer needs to see the total cost"}, {"label": "Applied exchange rate", "note": "Customer needs to see the applied exchange rate"}, {"label": "Fee breakdown", "note": "Customer needs to see the fee breakdown"}, {"label": "Expected delivery status", "note": "Customer needs to see the expected delivery status"}, {"label": "Hidden cost risk", "note": "If any of those are hidden or unclear, the customer cannot judge value"}, {"label": "Cannot judge arrival", "note": "If any are hidden, the customer cannot judge when it will arrive"}, {"label": "Product requirement", "note": "Transparency is a product requirement, not a nice-to-have"}]}}, "level": "advanced", "source_ref": "JEB-16"}, {"id": "INS-151", "seq": 317, "module": "Advanced", "source": "Jebaraj D", "title": "Richer data to support AML and reconciliation", "explain": "Structured purpose and remittance data helps compliance screening and lets the beneficiary reconcile the payment against the right invoice. But the data is only useful if it is captured correctly, mapped consistently, and consumed by the downstream systems that need it. Poor data quality in one system becomes a compliance and reconciliation problem in the next.", "takeaway": "Poor data quality in one system becomes a compliance and reconciliation problem in the next.", "visual": {"type": "diagram", "diagram": {"centre": "Richer data for AML and reconciliation", "parts": [{"label": "Purpose data", "note": "Structured purpose data helps compliance screening"}, {"label": "Remittance data", "note": "Structured remittance data lets beneficiary reconcile against the right invoice"}, {"label": "Captured correctly", "note": "Data is only useful if it is captured correctly"}, {"label": "Mapped consistently", "note": "Data is only useful if it is mapped consistently"}, {"label": "Consumed downstream", "note": "Data is only useful if consumed by the downstream systems that need it"}, {"label": "Poor quality spreads", "note": "Poor data quality in one system becomes a compliance and reconciliation problem"}]}}, "level": "advanced", "source_ref": "JEB-18"}, {"id": "INS-145", "seq": 318, "module": "Advanced", "source": "Jebaraj D", "title": "AML and sanctions controls in instant payments", "explain": "An instant payment that completes in 10 seconds still needs sanctions, anti-money laundering, and fraud checks, but those checks can take longer than the rail allows. The controls must be fast and automated, with a clear escalation path and a full audit trail when a payment is held. The design must never imply that controls are bypassed to meet the speed promise.", "takeaway": "The design must never imply that controls are bypassed to meet the speed promise.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Payment completes in 10 seconds", "note": "Instant payment completes in 10 seconds"}, {"kind": "step", "title": "Sanctions, AML and fraud checks", "note": "Sanctions, anti-money laundering, and fraud checks are still needed"}, {"kind": "step", "title": "Checks slower than the rail", "note": "Checks can take longer than the rail allows"}, {"kind": "step", "title": "Fast automated controls", "note": "Controls must be fast and automated"}, {"kind": "step", "title": "Escalation and audit trail", "note": "Clear escalation path and a full audit trail when a payment is held"}, {"kind": "step", "title": "Never bypass controls", "note": "Design must never imply controls are bypassed to meet the speed promise"}]}}, "level": "advanced", "source_ref": "JEB-23"}, {"id": "INS-146", "seq": 319, "module": "Advanced", "source": "Jebaraj D", "title": "Fraud controls in real-time payment journeys", "explain": "Instant payments settle in seconds, which is what customers want and what fraudsters want too. A fraudster who gains access to an account can move money out before the customer notices, and an authorised push payment scam can persuade the customer to send the money themselves. The controls must use risk signals, velocity checks, confirmation of payee, intervention points, and post-transaction monitoring together.", "takeaway": "The controls must use risk signals, velocity checks, confirmation of payee, intervention points, and post-transaction monitoring together.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Instant payments settle in seconds", "note": "Instant payments settle in seconds"}, {"kind": "step", "title": "Fraudster gains access", "note": "Fraudster who gains access can move money out before customer notices"}, {"kind": "step", "title": "Authorised push payment scam", "note": "Scam can persuade the customer to send the money themselves"}, {"kind": "step", "title": "Risk signals", "note": "Controls must use risk signals"}, {"kind": "step", "title": "Velocity checks, payee check", "note": "Controls must use velocity checks and confirmation of payee"}, {"kind": "step", "title": "Intervention and monitoring", "note": "Controls must use intervention points and post-transaction monitoring"}]}}, "level": "advanced", "source_ref": "JEB-23"}, {"id": "JEB-A01", "seq": 320, "module": "Advanced", "source": "Jebaraj D", "title": "Cancel or return: FOCR or cover, choose the refund method by agreement", "explain": "When a payment was made correctly but executed wrongly, the bank must choose between cancelling it and returning the funds. A camt.055 asks for cancellation, but it only works while the payment is still unsettled; once Bank B has settled it, the request is refused. The bank then returns the money with a camt.056 or a pacs.004, and the refund method depends on the agreement: FOCR returns the funds in full through the FOCR procedure, while the cover method sends them back to the original account. If a camt.055 goes unanswered, a pacs.004 is the fallback to request the return.", "takeaway": "If a camt.055 goes unanswered, a pacs.004 is the fallback to request the return.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Payment executed wrongly", "note": "Payment made correctly but executed wrongly, bank must choose cancel or return"}, {"kind": "decision", "title": "Still unsettled?", "note": "camt.055 works only while the payment is still unsettled"}, {"kind": "step", "title": "Send camt.055 to cancel", "note": "Ask for cancellation before settlement; once Bank B settles it, the request is refused"}, {"kind": "step", "title": "Return funds with camt.056 or pacs.004", "note": "After settlement the bank returns the money with camt.056 or pacs.004"}, {"kind": "decision", "title": "Which refund method applies?", "note": "FOCR returns funds in full; cover sends them back to the original account"}, {"kind": "step", "title": "pacs.004 as fallback", "note": "If a camt.055 goes unanswered, pacs.004 requests the return"}]}}, "level": "advanced", "source_ref": "https://www.linkedin.com/posts/jebaraj-d-65b5b01a_payments-iso20022-cbprplus-share-7525402284042817536-w-az/"}, {"id": "JEB-A02", "seq": 321, "module": "Advanced", "source": "Jebaraj D", "title": "No pacs.002 on an instant payment: send pacs.028, never pay twice", "explain": "In SEPA Instant, a payment should complete within seconds, but sometimes the sender bank receives no pacs.002 confirmation at all, even after the 20-second timeout. The customer has been debited and the money has left the bank, yet nobody knows whether the beneficiary was credited. The bank must never debit the account again and send the payment a second time, because that would create a duplicate. Instead it sends a pacs.028 status request, and the recipient bank's investigation confirms either that the payment was credited or that it was rejected, so the bank can close the case or start an automatic refund and restore the account.", "takeaway": "Instead it sends a pacs.028 status request, and the recipient bank's investigation confirms either that the payment was credited or that it was rejected, so the bank can close the case or start an automatic refund and restore the account.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Instant payment sent", "note": "Payment should complete within seconds but no pacs.002 confirmation arrives"}, {"kind": "step", "title": "20-second timeout passes", "note": "Sender bank receives no pacs.002 even after the 20-second timeout"}, {"kind": "decision", "title": "Was the beneficiary credited?", "note": "Customer debited and money left, yet nobody knows if beneficiary was credited"}, {"kind": "step", "title": "Never pay a second time", "note": "Do not debit the account again and send the payment a second time"}, {"kind": "step", "title": "Send pacs.028 status request", "note": "Ask the recipient bank to investigate the payment status"}, {"kind": "step", "title": "Close case or refund", "note": "If credited, close the case; if rejected, start an automatic refund"}]}}, "level": "advanced", "source_ref": "https://www.linkedin.com/posts/jebaraj-d-65b5b01a_payments-iso20022-pacs028-share-7524295580383219712-R5KS/"}, {"id": "JEB-A04", "seq": 322, "module": "Advanced", "source": "Jebaraj D", "title": "PMNE: the Nostro debit is missing, prove the state before re-effecting", "explain": "A Payment Missing a Nostro Entry happens when a payment has been made from the customer account and sent on, but the Nostro debit was never posted. The customer was debited and the confirmation was sent, yet the Nostro statement shows no debit, and the beneficiary may already have been credited. Before acting, the bank must prove the state of the payment, using a pacs.002, a camt.052 or camt.053, or a pacs.028 if no notification arrived. Once the state is proved, the correspondent bank posts the Nostro debit; the payment must not be re-effected, because that would create a duplicate payment and a Nostro break at reconciliation.", "takeaway": "Once the state is proved, the correspondent bank posts the Nostro debit; the payment must not be re-effected, because that would create a duplicate payment and a Nostro break at reconciliation.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Payment sent, Nostro debit missing", "note": "Customer debited and confirmation sent, but Nostro statement shows no debit"}, {"kind": "step", "title": "Prove the state of the payment", "note": "Use pacs.002, camt.052 or camt.053, or pacs.028 if no notification arrived"}, {"kind": "decision", "title": "Payment state proved?", "note": "Proof must come before any action on the missing Nostro debit"}, {"kind": "step", "title": "Correspondent posts Nostro debit", "note": "Once proved, the correspondent bank posts the missing Nostro debit"}, {"kind": "step", "title": "Do not re-effect the payment", "note": "Re-effecting would create a duplicate payment and a Nostro break at reconciliation"}]}}, "level": "advanced", "source_ref": "https://www.linkedin.com/posts/jebaraj-d-65b5b01a_payments-nostro-reconciliation-share-7522847516460101632-raze/"}, {"id": "JEB-A07", "seq": 323, "module": "Advanced", "source": "Jebaraj D", "title": "T2 or CBPR+: the BAH BizSvc decides the route, not the pacs.008", "explain": "The same pacs.008 for EUR 5 million takes a different route depending on where it is going, and the route is set by the BAH BizSvc code, not by the message itself. A T2 payment goes through ESMIG to the ECB as central bank money settlement, identified by a BizSvc such as trgt.002.001.01, while a CBPR+ payment goes cross-border through SWIFT FINplus, identified by a BizSvc such as swift.cbprplus.02. The route determines settlement, timing, cost and risk, so a payment sent down the wrong route can be delayed, rejected or settled incorrectly. The lesson is simple: the pacs.008 is not the route, the BAH plus BizSvc is the route.", "takeaway": "The lesson is simple: the pacs.008 is not the route, the BAH plus BizSvc is the route.", "visual": {"type": "diagram", "diagram": {"centre": "BAH BizSvc decides the route", "parts": [{"label": "pacs.008 EUR 5 million", "note": "Same message, different route depending on where it is going"}, {"label": "T2 via ESMIG to ECB", "note": "Central bank money settlement, BizSvc trgt.002.001.01"}, {"label": "CBPR+ via SWIFT FINplus", "note": "Cross-border route, BizSvc swift.cbprplus.02"}, {"label": "Settlement, timing, cost, risk", "note": "The route determines settlement, timing, cost and risk"}, {"label": "Wrong route consequences", "note": "A wrong route can delay, reject or settle the payment incorrectly"}]}}, "level": "advanced", "source_ref": "https://www.linkedin.com/posts/jebaraj-d-65b5b01a_payments-iso20022-cbprplus-share-7520316029441536000-fKgq/"}, {"id": "JEB-A10", "seq": 324, "module": "Advanced", "source": "Jebaraj D", "title": "Back valuation: the value date, not the booking date, drives interest", "explain": "Back valuation happens when a payment is processed with a value date that differs from its booking date, and it matters because interest is calculated from the value date, not the booking date. In a single-sided case the mismatch sits on one side of the transaction, for example the customer account is credited on Monday with a Monday value date while the Nostro debit is booked later with the same value date. In a double-sided case the mismatch sits on both sides. The bank should confirm the value date first, then check whether the back valuation is single or double-sided, and then assess the impact on interest, liquidity and reconciliation.", "takeaway": "The bank should confirm the value date first, then check whether the back valuation is single or double-sided, and then assess the impact on interest, liquidity and reconciliation.", "visual": {"type": "diagram", "diagram": {"centre": "Value date drives interest", "parts": [{"label": "Value date vs booking date", "note": "Payment processed with a value date that differs from its booking date"}, {"label": "Single-sided mismatch", "note": "Mismatch sits on one side, for example customer credited Monday, Nostro debited later"}, {"label": "Double-sided mismatch", "note": "Mismatch sits on both sides of the transaction"}, {"label": "Confirm the value date first", "note": "Bank should confirm the value date before anything else"}, {"label": "Impact on interest", "note": "Assess the impact on interest, liquidity and reconciliation"}]}}, "level": "advanced", "source_ref": "https://www.linkedin.com/posts/jebaraj-d-65b5b01a_payments-backvaluation-paymentoperations-share-7518868336429002752-zEz_/"}, {"id": "JEB-A14", "seq": 325, "module": "Advanced", "source": "Jebaraj D", "title": "Tracking is not stopping: SWIFT gpi Stop and Recall in three queues", "explain": "Tracking a SWIFT gpi payment is not the same as stopping it, because tracking only shows where the payment is while stopping prevents it from being credited. Once a payment is credited to the beneficiary, shown as ACSC, a stop message has no effect, and the bank needs a Stop and Recall request instead. The request runs on three queues: FAST, acknowledged within 2 hours when the payment is already settled and credited; MEDIUM, answered within 12 hours when the beneficiary bank needs time to contact the beneficiary; and SLOW, answered within 72 hours when more time is needed. Every minute of delay reduces the chance of stopping a payment, so speed decides whether a recall is still possible.", "takeaway": "Every minute of delay reduces the chance of stopping a payment, so speed decides whether a recall is still possible.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Tracking shows the location", "note": "Tracking only shows where the payment is"}, {"kind": "decision", "title": "Already credited as ACSC?", "note": "Once credited to the beneficiary, a stop message has no effect"}, {"kind": "step", "title": "Send Stop and Recall request", "note": "Stopping needs a Stop and Recall request instead of tracking"}, {"kind": "step", "title": "FAST queue: within 2 hours", "note": "Acknowledged within 2 hours when the payment is settled and credited"}, {"kind": "step", "title": "MEDIUM queue: within 12 hours", "note": "Answered within 12 hours when the bank needs time to contact the beneficiary"}, {"kind": "step", "title": "SLOW queue: within 72 hours", "note": "Answered within 72 hours when more time is needed"}, {"kind": "step", "title": "Act fast", "note": "Every minute of delay reduces the chance of stopping a payment"}]}}, "level": "advanced", "source_ref": "https://www.linkedin.com/posts/jebaraj-d-65b5b01a_payment-stories-episode-7-swift-gpi-tracking-ugcPost-7516328097718251521-DoDo/"}, {"id": "JEB-A15", "seq": 326, "module": "Advanced", "source": "Jebaraj D", "title": "INDA vs INGA: one code, two accounting outcomes in MT to MX migration", "explain": "The settlement method code on a pacs.008 changes the accounting: INDA means the instructed agent settles this leg, while INGA means the instructing agent has already settled it. MT to MX migration is not a one-to-one field replacement, because information that used to be implied is now explicit and carries business meaning. If an incoming INGA payment is wrongly mapped as INDA, the engine follows the wrong settlement logic and debits the sending bank's account again, creating a double posting and a reconciliation break found at day-end. During migration the bank should ask who settles each leg, whether settlement has already happened, and what accounting entries should follow, because a field mapping shows where data goes while business analysis shows what it means.", "takeaway": "During migration the bank should ask who settles each leg, whether settlement has already happened, and what accounting entries should follow, because a field mapping shows where data goes while business analysis shows what it means.", "visual": {"type": "diagram", "diagram": {"centre": "INDA vs INGA settlement code", "parts": [{"label": "INDA: instructed agent settles", "note": "The instructed agent settles this leg of the payment"}, {"label": "INGA: already settled", "note": "The instructing agent has already settled this leg"}, {"label": "Wrong mapping, double posting", "note": "INGA mapped as INDA debits the sending bank again, a double posting"}, {"label": "Reconciliation break at day-end", "note": "The double posting is found as a reconciliation break at day-end"}, {"label": "Who settles each leg?", "note": "Ask who settles each leg and whether settlement has already happened"}, {"label": "Mapping vs meaning", "note": "A field mapping shows where data goes, business analysis shows what it means"}]}}, "level": "advanced", "source_ref": "https://www.linkedin.com/posts/jebaraj-d-65b5b01a_paymentba-iso20022-cbprplus-ugcPost-7515964440845029376-jwOv/"}, {"id": "JEB-B03", "seq": 327, "module": "Advanced", "source": "Jebaraj D", "title": "One leg failed: check the cover before recalling it", "explain": "A USD 250,000 payment from India to Europe using the cover method had its pacs.008 rejected by the bank's own system before it was sent, while the pacs.009 COV had already been processed. Before recalling the cover, three questions decide the path: has the cover been released, has it settled, and is the beneficiary bank's USD cut-off still open. If the cover has not been released, stop it, fix the issue and regenerate both legs; if it has settled and the cut-off is still open, fixing the issue and sending the pacs.008 may complete the payment without a recall. Recalling straight away can make things worse, because cancelling a good cover and reprocessing it can delay the credit and affect the value date.", "takeaway": "Recalling straight away can make things worse, because cancelling a good cover and reprocessing it can delay the credit and affect the value date.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "pacs.008 rejected before sending", "note": "Bank system rejects the pacs.008 while the pacs.009 COV is already processed"}, {"kind": "decision", "title": "Has the cover been released?", "note": "First ask whether the cover has been released"}, {"kind": "decision", "title": "Has it settled, is cut-off open?", "note": "Ask whether it has settled and whether the beneficiary bank USD cut-off is open"}, {"kind": "step", "title": "Not released: stop and regenerate", "note": "Stop the cover, fix the issue and regenerate both legs"}, {"kind": "step", "title": "Settled and cut-off open: fix and send", "note": "Fix the issue and send the pacs.008, which may complete the payment without a recall"}, {"kind": "step", "title": "Do not recall straight away", "note": "Cancelling a good cover can delay the credit and affect the value date"}]}}, "level": "advanced", "source_ref": "https://www.linkedin.com/posts/jebaraj-d-65b5b01a_crossborderpayments-iso20022-cbprplus-share-7514519567734517760-tqaK/"}, {"id": "JEB-B06", "seq": 328, "module": "Advanced", "source": "Jebaraj D", "title": "pacs.002 RJCT: check the cover before crediting the remitter", "explain": "When a cross-border payment runs on the cover method, the pacs.008 goes directly to the beneficiary bank while the pacs.009 COV moves the funds through the correspondent. If a pacs.002 RJCT arrives for the pacs.008, the instinct is to credit the remitter, but the first question is the status of the cover: not yet processed, on hold, or already processed and settled. Crediting too early can refund the customer while the cover is still at the correspondent, a loss the bank has to absorb, so the bank must establish where the funds are before acting. Knowing pacs.002, pacs.004 and camt.056 individually is not enough; a senior professional understands how the two legs interact and what to check before taking action.", "takeaway": "Knowing pacs.002, pacs.004 and camt.056 individually is not enough; a senior professional understands how the two legs interact and what to check before taking action.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "pacs.008 and pacs.009 COV sent", "note": "pacs.008 goes to the beneficiary bank while the COV moves funds through the correspondent"}, {"kind": "step", "title": "pacs.002 RJCT arrives", "note": "A rejection arrives for the pacs.008, and the instinct is to credit the remitter"}, {"kind": "decision", "title": "What is the status of the cover?", "note": "Not yet processed, on hold, or already processed and settled"}, {"kind": "step", "title": "Establish where the funds are", "note": "Find where the funds are before acting"}, {"kind": "step", "title": "Do not credit too early", "note": "Crediting too early can refund the customer while the cover is still at the correspondent"}]}}, "level": "advanced", "source_ref": "https://www.linkedin.com/posts/jebaraj-d-65b5b01a_iso20022-correspondentbanking-payments-share-7513068544830537728-LjBx/"}, {"id": "JEB-B10", "seq": 329, "module": "Advanced", "source": "Jebaraj D", "title": "Regulatory vs client priority: phase both, do not choose blind", "explain": "A product owner prioritised CBPR+ structured-address work over a strategic client's Cash Pooling work because the regulatory date was November 2026, but the clash was worth challenging on the assumptions, not the authority. The question is what is truly mandatory, what can be phased, and what the capacity impact is: the Cash Pooling side might need only domestic pooling first, and the regulatory side might sequence incoming support before outgoing. Breaking both pieces down turned an either-or choice into a plan with incoming structured-address support first, domestic Cash Pooling on track, and outgoing support plus international and cross-currency pooling in the next phase. Challenge the thinking, not the person, and check whether either piece can be phased before locking the priority in.", "takeaway": "Challenge the thinking, not the person, and check whether either piece can be phased before locking the priority in.", "visual": {"type": "diagram", "diagram": {"centre": "Phase both, do not choose blind", "parts": [{"label": "Regulatory date November 2026", "note": "CBPR+ structured-address work was prioritised for the regulatory date"}, {"label": "Strategic client Cash Pooling", "note": "The client work was deprioritised against the regulatory work"}, {"label": "Challenge the assumptions", "note": "Challenge the thinking, not the person, and question what is truly mandatory"}, {"label": "What can be phased?", "note": "Check what can be phased and what the capacity impact is"}, {"label": "Incoming first, domestic on track", "note": "Incoming structured-address support first, with domestic Cash Pooling on track"}, {"label": "Next phase: outgoing and more", "note": "Outgoing support plus international and cross-currency pooling in the next phase"}]}}, "level": "advanced", "source_ref": "https://www.linkedin.com/posts/jebaraj-d-65b5b01a_businessanalysis-payments-iso20022-share-7511615890816192512-TfU7/"}, {"id": "JEB-B13", "seq": 330, "module": "Advanced", "source": "Jebaraj D", "title": "camt.055: cancellation depends on where the payment sits", "explain": "When a camt.055 cancellation request arrives, do not assume a camt.056 should be sent straight away; the first question is where the original payment sits in its lifecycle. A future-dated or warehoused payment that has not been released may be cancelled before execution, a payment pending a compliance decision must be considered alongside that process, and a payment already processed by the debtor bank is no longer an internal decision. In a direct and cover model, the pacs.008 and pacs.009 COV legs may each need separate follow-up, because each leg is controlled by a different party. A cancellation request is a request, not a guarantee, and if it fails, the next step is to determine the appropriate return or investigation path.", "takeaway": "A cancellation request is a request, not a guarantee, and if it fails, the next step is to determine the appropriate return or investigation path.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "camt.055 cancellation arrives", "note": "Do not assume a camt.056 should be sent straight away"}, {"kind": "decision", "title": "Where does the payment sit?", "note": "First ask where the original payment sits in its lifecycle"}, {"kind": "step", "title": "Warehoused: cancel before execution", "note": "A future-dated payment not yet released may be cancelled before execution"}, {"kind": "step", "title": "Pending compliance: consider together", "note": "A payment pending a compliance decision must be considered alongside that process"}, {"kind": "step", "title": "Already processed: not internal", "note": "A payment already processed by the debtor bank is no longer an internal decision"}, {"kind": "step", "title": "Each leg needs its own follow-up", "note": "In a direct and cover model, the pacs.008 and pacs.009 COV legs may each need follow-up"}, {"kind": "step", "title": "If it fails, find the return path", "note": "A cancellation is a request, not a guarantee; determine the return or investigation path"}]}}, "level": "advanced", "source_ref": "https://www.linkedin.com/feed/update/urn:li:groupPost:40975017-7508913034132901888/"}, {"id": "JEB-C09", "seq": 331, "module": "Advanced", "source": "Jebaraj D", "title": "Explain a recall as a journey, not a list of messages", "explain": "Many candidates can describe camt.055, camt.056, pacs.004 and camt.029 one by one but cannot connect them into the business journey. The journey runs from the customer asking the debtor bank to recall a payment, through the bank starting an investigation and sending a camt.056 to the creditor agent, to the creditor bank checking whether the payment was credited and whether the beneficiary agrees, and finally to the outcome and the investigation response. The interview answer should follow that chain of customer intention, investigation, interbank request, creditor decision, financial outcome and response, because that shows payments knowledge, not just message knowledge. When learning any ISO 20022 message, ask who sends it, why, what triggered it, and what happens before and after it.", "takeaway": "When learning any ISO 20022 message, ask who sends it, why, what triggered it, and what happens before and after it.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Customer asks to recall the payment", "note": "The journey starts with the customer asking the debtor bank to recall a payment"}, {"kind": "step", "title": "Bank starts an investigation", "note": "The bank starts an investigation and sends a camt.056 to the creditor agent"}, {"kind": "step", "title": "Creditor bank checks the payment", "note": "The creditor bank checks whether the payment was credited and the beneficiary agrees"}, {"kind": "step", "title": "Financial outcome decided", "note": "The outcome follows the creditor decision on the return of funds"}, {"kind": "step", "title": "Investigation response sent", "note": "Finally the outcome and the investigation response close the journey"}, {"kind": "step", "title": "Answer as a chain, not a list", "note": "Follow customer intention, investigation, request, decision, outcome and response"}]}}, "level": "advanced", "source_ref": "https://www.linkedin.com/posts/jebaraj-d-65b5b01a_payments-paymentba-iso20022-share-7492624304287735808-IrOc/"}, {"id": "JEB-C12", "seq": 332, "module": "Advanced", "source": "Jebaraj D", "title": "The recall journey in four messages, and one open question", "explain": "The end-to-end recall journey runs through camt.055, the customer cancellation request, camt.056, the interbank cancellation request, pacs.004, the payment return, and camt.029, the resolution of the investigation. The post asks which of these four messages is not used in the flow and puts it to a poll, promising the author's perspective later in the week. The post itself does not give the answer, so this item states the journey as the post presents it and leaves the poll question open rather than guessing the answer. Connecting the four messages into one journey is the point of the exercise, not naming each message on its own.", "takeaway": "Connecting the four messages into one journey is the point of the exercise, not naming each message on its own.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "camt.055: customer cancellation request", "note": "The journey starts with the customer cancellation request"}, {"kind": "step", "title": "camt.056: interbank cancellation request", "note": "The bank sends the interbank cancellation request"}, {"kind": "step", "title": "pacs.004: the payment return", "note": "The return of the payment follows"}, {"kind": "step", "title": "camt.029: resolution of investigation", "note": "The investigation is resolved with a camt.029"}, {"kind": "step", "title": "One message is not used: poll open", "note": "The post asks which message is not used and leaves the poll question open"}]}}, "level": "advanced", "source_ref": "https://www.linkedin.com/feed/update/urn:li:groupPost:40975017-7508066441900904448/"}, {"id": "INS-029", "seq": 333, "module": "Advanced", "source": "Harish Kavire", "title": "End-to-end payment transaction lifecycle", "explain": "A payment moves through a chain of states from initiation to confirmation, and each state needs a named owner and a named piece of evidence. Initiation creates the instruction with an instruction ID and an end-to-end ID, validation checks the instruction, routing chooses the rail, clearing moves it through the scheme, settlement moves the funds between banks, posting records it in the ledger, and confirmation tells the customer it is done. When a payment goes missing, the investigation follows this chain state by state, because the state where the evidence stops is the state where the payment is stuck.", "takeaway": "When a payment goes missing, the investigation follows this chain state by state, because the state where the evidence stops is the state where the payment is stuck.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Initiation", "note": "Creates the instruction with instruction and end-to-end IDs."}, {"kind": "step", "title": "Validation", "note": "Checks the instruction."}, {"kind": "step", "title": "Routing", "note": "Chooses the rail."}, {"kind": "step", "title": "Clearing", "note": "Moves the payment through the scheme."}, {"kind": "step", "title": "Settlement", "note": "Moves the funds between banks."}, {"kind": "step", "title": "Posting", "note": "Records the payment in the ledger."}, {"kind": "step", "title": "Confirmation", "note": "Tells the customer the payment is done."}]}}, "level": "advanced", "source_ref": "HAR-03"}, {"id": "INS-031", "seq": 334, "module": "Advanced", "source": "Harish Kavire", "title": "End-to-end credit card transaction flow", "explain": "A credit card transaction has four distinct stages with different owners and different evidence. Authorisation happens in seconds: the terminal sends the card and transaction details to the acquirer, the scheme routes them to the issuer, and the issuer checks the card status, the available credit and the fraud rules, then approves or declines and places a hold on the funds. Clearing exchanges the transaction records, settlement moves the funds between the banks, and billing and dispute touchpoints handle the customer statement and any later dispute. Each stage must be understood separately, because a problem at authorisation looks nothing like a problem at settlement.", "takeaway": "Each stage must be understood separately, because a problem at authorisation looks nothing like a problem at settlement.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Authorisation", "note": "Issuer checks card, credit and fraud rules, then holds funds."}, {"kind": "step", "title": "Clearing", "note": "Exchanges the transaction records."}, {"kind": "step", "title": "Settlement", "note": "Moves the funds between the banks."}, {"kind": "step", "title": "Billing and disputes", "note": "Handles the statement and any later dispute."}]}}, "level": "advanced", "source_ref": "HAR-03"}, {"id": "INS-006", "seq": 335, "module": "Advanced", "source": "Harish Kavire", "title": "Payment failed but customer account debited", "explain": "A customer sends EUR 850 through a mobile app, the app shows the payment as failed, yet the account statement shows the EUR 850 debit. The payment is in an uncertain state: the debit may mean the payment reached the clearing system and is still processing, or it may mean the ledger posted while the payment status update failed. Treat the payment as one transaction with one identity across every system, and use the original instruction ID, end-to-end ID and ledger posting reference to trace it through the channel, the payment engine, the clearing adapter and the core ledger. Do not retry until the true status is known, because a blind retry could create a duplicate payment of EUR 850.", "takeaway": "Do not retry until the true status is known, because a blind retry could create a duplicate payment of EUR 850.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Fix the transaction identity", "note": "One instruction ID, end-to-end ID and ledger reference."}, {"kind": "step", "title": "Trace the channel", "note": "Follow the payment through the channel."}, {"kind": "step", "title": "Trace the payment engine", "note": "Follow it through the payment engine."}, {"kind": "step", "title": "Trace the clearing adapter", "note": "Follow it through the clearing adapter."}, {"kind": "step", "title": "Trace the core ledger", "note": "Follow it through the core ledger."}, {"kind": "decision", "title": "Decide before retrying", "note": "Do not retry until the true status is known."}]}}, "level": "advanced", "source_ref": "HAR-01"}, {"id": "INS-032", "seq": 336, "module": "Advanced", "source": "Harish Kavire", "title": "Gateway success but core banking posting fails", "explain": "A payment gateway returns a success response for a EUR 40,000 supplier payment and the channel shows the payment as accepted, yet hours later the supplier has not been paid, the finance team finds no debit in the core banking ledger, and the payment engine still shows the payment as in progress. Separate the three facts and find the authoritative source for each: the gateway is authoritative for acceptance of the instruction, the ledger is authoritative for whether the debit posted, and the payment engine state must be reconciled against both. A success response from the gateway does not prove the ledger posted, so the investigation must check the posting rather than trusting the channel message.", "takeaway": "A success response from the gateway does not prove the ledger posted, so the investigation must check the posting rather than trusting the channel message.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Separate the three facts", "note": "Gateway acceptance, ledger debit and engine state."}, {"kind": "step", "title": "Check the gateway", "note": "Authoritative for acceptance of the instruction."}, {"kind": "step", "title": "Check the ledger", "note": "Authoritative for whether the debit posted."}, {"kind": "step", "title": "Reconcile the engine state", "note": "Reconcile the engine against gateway and ledger."}]}}, "level": "advanced", "source_ref": "HAR-03"}, {"id": "INS-071", "seq": 337, "module": "Advanced", "source": "Harish Kavire", "title": "Payment timeout and uncertain final status", "explain": "A corporate customer submits a supplier payment through the online channel, the screen spins and then times out, and no confirmation appears and no reference is shown. The payment is in an unknown state: it may have been accepted, executed, or never received. Make the timeout path explicit in the product, so the channel shows a pending or unknown state, never a success and never a failure, until the outcome is confirmed. The status enquiry uses the original correlation ID and payment reference to ask the payment engine, then the ledger, then the downstream clearing status, in that order, and only then is a retry safe.", "takeaway": "The status enquiry uses the original correlation ID and payment reference to ask the payment engine, then the ledger, then the downstream clearing status, in that order, and only then is a retry safe.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Show pending or unknown", "note": "Never a success and never a failure until confirmed."}, {"kind": "step", "title": "Ask the payment engine", "note": "Use the original correlation ID and payment reference."}, {"kind": "step", "title": "Ask the ledger", "note": "Check the ledger next, in that order."}, {"kind": "step", "title": "Ask clearing status", "note": "Check downstream clearing status last."}, {"kind": "decision", "title": "Retry only when confirmed", "note": "A retry is safe only once the outcome is known."}]}}, "level": "advanced", "source_ref": "HAR-13"}, {"id": "INS-087", "seq": 338, "module": "Advanced", "source": "Harish Kavire", "title": "Duplicate transaction investigation", "explain": "A supplier payment appears twice on the account statement for the same amount, to the same supplier, on the same day, and the supplier confirms receiving two credits. Reconstruct both payments end to end from the same evidence set: for each submission collect the channel timestamp, the idempotency key and payload hash, the gateway reference, the payment engine reference, the ledger posting reference and the clearing acknowledgement. Comparing the two sets of evidence shows whether the duplicate came from a client retry, a gateway redelivery or a missing idempotency check, and each cause has a different fix.", "takeaway": "Comparing the two sets of evidence shows whether the duplicate came from a client retry, a gateway redelivery or a missing idempotency check, and each cause has a different fix.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Collect evidence, first payment", "note": "Timestamps, idempotency key, hashes and references."}, {"kind": "step", "title": "Collect evidence, second payment", "note": "The same evidence set for the second payment."}, {"kind": "step", "title": "Compare the two sets", "note": "Comparing shows where the duplicate came from."}, {"kind": "step", "title": "Identify the cause", "note": "Client retry, gateway redelivery or missing check."}]}}, "level": "advanced", "source_ref": "HAR-13"}, {"id": "INS-050", "seq": 339, "module": "Advanced", "source": "Harish Kavire", "title": "Duplicate transactions appear after release", "explain": "After a new corporate payment channel is released, the operations team notices duplicate debits: several corporate customers have been charged twice for the same instruction, and a few suppliers have been paid twice. Contain the failure first by confirming whether duplicates are still being created and, if so, stopping the affected path or routing it through a manual check. Then establish the affected population using stable identifiers rather than guesswork, matching on idempotency key, instruction reference, end-to-end identification, debtor, creditor, amount, currency and value date, and separate confirmed duplicates from suspected ones before remediating.", "takeaway": "Then establish the affected population using stable identifiers rather than guesswork, matching on idempotency key, instruction reference, end-to-end identification, debtor, creditor, amount, currency and value date, and separate confirmed duplicates from suspected ones before remediating.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Contain the failure", "note": "Confirm duplicates are still being created; stop the path."}, {"kind": "step", "title": "Establish the population", "note": "Match on stable identifiers, not guesswork."}, {"kind": "step", "title": "Separate confirmed and suspected", "note": "Separate confirmed duplicates from suspected ones."}, {"kind": "step", "title": "Remediate", "note": "Fix the cause and put right the affected payments."}]}}, "level": "advanced", "source_ref": "HAR-05"}, {"id": "INS-033", "seq": 340, "module": "Advanced", "source": "Harish Kavire", "title": "Quantifying a 20,000-transaction reconciliation gap", "explain": "A bank processes 20,000 transactions in a day and the morning reconciliation shows 500 transactions unmatched between the ledger and the clearing reports. Quantify in layers and never present an illustrative figure as a confirmed loss. State the population clearly: 20,000 transactions processed, 500 unmatched, an unmatched rate of 2.5 percent, and an illustrative exposure of INR 40 lakh based on 500 multiplied by an average of INR 8,000. The illustrative figure frames the scale of the problem, but the real exposure is only known once the unmatched transactions are investigated one by one.", "takeaway": "The illustrative figure frames the scale of the problem, but the real exposure is only known once the unmatched transactions are investigated one by one.", "visual": {"type": "stacked", "stacked": {"segments": [{"label": "Matched transactions", "note": "19,500 of 20,000 transactions matched, 97.5 percent.", "value": 97.5}, {"label": "Unmatched transactions", "note": "500 of 20,000 transactions unmatched, 2.5 percent.", "value": 2.5}], "unit": "%"}}, "level": "advanced", "source_ref": "HAR-03"}, {"id": "INS-035", "seq": 341, "module": "Advanced", "source": "Harish Kavire", "title": "Two banking systems show different balances", "explain": "A customer checks the mobile app and sees a balance of EUR 4,120, then calls the contact centre where the agent's screen shows EUR 3,850. The difference is EUR 270, exactly the amount of a card payment the customer made that morning. Start by defining what each balance means: the ledger balance is the posted balance in the core banking system and it is authoritative for posted funds, while the app balance may include pending or unposted items. The EUR 270 difference is the pending card payment, so the two balances are both accurate for what they represent, and the fix is to explain the difference rather than to change either balance.", "takeaway": "The EUR 270 difference is the pending card payment, so the two balances are both accurate for what they represent, and the fix is to explain the difference rather than to change either balance.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Define each balance", "note": "Ledger balance is posted; the app may include pending items."}, {"kind": "step", "title": "Identify the EUR 270 difference", "note": "It is the pending card payment from this morning."}, {"kind": "step", "title": "Explain the difference", "note": "Both balances are accurate for what they represent."}]}}, "level": "advanced", "source_ref": "HAR-03"}, {"id": "INS-057", "seq": 342, "module": "Advanced", "source": "Harish Kavire", "title": "UI, API and database values differ", "explain": "A cross-border payment complaint shows one amount in the online banking screen, a different amount transmitted by the API, and a third value held in the database, and the beneficiary address appears complete in the user interface but arrives truncated in the payment message. Fix the record first: pick one affected payment and its stable identifier, such as the end-to-end identification, and use that single identifier at every layer so the comparison is about the same record. Then capture the value at each point, what the customer entered and what the screen displayed, the API request payload as received, the transformed canonical model, the validation and defaulting applied, and the persisted record, to find where the value changed.", "takeaway": "Then capture the value at each point, what the customer entered and what the screen displayed, the API request payload as received, the transformed canonical model, the validation and defaulting applied, and the persisted record, to find where the value changed.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Fix the record", "note": "Pick one payment and its end-to-end identification."}, {"kind": "step", "title": "Capture screen values", "note": "What the customer entered and what the screen displayed."}, {"kind": "step", "title": "Capture the API payload", "note": "The API request payload as received."}, {"kind": "step", "title": "Capture the canonical model", "note": "The transformed model, validation and defaulting."}, {"kind": "step", "title": "Capture the persisted record", "note": "The record as stored in the database."}, {"kind": "step", "title": "Find where the value changed", "note": "Compare the layers to find where it changed."}]}}, "level": "advanced", "source_ref": "HAR-08"}, {"id": "INS-036", "seq": 343, "module": "Advanced", "source": "Harish Kavire", "title": "Legacy-to-new customer data mismatch", "explain": "During a migration from a legacy core system to a new platform, the first rehearsal shows thousands of mismatches: names that do not match, addresses that cannot be placed into the new structured format, dates in different formats, and payment records whose beneficiary details are incomplete. Define the migration as a controlled data movement with proof at every stage. Start with a field-level mapping from the legacy system to the new platform, with every source field, its target field, its transformation rule, its validation rule and its owner, then prove the movement with control totals and exception handling at each stage.", "takeaway": "Start with a field-level mapping from the legacy system to the new platform, with every source field, its target field, its transformation rule, its validation rule and its owner, then prove the movement with control totals and exception handling at each stage.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Define the field mapping", "note": "Source field, target, transformation, validation, owner."}, {"kind": "step", "title": "Prove movement with control totals", "note": "Control totals and exception handling at each stage."}, {"kind": "step", "title": "Handle exceptions", "note": "Exception handling proves the movement at each stage."}]}}, "level": "advanced", "source_ref": "HAR-03"}, {"id": "INS-011", "seq": 344, "module": "Advanced", "source": "Harish Kavire", "title": "First response to a production issue", "explain": "When the monitoring dashboard shows a sharp rise in failed instant payments just after 09:00, customers report payments stuck in pending, and the contact centre queue is growing, the first responder must act in a fixed order and not improvise. First, confirm the incident is real using monitoring, error rates and customer reports, and declare it through the agreed channel with a severity based on customer impact, not on the suspected cause. Then establish the impact, the affected population, the containment, the ownership, the evidence and the update cadence, so that the response is organised from the first minutes rather than assembled under pressure.", "takeaway": "Then establish the impact, the affected population, the containment, the ownership, the evidence and the update cadence, so that the response is organised from the first minutes rather than assembled under pressure.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Confirm the incident is real", "note": "Use monitoring, error rates and customer reports."}, {"kind": "step", "title": "Declare the incident", "note": "Agreed channel, severity by customer impact."}, {"kind": "step", "title": "Establish impact and population", "note": "Establish the affected population."}, {"kind": "step", "title": "Establish containment", "note": "Establish the containment for the incident."}, {"kind": "step", "title": "Establish ownership and cadence", "note": "Ownership, evidence and update cadence."}]}}, "level": "advanced", "source_ref": "HAR-01"}, {"id": "INS-065", "seq": 345, "module": "Advanced", "source": "Harish Kavire", "title": "Hundreds of similar complaints within 20 minutes", "explain": "On a weekday morning between 09:12 and 09:32, a contact centre receives more than 300 complaints with the same shape: customers report a debit that does not match the payment status shown in the app, or a credit they expected that has not appeared. Start with an incident bridge that separates three workstreams: customer and financial containment, technical root cause analysis, and communications. Containment owns the affected-transaction register, the decision on the next batch and any remediation, while the other workstreams proceed in parallel, so that customers are protected even before the root cause is known.", "takeaway": "Containment owns the affected-transaction register, the decision on the next batch and any remediation, while the other workstreams proceed in parallel, so that customers are protected even before the root cause is known.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Open an incident bridge", "note": "Start with an incident bridge for the complaints."}, {"kind": "step", "title": "Separate three workstreams", "note": "Containment, root cause analysis and communications."}, {"kind": "step", "title": "Containment owns the register", "note": "Affected-transaction register and remediation decisions."}, {"kind": "step", "title": "Other workstreams run in parallel", "note": "Customers are protected before the root cause is known."}]}}, "level": "advanced", "source_ref": "HAR-11"}, {"id": "INS-067", "seq": 346, "module": "Advanced", "source": "Harish Kavire", "title": "Failures across UPI, cards, net banking and wallets", "explain": "On the same day, UPI payments fail with timeouts, card payments fail at the gateway, net banking sessions drop before confirmation, and wallet payments fail after the wallet is debited. Build one incident table segmented by rail and channel, gateway, bank, response code, time window and transaction state, and join each row to its ledger and clearing evidence by correlation ID. For each segment, establish whether the payment left the customer account, whether it reached clearing or the scheme, and what its authoritative state is now. Segmenting the incident this way shows whether there is one cause or several, which decides whether one fix or several are needed.", "takeaway": "Segmenting the incident this way shows whether there is one cause or several, which decides whether one fix or several are needed.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Segment the incident", "note": "One table by rail, channel, gateway, bank and code"}, {"kind": "step", "title": "Join each row to ledger evidence", "note": "Join by correlation ID to ledger and clearing evidence"}, {"kind": "step", "title": "Establish each segment state", "note": "Did it leave the account, reach clearing, what is its state"}, {"kind": "decision", "title": "One cause or several?", "note": "One cause means one fix, several means several fixes"}, {"kind": "step", "title": "Apply the fix", "note": "One fix or several, as the evidence decides"}]}}, "level": "advanced", "source_ref": "HAR-12"}, {"id": "INS-066", "seq": 347, "module": "Advanced", "source": "Harish Kavire", "title": "Payment volume rises 300 percent during a zero-fee campaign", "explain": "A bank launches a zero-fee weekend campaign for retail payments and within the first hour payment volume rises to 300 percent of a normal peak, roughly four times the usual load. Latency climbs, channel sessions start timing out, and the clearing connector queue grows faster than it drains. Treat the surge as a capacity problem with three controls: intake, queue and recovery. At intake, apply back-pressure through the API gateway and channel, queue or gracefully defer non-critical traffic, show a clear pending state instead of a silent timeout, and throttle campaign traffic to a rate the downstream chain can sustain.", "takeaway": "At intake, apply back-pressure through the API gateway and channel, queue or gracefully defer non-critical traffic, show a clear pending state instead of a silent timeout, and throttle campaign traffic to a rate the downstream chain can sustain.", "visual": {"type": "stacked", "stacked": {"segments": [{"label": "Normal peak volume", "note": "The usual peak load, the baseline for the campaign.", "value": 100}, {"label": "Additional campaign volume", "note": "Volume rises to 300 percent of a normal peak.", "value": 300}], "unit": "%"}}, "level": "advanced", "source_ref": "HAR-12"}, {"id": "INS-064", "seq": 348, "module": "Advanced", "source": "Harish Kavire", "title": "Rupees 18,500 debit but e-commerce order remains pending", "explain": "A customer pays Rs 18,500 for an order through a retailer's checkout, the bank account is debited, the payment gateway reports success, and the order remains pending with no confirmation, no dispatch and no delivery date. Start by fixing the reference: take the payment reference from the customer's bank statement and the gateway transaction ID, and confirm they belong to the same payment. Then trace the four boundaries in order, the gateway, the bank, the merchant callback and the order creation, to find where the payment outcome was lost, because the fulfilment path and the refund path depend on which boundary failed.", "takeaway": "Then trace the four boundaries in order, the gateway, the bank, the merchant callback and the order creation, to find where the payment outcome was lost, because the fulfilment path and the refund path depend on which boundary failed.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Fix the reference", "note": "Payment reference and gateway transaction ID, same payment."}, {"kind": "step", "title": "Trace the gateway boundary", "note": "Find where the outcome was lost at the gateway."}, {"kind": "step", "title": "Trace the bank boundary", "note": "Find where the outcome was lost at the bank."}, {"kind": "step", "title": "Trace the merchant callback", "note": "Find where the outcome was lost at the callback."}, {"kind": "step", "title": "Trace order creation", "note": "Find where the outcome was lost at order creation."}]}}, "level": "advanced", "source_ref": "HAR-11"}, {"id": "INS-062", "seq": 349, "module": "Advanced", "source": "Harish Kavire", "title": "Gateway response succeeds but order system receives no callback", "explain": "A retailer runs a checkout where the payment gateway returns a success response, the customer sees a confirmation screen, and then nothing happens: the order system never receives the callback, so no order is created, no goods are picked, and the customer is charged for a purchase the retailer cannot see. Contain the impact by identifying every payment with no matching order, stop telling customers a payment succeeded until its outcome is known, and give support a holding message that is honest about the uncertainty. Then trace one affected payment end to end using its correlation ID, from the gateway request and response through the payment service state, the event published to the bus, and the callback delivery, to find where the outcome was lost.", "takeaway": "Then trace one affected payment end to end using its correlation ID, from the gateway request and response through the payment service state, the event published to the bus, and the callback delivery, to find where the outcome was lost.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Identify payments with no order", "note": "Find every payment with no matching order."}, {"kind": "step", "title": "Stop confirming success", "note": "Stop telling customers a payment succeeded until known."}, {"kind": "step", "title": "Give support a holding message", "note": "An honest message about the uncertainty."}, {"kind": "step", "title": "Trace one payment end to end", "note": "Gateway, payment service, event bus and callback."}]}}, "level": "advanced", "source_ref": "HAR-10"}, {"id": "INS-030", "seq": 350, "module": "Advanced", "source": "Harish Kavire", "title": "Banking API integration walkthrough", "explain": "A retailer wants to connect its checkout directly to a bank's payment API so orders can be paid without leaving the retailer's site. The business analyst must explain how the integration actually works end to end: how the client authenticates, what the request and response mean, how the retailer learns the final payment outcome, how failures are handled and how the integration is monitored. Walk through the integration in layers and make each layer testable, starting with the contract, the endpoints, the request and response schemas, mandatory and optional fields, validation rules and error codes, then the authentication, the asynchronous status path and the recovery procedures.", "takeaway": "Walk through the integration in layers and make each layer testable, starting with the contract, the endpoints, the request and response schemas, mandatory and optional fields, validation rules and error codes, then the authentication, the asynchronous status path and the recovery procedures.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Define the contract", "note": "Endpoints, schemas, fields, validation and error codes."}, {"kind": "step", "title": "Explain authentication", "note": "How the client authenticates."}, {"kind": "step", "title": "Explain request and response", "note": "What the request and response mean."}, {"kind": "step", "title": "Explain the status path", "note": "How the retailer learns the final outcome."}, {"kind": "step", "title": "Explain failure handling", "note": "How failures are handled and recovered."}, {"kind": "step", "title": "Explain monitoring", "note": "How the integration is monitored."}]}}, "level": "advanced", "source_ref": "HAR-03"}, {"id": "INS-025", "seq": 351, "module": "Advanced", "source": "Harish Kavire", "title": "Gathering requirements for a third-party payment gateway", "explain": "A retailer sells online and in store and wants to add a third-party payment gateway so customers can pay by card and by instant payment at checkout, but the requirements are still a set of general wishes: fast, secure and easy to integrate. Start from the customer and finance outcomes, not from the provider brochure. List the payment methods, currencies, channels and customer journeys in scope, and for each one define the expected flow: authorisation, capture, refund, partial refund, void, chargeback handling and settlement timing. Then define the API capabilities, the request and response contracts, the error handling, the security, the retries and the reconciliation, so the provider can be compared on evidence rather than on marketing.", "takeaway": "Then define the API capabilities, the request and response contracts, the error handling, the security, the retries and the reconciliation, so the provider can be compared on evidence rather than on marketing.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "List what is in scope", "note": "Methods, currencies, channels and customer journeys."}, {"kind": "step", "title": "Define the flow per journey", "note": "Authorisation, capture, refund, void, chargeback, settlement."}, {"kind": "step", "title": "Define API capabilities", "note": "Contracts, error handling, security, retries, reconciliation."}, {"kind": "step", "title": "Compare providers on evidence", "note": "Compare on evidence, not on marketing."}]}}, "level": "advanced", "source_ref": "HAR-02"}, {"id": "INS-048", "seq": 352, "module": "Advanced", "source": "Harish Kavire", "title": "SIT passes but production API fails", "explain": "A merchant payment API integration passes system integration testing cleanly, with every test case returning the expected response, yet it fails in production. Contain the impact first by stopping new submissions if the failure rate is rising, telling the partner what is known and what is not, and confirming which payments have a financial effect and which do not. Then compare the environments side by side in a fixed order: endpoint and configuration, credentials and scopes, certificates and expiry dates, network routes and firewall rules, feature flags, downstream dependency versions and production data. The difference between test and production is usually in one of these, and comparing them in a fixed order finds it faster than guessing.", "takeaway": "The difference between test and production is usually in one of these, and comparing them in a fixed order finds it faster than guessing.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Contain the impact", "note": "Stop new submissions, tell the partner, confirm effect."}, {"kind": "step", "title": "Compare endpoint and configuration", "note": "Check endpoint and configuration first."}, {"kind": "step", "title": "Compare credentials and certificates", "note": "Credentials, scopes, certificates and expiry dates."}, {"kind": "step", "title": "Compare network and firewall", "note": "Network routes and firewall rules."}, {"kind": "step", "title": "Compare flags and dependencies", "note": "Feature flags and downstream dependency versions."}, {"kind": "step", "title": "Compare production data", "note": "Production data is the last comparison."}]}}, "level": "advanced", "source_ref": "HAR-05"}, {"id": "INS-089", "seq": 353, "module": "Advanced", "source": "Harish Kavire", "title": "Validating a payment API", "explain": "A fintech partner is integrating with a bank's payment API to submit customer credit transfers on behalf of its merchants. In testing, the API returns a successful HTTP response, but the merchant's downstream order record is not created, and in one case the payment is debited while the merchant dashboard still shows the order as unpaid. Start from the contract, not from the code: the API definition must state, for each endpoint, what a success response promises, receipt, validation, acceptance or completion, and what the caller must do next in each case. Then review authentication, schema, mandatory fields, business validation, response codes, idempotency and observability, because a success response that promises completion when it only means receipt will mislead every caller.", "takeaway": "Then review authentication, schema, mandatory fields, business validation, response codes, idempotency and observability, because a success response that promises completion when it only means receipt will mislead every caller.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "State what success promises", "note": "Receipt, validation, acceptance or completion per endpoint."}, {"kind": "step", "title": "State what the caller does next", "note": "What the caller must do next in each case."}, {"kind": "step", "title": "Review authentication", "note": "Review authentication for the API."}, {"kind": "step", "title": "Review schema and fields", "note": "Review schema, mandatory fields and business validation."}, {"kind": "step", "title": "Review response codes", "note": "Review response codes and what each means."}, {"kind": "step", "title": "Review idempotency", "note": "Review idempotency and observability."}]}}, "level": "advanced", "source_ref": "HAR-13"}, {"id": "INS-059", "seq": 354, "module": "Advanced", "source": "Harish Kavire", "title": "Defining request and response expectations", "explain": "A bank is publishing a Payment API for corporate customers and retail partners, and the first draft of the contract is a list of fields with no rules. It does not say which fields are required and which are optional, what happens when a field is missing, which error code means what, whether a success response means the payment completed, or how a caller should safely retry. Define every field with its name, type, cardinality, validation rule and error code, and state explicitly which fields are required, which are optional, and which are conditionally mandatory by rail, destination or product. Where a field is optional under the message schema but the bank's reporting or product needs it, say so in the contract and state the source the bank will use and the derivation rule.", "takeaway": "Where a field is optional under the message schema but the bank's reporting or product needs it, say so in the contract and state the source the bank will use and the derivation rule.", "visual": {"type": "diagram", "diagram": {"centre": "Request and response expectations", "parts": [{"label": "Field definition", "note": "Name, type, cardinality, validation rule and error code."}, {"label": "Required fields", "note": "Stated explicitly in the contract."}, {"label": "Optional fields", "note": "Stated explicitly in the contract."}, {"label": "Conditionally mandatory fields", "note": "Mandatory by rail, destination or product."}, {"label": "Bank-needed optional fields", "note": "State the source and the derivation rule."}, {"label": "Success response meaning", "note": "Say whether success means receipt or completion."}]}}, "level": "advanced", "source_ref": "HAR-09"}, {"id": "INS-058", "seq": 355, "module": "Advanced", "source": "Harish Kavire", "title": "Two-week BA sprint for a Payment API integration", "explain": "A retailer needs a Payment API integration delivered in a two-week sprint. The checkout must submit payment instructions to the bank, receive a clear acceptance or rejection, and create the order only when the payment outcome is known. Start the sprint with discovery compressed into the first two days: confirm the business outcome, the checkout journey, the payment types in scope, the expected volumes and the response contract. The contract definition matters most, so agree in writing what each response means, so that an acceptance response is never mistaken for completion, and define the status enquiry path the retailer uses when a payment outcome is unclear.", "takeaway": "The contract definition matters most, so agree in writing what each response means, so that an acceptance response is never mistaken for completion, and define the status enquiry path the retailer uses when a payment outcome is unclear.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Discovery in two days", "note": "Outcome, journey, payment types, volumes, contract."}, {"kind": "step", "title": "Agree the contract in writing", "note": "Acceptance is never mistaken for completion."}, {"kind": "step", "title": "Define the status enquiry path", "note": "The path used when an outcome is unclear."}, {"kind": "step", "title": "Submit and get a clear outcome", "note": "Clear acceptance or rejection from the bank."}, {"kind": "step", "title": "Create the order only when known", "note": "Order is created only when the outcome is known."}]}}, "level": "advanced", "source_ref": "HAR-09"}, {"id": "INS-022", "seq": 356, "module": "Advanced", "source": "Harish Kavire", "title": "Redesigning a KYC onboarding journey", "explain": "A bank wants more new retail customers to complete digital onboarding, but only a small share of started applications reach an active account. Customers abandon the journey at document upload and at identity verification, and many who do finish are later held for manual review because documents are unclear or data does not match. Start with evidence, not opinions, and measure the funnel stage by stage: started, identity details entered, document uploaded, identity verified, screening complete, account opened and first transaction. Then map the friction, the document collection, the validation, the screening, the exception handling and the conversion measures, so the redesign targets the stages where customers actually drop off.", "takeaway": "Then map the friction, the document collection, the validation, the screening, the exception handling and the conversion measures, so the redesign targets the stages where customers actually drop off.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Started to identity details", "note": "Measure the funnel stage by stage."}, {"kind": "step", "title": "Identity details to document upload", "note": "Customers abandon at document upload."}, {"kind": "step", "title": "Document upload to verified", "note": "Many are held for manual review after finishing."}, {"kind": "step", "title": "Verified to screening complete", "note": "Screening must complete before the account opens."}, {"kind": "step", "title": "Screening to account opened", "note": "The account opens after screening."}, {"kind": "step", "title": "Account opened to first transaction", "note": "The first transaction completes onboarding."}, {"kind": "step", "title": "Redesign at the drop-off stages", "note": "Target the stages where customers actually drop off."}]}}, "level": "advanced", "source_ref": "HAR-02"}, {"id": "INS-040", "seq": 357, "module": "Advanced", "source": "Harish Kavire", "title": "Change affects multiple applications and teams", "explain": "A bank must change its instant euro payments to match the current scheme rules: there is no longer a scheme-level maximum amount for SCT Inst, execution must complete within 10 seconds, and verification of payee is mandatory for instant euro payments. The change touches the mobile app, the payment engine, the sanctions and fraud services, the clearing adapter, the ledger and the customer notifications. Build the impact analysis as a map, not as a list of opinions. Start from the change and walk upstream to find which channels, products and customer journeys can submit an instant euro payment, which limits and validations apply today, and which of those must change, then walk downstream to find the systems, data, interfaces, controls, tests, operations and release dependencies that are affected.", "takeaway": "Start from the change and walk upstream to find which channels, products and customer journeys can submit an instant euro payment, which limits and validations apply today, and which of those must change, then walk downstream to find the systems, data, interfaces, controls, tests, operations and release dependencies that are affected.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Start from the change", "note": "No maximum, 10-second execution, payee verification."}, {"kind": "step", "title": "Walk upstream", "note": "Find channels, products and journeys that submit instant payments."}, {"kind": "step", "title": "Find limits to change", "note": "Find which limits and validations must change."}, {"kind": "step", "title": "Walk downstream", "note": "Find systems, data, interfaces, controls, tests and releases."}]}}, "level": "advanced", "source_ref": "HAR-04"}, {"id": "INS-049", "seq": 358, "module": "Advanced", "source": "Harish Kavire", "title": "Critical requirement appears one day before deployment", "explain": "A bank is one day from deploying an upgrade to its instant euro payment service. UAT is signed off, regression evidence is filed, the deployment window is booked and the communications to customers are ready, and late in the afternoon the compliance team raises a requirement nobody recorded. First classify the item precisely as a defect against an agreed requirement, a safety or compliance obligation, or genuinely new scope, and confirm the obligation at its source, for example verification of payee is mandatory for instant euro payments from 9 October 2025 under Regulation (EU) 2024/886, and SCT Inst execution has a 10-second maximum with no scheme-level maximum since the 2025 rulebook change. Then triage defect versus new scope, quantify the risk and obtain a formal go or no-go decision, because a mandatory compliance obligation cannot be deferred the way new scope can.", "takeaway": "Then triage defect versus new scope, quantify the risk and obtain a formal go or no-go decision, because a mandatory compliance obligation cannot be deferred the way new scope can.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Classify the item", "note": "Defect, safety or compliance obligation, or new scope."}, {"kind": "step", "title": "Confirm the obligation", "note": "Payee verification is mandatory from 9 October 2025."}, {"kind": "step", "title": "Triage defect versus scope", "note": "Triage defect versus genuinely new scope."}, {"kind": "step", "title": "Quantify the risk", "note": "Quantify the risk of the late requirement."}, {"kind": "step", "title": "Obtain a go or no-go decision", "note": "A mandatory obligation cannot be deferred like scope."}]}}, "level": "advanced", "source_ref": "HAR-05"}, {"id": "INS-054", "seq": 359, "module": "Advanced", "source": "Harish Kavire", "title": "Critical UAT failure rate at test start", "explain": "A bank is starting user acceptance testing for a new SEPA direct debit collection service. On the first morning the failure rate is critical: most test collections are rejected, mandate references cannot be found, and the test schedule shows collections submitted on the wrong day. Begin with a triage that separates the failure causes into four buckets, environment, test data, build and requirements, and check the environment first: whether the UAT build is the intended version, whether the endpoints, credentials and scheme adapters point at the right test systems, and whether the feature flags are set as the release notes state. Only then decide whether to continue, fix and restart, or stop, because continuing a test on a broken environment wastes the testers' time and produces evidence that cannot be trusted.", "takeaway": "Only then decide whether to continue, fix and restart, or stop, because continuing a test on a broken environment wastes the testers' time and produces evidence that cannot be trusted.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Triage into four buckets", "note": "Environment, test data, build and requirements."}, {"kind": "step", "title": "Check the environment first", "note": "Build version, endpoints, credentials, adapters, flags."}, {"kind": "decision", "title": "Decide continue, fix or stop", "note": "Continuing on a broken environment wastes tester time."}]}}, "level": "advanced", "source_ref": "HAR-08"}, {"id": "INS-055", "seq": 360, "module": "Advanced", "source": "Harish Kavire", "title": "Incorrect EMI for a small customer subset", "explain": "A bank receives complaints from a small group of loan customers that their monthly EMI is wrong. Most customers are unaffected, which makes the problem harder, not easier, so start by defining the affected population precisely: list every complaining account and search for others with the same characteristics, so the fix covers silent cases as well as complaints. For each affected loan, capture the full calculation inputs: principal, sanctioned rate, rate change history with effective dates, tenure, schedule generation rules, rounding policy, part-payment history and customer data. The pattern only emerges when the cases are compared, because the affected loans share a characteristic, such as a particular rate change date, that the unaffected loans do not.", "takeaway": "The pattern only emerges when the cases are compared, because the affected loans share a characteristic, such as a particular rate change date, that the unaffected loans do not.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Define the affected population", "note": "List complaining accounts and search for silent cases."}, {"kind": "step", "title": "Capture the calculation inputs", "note": "Principal, rate, history, tenure, rules, rounding, payments."}, {"kind": "step", "title": "Compare the cases", "note": "The affected loans share a characteristic the others lack."}]}}, "level": "advanced", "source_ref": "HAR-08"}, {"id": "INS-042", "seq": 361, "module": "Advanced", "source": "Harish Kavire", "title": "Designing discovery for a new product", "explain": "A bank wants to launch an instant payment product for small business customers, and the product sponsor has asked the team to make payments faster. The request has no named user group, no baseline, no target speed and no statement of the problem customers actually face today. Start by naming the target users precisely, for example small businesses that pay domestic suppliers on fixed weekly cycles, and exclude segments the product will not serve in the first release, then write a problem statement in the form of who suffers, what it costs them and how often, and gather evidence such as payment volumes, current settlement times, supplier discount losses and support contacts. Then define the hypotheses, the constraints, the minimum viable product and the success metrics, so discovery ends with a decision rather than with a longer list of ideas.", "takeaway": "Then define the hypotheses, the constraints, the minimum viable product and the success metrics, so discovery ends with a decision rather than with a longer list of ideas.", "visual": {"type": "diagram", "diagram": {"centre": "Discovery for a new instant payment product", "parts": [{"label": "Target users", "note": "Small businesses paying domestic suppliers weekly."}, {"label": "Excluded segments", "note": "Segments not served in the first release."}, {"label": "Problem statement", "note": "Who suffers, what it costs them and how often."}, {"label": "Evidence", "note": "Volumes, settlement times, discount losses, support contacts."}, {"label": "Hypotheses and constraints", "note": "Defined so discovery ends with a decision."}, {"label": "MVP and success metrics", "note": "Define the minimum product and how success is judged."}]}}, "level": "advanced", "source_ref": "HAR-04"}, {"id": "INS-043", "seq": 362, "module": "Advanced", "source": "Harish Kavire", "title": "Optimising an inefficient legacy process", "explain": "A bank runs a legacy supplier payment process that has grown by accretion over a decade. A corporate customer sends a payment file, operations staff print exception lists, re-key corrected details into three different screens, phone the customer for missing information, and then release the file late in the day. Begin by observing the work as performed, not as documented: follow real files from intake to release, time each step, and record every workaround, hand-off and re-key, then quantify the pain with measures the business can compare, such as straight-through processing rate, repair rate by defect type, average and worst-case cycle time per step, rework hours, error rate after release and customer contacts per file. Then design the target process, validate the controls and the operational impacts, and only then change the process.", "takeaway": "Then design the target process, validate the controls and the operational impacts, and only then change the process.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Observe the work as performed", "note": "Follow real files, time each step, record workarounds."}, {"kind": "step", "title": "Quantify the pain", "note": "Straight-through rate, repair rate, cycle time, rework, errors."}, {"kind": "step", "title": "Design the target process", "note": "Design the target process from the evidence."}, {"kind": "step", "title": "Validate controls and impacts", "note": "Validate the controls and operational impacts."}, {"kind": "step", "title": "Change the process", "note": "Only then change the process."}]}}, "level": "advanced", "source_ref": "HAR-04"}, {"id": "PAI-C041", "seq": 363, "module": "Advanced", "source": "Paiementor", "title": "The message flow after the clearing system", "explain": "After the clearing system, the message flow continues with the pacs.008 reaching the beneficiary bank and the pacs.002 reporting the status back, and the question is how those messages fit together once the clearing system is in the middle. The clearing system sits between the originator bank and the beneficiary bank, so the pacs.008 passes through it and the pacs.002 returns through it. A business analyst who draws the flow must include the clearing system as a party, not as a pipe, because it sends and receives messages of its own.", "takeaway": "A business analyst who draws the flow must include the clearing system as a party, not as a pipe, because it sends and receives messages of its own.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "pacs.008 passes through clearing system", "note": "The pacs.008 reaches the beneficiary bank through the clearing system"}, {"kind": "step", "title": "Clearing system sends and receives", "note": "The clearing system is a party that sends and receives messages of its own"}, {"kind": "step", "title": "pacs.002 reports status back", "note": "The pacs.002 reports the status back through the clearing system"}, {"kind": "step", "title": "Draw clearing system as a party", "note": "The flow must include the clearing system as a party, not as a pipe"}]}}, "level": "advanced", "source_ref": "https://www.paiementor.com/messages-in-the-interbank-space-pacs-008-and-pacs-002/"}, {"id": "PAI-C042", "seq": 364, "module": "Advanced", "source": "Paiementor", "title": "A payment deducted but never reaching the beneficiary", "explain": "When the originator bank deducts the amount from the customer but the payment never reaches the beneficiary because the clearing system rejected it, the funds must be returned, and the question is which messages carry that return inside the clearing system. The clearing system holds the funds it rejected, so the return starts there and travels back to the originator bank, which credits the customer. The customer sees a deduction with no payment, and the return is what makes the customer whole.", "takeaway": "The customer sees a deduction with no payment, and the return is what makes the customer whole.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Originator bank deducts from customer", "note": "The originator bank deducts the amount from the customer"}, {"kind": "step", "title": "Clearing system rejects the payment", "note": "The clearing system rejects the payment, so it never reaches the beneficiary"}, {"kind": "step", "title": "Clearing system holds the rejected funds", "note": "The clearing system holds the funds it rejected"}, {"kind": "step", "title": "Return travels back to originator bank", "note": "The return starts at the clearing system and travels back to the originator bank"}, {"kind": "step", "title": "Originator bank credits the customer", "note": "The originator bank credits the customer, making the customer whole"}]}}, "level": "advanced", "source_ref": "https://www.paiementor.com/messages-in-the-interbank-space-pacs-008-and-pacs-002/"}, {"id": "PAI-C043", "seq": 365, "module": "Advanced", "source": "Paiementor", "title": "A payment to a bank in a non-English-speaking country", "explain": "When the beneficiary bank is in a country whose language is not English, the MT103 is still processed from its structured fields, which are coded and do not depend on the language of the country. The names and addresses in the message may be in the local language, but the fields that drive processing, such as the account number, the currency, and the amount, are numeric or coded. The processing therefore does not stop at a language barrier; it follows the fields.", "takeaway": "The processing therefore does not stop at a language barrier; it follows the fields.", "visual": {"type": "diagram", "diagram": {"centre": "A payment to a non-English-speaking country", "parts": [{"label": "Structured fields are coded", "note": "The MT103 is processed from its structured fields, which are coded, not language-based"}, {"label": "Names may be in the local language", "note": "The names and addresses in the message may be in the local language"}, {"label": "Account, currency and amount drive processing", "note": "The fields that drive processing, like account number, currency and amount, are coded"}, {"label": "Processing follows the fields", "note": "Processing does not stop at a language barrier; it follows the fields"}]}}, "level": "advanced", "source_ref": "https://www.paiementor.com/swift-serial-and-cover-payments/"}, {"id": "PAI-C044", "seq": 366, "module": "Advanced", "source": "Paiementor", "title": "A transfer to a bank with no account at the sending bank", "explain": "A customer can transfer funds to a bank that has no account with the sending bank, because the payment travels through correspondent and intermediary banks that do hold accounts with each other. The sending bank passes the instruction to its correspondent, which passes it onward until it reaches a bank that holds an account for the beneficiary bank. The chain exists precisely to connect banks that have no direct relationship.", "takeaway": "The chain exists precisely to connect banks that have no direct relationship.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Sending bank has no account with beneficiary", "note": "The beneficiary bank holds no account with the sending bank"}, {"kind": "step", "title": "Sending bank passes to its correspondent", "note": "The sending bank passes the instruction to its correspondent"}, {"kind": "step", "title": "Correspondent passes it onward", "note": "Each correspondent passes it on until it reaches a bank holding the account"}, {"kind": "step", "title": "Payment reaches the beneficiary bank", "note": "The chain connects banks that have no direct relationship"}]}}, "level": "advanced", "source_ref": "https://www.paiementor.com/swift-serial-and-cover-payments/"}, {"id": "PAI-C045", "seq": 367, "module": "Advanced", "source": "Paiementor", "title": "Whether an intermediary is needed with a direct account relationship", "explain": "When the ordering bank and the beneficiary bank already hold accounts with each other, the question is whether an intermediary bank should still be used for an international payment. A direct relationship can carry the payment without an intermediary, which is faster and cheaper, but an intermediary may still be used for a currency, a corridor, or a compliance reason. The choice is a design decision, not a rule, and it depends on the corridor and the banks involved.", "takeaway": "The choice is a design decision, not a rule, and it depends on the corridor and the banks involved.", "visual": {"type": "diagram", "diagram": {"centre": "Direct account relationship", "parts": [{"label": "Direct route is faster and cheaper", "note": "A direct relationship can carry the payment without an intermediary"}, {"label": "Intermediary may still be used", "note": "An intermediary may still be used for a currency, a corridor, or a compliance reason"}, {"label": "Choice is a design decision", "note": "The choice is a design decision, not a rule, and it depends on the corridor and the banks"}]}}, "level": "advanced", "source_ref": "https://www.paiementor.com/swift-serial-and-cover-payments/"}, {"id": "PAI-C046", "seq": 368, "module": "Advanced", "source": "Paiementor", "title": "The ordering customer name misspelt in field 50", "explain": "When the ordering customer name in field 50 is misspelt, the MT103 can be returned to the originator bank, and the question is which message carries that return. The misspelling matters because screening and reconciliation match on the name, and a name that does not match the account can look like a different party. The return is therefore a data-quality failure, not a funds failure, and it is fixed by correcting the name and resending.", "takeaway": "The return is therefore a data-quality failure, not a funds failure, and it is fixed by correcting the name and resending.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Name in field 50 is misspelt", "note": "The ordering customer name in field 50 does not match the account"}, {"kind": "step", "title": "Screening and reconciliation flag the name", "note": "Screening and reconciliation match on the name, so a mismatch looks like a different party"}, {"kind": "step", "title": "MT103 returned to originator bank", "note": "The MT103 can be returned to the originator bank"}, {"kind": "step", "title": "Name corrected and payment resent", "note": "The failure is fixed by correcting the name and resending"}]}}, "level": "advanced", "source_ref": "https://www.paiementor.com/swift-serial-and-cover-payments/"}, {"id": "PAI-C047", "seq": 369, "module": "Advanced", "source": "Paiementor", "title": "A beneficiary who received less after intermediary deductions", "explain": "When an ordering customer pays an employee with an MT103 and an intermediary bank deducts its charges, the beneficiary receives less than the amount sent, and the shortfall is the charge, not an error. The beneficiary bank credits the amount that arrives after the deductions, and the ordering customer must explain the difference to the employee. The situation is a normal consequence of the serial method, and it is why the charge-bearer field matters before the payment is sent.", "takeaway": "The situation is a normal consequence of the serial method, and it is why the charge-bearer field matters before the payment is sent.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Ordering customer pays employee by MT103", "note": "An ordering customer pays an employee with an MT103"}, {"kind": "step", "title": "Intermediary deducts its charge", "note": "An intermediary bank deducts its charges from the payment"}, {"kind": "step", "title": "Beneficiary bank credits the reduced amount", "note": "The beneficiary bank credits the amount that arrives after the deductions"}, {"kind": "step", "title": "Ordering customer explains the shortfall", "note": "The ordering customer must explain the difference to the employee"}]}}, "level": "advanced", "source_ref": "https://www.paiementor.com/swift-serial-and-cover-payments/"}, {"id": "PAI-C048", "seq": 370, "module": "Advanced", "source": "Paiementor", "title": "UK Faster Payments and BACS message flows", "explain": "The messages exchanged between banks in UK Faster Payments and in BACS are different from the messages used in SEPA, and readers ask for the flow in each system. The SEPA message set is a good starting point, because the concepts of initiation, clearing, and status reporting are the same, but the actual messages and the clearing systems differ. A business analyst who understands the SEPA flow can learn the UK flows by mapping each SEPA message to its UK equivalent, rather than starting from nothing.", "takeaway": "A business analyst who understands the SEPA flow can learn the UK flows by mapping each SEPA message to its UK equivalent, rather than starting from nothing.", "visual": {"type": "diagram", "diagram": {"centre": "UK Faster Payments and BACS flows", "parts": [{"label": "Different messages from SEPA", "note": "The messages exchanged between banks in Faster Payments and BACS differ from SEPA messages"}, {"label": "Same concepts: initiation, clearing, status", "note": "The concepts of initiation, clearing, and status reporting are the same as in SEPA"}, {"label": "Actual messages and clearing differ", "note": "The actual messages and the clearing systems differ from SEPA"}, {"label": "Map each SEPA message to its UK equivalent", "note": "Learn the UK flows by mapping each SEPA message to its UK equivalent"}]}}, "level": "advanced", "source_ref": "https://www.paiementor.com/differences-uk-faster-payments-sepa-swift-payments/"}, {"id": "PAI-C049", "seq": 371, "module": "Advanced", "source": "Paiementor", "title": "CHAPS for cross-border payments", "explain": "CHAPS is the UK high-value payment system, and the question is whether it can be used for cross-border payments. CHAPS settles sterling payments between UK banks in central bank money, and a cross-border payment that needs sterling settlement in the UK can use it as the domestic leg. The cross-border leg itself still needs a correspondent or a scheme to carry the payment out of the UK, so CHAPS is one leg of the journey, not the whole journey.", "takeaway": "The cross-border leg itself still needs a correspondent or a scheme to carry the payment out of the UK, so CHAPS is one leg of the journey, not the whole journey.", "visual": {"type": "diagram", "diagram": {"centre": "CHAPS for cross-border payments", "parts": [{"label": "UK high-value payment system", "note": "CHAPS is the UK high-value payment system"}, {"label": "Settles sterling in central bank money", "note": "CHAPS settles sterling payments between UK banks in central bank money"}, {"label": "Usable as the domestic sterling leg", "note": "A cross-border payment needing sterling settlement can use CHAPS as the domestic leg"}, {"label": "Cross-border leg still needs a scheme", "note": "The cross-border leg still needs a correspondent or a scheme to carry the payment out"}]}}, "level": "advanced", "source_ref": "https://www.paiementor.com/differences-uk-faster-payments-sepa-swift-payments/"}, {"id": "PAI-C050", "seq": 372, "module": "Advanced", "source": "Paiementor", "title": "Why BACS is still preferred after Faster Payments", "explain": "Faster Payments settles in seconds, yet BACS remains the preferred way to pay for many UK businesses, and the reason is that BACS is built for bulk, scheduled, low-cost payments such as salaries and supplier runs. Faster Payments is built for single, urgent payments, and it costs more per payment and carries limits that bulk runs do not want. The two systems therefore serve different needs, and the older one survives because it fits the bulk use case better.", "takeaway": "The two systems therefore serve different needs, and the older one survives because it fits the bulk use case better.", "visual": {"type": "diagram", "diagram": {"centre": "Why BACS is still preferred after Faster Payments", "parts": [{"label": "BACS", "note": "Bulk, scheduled, low-cost payments such as salaries and supplier runs"}, {"label": "Faster Payments", "note": "Single, urgent payments, costs more per payment"}, {"label": "Different needs", "note": "The older system survives because it fits the bulk use case"}]}}, "level": "advanced", "source_ref": "https://www.paiementor.com/differences-uk-faster-payments-sepa-swift-payments/"}, {"id": "PAI-C051", "seq": 373, "module": "Advanced", "source": "Paiementor", "title": "How Wise moves money without SWIFT codes", "explain": "Wise moves money internationally without using SWIFT codes for every payment, because it holds local accounts in the countries it serves and settles each leg domestically. A customer paying from one country to another funds a local account in the sending country, and Wise pays the beneficiary from its local account in the receiving country, so no cross-border SWIFT message is needed for the legs. The model works because Wise nets the flows across its customers, and it is a different design from the correspondent banking chain.", "takeaway": "The model works because Wise nets the flows across its customers, and it is a different design from the correspondent banking chain.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Customer funds a local Wise account", "note": "A customer funds a local account in the sending country"}, {"kind": "step", "title": "Wise pays from its local account abroad", "note": "Wise pays the beneficiary from its local account in the receiving country"}, {"kind": "step", "title": "Each leg settles domestically", "note": "No cross-border SWIFT message is needed for the legs"}, {"kind": "step", "title": "Wise nets the flows across customers", "note": "The model works because Wise nets the flows across its customers"}]}}, "level": "advanced", "source_ref": "https://www.paiementor.com/differences-uk-faster-payments-sepa-swift-payments/"}, {"id": "PAI-C052", "seq": 374, "module": "Advanced", "source": "Paiementor", "title": "Currency and fields 52, 53 and 54 in the cover payment", "explain": "In a cover payment the MT103 and the MT202 can carry different currencies, and the question is how the currency of each leg is decided and what fields 52, 53 and 54 carry. Field 52 identifies the ordering institution, field 53 identifies the sender's correspondent, and field 54 identifies the receiver's correspondent, so together they describe the chain of banks that will fund the payment. The currency of the cover leg follows the correspondent account it settles in, which is why the two legs can differ.", "takeaway": "The currency of the cover leg follows the correspondent account it settles in, which is why the two legs can differ.", "visual": {"type": "diagram", "diagram": {"centre": "Currency and fields 52, 53 and 54", "parts": [{"label": "Legs can carry different currencies", "note": "The MT103 and the MT202 can carry different currencies in a cover payment"}, {"label": "Field 52: ordering institution", "note": "Field 52 identifies the ordering institution"}, {"label": "Field 53: sender's correspondent", "note": "Field 53 identifies the sender's correspondent"}, {"label": "Field 54: receiver's correspondent", "note": "Field 54 identifies the receiver's correspondent"}, {"label": "Cover currency follows its account", "note": "The currency of the cover leg follows the correspondent account it settles in"}]}}, "level": "advanced", "source_ref": "https://www.paiementor.com/swift-mt103-202-cover-payment-analysis-part-1/"}, {"id": "PAI-C053", "seq": 375, "module": "Advanced", "source": "Paiementor", "title": "SEPA dispute, cancellation and recall", "explain": "In SEPA, a dispute, a cancellation, and a recall are three different actions, and the question is how each one works and which message carries it. A recall is requested with a camt.056 and answered with a camt.029, a return is made with a pacs.004, and a cancellation stops a payment before it settles. The three are often confused because they all undo a payment, but they apply at different stages and they use different messages.", "takeaway": "The three are often confused because they all undo a payment, but they apply at different stages and they use different messages.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "decision", "title": "Payment already settled or not", "note": "The three actions apply at different stages of the payment"}, {"kind": "step", "title": "Cancellation stops a payment before settlement", "note": "A cancellation stops a payment before it settles"}, {"kind": "step", "title": "Recall requested with camt.056", "note": "A recall is requested with a camt.056 and answered with a camt.029"}, {"kind": "step", "title": "Return made with pacs.004", "note": "A return is made with a pacs.004"}]}}, "level": "advanced", "source_ref": "https://www.paiementor.com/differences-uk-faster-payments-sepa-swift-payments/"}, {"id": "PAI-C067", "seq": 376, "module": "Advanced", "source": "Paiementor", "title": "A beneficiary bank with a non-connected BIC", "explain": "Some banks hold a BIC with the digit 1 in position 8, which marks it as non-connected: it is a SWIFT participant but cannot receive messages directly. The MT103 announcement and the MT202 COV are then sent to a live BIC, which forwards the funds to the non-connected bank over an internal network, usually with a normal serial MT103. The same pattern appears in bank groups where SWIFT communication is centralised at the head office and the head office forwards payments to subsidiaries and branches.", "takeaway": "The same pattern appears in bank groups where SWIFT communication is centralised at the head office and the head office forwards payments to subsidiaries and branches.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Beneficiary bank holds a non-connected BIC", "note": "The BIC has the digit 1 in position 8, so the bank cannot receive messages directly"}, {"kind": "step", "title": "MT103 and MT202 COV sent to a live BIC", "note": "The announcement and the cover are sent to a live BIC"}, {"kind": "step", "title": "Live BIC forwards the funds onward", "note": "The live BIC forwards the funds to the non-connected bank over an internal network"}, {"kind": "step", "title": "Forwarding uses a normal serial MT103", "note": "The onward leg usually uses a normal serial MT103"}, {"kind": "step", "title": "Head office forwards to subsidiaries", "note": "The same pattern appears where SWIFT is centralised at the head office"}]}}, "level": "advanced", "source_ref": "https://www.paiementor.com/swift-mt103-202-cover-payment-analysis-part-3/"}, {"id": "PAI-C071", "seq": 377, "module": "Advanced", "source": "Paiementor", "title": "Why a bank waits before buying the payment currency", "explain": "A bank does not buy the currency of every payment the moment it is instructed, because it does not know in advance how much foreign currency it will need. It collects orders until a cut-off time and then decides whether to buy, sell or do nothing, based on the balance of orders and the funds already sitting in its nostro accounts. A payment can therefore wait for the bank's currency position to be settled, even when the instruction itself is complete.", "takeaway": "A payment can therefore wait for the bank's currency position to be settled, even when the instruction itself is complete.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Bank receives payment instructions", "note": "The bank is instructed on payments but does not buy the currency at once"}, {"kind": "step", "title": "Orders collected until cut-off time", "note": "The bank collects orders until a cut-off time"}, {"kind": "step", "title": "Bank checks its nostro balances", "note": "It weighs the balance of orders against funds already sitting in its nostro accounts"}, {"kind": "decision", "title": "Buy, sell or do nothing", "note": "It decides whether to buy, sell or do nothing based on the balance of orders"}, {"kind": "step", "title": "Payment waits for the currency position", "note": "A payment can wait for the bank's currency position to be settled"}]}}, "level": "advanced", "source_ref": "https://www.paiementor.com/swift-mt103-202-cover-payment-analysis-part-2/"}, {"id": "PAI-C073", "seq": 378, "module": "Advanced", "source": "Paiementor", "title": "Returned five times over a wrong 57A", "explain": "A payment sent to Australia was returned five times over six weeks, each time with the note that the beneficiary bank's SWIFT code had to appear in field 57A. The code had been placed in field 72 and in field 52A, where the receiving bank could see it, but that did not satisfy the validation: field 57A is the field the receiving bank reads to find the account with institution. The beneficiary bank had also been taken over and its SWIFT code had changed, so the sender had to use the new code in field 57A before the payment could be applied.", "takeaway": "The beneficiary bank had also been taken over and its SWIFT code had changed, so the sender had to use the new code in field 57A before the payment could be applied.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Payment sent to Australia", "note": "A payment sent to Australia was returned five times over six weeks"}, {"kind": "step", "title": "SWIFT code placed in field 72 and 52A", "note": "The beneficiary bank's SWIFT code was placed in field 72 and in field 52A"}, {"kind": "step", "title": "Receiving bank requires code in 57A", "note": "Field 57A is the field the receiving bank reads to find the account with institution"}, {"kind": "step", "title": "Beneficiary bank taken over, code changed", "note": "The beneficiary bank had been taken over and its SWIFT code had changed"}, {"kind": "step", "title": "New code used in field 57A", "note": "The sender had to use the new code in field 57A before the payment could be applied"}]}}, "level": "advanced", "source_ref": "https://www.paiementor.com/mt103-swift-message-with-optional-fields-52a-and-57a-part-2/"}, {"id": "PAI-C076", "seq": 379, "module": "Advanced", "source": "Paiementor", "title": "Reconciling a pass-through payment: the UETR links the incoming and outgoing legs", "explain": "When a payment passes through a correspondent bank, that bank sees two payments: the incoming payment from the sender and the outgoing payment to the next bank. The two legs are linked by the unique end-to-end transaction reference, the UETR, which travels unchanged from one message to the next and is carried in field 121 of block 3. No bank in the chain may modify field 121, because changing it would break the link that lets every bank reconcile the payment it received with the payment it sent.", "takeaway": "No bank in the chain may modify field 121, because changing it would break the link that lets every bank reconcile the payment it received with the payment it sent.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Correspondent sees two payments", "note": "The bank sees the incoming payment and the outgoing payment to the next bank"}, {"kind": "step", "title": "UETR travels unchanged in both legs", "note": "The unique end-to-end transaction reference travels unchanged from one message to the next"}, {"kind": "step", "title": "UETR carried in field 121 of block 3", "note": "The UETR is carried in field 121 of block 3"}, {"kind": "step", "title": "No bank may modify field 121", "note": "Changing it would break the link between the payment received and the payment sent"}, {"kind": "step", "title": "Bank reconciles incoming and outgoing legs", "note": "The UETR lets every bank reconcile the payment it received with the payment it sent"}]}}, "level": "advanced", "source_ref": "https://www.paiementor.com/mt103-swift-message-with-optional-fields-52a-and-57a-part-2/"}, {"id": "PAI-C086", "seq": 380, "module": "Advanced", "source": "Paiementor", "title": "A future-dated MT103 is not a discountable instrument", "explain": "An MT103 can be value-dated far in the future, but that does not turn it into an instrument a bank will discount. An MT103 is an instruction to pay, not a proof of financial commitment: at the due date the payment will be executed only if the payer's account holds sufficient funds. If the payer does not pay, the beneficiary has no recourse, and neither does a bank that discounted it, unless it signed a separate contract with the payer.", "takeaway": "If the payer does not pay, the beneficiary has no recourse, and neither does a bank that discounted it, unless it signed a separate contract with the payer.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "MT103 value-dated far in the future", "note": "An MT103 can be value-dated far in the future"}, {"kind": "step", "title": "MT103 is an instruction to pay", "note": "An MT103 is an instruction to pay, not a proof of financial commitment"}, {"kind": "decision", "title": "Payer account holds sufficient funds", "note": "At the due date the payment is executed only if the payer's account holds sufficient funds"}, {"kind": "step", "title": "Beneficiary has no recourse if unpaid", "note": "If the payer does not pay, the beneficiary has no recourse"}, {"kind": "step", "title": "Discounting bank needs a separate contract", "note": "A bank that discounted it has no recourse without a separate contract with the payer"}]}}, "level": "advanced", "source_ref": "https://www.paiementor.com/swift-mt103-message-example-with-optional-fields-53b-70-and-71g-explained/"}, {"id": "PAI-C099", "seq": 381, "module": "Advanced", "source": "Paiementor", "title": "The accounting behind an MT101", "explain": "Accounting is done on the MT101 itself, in part: the debtor's account is debited and the funds are placed on an intermediary account inside the bank. When the MT103 is generated to move the money onward, the funds are debited from that intermediary account and forwarded to the destination. The MT101 therefore does the customer-side accounting, and the MT103 does the interbank settlement.", "takeaway": "The MT101 therefore does the customer-side accounting, and the MT103 does the interbank settlement.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Debtor account debited to intermediary account", "note": "The debtor's account is debited and the funds go to an intermediary account in the bank"}, {"kind": "step", "title": "MT103 generated to move money onward", "note": "When the MT103 is generated, the funds are debited from that intermediary account"}, {"kind": "step", "title": "Funds forwarded to the destination", "note": "The funds are forwarded to the destination from the intermediary account"}, {"kind": "step", "title": "MT101 is customer-side accounting", "note": "The MT101 does the customer-side accounting"}, {"kind": "step", "title": "MT103 is interbank settlement", "note": "The MT103 does the interbank settlement"}]}}, "level": "advanced", "source_ref": "https://www.paiementor.com/basic-swift-mt101-message-with-two-domestic-transactions/"}, {"id": "RUN4-017", "seq": 382, "module": "Advanced", "source": "Paiementor", "title": "Bank to bank dollars move inside the USA, not across borders", "explain": "When a French bank sends USD to a German bank, it instructs its US correspondent to debit its nostro account and credit the German bank's account with its own US correspondent. That transfer happens in one step through the domestic payment systems in the USA, because both accounts sit in the USA. The sender finds the German bank's US correspondent from its Standing Settlement Instructions and states it in the MT103.", "takeaway": "The sender finds the German bank's US correspondent from its Standing Settlement Instructions and states it in the MT103.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "French bank instructs its US correspondent", "note": "It instructs its US correspondent to debit its nostro account."}, {"kind": "step", "title": "German bank account credited in the USA", "note": "The correspondent credits the German bank's account with its own US correspondent."}, {"kind": "step", "title": "Transfer settles in one step", "note": "That transfer happens in one step through the domestic payment systems in the USA."}, {"kind": "step", "title": "Correspondent found in settlement instructions", "note": "The sender finds the German bank's US correspondent in the settlement instructions."}, {"kind": "step", "title": "MT103 states the correspondent", "note": "The sender states the German bank's US correspondent in the MT103."}]}}, "level": "advanced", "source_ref": "https://www.paiementor.com/strategy-2-understand-how-cross-border-payments-work/"}, {"id": "RUN4-019", "seq": 383, "module": "Advanced", "source": "Paiementor", "title": "Settling a letter of credit: serial MT103 or MT103 plus MT202 COV", "explain": "A letter of credit itself is issued with an MT700, but the standard does not fix how it must be settled, so the parties agree the payment instrument between themselves. In general the settlement is done through a serial MT103 or through an MT103 together with an MT202 COV. Either route moves the funds under the credit once the documents have been accepted.", "takeaway": "Either route moves the funds under the credit once the documents have been accepted.", "visual": {"type": "flow", "flow": {"stepSeconds": 3, "steps": [{"kind": "step", "title": "Letter of credit issued with MT700", "note": "A letter of credit itself is issued with an MT700."}, {"kind": "step", "title": "Parties agree the settlement instrument", "note": "The standard does not fix the settlement, so the parties agree the instrument themselves."}, {"kind": "step", "title": "Settle by serial MT103", "note": "In general the settlement is done through a serial MT103."}, {"kind": "step", "title": "Or MT103 plus MT202 COV", "note": "Alternatively the settlement is done through an MT103 together with an MT202 COV."}, {"kind": "step", "title": "Funds move once documents accepted", "note": "Either route moves the funds under the credit once the documents have been accepted."}]}}, "level": "advanced", "source_ref": "https://www.paiementor.com/documentary-credit-process-with-a-confirming-bank/"}, {"id": "RUN4-020", "seq": 384, "module": "Advanced", "source": "Paiementor", "title": "France before SEPA: PNS and TBF for high value, CORE for retail", "explain": "Before SEPA, France already had EBA systems for interbank payments and high value systems called PNS and TBF. CORE, the retail clearing system, was introduced after SEPA to handle files in XML formats and provide better services for retail payments. The market infrastructures changed a lot with the SEPA project, with old and new systems sitting side by side for a time.", "takeaway": "The market infrastructures changed a lot with the SEPA project, with old and new systems sitting side by side for a time.", "visual": {"type": "diagram", "diagram": {"centre": "France before SEPA", "parts": [{"label": "PNS and TBF for high value", "note": "France had high value systems called PNS and TBF before SEPA."}, {"label": "EBA systems for interbank payments", "note": "France already had EBA systems for interbank payments before SEPA."}, {"label": "CORE for retail", "note": "CORE, the retail clearing system, was introduced after SEPA for files in XML formats."}, {"label": "Better retail services", "note": "CORE was introduced to provide better services for retail payments."}, {"label": "Old and new side by side", "note": "The market infrastructures changed a lot with SEPA, with old and new systems side by side."}]}}, "level": "advanced", "source_ref": "https://www.paiementor.com/strategy-1-understand-how-cross-border-payments-work/"}, {"id": "RUN5-005", "seq": 385, "module": "Advanced", "source": "Paiementor", "title": "How clearing and settlement works on RuPay", "explain": "On RuPay, clearing and settlement happen between domestic and other network partners, with RuPay acting as both the card scheme and the clearing house. In India the clearing house role sits with NPCI, which operates RuPay. When the issuer and the acquirer are both members of RuPay, they clear their transactions through RuPay itself rather than through a separate clearing house.", "takeaway": "When the issuer and the acquirer are both members of RuPay, they clear their transactions through RuPay itself rather than through a separate clearing house.", "visual": {"type": "diagram", "diagram": {"centre": "RuPay clearing and settlement", "parts": [{"label": "RuPay is both scheme and clearing house", "note": "RuPay acts as both the card scheme and the clearing house."}, {"label": "NPCI operates RuPay in India", "note": "In India the clearing house role sits with NPCI, which operates RuPay."}, {"label": "Clearing between domestic partners", "note": "Clearing and settlement happen between domestic and other network partners."}, {"label": "Members clear through RuPay", "note": "When issuer and acquirer are both RuPay members, they clear through RuPay itself."}]}}, "level": "advanced", "source_ref": "https://www.paiementor.com/4-party-scheme-in-card-flow-exchanges-for-a-card-payment/"}];
